INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u1-C1','math',4,2,'u1',2,'단위분수의 개수와 대분수·가분수 — 진분수·가분수·대분수를 가르고, 분수를 단위분수가 몇 개인 수로 보며 대분수와 가분수를 서로 바꾸기',ARRAY['4수01-12']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u1-C2','math',4,2,'u1',2,'1을 가르고 분수를 모으기 — 1을 분모와 분자가 같은 분수(⟨b/b⟩)로 나타내고, 1을 분모가 같은 두 분수로 가르거나 두 분수를 모아 1 만들기',ARRAY['4수01-12']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u1-C3','math',4,2,'u1',3,'진분수의 덧셈 — 분모가 같은 진분수끼리는 분모는 그대로 두고 분자끼리 더하며, 결과가 1보다 크면 대분수로 나타내기',ARRAY['4수01-12']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u1-C4','math',4,2,'u1',4,'진분수의 뺄셈과 1 − 진분수 — 분모가 같은 진분수끼리 분자끼리 빼고, 1에서 뺄 때는 1을 ⟨b/b⟩로 바꾸어 빼기',ARRAY['4수01-12']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u1-C5','math',4,2,'u1',5,'대분수의 덧셈 — 자연수끼리·진분수끼리 더하고 진분수끼리의 합이 1보다 크면 1을 자연수로 넘기거나, 가분수로 바꾸어 더하기',ARRAY['4수01-12']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u1-C6','math',4,2,'u1',6,'대분수의 뺄셈 — 자연수끼리·진분수끼리 빼거나 가분수로 바꾸어 빼기(자연수 부분이 없어지는 뺄셈 포함)',ARRAY['4수01-12']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u1-C7','math',4,2,'u1',7,'자연수 − 분수 — 자연수에서 1만큼을 분모가 같은 분수로 바꾸어(3 = ⟨2 4/4⟩) 빼기, 자연수 부분은 1 줄어든다',ARRAY['4수01-12']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u1-C8','math',4,2,'u1',7,'대분수 − 진분수(1만큼 바꾸기) — 진분수끼리 뺄 수 없으면 자연수에서 1만큼을 ⟨b/b⟩로 바꾸어 분수 부분에 더한 뒤 빼거나, 가분수로 바꾸어 빼기',ARRAY['4수01-12']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u1-C9','math',4,2,'u1',8,'대분수 − 대분수(1만큼 바꾸기) — 진분수끼리 뺄 수 없는 대분수의 뺄셈을 1만큼 바꾸어 부분끼리 또는 가분수로 바꾸어 계산하고, 잘못 계산한 곳을 찾아 고치기',ARRAY['4수01-12']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-2-u1-C10','math',4,2,'u1',9,'분수 카드로 식 만들기 — 결과에 맞는 덧셈식·뺄셈식을 어림해서 고르고 계산으로 확인하며, 합·차가 가장 크거나 작게 되는 식 만들기',ARRAY['4수01-12']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X01','math',4,'u1',ARRAY['M4-2-u1-C3','M4-2-u1-C4','M4-2-u1-C5','M4-2-u1-C6']::text[],'분모끼리도 더하거나 뺀다(⟨1/5⟩ + ⟨3/5⟩ → ⟨4/10⟩)','분모는 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X02','math',4,'u1',ARRAY['M4-2-u1-C1']::text[],'진분수·가분수·대분수의 뜻이나 단위분수의 개수를 헷갈린다(⟨7/9⟩ → ⟨1/9⟩이 9개)','분자 = 단위분수 개수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X03','math',4,'u1',ARRAY['M4-2-u1-C1','M4-2-u1-C5','M4-2-u1-C6','M4-2-u1-C9']::text[],'대분수를 가분수로 바꿀 때 자연수 부분을 단위분수 개수로 바꾸지 않는다(⟨2 1/3⟩ → ⟨3/3⟩)','자연수 1 = 분모만큼') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X04','math',4,'u1',ARRAY['M4-2-u1-C1','M4-2-u1-C3','M4-2-u1-C5']::text[],'가분수를 대분수로 바꿀 때 자연수(통째 1)를 잘못 센다(⟨11/4⟩ → ⟨3 3/4⟩·⟨1 3/4⟩)','분모만큼씩 모아 1') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X05','math',4,'u1',ARRAY['M4-2-u1-C2','M4-2-u1-C4','M4-2-u1-C7']::text[],'1을 분모와 분자가 같은 분수로 보지 못한다(1 = ⟨1/7⟩)','1 = ⟨b/b⟩') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X06','math',4,'u1',ARRAY['M4-2-u1-C2']::text[],'모아서 1이 되는 분수를 구할 때 분모에서 분자를 빼지 않는다(⟨4/9⟩와 모아 1 → ⟨4/9⟩·⟨9/4⟩)','모자란 단위분수 개수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X07','math',4,'u1',ARRAY['M4-2-u1-C3','M4-2-u1-C5']::text[],'진분수끼리의 합이 1보다 클 때 1을 자연수에 더하지 않는다(⟨1 3/5⟩ + ⟨1 4/5⟩ → ⟨2 2/5⟩)','넘친 1은 자연수로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X08','math',4,'u1',ARRAY['M4-2-u1-C4','M4-2-u1-C7']::text[],'1에서 진분수를 뺄 때 1을 ⟨b/b⟩로 바꾸지 않고 분자에서 1을 뺀다(1 − ⟨2/7⟩ → ⟨1/7⟩)','1 = ⟨b/b⟩로 바꾸기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X09','math',4,'u1',ARRAY['M4-2-u1-C7','M4-2-u1-C8','M4-2-u1-C9']::text[],'1만큼을 분수로 바꾸고도 자연수 부분에서 1을 빼지 않는다(3 − ⟨1/4⟩ → ⟨3 3/4⟩, ⟨5 1/6⟩ − ⟨2 5/6⟩ → ⟨3 2/6⟩)','바꾼 1은 자연수에서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X10','math',4,'u1',ARRAY['M4-2-u1-C7']::text[],'자연수에서 분수를 뺄 때 빼는 분수를 그대로 쓴다(3 − ⟨1/4⟩ → ⟨2 1/4⟩)','⟨4/4⟩에서 덜어 내기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X11','math',4,'u1',ARRAY['M4-2-u1-C8','M4-2-u1-C9']::text[],'진분수끼리 뺄 수 없을 때 큰 분자에서 작은 분자를 거꾸로 뺀다(⟨5 1/6⟩ − ⟨2 5/6⟩ → ⟨3 4/6⟩)','거꾸로 빼지 않기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X12','math',4,'u1',ARRAY['M4-2-u1-C8','M4-2-u1-C9']::text[],'1만큼을 분수로 바꿀 때 분자에 분모가 아닌 10을 더한다(⟨5 1/6⟩ → ⟨4 11/6⟩)','1 = 분모만큼') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X13','math',4,'u1',ARRAY['M4-2-u1-C5','M4-2-u1-C6','M4-2-u1-C8','M4-2-u1-C9']::text[],'대분수의 덧셈·뺄셈에서 자연수 부분을 빼먹는다(⟨3 5/6⟩ − ⟨1 2/6⟩ → ⟨3/6⟩)','자연수끼리도 계산') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X14','math',4,'u1',ARRAY['M4-2-u1-C3','M4-2-u1-C4','M4-2-u1-C5','M4-2-u1-C6','M4-2-u1-C7','M4-2-u1-C9','M4-2-u1-C10']::text[],'더해야 할 때 빼거나 빼야 할 때 더한다(「얼마나 더」·「남은」을 덧셈으로)','모으면 덧셈·덜어 내면 뺄셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X15','math',4,'u1',ARRAY['M4-2-u1-C1','M4-2-u1-C2','M4-2-u1-C3','M4-2-u1-C4','M4-2-u1-C5','M4-2-u1-C6','M4-2-u1-C7','M4-2-u1-C8','M4-2-u1-C9','M4-2-u1-C10']::text[],'묻는 말을 거꾸로 읽는다 — 남은↔쓴, 더 많은↔더 적은, 가장 큰↔가장 작은','물음에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X16','math',4,'u1',ARRAY['M4-2-u1-C1','M4-2-u1-C2','M4-2-u1-C3','M4-2-u1-C4','M4-2-u1-C5','M4-2-u1-C7','M4-2-u1-C10']::text[],'분자를 하나 많거나 적게 세거나, □에 들어갈 수를 셀 때 경계의 수를 넣거나 뺀다','하나씩 넣어 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X17','math',4,'u1',ARRAY['M4-2-u1-C10']::text[],'어림 없이 분자나 자연수 하나만 보고 식의 크기를 정한다(합을 가장 크게 하려고 분자가 큰 카드 하나만 본다)','어림한 뒤 계산으로 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-2-u1-X18','math',4,'u1',ARRAY['M4-2-u1-C3','M4-2-u1-C5','M4-2-u1-C10']::text[],'계산해서 견줄 수 있는데도 「알 수 없다」·「같다」고 한다','계산해서 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L02_basic#1','math',4,2,'u1','L02','g4_2_math_u1_L02_basic','lesson_basic','M4-2-u1-C1',1,'sa','auto','⟨7/9⟩은 ⟨1/9⟩이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-2-u1-C1","difficulty":1,"kind":"sa","stem":"⟨7/9⟩은 ⟨1/9⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["분모 9 — 1을 똑같이 9칸으로 나눈 것 중 한 칸이 ⟨1/9⟩이에요.","분자 7 — ⟨1/9⟩이 7개라는 뜻이에요.","⟨7/9⟩은 ⟨1/9⟩이 7개인 수예요."],"variant_rule":{"alt":[{"stem":"⟨6/5⟩은 ⟨1/5⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["분모 5 — 1을 똑같이 5칸으로 나눈 것 중 한 칸이 ⟨1/5⟩이에요.","분자 6 — ⟨1/5⟩이 6개라는 뜻이에요.","⟨6/5⟩은 ⟨1/5⟩이 6개인 수예요."],"asset":null},{"stem":"⟨9/5⟩는 ⟨1/5⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["분모 5 — 1을 똑같이 5칸으로 나눈 것 중 한 칸이 ⟨1/5⟩이에요.","분자 9 — ⟨1/5⟩이 9개라는 뜻이에요.","⟨9/5⟩는 ⟨1/5⟩이 9개인 수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L02_basic#2','math',4,2,'u1','L02','g4_2_math_u1_L02_basic','lesson_basic','M4-2-u1-C2',1,'mc','auto','1을 분모가 7인 분수로 나타내면 무엇인가요?',ARRAY['M4-2-u1-X05','M4-2-u1-X16']::text[],true,'{"seq":2,"concept":"M4-2-u1-C2","difficulty":1,"kind":"mc","stem":"1을 분모가 7인 분수로 나타내면 무엇인가요?","options":[{"t":"⟨7/7⟩","correct":true},{"t":"⟨1/7⟩","mis":"M4-2-u1-X05"},{"t":"⟨6/7⟩","mis":"M4-2-u1-X16"},{"t":"⟨8/7⟩","mis":"M4-2-u1-X16"}],"explanation":["분모가 7이면 1을 똑같이 7칸으로 나누어요.","7칸을 모두 모으면 1 — ⟨1/7⟩이 7개.","1 = ⟨7/7⟩ — 분모와 분자가 같아요."],"variant_rule":{"alt":[{"stem":"1을 분모가 11인 분수로 나타내면 무엇인가요?","options":[{"t":"⟨11/11⟩","correct":true},{"t":"⟨1/11⟩","mis":"M4-2-u1-X05"},{"t":"⟨10/11⟩","mis":"M4-2-u1-X16"},{"t":"⟨12/11⟩","mis":"M4-2-u1-X16"}],"explanation":["분모가 11이면 1을 똑같이 11칸으로 나누어요.","11칸을 모두 모으면 1 — ⟨1/11⟩이 11개.","1 = ⟨11/11⟩ — 분모와 분자가 같아요."],"asset":null},{"stem":"1을 분모가 10인 분수로 나타내면 무엇인가요?","options":[{"t":"⟨10/10⟩","correct":true},{"t":"⟨1/10⟩","mis":"M4-2-u1-X05"},{"t":"⟨9/10⟩","mis":"M4-2-u1-X16"},{"t":"⟨11/10⟩","mis":"M4-2-u1-X16"}],"explanation":["분모가 10이면 1을 똑같이 10칸으로 나누어요.","10칸을 모두 모으면 1 — ⟨1/10⟩이 10개.","1 = ⟨10/10⟩ — 분모와 분자가 같아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L02_basic#3','math',4,2,'u1','L02','g4_2_math_u1_L02_basic','lesson_basic','M4-2-u1-C2',1,'sa','auto','1을 ⟨1/5⟩이 1개인 분수와 ⟨1/5⟩이 □개인 분수로 갈랐어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u1-C2","difficulty":1,"kind":"sa","stem":"1을 ⟨1/5⟩이 1개인 분수와 ⟨1/5⟩이 □개인 분수로 갈랐어요. □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["분모가 5이면 1 = ⟨5/5⟩ — ⟨1/5⟩이 5개예요.","5개 중 1개를 떼면 5 − 1 = 4개가 남아요.","□ = 4 — 1 = ⟨1/5⟩ + ⟨4/5⟩."],"variant_rule":{"alt":[{"stem":"1을 ⟨1/9⟩이 2개인 분수와 ⟨1/9⟩이 □개인 분수로 갈랐어요. □에 알맞은 수를 쓰세요.","answer":["7"],"explanation":["분모가 9이면 1 = ⟨9/9⟩ — ⟨1/9⟩이 9개예요.","9개 중 2개를 떼면 9 − 2 = 7개가 남아요.","□ = 7 — 1 = ⟨2/9⟩ + ⟨7/9⟩."],"asset":null},{"stem":"1을 ⟨1/9⟩이 3개인 분수와 ⟨1/9⟩이 □개인 분수로 갈랐어요. □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["분모가 9이면 1 = ⟨9/9⟩ — ⟨1/9⟩이 9개예요.","9개 중 3개를 떼면 9 − 3 = 6개가 남아요.","□ = 6 — 1 = ⟨3/9⟩ + ⟨6/9⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L02_basic#4','math',4,2,'u1','L02','g4_2_math_u1_L02_basic','lesson_basic','M4-2-u1-C1',1,'mc','auto','⟨2 1/3⟩을 가분수로 나타내면 무엇인가요?',ARRAY['M4-2-u1-X03','M4-2-u1-X16']::text[],true,'{"seq":4,"concept":"M4-2-u1-C1","difficulty":1,"kind":"mc","stem":"⟨2 1/3⟩을 가분수로 나타내면 무엇인가요?","options":[{"t":"⟨7/3⟩","correct":true},{"t":"⟨3/3⟩","mis":"M4-2-u1-X03"},{"t":"⟨8/3⟩","mis":"M4-2-u1-X16"},{"t":"⟨6/3⟩","mis":"M4-2-u1-X16"}],"explanation":["자연수 2는 ⟨1/3⟩이 2 × 3 = 6개예요.","분수 부분 ⟨1/3⟩은 ⟨1/3⟩이 1개예요.","6 + 1 = 7 — ⟨2 1/3⟩ = ⟨7/3⟩."],"variant_rule":{"alt":[{"stem":"⟨2 3/6⟩을 가분수로 나타내면 무엇인가요?","options":[{"t":"⟨15/6⟩","correct":true},{"t":"⟨5/6⟩","mis":"M4-2-u1-X03"},{"t":"⟨16/6⟩","mis":"M4-2-u1-X16"},{"t":"⟨14/6⟩","mis":"M4-2-u1-X16"}],"explanation":["자연수 2는 ⟨1/6⟩이 2 × 6 = 12개예요.","분수 부분 ⟨3/6⟩은 ⟨1/6⟩이 3개예요.","12 + 3 = 15 — ⟨2 3/6⟩ = ⟨15/6⟩."],"asset":null},{"stem":"⟨3 2/4⟩를 가분수로 나타내면 무엇인가요?","options":[{"t":"⟨14/4⟩","correct":true},{"t":"⟨5/4⟩","mis":"M4-2-u1-X03"},{"t":"⟨15/4⟩","mis":"M4-2-u1-X16"},{"t":"⟨13/4⟩","mis":"M4-2-u1-X16"}],"explanation":["자연수 3은 ⟨1/4⟩이 3 × 4 = 12개예요.","분수 부분 ⟨2/4⟩는 ⟨1/4⟩이 2개예요.","12 + 2 = 14 — ⟨3 2/4⟩ = ⟨14/4⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L02_basic#5','math',4,2,'u1','L02','g4_2_math_u1_L02_basic','lesson_basic','M4-2-u1-C1',2,'mc','auto','⟨11/4⟩을 대분수로 나타내면 무엇인가요?',ARRAY['M4-2-u1-X04','M4-2-u1-X16']::text[],true,'{"seq":5,"concept":"M4-2-u1-C1","difficulty":2,"kind":"mc","stem":"⟨11/4⟩을 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨2 3/4⟩","correct":true},{"t":"⟨3 3/4⟩","mis":"M4-2-u1-X04"},{"t":"⟨1 3/4⟩","mis":"M4-2-u1-X04"},{"t":"⟨2 2/4⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨11/4⟩은 ⟨1/4⟩이 11개예요.","⟨1/4⟩이 4개 모이면 1 — 4개씩 모으면 1이 2번, 3개가 남아요.","⟨11/4⟩ = ⟨2 3/4⟩."],"variant_rule":{"alt":[{"stem":"⟨10/4⟩을 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨2 2/4⟩","correct":true},{"t":"⟨3 2/4⟩","mis":"M4-2-u1-X04"},{"t":"⟨1 2/4⟩","mis":"M4-2-u1-X04"},{"t":"⟨2 3/4⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨10/4⟩은 ⟨1/4⟩이 10개예요.","⟨1/4⟩이 4개 모이면 1 — 4개씩 모으면 1이 2번, 2개가 남아요.","⟨10/4⟩ = ⟨2 2/4⟩."],"asset":null},{"stem":"⟨17/8⟩을 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨2 1/8⟩","correct":true},{"t":"⟨3 1/8⟩","mis":"M4-2-u1-X04"},{"t":"⟨1 1/8⟩","mis":"M4-2-u1-X04"},{"t":"⟨2 2/8⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨17/8⟩은 ⟨1/8⟩이 17개예요.","⟨1/8⟩이 8개 모이면 1 — 8개씩 모으면 1이 2번, 1개가 남아요.","⟨17/8⟩ = ⟨2 1/8⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L02_basic#6','math',4,2,'u1','L02','g4_2_math_u1_L02_basic','lesson_basic','M4-2-u1-C2',2,'mc','auto','⟨4/9⟩와 모아서 1이 되는 분수는 무엇인가요?',ARRAY['M4-2-u1-X06','M4-2-u1-X16']::text[],true,'{"seq":6,"concept":"M4-2-u1-C2","difficulty":2,"kind":"mc","stem":"⟨4/9⟩와 모아서 1이 되는 분수는 무엇인가요?","options":[{"t":"⟨5/9⟩","correct":true},{"t":"⟨4/9⟩","mis":"M4-2-u1-X06"},{"t":"⟨9/4⟩","mis":"M4-2-u1-X06"},{"t":"⟨6/9⟩","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨9/9⟩ — ⟨1/9⟩이 9개예요.","⟨4/9⟩는 ⟨1/9⟩이 4개 — 5개가 모자라요.","⟨4/9⟩와 ⟨5/9⟩를 모으면 1이에요."],"variant_rule":{"alt":[{"stem":"⟨4/7⟩와 모아서 1이 되는 분수는 무엇인가요?","options":[{"t":"⟨3/7⟩","correct":true},{"t":"⟨4/7⟩","mis":"M4-2-u1-X06"},{"t":"⟨7/4⟩","mis":"M4-2-u1-X06"},{"t":"⟨2/7⟩","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨7/7⟩ — ⟨1/7⟩이 7개예요.","⟨4/7⟩는 ⟨1/7⟩이 4개 — 3개가 모자라요.","⟨4/7⟩와 ⟨3/7⟩을 모으면 1이에요."],"asset":null},{"stem":"⟨5/11⟩와 모아서 1이 되는 분수는 무엇인가요?","options":[{"t":"⟨6/11⟩","correct":true},{"t":"⟨5/11⟩","mis":"M4-2-u1-X06"},{"t":"⟨11/5⟩","mis":"M4-2-u1-X06"},{"t":"⟨7/11⟩","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨11/11⟩ — ⟨1/11⟩이 11개예요.","⟨5/11⟩는 ⟨1/11⟩이 5개 — 6개가 모자라요.","⟨5/11⟩와 ⟨6/11⟩을 모으면 1이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L02_basic#7','math',4,2,'u1','L02','g4_2_math_u1_L02_basic','lesson_basic','M4-2-u1-C1',2,'mc','auto','다음 중 대분수는 무엇인가요?',ARRAY['M4-2-u1-X02']::text[],true,'{"seq":7,"concept":"M4-2-u1-C1","difficulty":2,"kind":"mc","stem":"다음 중 대분수는 무엇인가요?","options":[{"t":"⟨3 5/7⟩","correct":true},{"t":"⟨14/7⟩","mis":"M4-2-u1-X02"},{"t":"⟨5/7⟩","mis":"M4-2-u1-X02"},{"t":"⟨1/7⟩","mis":"M4-2-u1-X02"}],"explanation":["대분수는 자연수와 진분수로 이루어진 분수예요.","⟨3 5/7⟩ — 자연수와 진분수로 이루어진 분수.","나머지는 대분수가 아니에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 다음 중 대분수는 무엇인가요?","options":[{"t":"⟨3 3/5⟩","correct":true},{"t":"⟨11/5⟩","mis":"M4-2-u1-X02"},{"t":"⟨2/5⟩","mis":"M4-2-u1-X02"},{"t":"⟨5/5⟩","mis":"M4-2-u1-X02"}],"explanation":["대분수는 자연수와 진분수로 이루어진 분수예요.","⟨3 3/5⟩ — 자연수와 진분수로 이루어진 분수.","나머지는 대분수가 아니에요."],"asset":null},{"stem":"이번에는 다른 문제예요. 다음 중 대분수는 무엇인가요?","options":[{"t":"⟨3 4/7⟩","correct":true},{"t":"⟨4/7⟩","mis":"M4-2-u1-X02"},{"t":"⟨2/7⟩","mis":"M4-2-u1-X02"},{"t":"⟨9/7⟩","mis":"M4-2-u1-X02"}],"explanation":["대분수는 자연수와 진분수로 이루어진 분수예요.","⟨3 4/7⟩ — 자연수와 진분수로 이루어진 분수.","나머지는 대분수가 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L02_basic#8','math',4,2,'u1','L02','g4_2_math_u1_L02_basic','lesson_basic','M4-2-u1-C2',2,'mc','auto','피자 한 판을 똑같이 8조각으로 나누어 펭이가 3조각을 먹었어요. 남은 피자는 한 판의 얼마인가요?',ARRAY['M4-2-u1-X15','M4-2-u1-X06','M4-2-u1-X16']::text[],true,'{"seq":8,"concept":"M4-2-u1-C2","difficulty":2,"kind":"mc","stem":"피자 한 판을 똑같이 8조각으로 나누어 펭이가 3조각을 먹었어요. 남은 피자는 한 판의 얼마인가요?","options":[{"t":"⟨5/8⟩","correct":true},{"t":"⟨3/8⟩","mis":"M4-2-u1-X15"},{"t":"⟨5/3⟩","mis":"M4-2-u1-X06"},{"t":"⟨6/8⟩","mis":"M4-2-u1-X16"}],"explanation":["한 판 = 1 = ⟨8/8⟩이에요.","먹은 피자는 ⟨3/8⟩ — 8조각 중 3조각.","남은 피자는 1 − ⟨3/8⟩ = ⟨5/8⟩예요."],"asset":{"type":"fbar","bars":[{"den":8,"num":3,"label":"먹은 조각 ⟨3/8⟩"}]},"variant_rule":{"alt":[{"stem":"피자 한 판을 똑같이 5조각으로 나누어 곰이가 1조각을 먹었어요. 남은 피자는 한 판의 얼마인가요?","options":[{"t":"⟨4/5⟩","correct":true},{"t":"⟨1/5⟩","mis":"M4-2-u1-X15"},{"t":"⟨5/5⟩","mis":"M4-2-u1-X16"},{"t":"⟨3/5⟩","mis":"M4-2-u1-X16"}],"explanation":["한 판 = 1 = ⟨5/5⟩예요.","먹은 피자는 ⟨1/5⟩ — 5조각 중 1조각.","남은 피자는 1 − ⟨1/5⟩ = ⟨4/5⟩예요."],"asset":{"type":"fbar","bars":[{"den":5,"num":1,"label":"먹은 조각 ⟨1/5⟩"}]}},{"stem":"피자 한 판을 똑같이 9조각으로 나누어 펭이가 1조각을 먹었어요. 남은 피자는 한 판의 얼마인가요?","options":[{"t":"⟨8/9⟩","correct":true},{"t":"⟨1/9⟩","mis":"M4-2-u1-X15"},{"t":"⟨9/9⟩","mis":"M4-2-u1-X16"},{"t":"⟨7/9⟩","mis":"M4-2-u1-X16"}],"explanation":["한 판 = 1 = ⟨9/9⟩예요.","먹은 피자는 ⟨1/9⟩ — 9조각 중 1조각.","남은 피자는 1 − ⟨1/9⟩ = ⟨8/9⟩이에요."],"asset":{"type":"fbar","bars":[{"den":9,"num":1,"label":"먹은 조각 ⟨1/9⟩"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L02_basic#9','math',4,2,'u1','L02','g4_2_math_u1_L02_basic','lesson_basic','M4-2-u1-C2',2,'ox','auto','서윤이 「1을 분모가 7인 분수로 나타내면 ⟨1/7⟩이야.」라고 했어요. 바르게 말했어요.',ARRAY['M4-2-u1-X05']::text[],true,'{"seq":9,"concept":"M4-2-u1-C2","difficulty":2,"kind":"ox","stem":"서윤이 「1을 분모가 7인 분수로 나타내면 ⟨1/7⟩이야.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"1은 ⟨1/7⟩이 7개인 ⟨7/7⟩라서","correct":true},{"t":"1은 분자가 1인 분수라서","mis":"M4-2-u1-X05"}],"mis":"M4-2-u1-X05","explanation":["⟨1/7⟩은 1을 7칸으로 나눈 한 칸이에요.","1은 7칸 모두 — ⟨7/7⟩.","서윤의 말은 틀렸어요 ×."],"variant_rule":{"alt":[{"stem":"채원이 「⟨5/9⟩와 모아서 1이 되는 분수는 ⟨9/5⟩야.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"1이 되려면 ⟨1/9⟩이 4개 더 있어야 해서","correct":true},{"t":"분모와 분자를 바꾸면 1이 되어서","mis":"M4-2-u1-X06"}],"explanation":["1 = ⟨9/9⟩.","⟨5/9⟩에 ⟨1/9⟩이 4개 더 있어야 해요.","⟨4/9⟩ — ⟨9/5⟩는 틀렸어요 ×."],"asset":null},{"stem":"준우가 「1을 분모가 4인 분수로 나타내면 ⟨1/4⟩이야.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"1은 ⟨1/4⟩이 4개인 ⟨4/4⟩라서","correct":true},{"t":"1은 분자가 1인 분수라서","mis":"M4-2-u1-X05"}],"explanation":["⟨1/4⟩은 1을 4칸으로 나눈 한 칸이에요.","1은 4칸 모두 — ⟨4/4⟩.","준우의 말은 틀렸어요 ×."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L02_basic#10','math',4,2,'u1','L02','g4_2_math_u1_L02_basic','lesson_basic','M4-2-u1-C1',3,'sa','auto','⟨3 2/5⟩는 ⟨1/5⟩이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-2-u1-C1","difficulty":3,"kind":"sa","stem":"⟨3 2/5⟩는 ⟨1/5⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["1은 ⟨1/5⟩이 5개 — 자연수 3은 3 × 5 = 15개예요.","⟨2/5⟩는 ⟨1/5⟩이 2개예요.","모두 15 + 2 = 17개 — ⟨3 2/5⟩ = ⟨17/5⟩."],"variant_rule":{"alt":[{"stem":"⟨1 1/8⟩은 ⟨1/8⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["1은 ⟨1/8⟩이 8개 — 자연수 1은 1 × 8 = 8개예요.","⟨1/8⟩은 ⟨1/8⟩이 1개예요.","모두 8 + 1 = 9개 — ⟨1 1/8⟩ = ⟨9/8⟩."],"asset":null},{"stem":"⟨1 8/9⟩은 ⟨1/9⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["1은 ⟨1/9⟩이 9개 — 자연수 1은 1 × 9 = 9개예요.","⟨8/9⟩은 ⟨1/9⟩이 8개예요.","모두 9 + 8 = 17개 — ⟨1 8/9⟩ = ⟨17/9⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L02_challenge#1','math',4,2,'u1','L02','g4_2_math_u1_L02_challenge','lesson_challenge','M4-2-u1-C1',2,'mc','auto','⟨19/6⟩를 대분수로 나타내면 무엇인가요?',ARRAY['M4-2-u1-X04','M4-2-u1-X16']::text[],true,'{"seq":1,"concept":"M4-2-u1-C1","difficulty":2,"kind":"mc","stem":"⟨19/6⟩를 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨3 1/6⟩","correct":true},{"t":"⟨4 1/6⟩","mis":"M4-2-u1-X04"},{"t":"⟨2 1/6⟩","mis":"M4-2-u1-X04"},{"t":"⟨3 2/6⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨19/6⟩는 ⟨1/6⟩이 19개예요.","⟨1/6⟩이 6개 모이면 1 — 6개씩 모으면 1이 3번, 1개가 남아요.","⟨19/6⟩ = ⟨3 1/6⟩."],"variant_rule":{"alt":[{"stem":"⟨32/9⟩를 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨3 5/9⟩","correct":true},{"t":"⟨4 5/9⟩","mis":"M4-2-u1-X04"},{"t":"⟨2 5/9⟩","mis":"M4-2-u1-X04"},{"t":"⟨3 6/9⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨32/9⟩는 ⟨1/9⟩이 32개예요.","⟨1/9⟩이 9개 모이면 1 — 9개씩 모으면 1이 3번, 5개가 남아요.","⟨32/9⟩ = ⟨3 5/9⟩."],"asset":null},{"stem":"⟨9/6⟩를 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨1 3/6⟩","correct":true},{"t":"⟨2 3/6⟩","mis":"M4-2-u1-X04"},{"t":"⟨1 4/6⟩","mis":"M4-2-u1-X16"},{"t":"⟨1 2/6⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨9/6⟩는 ⟨1/6⟩이 9개예요.","⟨1/6⟩이 6개 모이면 1 — 6개씩 모으면 1이 1번, 3개가 남아요.","⟨9/6⟩ = ⟨1 3/6⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L02_challenge#2','math',4,2,'u1','L02','g4_2_math_u1_L02_challenge','lesson_challenge','M4-2-u1-C2',2,'mc','auto','⟨9/14⟩와 모아서 1이 되는 분수는 무엇인가요?',ARRAY['M4-2-u1-X06','M4-2-u1-X16']::text[],true,'{"seq":2,"concept":"M4-2-u1-C2","difficulty":2,"kind":"mc","stem":"⟨9/14⟩와 모아서 1이 되는 분수는 무엇인가요?","options":[{"t":"⟨5/14⟩","correct":true},{"t":"⟨9/14⟩","mis":"M4-2-u1-X06"},{"t":"⟨14/9⟩","mis":"M4-2-u1-X06"},{"t":"⟨6/14⟩","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨14/14⟩ — ⟨1/14⟩이 14개예요.","⟨9/14⟩는 ⟨1/14⟩이 9개 — 5개가 모자라요.","⟨9/14⟩와 ⟨5/14⟩를 모으면 1이에요."],"variant_rule":{"alt":[{"stem":"⟨2/9⟩와 모아서 1이 되는 분수는 무엇인가요?","options":[{"t":"⟨7/9⟩","correct":true},{"t":"⟨2/9⟩","mis":"M4-2-u1-X06"},{"t":"⟨9/2⟩","mis":"M4-2-u1-X06"},{"t":"⟨8/9⟩","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨9/9⟩ — ⟨1/9⟩이 9개예요.","⟨2/9⟩는 ⟨1/9⟩이 2개 — 7개가 모자라요.","⟨2/9⟩와 ⟨7/9⟩을 모으면 1이에요."],"asset":null},{"stem":"⟨6/8⟩과 모아서 1이 되는 분수는 무엇인가요?","options":[{"t":"⟨2/8⟩","correct":true},{"t":"⟨6/8⟩","mis":"M4-2-u1-X06"},{"t":"⟨8/6⟩","mis":"M4-2-u1-X06"},{"t":"⟨3/8⟩","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨8/8⟩ — ⟨1/8⟩이 8개예요.","⟨6/8⟩은 ⟨1/8⟩이 6개 — 2개가 모자라요.","⟨6/8⟩과 ⟨2/8⟩를 모으면 1이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L02_challenge#3','math',4,2,'u1','L02','g4_2_math_u1_L02_challenge','lesson_challenge','M4-2-u1-C1',3,'sa','auto','⟨5 8/9⟩은 ⟨1/9⟩이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u1-C1","difficulty":3,"kind":"sa","stem":"⟨5 8/9⟩은 ⟨1/9⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["53"],"explanation":["1은 ⟨1/9⟩이 9개 — 자연수 5는 5 × 9 = 45개예요.","⟨8/9⟩은 ⟨1/9⟩이 8개예요.","모두 45 + 8 = 53개 — ⟨5 8/9⟩ = ⟨53/9⟩."],"variant_rule":{"alt":[{"stem":"⟨5 5/8⟩는 ⟨1/8⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["1은 ⟨1/8⟩이 8개 — 자연수 5는 5 × 8 = 40개예요.","⟨5/8⟩는 ⟨1/8⟩이 5개예요.","모두 40 + 5 = 45개 — ⟨5 5/8⟩ = ⟨45/8⟩."],"asset":null},{"stem":"⟨5 1/7⟩은 ⟨1/7⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["1은 ⟨1/7⟩이 7개 — 자연수 5는 5 × 7 = 35개예요.","⟨1/7⟩은 ⟨1/7⟩이 1개예요.","모두 35 + 1 = 36개 — ⟨5 1/7⟩ = ⟨36/7⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L02_challenge#4','math',4,2,'u1','L02','g4_2_math_u1_L02_challenge','lesson_challenge','M4-2-u1-C1',3,'error','auto','분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u1-X06','M4-2-u1-X15']::text[],true,'{"seq":4,"concept":"M4-2-u1-C1","difficulty":3,"kind":"error","stem":"분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은비 — 「⟨1/7⟩과 모아서 1이 되는 분수는 ⟨1/7⟩」","correct":true,"mis_target":"M4-2-u1-X06"},{"t":"하윤 — 「⟨1 1/7⟩ = ⟨8/7⟩」","mis":"M4-2-u1-X15"},{"t":"서윤 — 「1 = ⟨7/7⟩」","mis":"M4-2-u1-X15"},{"t":"도연 — 「⟨1/7⟩과 ⟨6/7⟩을 모으면 1」","mis":"M4-2-u1-X15"}],"explanation":["⟨1 1/7⟩ = ⟨8/7⟩ — 자연수 1은 ⟨1/7⟩이 7개.","1 = ⟨7/7⟩, ⟨1/7⟩ + ⟨6/7⟩ = 1.","은비의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지훈 — 「⟨3 5/9⟩ = ⟨8/9⟩」","correct":true,"mis_target":"M4-2-u1-X03"},{"t":"서윤 — 「⟨3 5/9⟩ = ⟨32/9⟩」","mis":"M4-2-u1-X15"},{"t":"은비 — 「1 = ⟨9/9⟩」","mis":"M4-2-u1-X15"},{"t":"도연 — 「⟨5/9⟩와 ⟨4/9⟩를 모으면 1」","mis":"M4-2-u1-X15"}],"explanation":["⟨3 5/9⟩ = ⟨32/9⟩ — 자연수 3은 ⟨1/9⟩이 27개.","1 = ⟨9/9⟩, ⟨5/9⟩ + ⟨4/9⟩ = 1.","지훈의 말이 틀렸어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 분수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"채원 — 「⟨9/7⟩ = ⟨2 2/7⟩」","correct":true,"mis_target":"M4-2-u1-X04"},{"t":"서준 — 「⟨1 2/7⟩ = ⟨9/7⟩」","mis":"M4-2-u1-X15"},{"t":"건우 — 「1 = ⟨7/7⟩」","mis":"M4-2-u1-X15"},{"t":"하윤 — 「⟨2/7⟩와 ⟨5/7⟩를 모으면 1」","mis":"M4-2-u1-X15"}],"explanation":["⟨1 2/7⟩ = ⟨9/7⟩ — 자연수 1은 ⟨1/7⟩이 7개.","1 = ⟨7/7⟩, ⟨2/7⟩ + ⟨5/7⟩ = 1.","채원의 말이 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L02_challenge#5','math',4,2,'u1','L02','g4_2_math_u1_L02_challenge','lesson_challenge','M4-2-u1-C2',3,'sa','auto','1을 분모가 6인 진분수 두 개로 가르려고 해요. ⟨1/6⟩과 ⟨5/6⟩, ⟨5/6⟩와 ⟨1/6⟩처럼 순서만 바꾼 것은 한 가지로 셀 때, 가르는 방법은 모두 몇 가지인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u1-C2","difficulty":3,"kind":"sa","stem":"1을 분모가 6인 진분수 두 개로 가르려고 해요. ⟨1/6⟩과 ⟨5/6⟩, ⟨5/6⟩와 ⟨1/6⟩처럼 순서만 바꾼 것은 한 가지로 셀 때, 가르는 방법은 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["1 = ⟨6/6⟩ — 두 분자의 합이 6이 되게 가르면 돼요.","⟨1/6⟩과 ⟨5/6⟩, ⟨2/6⟩와 ⟨4/6⟩, ⟨3/6⟩과 ⟨3/6⟩.","모두 3가지예요."],"variant_rule":{"alt":[{"stem":"1을 분모가 10인 진분수 두 개로 가르려고 해요. ⟨1/10⟩과 ⟨9/10⟩, ⟨9/10⟩와 ⟨1/10⟩처럼 순서만 바꾼 것은 한 가지로 셀 때, 가르는 방법은 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["1 = ⟨10/10⟩ — 두 분자의 합이 10이 되게 가르면 돼요.","⟨1/10⟩과 ⟨9/10⟩, ⟨2/10⟩와 ⟨8/10⟩, ⟨3/10⟩과 ⟨7/10⟩, ⟨4/10⟩와 ⟨6/10⟩, ⟨5/10⟩와 ⟨5/10⟩.","모두 5가지예요."],"asset":null},{"stem":"1을 분모가 5인 진분수 두 개로 가르려고 해요. ⟨1/5⟩과 ⟨4/5⟩, ⟨4/5⟩와 ⟨1/5⟩처럼 순서만 바꾼 것은 한 가지로 셀 때, 가르는 방법은 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["1 = ⟨5/5⟩ — 두 분자의 합이 5가 되게 가르면 돼요.","⟨1/5⟩과 ⟨4/5⟩, ⟨2/5⟩와 ⟨3/5⟩.","모두 2가지예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L02_challenge#6','math',4,2,'u1','L02','g4_2_math_u1_L02_challenge','lesson_challenge','M4-2-u1-C2',3,'ox','auto','민서가 「1을 분모가 5인 분수로 나타내면 ⟨1/5⟩이야.」라고 했어요. 바르게 말했어요.',ARRAY['M4-2-u1-X05']::text[],true,'{"seq":6,"concept":"M4-2-u1-C2","difficulty":3,"kind":"ox","stem":"민서가 「1을 분모가 5인 분수로 나타내면 ⟨1/5⟩이야.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"1은 ⟨1/5⟩이 5개인 ⟨5/5⟩라서","correct":true},{"t":"1은 분자가 1인 분수라서","mis":"M4-2-u1-X05"}],"mis":"M4-2-u1-X05","explanation":["⟨1/5⟩은 1을 5칸으로 나눈 한 칸이에요.","1은 5칸 모두 — ⟨5/5⟩.","민서의 말은 틀렸어요 ×."],"variant_rule":{"alt":[{"stem":"도연이 「⟨3/9⟩과 ⟨6/9⟩을 모으면 1이 돼.」라고 했어요. 바르게 말했어요.","answer":"O","reason_options":[{"t":"⟨1/9⟩이 3 + 6 = 9개라서","correct":true},{"t":"분모 9와 9를 더하면 되어서","mis":"M4-2-u1-X01"}],"explanation":["⟨3/9⟩은 ⟨1/9⟩이 3개, ⟨6/9⟩은 6개.","모으면 ⟨1/9⟩이 9개 = ⟨9/9⟩.","⟨9/9⟩ = 1 — 바르게 말했어요 ○."],"asset":null},{"stem":"채원이 「⟨7/9⟩과 모아서 1이 되는 분수는 ⟨9/7⟩야.」라고 했어요. 바르게 말했어요.","answer":"X","reason_options":[{"t":"1이 되려면 ⟨1/9⟩이 2개 더 있어야 해서","correct":true},{"t":"분모와 분자를 바꾸면 1이 되어서","mis":"M4-2-u1-X06"}],"explanation":["1 = ⟨9/9⟩.","⟨7/9⟩에 ⟨1/9⟩이 2개 더 있어야 해요.","⟨2/9⟩ — ⟨9/7⟩는 틀렸어요 ×."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L02_challenge#7','math',4,2,'u1','L02','g4_2_math_u1_L02_challenge','lesson_challenge','M4-2-u1-C1',3,'mc','auto','다음 중 가분수는 무엇인가요?',ARRAY['M4-2-u1-X02']::text[],true,'{"seq":7,"concept":"M4-2-u1-C1","difficulty":3,"kind":"mc","stem":"다음 중 가분수는 무엇인가요?","options":[{"t":"⟨16/6⟩","correct":true},{"t":"⟨2 1/6⟩","mis":"M4-2-u1-X02"},{"t":"⟨3 5/6⟩","mis":"M4-2-u1-X02"},{"t":"⟨5/6⟩","mis":"M4-2-u1-X02"}],"explanation":["가분수는 분자가 분모와 같거나 큰 분수예요.","⟨16/6⟩ — 분자가 분모와 같거나 큰 분수.","나머지는 가분수가 아니에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 다음 중 가분수는 무엇인가요?","options":[{"t":"⟨12/7⟩","correct":true},{"t":"⟨1/7⟩","mis":"M4-2-u1-X02"},{"t":"⟨3 6/7⟩","mis":"M4-2-u1-X02"},{"t":"⟨4 1/7⟩","mis":"M4-2-u1-X02"}],"explanation":["가분수는 분자가 분모와 같거나 큰 분수예요.","⟨12/7⟩ — 분자가 분모와 같거나 큰 분수.","나머지는 가분수가 아니에요."],"asset":null},{"stem":"이번에는 다른 문제예요. 다음 중 가분수는 무엇인가요?","options":[{"t":"⟨13/5⟩","correct":true},{"t":"⟨2 2/5⟩","mis":"M4-2-u1-X02"},{"t":"⟨1/5⟩","mis":"M4-2-u1-X02"},{"t":"⟨1 1/5⟩","mis":"M4-2-u1-X02"}],"explanation":["가분수는 분자가 분모와 같거나 큰 분수예요.","⟨13/5⟩ — 분자가 분모와 같거나 큰 분수.","나머지는 가분수가 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L02_challenge#8','math',4,2,'u1','L02','g4_2_math_u1_L02_challenge','lesson_challenge','M4-2-u1-C1',4,'essay','teacher','곰이는 사과를 ⟨2 1/4⟩ kg, 펭이는 ⟨9/4⟩ kg 땄어요. 펭이는 「내 분수가 더 크니까 내가 더 많이 땄어.」라고 했어요. 두 사람이 딴 양을 단위분수 ⟨1/4⟩의 개수로 견주어 펭이의 말이 맞는지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u1-C1","difficulty":4,"kind":"essay","stem":"곰이는 사과를 ⟨2 1/4⟩ kg, 펭이는 ⟨9/4⟩ kg 땄어요. 펭이는 「내 분수가 더 크니까 내가 더 많이 땄어.」라고 했어요. 두 사람이 딴 양을 단위분수 ⟨1/4⟩의 개수로 견주어 펭이의 말이 맞는지 설명해 보세요.","answer_guide":{"answer":"예: ⟨2 1/4⟩은 2가 ⟨1/4⟩ 8개, ⟨1/4⟩이 1개라서 ⟨1/4⟩이 9개이다. ⟨9/4⟩도 ⟨1/4⟩이 9개이다. 두 양은 같으므로 펭이의 말은 틀렸다. 대분수와 가분수는 같은 양을 다르게 적은 것이다.","scoring_points":["⟨2 1/4⟩이 ⟨1/4⟩ 9개라고 썼는가","⟨9/4⟩도 9개라고 썼는가","두 양이 같아 펭이의 말이 틀렸다고 판단했는가"]},"explanation":["⟨2 1/4⟩ = ⟨9/4⟩.","둘 다 ⟨1/4⟩이 9개.","같은 양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L02_challenge#9','math',4,2,'u1','L02','g4_2_math_u1_L02_challenge','lesson_challenge','M4-2-u1-C2',4,'essay','teacher','1을 분모가 6인 진분수 두 개로 가르는 방법을 모두 쓰고, 왜 두 분수의 분자의 합이 언제나 6이 되는지 설명해 보세요(순서만 바꾼 것은 한 가지로).','{}'::text[],false,'{"seq":9,"concept":"M4-2-u1-C2","difficulty":4,"kind":"essay","stem":"1을 분모가 6인 진분수 두 개로 가르는 방법을 모두 쓰고, 왜 두 분수의 분자의 합이 언제나 6이 되는지 설명해 보세요(순서만 바꾼 것은 한 가지로).","answer_guide":{"answer":"예: ⟨1/6⟩과 ⟨5/6⟩, ⟨2/6⟩와 ⟨4/6⟩, ⟨3/6⟩과 ⟨3/6⟩ — 3가지이다. 1 = ⟨6/6⟩이고 ⟨1/6⟩이 6개이므로 두 분수의 ⟨1/6⟩ 개수를 합하면 6이 되어야 한다.","scoring_points":["세 가지를 모두 썼는가","1 = ⟨6/6⟩이라고 썼는가","⟨1/6⟩의 개수 합이 6이라고 설명했는가"]},"explanation":["1 = ⟨6/6⟩.","1+5, 2+4, 3+3.","3가지."],"asset":{"type":"fbar","bars":[{"den":6,"num":6}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L02_challenge#10','math',4,2,'u1','L02','g4_2_math_u1_L02_challenge','lesson_challenge','M4-2-u1-C2',4,'sa','auto','1을 분모가 8인 진분수 두 개로 가르려고 해요. ⟨1/8⟩과 ⟨7/8⟩, ⟨7/8⟩과 ⟨1/8⟩처럼 순서만 바꾼 것은 한 가지로 셀 때, 가르는 방법은 모두 몇 가지인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-2-u1-C2","difficulty":4,"kind":"sa","stem":"1을 분모가 8인 진분수 두 개로 가르려고 해요. ⟨1/8⟩과 ⟨7/8⟩, ⟨7/8⟩과 ⟨1/8⟩처럼 순서만 바꾼 것은 한 가지로 셀 때, 가르는 방법은 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["1 = ⟨8/8⟩ — 두 분자의 합이 8이 되게 가르면 돼요.","⟨1/8⟩과 ⟨7/8⟩, ⟨2/8⟩와 ⟨6/8⟩, ⟨3/8⟩과 ⟨5/8⟩, ⟨4/8⟩와 ⟨4/8⟩.","모두 4가지예요."],"variant_rule":{"alt":[{"stem":"1을 분모가 10인 진분수 두 개로 가르려고 해요. ⟨1/10⟩과 ⟨9/10⟩, ⟨9/10⟩와 ⟨1/10⟩처럼 순서만 바꾼 것은 한 가지로 셀 때, 가르는 방법은 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["1 = ⟨10/10⟩ — 두 분자의 합이 10이 되게 가르면 돼요.","⟨1/10⟩과 ⟨9/10⟩, ⟨2/10⟩와 ⟨8/10⟩, ⟨3/10⟩과 ⟨7/10⟩, ⟨4/10⟩와 ⟨6/10⟩, ⟨5/10⟩와 ⟨5/10⟩.","모두 5가지예요."],"asset":null},{"stem":"1을 분모가 14인 진분수 두 개로 가르려고 해요. ⟨1/14⟩과 ⟨13/14⟩, ⟨13/14⟩과 ⟨1/14⟩처럼 순서만 바꾼 것은 한 가지로 셀 때, 가르는 방법은 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["1 = ⟨14/14⟩ — 두 분자의 합이 14가 되게 가르면 돼요.","⟨1/14⟩과 ⟨13/14⟩, ⟨2/14⟩와 ⟨12/14⟩, ⟨3/14⟩과 ⟨11/14⟩, ⟨4/14⟩와 ⟨10/14⟩, ⟨5/14⟩와 ⟨9/14⟩, ⟨6/14⟩과 ⟨8/14⟩, ⟨7/14⟩과 ⟨7/14⟩.","모두 7가지예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L03_basic#1','math',4,2,'u1','L03','g4_2_math_u1_L03_basic','lesson_basic','M4-2-u1-C3',1,'sa','auto','⟨1/5⟩ + ⟨3/5⟩ = ⟨□/5⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-2-u1-C3","difficulty":1,"kind":"sa","stem":"⟨1/5⟩ + ⟨3/5⟩ = ⟨□/5⟩ — □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["분모가 5로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/5⟩이 1 + 3 = 4개.","⟨1/5⟩ + ⟨3/5⟩ = ⟨4/5⟩.","분모끼리 더해 ⟨4/10⟩로 쓰지 않아요."],"variant_rule":{"alt":[{"stem":"⟨4/7⟩ + ⟨2/7⟩ = ⟨□/7⟩ — □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["분모가 7로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/7⟩이 4 + 2 = 6개.","⟨4/7⟩ + ⟨2/7⟩ = ⟨6/7⟩.","분모끼리 더해 ⟨6/14⟩으로 쓰지 않아요."],"asset":null},{"stem":"⟨1/6⟩ + ⟨4/6⟩ = ⟨□/6⟩ — □에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["분모가 6으로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/6⟩이 1 + 4 = 5개.","⟨1/6⟩ + ⟨4/6⟩ = ⟨5/6⟩.","분모끼리 더해 ⟨5/12⟩로 쓰지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L03_basic#2','math',4,2,'u1','L03','g4_2_math_u1_L03_basic','lesson_basic','M4-2-u1-C3',1,'mc','auto','⟨2/7⟩ + ⟨3/7⟩을 계산하면 얼마인가요?',ARRAY['M4-2-u1-X01','M4-2-u1-X16']::text[],true,'{"seq":2,"concept":"M4-2-u1-C3","difficulty":1,"kind":"mc","stem":"⟨2/7⟩ + ⟨3/7⟩을 계산하면 얼마인가요?","options":[{"t":"⟨5/7⟩","correct":true},{"t":"⟨5/14⟩","mis":"M4-2-u1-X01"},{"t":"⟨6/7⟩","mis":"M4-2-u1-X16"},{"t":"⟨4/7⟩","mis":"M4-2-u1-X16"}],"explanation":["분모가 7로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/7⟩이 2 + 3 = 5개.","⟨2/7⟩ + ⟨3/7⟩ = ⟨5/7⟩.","분모끼리 더해 ⟨5/14⟩로 쓰지 않아요."],"asset":{"type":"fbar","bars":[{"den":7,"num":2},{"den":7,"num":3}]},"variant_rule":{"alt":[{"stem":"⟨2/6⟩ + ⟨1/6⟩을 계산하면 얼마인가요?","options":[{"t":"⟨3/6⟩","correct":true},{"t":"⟨3/12⟩","mis":"M4-2-u1-X01"},{"t":"⟨4/6⟩","mis":"M4-2-u1-X16"},{"t":"⟨2/6⟩","mis":"M4-2-u1-X16"}],"explanation":["분모가 6으로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/6⟩이 2 + 1 = 3개.","⟨2/6⟩ + ⟨1/6⟩ = ⟨3/6⟩.","분모끼리 더해 ⟨3/12⟩으로 쓰지 않아요."],"asset":{"type":"fbar","bars":[{"den":6,"num":2},{"den":6,"num":1}]}},{"stem":"⟨1/6⟩ + ⟨1/6⟩을 계산하면 얼마인가요?","options":[{"t":"⟨2/6⟩","correct":true},{"t":"⟨2/12⟩","mis":"M4-2-u1-X01"},{"t":"⟨3/6⟩","mis":"M4-2-u1-X16"},{"t":"⟨1/6⟩","mis":"M4-2-u1-X16"}],"explanation":["분모가 6으로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/6⟩이 1 + 1 = 2개.","⟨1/6⟩ + ⟨1/6⟩ = ⟨2/6⟩.","분모끼리 더해 ⟨2/12⟩로 쓰지 않아요."],"asset":{"type":"fbar","bars":[{"den":6,"num":1},{"den":6,"num":1}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L03_basic#3','math',4,2,'u1','L03','g4_2_math_u1_L03_basic','lesson_basic','M4-2-u1-C3',1,'sa','auto','⟨1/12⟩ + ⟨9/12⟩ = ⟨□/12⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u1-C3","difficulty":1,"kind":"sa","stem":"⟨1/12⟩ + ⟨9/12⟩ = ⟨□/12⟩ — □에 알맞은 수를 쓰세요.","answer":["10"],"explanation":["분모가 12로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/12⟩이 1 + 9 = 10개.","⟨1/12⟩ + ⟨9/12⟩ = ⟨10/12⟩.","분모끼리 더해 ⟨10/24⟩으로 쓰지 않아요."],"variant_rule":{"alt":[{"stem":"⟨6/11⟩ + ⟨2/11⟩ = ⟨□/11⟩ — □에 알맞은 수를 쓰세요.","answer":["8"],"explanation":["분모가 11로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/11⟩이 6 + 2 = 8개.","⟨6/11⟩ + ⟨2/11⟩ = ⟨8/11⟩.","분모끼리 더해 ⟨8/22⟩로 쓰지 않아요."],"asset":null},{"stem":"⟨4/11⟩ + ⟨5/11⟩ = ⟨□/11⟩ — □에 알맞은 수를 쓰세요.","answer":["9"],"explanation":["분모가 11로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/11⟩이 4 + 5 = 9개.","⟨4/11⟩ + ⟨5/11⟩ = ⟨9/11⟩.","분모끼리 더해 ⟨9/22⟩로 쓰지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L03_basic#4','math',4,2,'u1','L03','g4_2_math_u1_L03_basic','lesson_basic','M4-2-u1-C3',1,'mc','auto','⟨4/6⟩ + ⟨5/6⟩를 계산하여 대분수로 나타내면 얼마인가요?',ARRAY['M4-2-u1-X01','M4-2-u1-X16']::text[],true,'{"seq":4,"concept":"M4-2-u1-C3","difficulty":1,"kind":"mc","stem":"⟨4/6⟩ + ⟨5/6⟩를 계산하여 대분수로 나타내면 얼마인가요?","options":[{"t":"⟨1 3/6⟩","correct":true},{"t":"⟨9/12⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 4/6⟩","mis":"M4-2-u1-X16"},{"t":"⟨1 2/6⟩","mis":"M4-2-u1-X16"}],"explanation":["분모가 6으로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/6⟩이 4 + 5 = 9개.","⟨4/6⟩ + ⟨5/6⟩ = ⟨9/6⟩.","⟨9/6⟩는 1보다 커요 — ⟨9/6⟩ = ⟨1 3/6⟩."],"variant_rule":{"alt":[{"stem":"⟨3/7⟩ + ⟨6/7⟩을 계산하여 대분수로 나타내면 얼마인가요?","options":[{"t":"⟨1 2/7⟩","correct":true},{"t":"⟨9/14⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 3/7⟩","mis":"M4-2-u1-X16"},{"t":"⟨1 1/7⟩","mis":"M4-2-u1-X16"}],"explanation":["분모가 7로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/7⟩이 3 + 6 = 9개.","⟨3/7⟩ + ⟨6/7⟩ = ⟨9/7⟩.","⟨9/7⟩는 1보다 커요 — ⟨9/7⟩ = ⟨1 2/7⟩."],"asset":null},{"stem":"⟨8/9⟩ + ⟨3/9⟩을 계산하여 대분수로 나타내면 얼마인가요?","options":[{"t":"⟨1 2/9⟩","correct":true},{"t":"⟨11/18⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 3/9⟩","mis":"M4-2-u1-X16"},{"t":"⟨1 1/9⟩","mis":"M4-2-u1-X16"}],"explanation":["분모가 9로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/9⟩이 8 + 3 = 11개.","⟨8/9⟩ + ⟨3/9⟩ = ⟨11/9⟩.","⟨11/9⟩은 1보다 커요 — ⟨11/9⟩ = ⟨1 2/9⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L03_basic#5','math',4,2,'u1','L03','g4_2_math_u1_L03_basic','lesson_basic','M4-2-u1-C3',2,'mc','auto','빨간 페인트 ⟨2/7⟩ L와 노란 페인트 ⟨4/7⟩ L를 섞었어요. 주황 페인트는 몇 L가 되었나요?',ARRAY['M4-2-u1-X01','M4-2-u1-X16']::text[],true,'{"seq":5,"concept":"M4-2-u1-C3","difficulty":2,"kind":"mc","stem":"빨간 페인트 ⟨2/7⟩ L와 노란 페인트 ⟨4/7⟩ L를 섞었어요. 주황 페인트는 몇 L가 되었나요?","options":[{"t":"⟨6/7⟩ L","correct":true},{"t":"⟨6/14⟩ L","mis":"M4-2-u1-X01"},{"t":"1 L","mis":"M4-2-u1-X16"},{"t":"⟨5/7⟩ L","mis":"M4-2-u1-X16"}],"explanation":["분모가 7로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/7⟩이 2 + 4 = 6개.","⟨2/7⟩ + ⟨4/7⟩ = ⟨6/7⟩.","분모끼리 더해 ⟨6/14⟩으로 쓰지 않아요."],"variant_rule":{"alt":[{"stem":"곰이는 사과를 ⟨1/8⟩ kg, 펭이는 ⟨4/8⟩ kg 땄어요. 두 사람이 딴 사과는 모두 몇 kg인가요?","options":[{"t":"⟨5/8⟩ kg","correct":true},{"t":"⟨5/16⟩ kg","mis":"M4-2-u1-X01"},{"t":"⟨6/8⟩ kg","mis":"M4-2-u1-X16"},{"t":"⟨4/8⟩ kg","mis":"M4-2-u1-X16"}],"explanation":["분모가 8로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/8⟩이 1 + 4 = 5개.","⟨1/8⟩ + ⟨4/8⟩ = ⟨5/8⟩.","분모끼리 더해 ⟨5/16⟩로 쓰지 않아요."],"asset":null},{"stem":"빨간 페인트 ⟨2/5⟩ L와 노란 페인트 ⟨2/5⟩ L를 섞었어요. 주황 페인트는 몇 L가 되었나요?","options":[{"t":"⟨4/5⟩ L","correct":true},{"t":"⟨4/10⟩ L","mis":"M4-2-u1-X01"},{"t":"1 L","mis":"M4-2-u1-X16"},{"t":"⟨3/5⟩ L","mis":"M4-2-u1-X16"}],"explanation":["분모가 5로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/5⟩이 2 + 2 = 4개.","⟨2/5⟩ + ⟨2/5⟩ = ⟨4/5⟩.","분모끼리 더해 ⟨4/10⟩로 쓰지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L03_basic#6','math',4,2,'u1','L03','g4_2_math_u1_L03_basic','lesson_basic','M4-2-u1-C3',2,'ox','auto','준우가 「⟨1/5⟩ + ⟨3/5⟩ = ⟨4/10⟩야.」라고 했어요. 바르게 계산했어요.',ARRAY['M4-2-u1-X01']::text[],true,'{"seq":6,"concept":"M4-2-u1-C3","difficulty":2,"kind":"ox","stem":"준우가 「⟨1/5⟩ + ⟨3/5⟩ = ⟨4/10⟩야.」라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"분모는 그대로 두고 분자끼리만 더해야 해서","correct":true},{"t":"분모끼리 더해도 되어서","mis":"M4-2-u1-X01"}],"mis":"M4-2-u1-X01","explanation":["분모가 같으면 단위분수 ⟨1/5⟩의 개수만 더해요.","⟨1/5⟩ + ⟨3/5⟩ = ⟨4/5⟩.","준우는 분모끼리도 더했어요 — ×."],"variant_rule":{"alt":[{"stem":"서준이 「⟨4/7⟩ + ⟨5/7⟩ = ⟨1 2/7⟩야.」라고 했어요. 바르게 계산했어요.","answer":"O","reason_options":[{"t":"⟨1/7⟩이 9개라서","correct":true},{"t":"분모끼리도 더해야 해서","mis":"M4-2-u1-X01"}],"explanation":["분모가 7로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/7⟩이 4 + 5 = 9개.","⟨4/7⟩ + ⟨5/7⟩ = ⟨9/7⟩.","⟨9/7⟩는 1보다 커요 — ⟨9/7⟩ = ⟨1 2/7⟩."],"asset":null},{"stem":"채원이 「⟨2/5⟩ + ⟨4/5⟩ = ⟨6/10⟩이야.」라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"분모는 그대로 두고 분자끼리만 더해야 해서","correct":true},{"t":"분모끼리 더해도 되어서","mis":"M4-2-u1-X01"}],"explanation":["분모가 같으면 단위분수 ⟨1/5⟩의 개수만 더해요.","⟨2/5⟩ + ⟨4/5⟩ = ⟨6/5⟩.","채원는 분모끼리도 더했어요 — ×."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L03_basic#7','math',4,2,'u1','L03','g4_2_math_u1_L03_basic','lesson_basic','M4-2-u1-C3',2,'mc','auto','⟨5/6⟩ + ⟨3/6⟩을 계산하여 대분수로 나타내면 얼마인가요?',ARRAY['M4-2-u1-X01','M4-2-u1-X16']::text[],true,'{"seq":7,"concept":"M4-2-u1-C3","difficulty":2,"kind":"mc","stem":"⟨5/6⟩ + ⟨3/6⟩을 계산하여 대분수로 나타내면 얼마인가요?","options":[{"t":"⟨1 2/6⟩","correct":true},{"t":"⟨8/12⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 3/6⟩","mis":"M4-2-u1-X16"},{"t":"⟨1 1/6⟩","mis":"M4-2-u1-X16"}],"explanation":["분모가 6으로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/6⟩이 5 + 3 = 8개.","⟨5/6⟩ + ⟨3/6⟩ = ⟨8/6⟩.","⟨8/6⟩은 1보다 커요 — ⟨8/6⟩ = ⟨1 2/6⟩."],"variant_rule":{"alt":[{"stem":"⟨10/12⟩ + ⟨9/12⟩를 계산하여 대분수로 나타내면 얼마인가요?","options":[{"t":"⟨1 7/12⟩","correct":true},{"t":"⟨19/24⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 8/12⟩","mis":"M4-2-u1-X16"},{"t":"⟨1 6/12⟩","mis":"M4-2-u1-X16"}],"explanation":["분모가 12로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/12⟩이 10 + 9 = 19개.","⟨10/12⟩ + ⟨9/12⟩ = ⟨19/12⟩.","⟨19/12⟩는 1보다 커요 — ⟨19/12⟩ = ⟨1 7/12⟩."],"asset":null},{"stem":"⟨8/10⟩ + ⟨4/10⟩를 계산하여 대분수로 나타내면 얼마인가요?","options":[{"t":"⟨1 2/10⟩","correct":true},{"t":"⟨12/20⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 3/10⟩","mis":"M4-2-u1-X16"},{"t":"⟨1 1/10⟩","mis":"M4-2-u1-X16"}],"explanation":["분모가 10으로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/10⟩이 8 + 4 = 12개.","⟨8/10⟩ + ⟨4/10⟩ = ⟨12/10⟩.","⟨12/10⟩는 1보다 커요 — ⟨12/10⟩ = ⟨1 2/10⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L03_basic#8','math',4,2,'u1','L03','g4_2_math_u1_L03_basic','lesson_basic','M4-2-u1-C3',2,'mc','auto','⟨2/8⟩ + ⟨3/8⟩ ○ ⟨3/8⟩ + ⟨3/8⟩ — ○ 안에 알맞은 것은 무엇인가요?',ARRAY['M4-2-u1-X15','M4-2-u1-X18']::text[],true,'{"seq":8,"concept":"M4-2-u1-C3","difficulty":2,"kind":"mc","stem":"⟨2/8⟩ + ⟨3/8⟩ ○ ⟨3/8⟩ + ⟨3/8⟩ — ○ 안에 알맞은 것은 무엇인가요?","options":[{"t":"<","correct":true},{"t":">","mis":"M4-2-u1-X15"},{"t":"=","mis":"M4-2-u1-X18"},{"t":"알 수 없어요","mis":"M4-2-u1-X18"}],"explanation":["왼쪽 ⟨2/8⟩ + ⟨3/8⟩ = ⟨5/8⟩.","오른쪽 ⟨3/8⟩ + ⟨3/8⟩ = ⟨6/8⟩.","분자 5 < 6 — <."],"variant_rule":{"alt":[{"stem":"⟨2/5⟩ + ⟨2/5⟩ ○ ⟨4/5⟩ + ⟨2/5⟩ — ○ 안에 알맞은 것은 무엇인가요?","options":[{"t":"<","correct":true},{"t":">","mis":"M4-2-u1-X15"},{"t":"=","mis":"M4-2-u1-X18"},{"t":"알 수 없어요","mis":"M4-2-u1-X18"}],"explanation":["왼쪽 ⟨2/5⟩ + ⟨2/5⟩ = ⟨4/5⟩.","오른쪽 ⟨4/5⟩ + ⟨2/5⟩ = ⟨6/5⟩.","분자 4 < 6 — <."],"asset":null},{"stem":"⟨6/8⟩ + ⟨3/8⟩ ○ ⟨1/8⟩ + ⟨7/8⟩ — ○ 안에 알맞은 것은 무엇인가요?","options":[{"t":">","correct":true},{"t":"<","mis":"M4-2-u1-X15"},{"t":"=","mis":"M4-2-u1-X18"},{"t":"알 수 없어요","mis":"M4-2-u1-X18"}],"explanation":["왼쪽 ⟨6/8⟩ + ⟨3/8⟩ = ⟨9/8⟩.","오른쪽 ⟨1/8⟩ + ⟨7/8⟩ = ⟨8/8⟩.","분자 9 > 8 — >."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L03_basic#9','math',4,2,'u1','L03','g4_2_math_u1_L03_basic','lesson_basic','M4-2-u1-C3',2,'mc','auto','빨간 페인트 ⟨4/7⟩ L와 노란 페인트 ⟨6/7⟩ L를 섞었어요. 주황 페인트는 몇 L가 되었나요?',ARRAY['M4-2-u1-X01','M4-2-u1-X16']::text[],true,'{"seq":9,"concept":"M4-2-u1-C3","difficulty":2,"kind":"mc","stem":"빨간 페인트 ⟨4/7⟩ L와 노란 페인트 ⟨6/7⟩ L를 섞었어요. 주황 페인트는 몇 L가 되었나요?","options":[{"t":"⟨1 3/7⟩ L","correct":true},{"t":"⟨10/14⟩ L","mis":"M4-2-u1-X01"},{"t":"⟨1 4/7⟩ L","mis":"M4-2-u1-X16"},{"t":"⟨1 2/7⟩ L","mis":"M4-2-u1-X16"}],"explanation":["분모가 7로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/7⟩이 4 + 6 = 10개.","⟨4/7⟩ + ⟨6/7⟩ = ⟨10/7⟩.","⟨10/7⟩은 1보다 커요 — ⟨10/7⟩ = ⟨1 3/7⟩."],"variant_rule":{"alt":[{"stem":"곰이는 사과를 ⟨5/8⟩ kg, 펭이는 ⟨6/8⟩ kg 땄어요. 두 사람이 딴 사과는 모두 몇 kg인가요?","options":[{"t":"⟨1 3/8⟩ kg","correct":true},{"t":"⟨11/16⟩ kg","mis":"M4-2-u1-X01"},{"t":"⟨1 4/8⟩ kg","mis":"M4-2-u1-X16"},{"t":"⟨1 2/8⟩ kg","mis":"M4-2-u1-X16"}],"explanation":["분모가 8로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/8⟩이 5 + 6 = 11개.","⟨5/8⟩ + ⟨6/8⟩ = ⟨11/8⟩.","⟨11/8⟩은 1보다 커요 — ⟨11/8⟩ = ⟨1 3/8⟩."],"asset":null},{"stem":"빨간 페인트 ⟨4/6⟩ L와 노란 페인트 ⟨4/6⟩ L를 섞었어요. 주황 페인트는 몇 L가 되었나요?","options":[{"t":"⟨1 2/6⟩ L","correct":true},{"t":"⟨8/12⟩ L","mis":"M4-2-u1-X01"},{"t":"⟨1 3/6⟩ L","mis":"M4-2-u1-X16"},{"t":"⟨1 1/6⟩ L","mis":"M4-2-u1-X16"}],"explanation":["분모가 6으로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/6⟩이 4 + 4 = 8개.","⟨4/6⟩ + ⟨4/6⟩ = ⟨8/6⟩.","⟨8/6⟩은 1보다 커요 — ⟨8/6⟩ = ⟨1 2/6⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L03_basic#10','math',4,2,'u1','L03','g4_2_math_u1_L03_basic','lesson_basic','M4-2-u1-C3',3,'mc','auto','계산 결과가 1보다 큰 것은 무엇인가요?',ARRAY['M4-2-u1-X17']::text[],true,'{"seq":10,"concept":"M4-2-u1-C3","difficulty":3,"kind":"mc","stem":"계산 결과가 1보다 큰 것은 무엇인가요?","options":[{"t":"⟨7/9⟩ + ⟨3/9⟩","correct":true},{"t":"⟨1/9⟩ + ⟨1/9⟩","mis":"M4-2-u1-X17"},{"t":"⟨1/9⟩ + ⟨7/9⟩","mis":"M4-2-u1-X17"},{"t":"⟨1/9⟩ + ⟨6/9⟩","mis":"M4-2-u1-X17"}],"explanation":["분모가 9 — 분자의 합이 9보다 크면 1보다 커요.","분자의 합 — 2, 10, 8, 7.","⟨7/9⟩ + ⟨3/9⟩ = ⟨1 1/9⟩ — 1보다 커요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 계산 결과가 1보다 큰 것은 무엇인가요?","options":[{"t":"⟨8/9⟩ + ⟨8/9⟩","correct":true},{"t":"⟨2/9⟩ + ⟨3/9⟩","mis":"M4-2-u1-X17"},{"t":"⟨4/9⟩ + ⟨1/9⟩","mis":"M4-2-u1-X17"},{"t":"⟨7/9⟩ + ⟨1/9⟩","mis":"M4-2-u1-X17"}],"explanation":["분모가 9 — 분자의 합이 9보다 크면 1보다 커요.","분자의 합 — 5, 5, 16, 8.","⟨8/9⟩ + ⟨8/9⟩ = ⟨1 7/9⟩ — 1보다 커요."],"asset":null},{"stem":"이번에는 다른 문제예요. 계산 결과가 1보다 큰 것은 무엇인가요?","options":[{"t":"⟨2/5⟩ + ⟨4/5⟩","correct":true},{"t":"⟨1/5⟩ + ⟨3/5⟩","mis":"M4-2-u1-X17"},{"t":"⟨2/5⟩ + ⟨1/5⟩","mis":"M4-2-u1-X17"},{"t":"⟨3/5⟩ + ⟨1/5⟩","mis":"M4-2-u1-X17"}],"explanation":["분모가 5 — 분자의 합이 5보다 크면 1보다 커요.","분자의 합 — 4, 3, 4, 6.","⟨2/5⟩ + ⟨4/5⟩ = ⟨1 1/5⟩ — 1보다 커요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L03_challenge#1','math',4,2,'u1','L03','g4_2_math_u1_L03_challenge','lesson_challenge','M4-2-u1-C3',2,'mc','auto','⟨4/10⟩ + ⟨8/10⟩을 계산하여 대분수로 나타내면 얼마인가요?',ARRAY['M4-2-u1-X01','M4-2-u1-X16']::text[],true,'{"seq":1,"concept":"M4-2-u1-C3","difficulty":2,"kind":"mc","stem":"⟨4/10⟩ + ⟨8/10⟩을 계산하여 대분수로 나타내면 얼마인가요?","options":[{"t":"⟨1 2/10⟩","correct":true},{"t":"⟨12/20⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 3/10⟩","mis":"M4-2-u1-X16"},{"t":"⟨1 1/10⟩","mis":"M4-2-u1-X16"}],"explanation":["분모가 10으로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/10⟩이 4 + 8 = 12개.","⟨4/10⟩ + ⟨8/10⟩ = ⟨12/10⟩.","⟨12/10⟩는 1보다 커요 — ⟨12/10⟩ = ⟨1 2/10⟩."],"variant_rule":{"alt":[{"stem":"⟨4/12⟩ + ⟨10/12⟩을 계산하여 대분수로 나타내면 얼마인가요?","options":[{"t":"⟨1 2/12⟩","correct":true},{"t":"⟨14/24⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 3/12⟩","mis":"M4-2-u1-X16"},{"t":"⟨1 1/12⟩","mis":"M4-2-u1-X16"}],"explanation":["분모가 12로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/12⟩이 4 + 10 = 14개.","⟨4/12⟩ + ⟨10/12⟩ = ⟨14/12⟩.","⟨14/12⟩는 1보다 커요 — ⟨14/12⟩ = ⟨1 2/12⟩."],"asset":null},{"stem":"⟨12/13⟩ + ⟨10/13⟩을 계산하여 대분수로 나타내면 얼마인가요?","options":[{"t":"⟨1 9/13⟩","correct":true},{"t":"⟨22/26⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 10/13⟩","mis":"M4-2-u1-X16"},{"t":"⟨1 8/13⟩","mis":"M4-2-u1-X16"}],"explanation":["분모가 13으로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/13⟩이 12 + 10 = 22개.","⟨12/13⟩ + ⟨10/13⟩ = ⟨22/13⟩.","⟨22/13⟩는 1보다 커요 — ⟨22/13⟩ = ⟨1 9/13⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L03_challenge#2','math',4,2,'u1','L03','g4_2_math_u1_L03_challenge','lesson_challenge','M4-2-u1-C3',2,'mc','auto','곰이는 사과를 ⟨7/10⟩ kg, 펭이는 ⟨6/10⟩ kg 땄어요. 두 사람이 딴 사과는 모두 몇 kg인가요?',ARRAY['M4-2-u1-X01','M4-2-u1-X16']::text[],true,'{"seq":2,"concept":"M4-2-u1-C3","difficulty":2,"kind":"mc","stem":"곰이는 사과를 ⟨7/10⟩ kg, 펭이는 ⟨6/10⟩ kg 땄어요. 두 사람이 딴 사과는 모두 몇 kg인가요?","options":[{"t":"⟨1 3/10⟩ kg","correct":true},{"t":"⟨13/20⟩ kg","mis":"M4-2-u1-X01"},{"t":"⟨1 4/10⟩ kg","mis":"M4-2-u1-X16"},{"t":"⟨1 2/10⟩ kg","mis":"M4-2-u1-X16"}],"explanation":["분모가 10으로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/10⟩이 7 + 6 = 13개.","⟨7/10⟩ + ⟨6/10⟩ = ⟨13/10⟩.","⟨13/10⟩은 1보다 커요 — ⟨13/10⟩ = ⟨1 3/10⟩."],"variant_rule":{"alt":[{"stem":"빨간 페인트 ⟨10/11⟩ L와 노란 페인트 ⟨10/11⟩ L를 섞었어요. 주황 페인트는 몇 L가 되었나요?","options":[{"t":"⟨1 9/11⟩ L","correct":true},{"t":"⟨20/22⟩ L","mis":"M4-2-u1-X01"},{"t":"⟨1 10/11⟩ L","mis":"M4-2-u1-X16"},{"t":"⟨1 8/11⟩ L","mis":"M4-2-u1-X16"}],"explanation":["분모가 11로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/11⟩이 10 + 10 = 20개.","⟨10/11⟩ + ⟨10/11⟩ = ⟨20/11⟩.","⟨20/11⟩은 1보다 커요 — ⟨20/11⟩ = ⟨1 9/11⟩."],"asset":null},{"stem":"곰이는 사과를 ⟨5/6⟩ kg, 펭이는 ⟨4/6⟩ kg 땄어요. 두 사람이 딴 사과는 모두 몇 kg인가요?","options":[{"t":"⟨1 3/6⟩ kg","correct":true},{"t":"⟨9/12⟩ kg","mis":"M4-2-u1-X01"},{"t":"⟨1 4/6⟩ kg","mis":"M4-2-u1-X16"},{"t":"⟨1 2/6⟩ kg","mis":"M4-2-u1-X16"}],"explanation":["분모가 6으로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/6⟩이 5 + 4 = 9개.","⟨5/6⟩ + ⟨4/6⟩ = ⟨9/6⟩.","⟨9/6⟩는 1보다 커요 — ⟨9/6⟩ = ⟨1 3/6⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L03_challenge#3','math',4,2,'u1','L03','g4_2_math_u1_L03_challenge','lesson_challenge','M4-2-u1-C3',3,'error','auto','친구들이 분수의 덧셈을 했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M4-2-u1-X01','M4-2-u1-X15']::text[],true,'{"seq":3,"concept":"M4-2-u1-C3","difficulty":3,"kind":"error","stem":"친구들이 분수의 덧셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"하윤 — ⟨3/8⟩ + ⟨2/8⟩ = ⟨5/16⟩","correct":true,"mis_target":"M4-2-u1-X01"},{"t":"서준 — ⟨1/7⟩ + ⟨1/7⟩ = ⟨2/7⟩","mis":"M4-2-u1-X15"},{"t":"도연 — ⟨1/3⟩ + ⟨1/3⟩ = ⟨2/3⟩","mis":"M4-2-u1-X15"},{"t":"은비 — ⟨2/3⟩ + ⟨2/3⟩ = ⟨1 1/3⟩","mis":"M4-2-u1-X15"}],"explanation":["분모가 같으면 분모는 그대로, 분자끼리 더해요.","⟨3/8⟩ + ⟨2/8⟩ = ⟨5/8⟩.","하윤의 계산이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 친구들이 분수의 덧셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"채원 — ⟨4/6⟩ + ⟨3/6⟩ = ⟨1 2/6⟩","correct":true,"mis_target":"M4-2-u1-X04"},{"t":"지훈 — ⟨3/9⟩ + ⟨7/9⟩ = ⟨1 1/9⟩","mis":"M4-2-u1-X15"},{"t":"준우 — ⟨1/4⟩ + ⟨2/4⟩ = ⟨3/4⟩","mis":"M4-2-u1-X15"},{"t":"하윤 — ⟨6/8⟩ + ⟨5/8⟩ = ⟨1 3/8⟩","mis":"M4-2-u1-X15"}],"explanation":["분모가 같으면 분모는 그대로, 분자끼리 더해요.","⟨4/6⟩ + ⟨3/6⟩ = ⟨1 1/6⟩.","채원의 계산이 틀렸어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 친구들이 분수의 덧셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"지훈 — ⟨2/6⟩ + ⟨2/6⟩ = ⟨4/12⟩","correct":true,"mis_target":"M4-2-u1-X01"},{"t":"채원 — ⟨4/5⟩ + ⟨2/5⟩ = ⟨1 1/5⟩","mis":"M4-2-u1-X15"},{"t":"도연 — ⟨3/4⟩ + ⟨3/4⟩ = ⟨1 2/4⟩","mis":"M4-2-u1-X15"},{"t":"은비 — ⟨1/5⟩ + ⟨2/5⟩ = ⟨3/5⟩","mis":"M4-2-u1-X15"}],"explanation":["분모가 같으면 분모는 그대로, 분자끼리 더해요.","⟨2/6⟩ + ⟨2/6⟩ = ⟨4/6⟩.","지훈의 계산이 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L03_challenge#4','math',4,2,'u1','L03','g4_2_math_u1_L03_challenge','lesson_challenge','M4-2-u1-C3',3,'sa','auto','⟨4/6⟩ + ⟨□/6⟩ = ⟨1 3/6⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u1-C3","difficulty":3,"kind":"sa","stem":"⟨4/6⟩ + ⟨□/6⟩ = ⟨1 3/6⟩ — □에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["⟨1 3/6⟩을 가분수로 — ⟨9/6⟩.","⟨1/6⟩이 9개가 되려면 4개에서 5개를 더 모아야 해요.","□ = 9 − 4 = 5."],"variant_rule":{"alt":[{"stem":"⟨3/8⟩ + ⟨□/8⟩ = ⟨1 1/8⟩ — □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["⟨1 1/8⟩을 가분수로 — ⟨9/8⟩.","⟨1/8⟩이 9개가 되려면 3개에서 6개를 더 모아야 해요.","□ = 9 − 3 = 6."],"asset":null},{"stem":"⟨7/8⟩ + ⟨□/8⟩ = ⟨1 6/8⟩ — □에 알맞은 수를 쓰세요.","answer":["7"],"explanation":["⟨1 6/8⟩을 가분수로 — ⟨14/8⟩.","⟨1/8⟩이 14개가 되려면 7개에서 7개를 더 모아야 해요.","□ = 14 − 7 = 7."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L03_challenge#5','math',4,2,'u1','L03','g4_2_math_u1_L03_challenge','lesson_challenge','M4-2-u1-C3',3,'sa','auto','⟨3/8⟩ + ⟨□/8⟩ < 1일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u1-C3","difficulty":3,"kind":"sa","stem":"⟨3/8⟩ + ⟨□/8⟩ < 1일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["1 = ⟨8/8⟩ — 분자의 합이 8보다 작아야 해요.","3 + □ < 8 — □는 1, 2, 3, 4.","모두 4개 — 5를 넣으면 1이 되어 빼요."],"variant_rule":{"alt":[{"stem":"⟨2/6⟩ + ⟨□/6⟩ < 1일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["1 = ⟨6/6⟩ — 분자의 합이 6보다 작아야 해요.","2 + □ < 6 — □는 1, 2, 3.","모두 3개 — 4를 넣으면 1이 되어 빼요."],"asset":null},{"stem":"⟨4/8⟩ + ⟨□/8⟩ < 1일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["1 = ⟨8/8⟩ — 분자의 합이 8보다 작아야 해요.","4 + □ < 8 — □는 1, 2, 3.","모두 3개 — 4를 넣으면 1이 되어 빼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L03_challenge#6','math',4,2,'u1','L03','g4_2_math_u1_L03_challenge','lesson_challenge','M4-2-u1-C3',3,'mc','auto','계산 결과가 1보다 큰 것은 무엇인가요?',ARRAY['M4-2-u1-X17']::text[],true,'{"seq":6,"concept":"M4-2-u1-C3","difficulty":3,"kind":"mc","stem":"계산 결과가 1보다 큰 것은 무엇인가요?","options":[{"t":"⟨3/9⟩ + ⟨7/9⟩","correct":true},{"t":"⟨3/9⟩ + ⟨2/9⟩","mis":"M4-2-u1-X17"},{"t":"⟨2/9⟩ + ⟨3/9⟩","mis":"M4-2-u1-X17"},{"t":"⟨7/9⟩ + ⟨1/9⟩","mis":"M4-2-u1-X17"}],"explanation":["분모가 9 — 분자의 합이 9보다 크면 1보다 커요.","분자의 합 — 10, 5, 5, 8.","⟨3/9⟩ + ⟨7/9⟩ = ⟨1 1/9⟩ — 1보다 커요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 계산 결과가 1보다 큰 것은 무엇인가요?","options":[{"t":"⟨4/8⟩ + ⟨5/8⟩","correct":true},{"t":"⟨6/8⟩ + ⟨1/8⟩","mis":"M4-2-u1-X17"},{"t":"⟨2/8⟩ + ⟨2/8⟩","mis":"M4-2-u1-X17"},{"t":"⟨5/8⟩ + ⟨2/8⟩","mis":"M4-2-u1-X17"}],"explanation":["분모가 8 — 분자의 합이 8보다 크면 1보다 커요.","분자의 합 — 7, 9, 4, 7.","⟨4/8⟩ + ⟨5/8⟩ = ⟨1 1/8⟩ — 1보다 커요."],"asset":null},{"stem":"이번에는 다른 문제예요. 계산 결과가 1보다 큰 것은 무엇인가요?","options":[{"t":"⟨2/6⟩ + ⟨5/6⟩","correct":true},{"t":"⟨3/6⟩ + ⟨1/6⟩","mis":"M4-2-u1-X17"},{"t":"⟨2/6⟩ + ⟨3/6⟩","mis":"M4-2-u1-X17"},{"t":"⟨2/6⟩ + ⟨1/6⟩","mis":"M4-2-u1-X17"}],"explanation":["분모가 6 — 분자의 합이 6보다 크면 1보다 커요.","분자의 합 — 7, 4, 5, 3.","⟨2/6⟩ + ⟨5/6⟩ = ⟨1 1/6⟩ — 1보다 커요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L03_challenge#7','math',4,2,'u1','L03','g4_2_math_u1_L03_challenge','lesson_challenge','M4-2-u1-C3',3,'mc','auto','⟨2/9⟩ + ⟨7/9⟩ ○ ⟨5/9⟩ + ⟨7/9⟩ — ○ 안에 알맞은 것은 무엇인가요?',ARRAY['M4-2-u1-X15','M4-2-u1-X18']::text[],true,'{"seq":7,"concept":"M4-2-u1-C3","difficulty":3,"kind":"mc","stem":"⟨2/9⟩ + ⟨7/9⟩ ○ ⟨5/9⟩ + ⟨7/9⟩ — ○ 안에 알맞은 것은 무엇인가요?","options":[{"t":"<","correct":true},{"t":">","mis":"M4-2-u1-X15"},{"t":"=","mis":"M4-2-u1-X18"},{"t":"알 수 없어요","mis":"M4-2-u1-X18"}],"explanation":["왼쪽 ⟨2/9⟩ + ⟨7/9⟩ = ⟨9/9⟩.","오른쪽 ⟨5/9⟩ + ⟨7/9⟩ = ⟨12/9⟩.","분자 9 < 12 — <."],"variant_rule":{"alt":[{"stem":"⟨4/5⟩ + ⟨4/5⟩ ○ ⟨4/5⟩ + ⟨1/5⟩ — ○ 안에 알맞은 것은 무엇인가요?","options":[{"t":">","correct":true},{"t":"<","mis":"M4-2-u1-X15"},{"t":"=","mis":"M4-2-u1-X18"},{"t":"알 수 없어요","mis":"M4-2-u1-X18"}],"explanation":["왼쪽 ⟨4/5⟩ + ⟨4/5⟩ = ⟨8/5⟩.","오른쪽 ⟨4/5⟩ + ⟨1/5⟩ = ⟨5/5⟩.","분자 8 > 5 — >."],"asset":null},{"stem":"⟨9/11⟩ + ⟨5/11⟩ ○ ⟨10/11⟩ + ⟨3/11⟩ — ○ 안에 알맞은 것은 무엇인가요?","options":[{"t":">","correct":true},{"t":"<","mis":"M4-2-u1-X15"},{"t":"=","mis":"M4-2-u1-X18"},{"t":"알 수 없어요","mis":"M4-2-u1-X18"}],"explanation":["왼쪽 ⟨9/11⟩ + ⟨5/11⟩ = ⟨14/11⟩.","오른쪽 ⟨10/11⟩ + ⟨3/11⟩ = ⟨13/11⟩.","분자 14 > 13 — >."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L03_challenge#8','math',4,2,'u1','L03','g4_2_math_u1_L03_challenge','lesson_challenge','M4-2-u1-C3',4,'essay','teacher','서준이는 ⟨1/5⟩ + ⟨3/5⟩ = ⟨4/10⟩이라고 계산했어요. 서준이의 계산이 왜 틀렸는지 분수 띠(단위분수의 개수)로 설명하고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u1-C3","difficulty":4,"kind":"essay","stem":"서준이는 ⟨1/5⟩ + ⟨3/5⟩ = ⟨4/10⟩이라고 계산했어요. 서준이의 계산이 왜 틀렸는지 분수 띠(단위분수의 개수)로 설명하고 바르게 계산해 보세요.","answer_guide":{"answer":"예: ⟨1/5⟩은 ⟨1/5⟩이 1개, ⟨3/5⟩은 ⟨1/5⟩이 3개이므로 모으면 ⟨1/5⟩이 4개, 곧 ⟨4/5⟩이다. 분수 띠 한 칸의 크기(분모)는 더해도 바뀌지 않으므로 분모끼리 더하면 안 된다. ⟨4/10⟩는 ⟨1/5⟩보다 조금 큰 수라서 ⟨1/5⟩과 ⟨3/5⟩을 모은 것보다 작다.","scoring_points":["⟨4/5⟩이라고 바르게 계산했는가","단위분수 ⟨1/5⟩의 개수로 설명했는가","분모(한 칸의 크기)는 그대로라고 썼는가"]},"explanation":["⟨1/5⟩이 1 + 3 = 4개.","⟨4/5⟩.","분모는 그대로."],"asset":{"type":"fbar","bars":[{"den":5,"num":1},{"den":5,"num":3}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L03_challenge#9','math',4,2,'u1','L03','g4_2_math_u1_L03_challenge','lesson_challenge','M4-2-u1-C3',4,'essay','teacher','곰이는 사과를 ⟨4/6⟩ kg, 펭이는 ⟨5/6⟩ kg 땄어요. 두 사람이 딴 사과는 모두 몇 kg인지 대분수로 나타내고, 1보다 큰 가분수를 대분수로 바꾼 방법을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u1-C3","difficulty":4,"kind":"essay","stem":"곰이는 사과를 ⟨4/6⟩ kg, 펭이는 ⟨5/6⟩ kg 땄어요. 두 사람이 딴 사과는 모두 몇 kg인지 대분수로 나타내고, 1보다 큰 가분수를 대분수로 바꾼 방법을 설명해 보세요.","answer_guide":{"answer":"예: ⟨4/6⟩ + ⟨5/6⟩ = ⟨9/6⟩이다. ⟨1/6⟩이 6개 모이면 1이므로 9개 중 6개를 1로 바꾸면 ⟨1/6⟩이 3개 남는다. 그래서 ⟨9/6⟩ = ⟨1 3/6⟩ kg이다.","scoring_points":["⟨9/6⟩를 구했는가","⟨6/6⟩ = 1로 바꾼 방법을 썼는가","⟨1 3/6⟩ kg이라고 답했는가"]},"explanation":["⟨4/6⟩ + ⟨5/6⟩ = ⟨9/6⟩.","⟨6/6⟩ = 1.","⟨1 3/6⟩ kg."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L03_challenge#10','math',4,2,'u1','L03','g4_2_math_u1_L03_challenge','lesson_challenge','M4-2-u1-C3',4,'sa','auto','⟨6/9⟩ + ⟨□/9⟩ < 1일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-2-u1-C3","difficulty":4,"kind":"sa","stem":"⟨6/9⟩ + ⟨□/9⟩ < 1일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["1 = ⟨9/9⟩ — 분자의 합이 9보다 작아야 해요.","6 + □ < 9 — □는 1, 2.","모두 2개 — 3을 넣으면 1이 되어 빼요."],"variant_rule":{"alt":[{"stem":"⟨2/5⟩ + ⟨□/5⟩ < 1일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["1 = ⟨5/5⟩ — 분자의 합이 5보다 작아야 해요.","2 + □ < 5 — □는 1, 2.","모두 2개 — 3을 넣으면 1이 되어 빼요."],"asset":null},{"stem":"⟨6/10⟩ + ⟨□/10⟩ < 1일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["1 = ⟨10/10⟩ — 분자의 합이 10보다 작아야 해요.","6 + □ < 10 — □는 1, 2, 3.","모두 3개 — 4를 넣으면 1이 되어 빼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L04_basic#1','math',4,2,'u1','L04','g4_2_math_u1_L04_basic','lesson_basic','M4-2-u1-C4',1,'sa','auto','⟨5/7⟩ − ⟨2/7⟩ = ⟨□/7⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-2-u1-C4","difficulty":1,"kind":"sa","stem":"⟨5/7⟩ − ⟨2/7⟩ = ⟨□/7⟩ — □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["분모가 같으니 분모는 그대로 두고 분자끼리 빼요 — ⟨1/7⟩이 5 − 2 = 3개.","⟨5/7⟩ − ⟨2/7⟩ = ⟨3/7⟩.","분모끼리 빼지 않아요."],"variant_rule":{"alt":[{"stem":"⟨3/4⟩ − ⟨1/4⟩ = ⟨□/4⟩ — □에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["분모가 같으니 분모는 그대로 두고 분자끼리 빼요 — ⟨1/4⟩이 3 − 1 = 2개.","⟨3/4⟩ − ⟨1/4⟩ = ⟨2/4⟩.","분모끼리 빼지 않아요."],"asset":null},{"stem":"⟨3/9⟩ − ⟨1/9⟩ = ⟨□/9⟩ — □에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["분모가 같으니 분모는 그대로 두고 분자끼리 빼요 — ⟨1/9⟩이 3 − 1 = 2개.","⟨3/9⟩ − ⟨1/9⟩ = ⟨2/9⟩.","분모끼리 빼지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
