INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L04_basic#6','math',4,2,'u1','L04','g4_2_math_u1_L04_basic','lesson_basic','M4-2-u1-C4',2,'mc','auto','물 1 L가 든 병에서 ⟨3/8⟩ L를 컵에 따랐어요. 병에 남은 물은 몇 L인가요?',ARRAY['M4-2-u1-X08','M4-2-u1-X16']::text[],true,'{"seq":6,"concept":"M4-2-u1-C4","difficulty":2,"kind":"mc","stem":"물 1 L가 든 병에서 ⟨3/8⟩ L를 컵에 따랐어요. 병에 남은 물은 몇 L인가요?","options":[{"t":"⟨5/8⟩ L","correct":true},{"t":"⟨2/8⟩ L","mis":"M4-2-u1-X08"},{"t":"⟨6/8⟩ L","mis":"M4-2-u1-X16"},{"t":"⟨4/8⟩ L","mis":"M4-2-u1-X16"}],"explanation":["1을 분모가 8인 분수로 바꾸면 ⟨8/8⟩이에요.","⟨8/8⟩ − ⟨3/8⟩ — ⟨1/8⟩이 8 − 3 = 5개.","1 − ⟨3/8⟩ = ⟨5/8⟩."],"asset":{"type":"fbar","bars":[{"den":8,"num":8},{"den":8,"num":3,"label":"따른 물 ⟨3/8⟩ L"}]},"variant_rule":{"alt":[{"stem":"물 1 L가 든 병에서 ⟨4/9⟩ L를 컵에 따랐어요. 병에 남은 물은 몇 L인가요?","options":[{"t":"⟨5/9⟩ L","correct":true},{"t":"⟨3/9⟩ L","mis":"M4-2-u1-X08"},{"t":"⟨6/9⟩ L","mis":"M4-2-u1-X16"},{"t":"⟨4/9⟩ L","mis":"M4-2-u1-X16"}],"explanation":["1을 분모가 9인 분수로 바꾸면 ⟨9/9⟩예요.","⟨9/9⟩ − ⟨4/9⟩ — ⟨1/9⟩이 9 − 4 = 5개.","1 − ⟨4/9⟩ = ⟨5/9⟩."],"asset":{"type":"fbar","bars":[{"den":9,"num":9},{"den":9,"num":4,"label":"따른 물 ⟨4/9⟩ L"}]}},{"stem":"물 1 L가 든 병에서 ⟨2/10⟩ L를 컵에 따랐어요. 병에 남은 물은 몇 L인가요?","options":[{"t":"⟨8/10⟩ L","correct":true},{"t":"⟨1/10⟩ L","mis":"M4-2-u1-X08"},{"t":"⟨9/10⟩ L","mis":"M4-2-u1-X16"},{"t":"⟨7/10⟩ L","mis":"M4-2-u1-X16"}],"explanation":["1을 분모가 10인 분수로 바꾸면 ⟨10/10⟩이에요.","⟨10/10⟩ − ⟨2/10⟩ — ⟨1/10⟩이 10 − 2 = 8개.","1 − ⟨2/10⟩ = ⟨8/10⟩."],"asset":{"type":"fbar","bars":[{"den":10,"num":10},{"den":10,"num":2,"label":"따른 물 ⟨2/10⟩ L"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EX