INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L04_basic#7','math',4,2,'u1','L04','g4_2_math_u1_L04_basic','lesson_basic','M4-2-u1-C4',2,'mc','auto','곰이는 사과를 ⟨5/11⟩ kg, 펭이는 ⟨3/11⟩ kg 땄어요. 곰이는 펭이보다 사과를 몇 kg 더 땄나요?',ARRAY['M4-2-u1-X01','M4-2-u1-X14','M4-2-u1-X16']::text[],true,'{"seq":7,"concept":"M4-2-u1-C4","difficulty":2,"kind":"mc","stem":"곰이는 사과를 ⟨5/11⟩ kg, 펭이는 ⟨3/11⟩ kg 땄어요. 곰이는 펭이보다 사과를 몇 kg 더 땄나요?","options":[{"t":"⟨2/11⟩ kg","correct":true},{"t":"⟨2/8⟩ kg","mis":"M4-2-u1-X01"},{"t":"⟨8/11⟩ kg","mis":"M4-2-u1-X14"},{"t":"⟨3/11⟩ kg","mis":"M4-2-u1-X16"}],"explanation":["「얼마나 더」는 큰 수에서 작은 수를 빼요.","⟨5/11⟩ − ⟨3/11⟩ = ⟨2/11⟩.","⟨2/11⟩ kg 더 땄어요 — 더하지 않아요."],"variant_rule":{"alt":[{"stem":"곰이는 사과를 ⟨2/9⟩ kg, 펭이는 ⟨1/9⟩ kg 땄어요. 곰이는 펭이보다 사과를 몇 kg 더 땄나요?","options":[{"t":"⟨1/9⟩ kg","correct":true},{"t":"⟨1/8⟩ kg","mis":"M4-2-u1-X01"},{"t":"⟨3/9⟩ kg","mis":"M4-2-u1-X14"},{"t":"⟨2/9⟩ kg","mis":"M4-2-u1-X16"}],"explanation":["「얼마나 더」는 큰 수에서 작은 수를 빼요.","⟨2/9⟩ − ⟨1/9⟩ = ⟨1/9⟩.","⟨1/9⟩ kg 더 땄어요 — 더하지 않아요."],"asset":null},{"stem":"곰이는 사과를 ⟨6/7⟩ kg, 펭이는 ⟨3/7⟩ kg 땄어요. 곰이는 펭이보다 사과를 몇 kg 더 땄나요?","options":[{"t":"⟨3/7⟩ kg","correct":true},{"t":"⟨3/4⟩ kg","mis":"M4-2-u1-X01"},{"t":"⟨1 2/7⟩ kg","mis":"M4-2-u1-X14"},{"t":"⟨4/7⟩ kg","mis":"M4-2-u1-X16"}],"explanation":["「얼마나 더」는 큰 수에서 작은 수를 빼요.","⟨6/7⟩ − ⟨3/7⟩ = ⟨3/7⟩.","⟨3/7⟩ kg 더 땄어요 — 더하지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L04_basic#8','math',4,2,'u1','L04','g4_2_math_u1_L04_basic','lesson_basic','M4-2-u1-C4',2,'ox','auto','서준이 「⟨5/7⟩ − ⟨2/7⟩ = ⟨3/5⟩이야.」라고 했어요. 바르게 계산했어요.',ARRAY['M4-2-u1-X01']::text[],true,'{"seq":8,"concept":"M4-2-u1-C4","difficulty":2,"kind":"ox","stem":"서준이 「⟨5/7⟩ − ⟨2/7⟩ = ⟨3/5⟩이야.」라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"분모는 그대로 두고 분자끼리만 빼야 해서","correct":true},{"t":"분모끼리도 빼야 해서","mis":"M4-2-u1-X01"}],"mis":"M4-2-u1-X01","explanation":["분모가 같으면 분자끼리만 빼요.","⟨5/7⟩ − ⟨2/7⟩ = ⟨3/7⟩.","서준는 분모끼리도 뺐어요 — ×."],"variant_rule":{"alt":[{"stem":"하윤이 「⟨6/8⟩ − ⟨3/8⟩ = ⟨3/5⟩이야.」라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"분모는 그대로 두고 분자끼리만 빼야 해서","correct":true},{"t":"분모끼리도 빼야 해서","mis":"M4-2-u1-X01"}],"explanation":["분모가 같으면 분자끼리만 빼요.","⟨6/8⟩ − ⟨3/8⟩ = ⟨3/8⟩.","하윤는 분모끼리도 뺐어요 — ×."],"asset":null},{"stem":"채원이 「1 − ⟨2/5⟩ = ⟨1/5⟩이야.」라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"1을 ⟨5/5⟩로 바꾸어 빼야 해서","correct":true},{"t":"1을 분자에서 빼면 되어서","mis":"M4-2-u1-X08"}],"explanation":["1을 분모가 5인 분수로 바꾸면 ⟨5/5⟩예요.","⟨5/5⟩ − ⟨2/5⟩ — ⟨1/5⟩이 5 − 2 = 3개.","1 − ⟨2/5⟩ = ⟨3/5⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L04_basic#9','math',4,2,'u1','L04','g4_2_math_u1_L04_basic','lesson_basic','M4-2-u1-C4',2,'mc','auto','⟨10/12⟩ − ⟨3/12⟩을 계산하면 얼마인가요?',ARRAY['M4-2-u1-X01','M4-2-u1-X14','M4-2-u1-X16']::text[],true,'{"seq":9,"concept":"M4-2-u1-C4","difficulty":2,"kind":"mc","stem":"⟨10/12⟩ − ⟨3/12⟩을 계산하면 얼마인가요?","options":[{"t":"⟨7/12⟩","correct":true},{"t":"⟨7/9⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 1/12⟩","mis":"M4-2-u1-X14"},{"t":"⟨8/12⟩","mis":"M4-2-u1-X16"}],"explanation":["분모가 같으니 분모는 그대로 두고 분자끼리 빼요 — ⟨1/12⟩이 10 − 3 = 7개.","⟨10/12⟩ − ⟨3/12⟩ = ⟨7/12⟩.","분모끼리 빼지 않아요."],"variant_rule":{"alt":[{"stem":"⟨2/10⟩ − ⟨1/10⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/10⟩","correct":true},{"t":"⟨1/9⟩","mis":"M4-2-u1-X01"},{"t":"⟨3/10⟩","mis":"M4-2-u1-X14"},{"t":"⟨2/10⟩","mis":"M4-2-u1-X16"}],"explanation":["분모가 같으니 분모는 그대로 두고 분자끼리 빼요 — ⟨1/10⟩이 2 − 1 = 1개.","⟨2/10⟩ − ⟨1/10⟩ = ⟨1/10⟩.","분모끼리 빼지 않아요."],"asset":null},{"stem":"⟨6/7⟩ − ⟨2/7⟩를 계산하면 얼마인가요?","options":[{"t":"⟨4/7⟩","correct":true},{"t":"⟨4/5⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 1/7⟩","mis":"M4-2-u1-X14"},{"t":"⟨5/7⟩","mis":"M4-2-u1-X16"}],"explanation":["분모가 같으니 분모는 그대로 두고 분자끼리 빼요 — ⟨1/7⟩이 6 − 2 = 4개.","⟨6/7⟩ − ⟨2/7⟩ = ⟨4/7⟩.","분모끼리 빼지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L04_basic#10','math',4,2,'u1','L04','g4_2_math_u1_L04_basic','lesson_basic','M4-2-u1-C4',3,'mc','auto','물 1 L 가운데 곰이가 ⟨2/8⟩ L, 펭이가 ⟨3/8⟩ L를 마셨어요. 남은 물은 몇 L인가요?',ARRAY['M4-2-u1-X15','M4-2-u1-X16']::text[],true,'{"seq":10,"concept":"M4-2-u1-C4","difficulty":3,"kind":"mc","stem":"물 1 L 가운데 곰이가 ⟨2/8⟩ L, 펭이가 ⟨3/8⟩ L를 마셨어요. 남은 물은 몇 L인가요?","options":[{"t":"⟨3/8⟩ L","correct":true},{"t":"⟨5/8⟩ L","mis":"M4-2-u1-X15"},{"t":"⟨6/8⟩ L","mis":"M4-2-u1-X16"},{"t":"⟨4/8⟩ L","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨8/8⟩.","두 사람이 마신 물 ⟨2/8⟩ + ⟨3/8⟩ = ⟨5/8⟩.","남은 물 ⟨8/8⟩ − ⟨5/8⟩ = ⟨3/8⟩ L."],"variant_rule":{"alt":[{"stem":"물 1 L 가운데 곰이가 ⟨5/12⟩ L, 펭이가 ⟨5/12⟩ L를 마셨어요. 남은 물은 몇 L인가요?","options":[{"t":"⟨2/12⟩ L","correct":true},{"t":"⟨10/12⟩ L","mis":"M4-2-u1-X15"},{"t":"⟨7/12⟩ L","mis":"M4-2-u1-X16"},{"t":"⟨3/12⟩ L","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨12/12⟩.","두 사람이 마신 물 ⟨5/12⟩ + ⟨5/12⟩ = ⟨10/12⟩.","남은 물 ⟨12/12⟩ − ⟨10/12⟩ = ⟨2/12⟩ L."],"asset":null},{"stem":"물 1 L 가운데 곰이가 ⟨2/10⟩ L, 펭이가 ⟨2/10⟩ L를 마셨어요. 남은 물은 몇 L인가요?","options":[{"t":"⟨6/10⟩ L","correct":true},{"t":"⟨4/10⟩ L","mis":"M4-2-u1-X15"},{"t":"⟨8/10⟩ L","mis":"M4-2-u1-X16"},{"t":"⟨7/10⟩ L","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨10/10⟩.","두 사람이 마신 물 ⟨2/10⟩ + ⟨2/10⟩ = ⟨4/10⟩.","남은 물 ⟨10/10⟩ − ⟨4/10⟩ = ⟨6/10⟩ L."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L04_challenge#1','math',4,2,'u1','L04','g4_2_math_u1_L04_challenge','lesson_challenge','M4-2-u1-C4',2,'mc','auto','1 − ⟨2/13⟩를 계산하면 얼마인가요?',ARRAY['M4-2-u1-X08','M4-2-u1-X16']::text[],true,'{"seq":1,"concept":"M4-2-u1-C4","difficulty":2,"kind":"mc","stem":"1 − ⟨2/13⟩를 계산하면 얼마인가요?","options":[{"t":"⟨11/13⟩","correct":true},{"t":"⟨1/13⟩","mis":"M4-2-u1-X08"},{"t":"⟨12/13⟩","mis":"M4-2-u1-X16"},{"t":"⟨10/13⟩","mis":"M4-2-u1-X16"}],"explanation":["1을 분모가 13인 분수로 바꾸면 ⟨13/13⟩이에요.","⟨13/13⟩ − ⟨2/13⟩ — ⟨1/13⟩이 13 − 2 = 11개.","1 − ⟨2/13⟩ = ⟨11/13⟩."],"variant_rule":{"alt":[{"stem":"1 − ⟨3/14⟩을 계산하면 얼마인가요?","options":[{"t":"⟨11/14⟩","correct":true},{"t":"⟨2/14⟩","mis":"M4-2-u1-X08"},{"t":"⟨12/14⟩","mis":"M4-2-u1-X16"},{"t":"⟨10/14⟩","mis":"M4-2-u1-X16"}],"explanation":["1을 분모가 14인 분수로 바꾸면 ⟨14/14⟩예요.","⟨14/14⟩ − ⟨3/14⟩ — ⟨1/14⟩이 14 − 3 = 11개.","1 − ⟨3/14⟩ = ⟨11/14⟩."],"asset":null},{"stem":"1 − ⟨7/15⟩을 계산하면 얼마인가요?","options":[{"t":"⟨8/15⟩","correct":true},{"t":"⟨6/15⟩","mis":"M4-2-u1-X08"},{"t":"⟨9/15⟩","mis":"M4-2-u1-X16"},{"t":"⟨7/15⟩","mis":"M4-2-u1-X16"}],"explanation":["1을 분모가 15인 분수로 바꾸면 ⟨15/15⟩예요.","⟨15/15⟩ − ⟨7/15⟩ — ⟨1/15⟩이 15 − 7 = 8개.","1 − ⟨7/15⟩ = ⟨8/15⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L04_challenge#2','math',4,2,'u1','L04','g4_2_math_u1_L04_challenge','lesson_challenge','M4-2-u1-C4',2,'mc','auto','곰이는 사과를 ⟨8/11⟩ kg, 펭이는 ⟨4/11⟩ kg 땄어요. 곰이는 펭이보다 사과를 몇 kg 더 땄나요?',ARRAY['M4-2-u1-X01','M4-2-u1-X14','M4-2-u1-X16']::text[],true,'{"seq":2,"concept":"M4-2-u1-C4","difficulty":2,"kind":"mc","stem":"곰이는 사과를 ⟨8/11⟩ kg, 펭이는 ⟨4/11⟩ kg 땄어요. 곰이는 펭이보다 사과를 몇 kg 더 땄나요?","options":[{"t":"⟨4/11⟩ kg","correct":true},{"t":"⟨4/7⟩ kg","mis":"M4-2-u1-X01"},{"t":"⟨1 1/11⟩ kg","mis":"M4-2-u1-X14"},{"t":"⟨5/11⟩ kg","mis":"M4-2-u1-X16"}],"explanation":["「얼마나 더」는 큰 수에서 작은 수를 빼요.","⟨8/11⟩ − ⟨4/11⟩ = ⟨4/11⟩.","⟨4/11⟩ kg 더 땄어요 — 더하지 않아요."],"variant_rule":{"alt":[{"stem":"곰이는 사과를 ⟨6/8⟩ kg, 펭이는 ⟨4/8⟩ kg 땄어요. 곰이는 펭이보다 사과를 몇 kg 더 땄나요?","options":[{"t":"⟨2/8⟩ kg","correct":true},{"t":"⟨2/4⟩ kg","mis":"M4-2-u1-X01"},{"t":"⟨1 2/8⟩ kg","mis":"M4-2-u1-X14"},{"t":"⟨3/8⟩ kg","mis":"M4-2-u1-X16"}],"explanation":["「얼마나 더」는 큰 수에서 작은 수를 빼요.","⟨6/8⟩ − ⟨4/8⟩ = ⟨2/8⟩.","⟨2/8⟩ kg 더 땄어요 — 더하지 않아요."],"asset":null},{"stem":"곰이는 사과를 ⟨4/8⟩ kg, 펭이는 ⟨3/8⟩ kg 땄어요. 곰이는 펭이보다 사과를 몇 kg 더 땄나요?","options":[{"t":"⟨1/8⟩ kg","correct":true},{"t":"⟨1/5⟩ kg","mis":"M4-2-u1-X01"},{"t":"⟨7/8⟩ kg","mis":"M4-2-u1-X14"},{"t":"⟨2/8⟩ kg","mis":"M4-2-u1-X16"}],"explanation":["「얼마나 더」는 큰 수에서 작은 수를 빼요.","⟨4/8⟩ − ⟨3/8⟩ = ⟨1/8⟩.","⟨1/8⟩ kg 더 땄어요 — 더하지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L04_challenge#3','math',4,2,'u1','L04','g4_2_math_u1_L04_challenge','lesson_challenge','M4-2-u1-C4',3,'error','auto','친구들이 분수의 뺄셈을 했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M4-2-u1-X01','M4-2-u1-X15']::text[],true,'{"seq":3,"concept":"M4-2-u1-C4","difficulty":3,"kind":"error","stem":"친구들이 분수의 뺄셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"은비 — ⟨4/7⟩ − ⟨1/7⟩ = ⟨3/6⟩","correct":true,"mis_target":"M4-2-u1-X01"},{"t":"건우 — ⟨3/4⟩ − ⟨1/4⟩ = ⟨2/4⟩","mis":"M4-2-u1-X15"},{"t":"하윤 — ⟨3/6⟩ − ⟨1/6⟩ = ⟨2/6⟩","mis":"M4-2-u1-X15"},{"t":"서준 — ⟨5/8⟩ − ⟨2/8⟩ = ⟨3/8⟩","mis":"M4-2-u1-X15"}],"explanation":["분모가 같으면 분모는 그대로, 분자끼리 빼요.","1에서 뺄 때는 1 = ⟨7/7⟩로 바꾸어요.","은비의 계산이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 친구들이 분수의 뺄셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"하윤 — ⟨3/4⟩ − ⟨1/4⟩ = ⟨2/3⟩","correct":true,"mis_target":"M4-2-u1-X01"},{"t":"채원 — ⟨2/5⟩ − ⟨1/5⟩ = ⟨1/5⟩","mis":"M4-2-u1-X15"},{"t":"서윤 — ⟨7/9⟩ − ⟨6/9⟩ = ⟨1/9⟩","mis":"M4-2-u1-X15"},{"t":"서준 — ⟨6/8⟩ − ⟨3/8⟩ = ⟨3/8⟩","mis":"M4-2-u1-X15"}],"explanation":["분모가 같으면 분모는 그대로, 분자끼리 빼요.","1에서 뺄 때는 1 = ⟨4/4⟩로 바꾸어요.","하윤의 계산이 틀렸어요."],"asset":null},{"stem":"이번에는 다른 문제예요. 친구들이 분수의 뺄셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"은비 — ⟨4/6⟩ − ⟨1/6⟩ = ⟨3/5⟩","correct":true,"mis_target":"M4-2-u1-X01"},{"t":"도연 — ⟨2/5⟩ − ⟨1/5⟩ = ⟨1/5⟩","mis":"M4-2-u1-X15"},{"t":"서윤 — ⟨2/4⟩ − ⟨1/4⟩ = ⟨1/4⟩","mis":"M4-2-u1-X15"},{"t":"하윤 — ⟨7/9⟩ − ⟨3/9⟩ = ⟨4/9⟩","mis":"M4-2-u1-X15"}],"explanation":["분모가 같으면 분모는 그대로, 분자끼리 빼요.","1에서 뺄 때는 1 = ⟨6/6⟩으로 바꾸어요.","은비의 계산이 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L04_challenge#4','math',4,2,'u1','L04','g4_2_math_u1_L04_challenge','lesson_challenge','M4-2-u1-C4',3,'sa','auto','⟨8/9⟩ − ⟨□/9⟩ = ⟨5/9⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u1-C4","difficulty":3,"kind":"sa","stem":"⟨8/9⟩ − ⟨□/9⟩ = ⟨5/9⟩ — □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["⟨1/9⟩이 8개에서 몇 개를 덜어야 5개가 남을까요?","8 − □ = 5.","□ = 8 − 5 = 3."],"variant_rule":{"alt":[{"stem":"⟨4/8⟩ − ⟨□/8⟩ = ⟨2/8⟩ — □에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["⟨1/8⟩이 4개에서 몇 개를 덜어야 2개가 남을까요?","4 − □ = 2.","□ = 4 − 2 = 2."],"asset":null},{"stem":"⟨4/5⟩ − ⟨□/5⟩ = ⟨1/5⟩ — □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["⟨1/5⟩이 4개에서 몇 개를 덜어야 1개가 남을까요?","4 − □ = 1.","□ = 4 − 1 = 3."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L04_challenge#5','math',4,2,'u1','L04','g4_2_math_u1_L04_challenge','lesson_challenge','M4-2-u1-C4',3,'sa','auto','⟨□/6⟩ − ⟨4/6⟩ = ⟨1/6⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u1-C4","difficulty":3,"kind":"sa","stem":"⟨□/6⟩ − ⟨4/6⟩ = ⟨1/6⟩ — □에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["□에서 4를 덜어 1이 남았어요.","덧셈으로 되돌려요 — ⟨1/6⟩ + ⟨4/6⟩.","□ = 1 + 4 = 5."],"variant_rule":{"alt":[{"stem":"⟨□/9⟩ − ⟨3/9⟩ = ⟨1/9⟩ — □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["□에서 3을 덜어 1이 남았어요.","덧셈으로 되돌려요 — ⟨1/9⟩ + ⟨3/9⟩.","□ = 1 + 3 = 4."],"asset":null},{"stem":"⟨□/11⟩ − ⟨4/11⟩ = ⟨2/11⟩ — □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["□에서 4를 덜어 2가 남았어요.","덧셈으로 되돌려요 — ⟨2/11⟩ + ⟨4/11⟩.","□ = 2 + 4 = 6."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L04_challenge#6','math',4,2,'u1','L04','g4_2_math_u1_L04_challenge','lesson_challenge','M4-2-u1-C4',3,'mc','auto','물 1 L 가운데 곰이가 ⟨2/8⟩ L, 펭이가 ⟨1/8⟩ L를 마셨어요. 남은 물은 몇 L인가요?',ARRAY['M4-2-u1-X15','M4-2-u1-X16']::text[],true,'{"seq":6,"concept":"M4-2-u1-C4","difficulty":3,"kind":"mc","stem":"물 1 L 가운데 곰이가 ⟨2/8⟩ L, 펭이가 ⟨1/8⟩ L를 마셨어요. 남은 물은 몇 L인가요?","options":[{"t":"⟨5/8⟩ L","correct":true},{"t":"⟨3/8⟩ L","mis":"M4-2-u1-X15"},{"t":"⟨6/8⟩ L","mis":"M4-2-u1-X16"},{"t":"⟨7/8⟩ L","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨8/8⟩.","두 사람이 마신 물 ⟨2/8⟩ + ⟨1/8⟩ = ⟨3/8⟩.","남은 물 ⟨8/8⟩ − ⟨3/8⟩ = ⟨5/8⟩ L."],"variant_rule":{"alt":[{"stem":"물 1 L 가운데 곰이가 ⟨3/8⟩ L, 펭이가 ⟨2/8⟩ L를 마셨어요. 남은 물은 몇 L인가요?","options":[{"t":"⟨3/8⟩ L","correct":true},{"t":"⟨5/8⟩ L","mis":"M4-2-u1-X15"},{"t":"⟨6/8⟩ L","mis":"M4-2-u1-X16"},{"t":"⟨4/8⟩ L","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨8/8⟩.","두 사람이 마신 물 ⟨3/8⟩ + ⟨2/8⟩ = ⟨5/8⟩.","남은 물 ⟨8/8⟩ − ⟨5/8⟩ = ⟨3/8⟩ L."],"asset":null},{"stem":"물 1 L 가운데 곰이가 ⟨9/12⟩ L, 펭이가 ⟨1/12⟩ L를 마셨어요. 남은 물은 몇 L인가요?","options":[{"t":"⟨2/12⟩ L","correct":true},{"t":"⟨10/12⟩ L","mis":"M4-2-u1-X15"},{"t":"⟨3/12⟩ L","mis":"M4-2-u1-X16"},{"t":"⟨11/12⟩ L","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨12/12⟩.","두 사람이 마신 물 ⟨9/12⟩ + ⟨1/12⟩ = ⟨10/12⟩.","남은 물 ⟨12/12⟩ − ⟨10/12⟩ = ⟨2/12⟩ L."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L04_challenge#7','math',4,2,'u1','L04','g4_2_math_u1_L04_challenge','lesson_challenge','M4-2-u1-C4',3,'sa','auto','1 − ⟨□/7⟩ > ⟨2/7⟩일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-2-u1-C4","difficulty":3,"kind":"sa","stem":"1 − ⟨□/7⟩ > ⟨2/7⟩일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["1 = ⟨7/7⟩ — 1에서 □개를 덜면 분자는 7 − □예요.","7 − □가 2보다 커야 해요.","□ < 5 — □는 1, 2, 3, 4, 모두 4개예요."],"variant_rule":{"alt":[{"stem":"1 − ⟨□/12⟩ > ⟨3/12⟩일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["1 = ⟨12/12⟩ — 1에서 □개를 덜면 분자는 12 − □예요.","12 − □가 3보다 커야 해요.","□ < 9 — □는 1, 2, 3, 4, 5, 6, 7, 8, 모두 8개예요."],"asset":null},{"stem":"1 − ⟨□/6⟩ > ⟨1/6⟩일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["1 = ⟨6/6⟩ — 1에서 □개를 덜면 분자는 6 − □예요.","6 − □가 1보다 커야 해요.","□ < 5 — □는 1, 2, 3, 4, 모두 4개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L04_challenge#8','math',4,2,'u1','L04','g4_2_math_u1_L04_challenge','lesson_challenge','M4-2-u1-C4',4,'essay','teacher','텃밭 영양제 1 L 가운데 ⟨2/5⟩ L를 뿌렸어요. 하윤이는 「1 − ⟨2/5⟩는 1에서 2를 뺄 수 없으니 계산할 수 없어.」라고 했어요. 남은 영양제의 양을 구하고, 하윤이에게 계산 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u1-C4","difficulty":4,"kind":"essay","stem":"텃밭 영양제 1 L 가운데 ⟨2/5⟩ L를 뿌렸어요. 하윤이는 「1 − ⟨2/5⟩는 1에서 2를 뺄 수 없으니 계산할 수 없어.」라고 했어요. 남은 영양제의 양을 구하고, 하윤이에게 계산 방법을 설명해 보세요.","answer_guide":{"answer":"예: 1을 분모가 5인 분수 ⟨5/5⟩로 바꾸면 ⟨5/5⟩ − ⟨2/5⟩ = ⟨3/5⟩이다. 1은 ⟨1/5⟩이 5개이므로 그중 2개를 덜어 내면 3개가 남는다. 남은 영양제는 ⟨3/5⟩ L이다.","scoring_points":["1 = ⟨5/5⟩로 바꾸었는가","⟨1/5⟩의 개수로 설명했는가","⟨3/5⟩ L라고 답했는가"]},"explanation":["1 = ⟨5/5⟩.","⟨5/5⟩ − ⟨2/5⟩ = ⟨3/5⟩.","⟨3/5⟩ L."],"asset":{"type":"fbar","bars":[{"den":5,"num":5},{"den":5,"num":2}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L04_challenge#9','math',4,2,'u1','L04','g4_2_math_u1_L04_challenge','lesson_challenge','M4-2-u1-C4',4,'essay','teacher','곰이는 물을 ⟨5/8⟩ L, 펭이는 ⟨2/8⟩ L 마셨어요. 「누가 얼마나 더 마셨나요?」에 답할 때 덧셈과 뺄셈 중 무엇을 써야 하는지 까닭과 함께 쓰고 답을 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u1-C4","difficulty":4,"kind":"essay","stem":"곰이는 물을 ⟨5/8⟩ L, 펭이는 ⟨2/8⟩ L 마셨어요. 「누가 얼마나 더 마셨나요?」에 답할 때 덧셈과 뺄셈 중 무엇을 써야 하는지 까닭과 함께 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 두 양의 차이를 묻는 것이므로 뺄셈을 쓴다. ⟨5/8⟩ − ⟨2/8⟩ = ⟨3/8⟩이므로 곰이가 ⟨3/8⟩ L 더 마셨다. 더하면 두 사람이 마신 전체 양이 되어 묻는 것과 다르다.","scoring_points":["뺄셈을 골랐는가","차이를 묻기 때문이라고 썼는가","곰이가 ⟨3/8⟩ L 더 마셨다고 답했는가"]},"explanation":["「얼마나 더」는 차이.","⟨5/8⟩ − ⟨2/8⟩ = ⟨3/8⟩.","곰이가 ⟨3/8⟩ L 더."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L04_challenge#10','math',4,2,'u1','L04','g4_2_math_u1_L04_challenge','lesson_challenge','M4-2-u1-C4',4,'sa','auto','1 − ⟨□/11⟩ > ⟨4/11⟩일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-2-u1-C4","difficulty":4,"kind":"sa","stem":"1 − ⟨□/11⟩ > ⟨4/11⟩일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["1 = ⟨11/11⟩ — 1에서 □개를 덜면 분자는 11 − □예요.","11 − □가 4보다 커야 해요.","□ < 7 — □는 1, 2, 3, 4, 5, 6, 모두 6개예요."],"variant_rule":{"alt":[{"stem":"1 − ⟨□/8⟩ > ⟨3/8⟩일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["1 = ⟨8/8⟩ — 1에서 □개를 덜면 분자는 8 − □예요.","8 − □가 3보다 커야 해요.","□ < 5 — □는 1, 2, 3, 4, 모두 4개예요."],"asset":null},{"stem":"1 − ⟨□/9⟩ > ⟨2/9⟩일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["1 = ⟨9/9⟩ — 1에서 □개를 덜면 분자는 9 − □예요.","9 − □가 2보다 커야 해요.","□ < 7 — □는 1, 2, 3, 4, 5, 6, 모두 6개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L05_basic#1','math',4,2,'u1','L05','g4_2_math_u1_L05_basic','lesson_basic','M4-2-u1-C5',1,'mc','auto','⟨1 1/4⟩ + ⟨2 2/4⟩를 계산하면 얼마인가요?',ARRAY['M4-2-u1-X01','M4-2-u1-X13','M4-2-u1-X16']::text[],true,'{"seq":1,"concept":"M4-2-u1-C5","difficulty":1,"kind":"mc","stem":"⟨1 1/4⟩ + ⟨2 2/4⟩를 계산하면 얼마인가요?","options":[{"t":"⟨3 3/4⟩","correct":true},{"t":"⟨3 3/8⟩","mis":"M4-2-u1-X01"},{"t":"⟨3/4⟩","mis":"M4-2-u1-X13"},{"t":"4","mis":"M4-2-u1-X16"}],"explanation":["자연수끼리 1 + 2 = 3.","진분수끼리 ⟨1/4⟩ + ⟨2/4⟩ = ⟨3/4⟩.","⟨1 1/4⟩ + ⟨2 2/4⟩ = ⟨3 3/4⟩."],"variant_rule":{"alt":[{"stem":"⟨1 1/9⟩ + ⟨2 6/9⟩을 계산하면 얼마인가요?","options":[{"t":"⟨3 7/9⟩","correct":true},{"t":"⟨3 7/18⟩","mis":"M4-2-u1-X01"},{"t":"⟨7/9⟩","mis":"M4-2-u1-X13"},{"t":"⟨3 8/9⟩","mis":"M4-2-u1-X16"}],"explanation":["자연수끼리 1 + 2 = 3.","진분수끼리 ⟨1/9⟩ + ⟨6/9⟩ = ⟨7/9⟩.","⟨1 1/9⟩ + ⟨2 6/9⟩ = ⟨3 7/9⟩."],"asset":null},{"stem":"⟨2 3/8⟩ + ⟨1 4/8⟩를 계산하면 얼마인가요?","options":[{"t":"⟨3 7/8⟩","correct":true},{"t":"⟨3 7/16⟩","mis":"M4-2-u1-X01"},{"t":"⟨7/8⟩","mis":"M4-2-u1-X13"},{"t":"4","mis":"M4-2-u1-X16"}],"explanation":["자연수끼리 2 + 1 = 3.","진분수끼리 ⟨3/8⟩ + ⟨4/8⟩ = ⟨7/8⟩.","⟨2 3/8⟩ + ⟨1 4/8⟩ = ⟨3 7/8⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L05_basic#2','math',4,2,'u1','L05','g4_2_math_u1_L05_basic','lesson_basic','M4-2-u1-C5',1,'sa','auto','⟨4 2/8⟩ + ⟨3 4/8⟩를 계산하여 대분수로 나타낼 때, 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u1-C5","difficulty":1,"kind":"sa","stem":"⟨4 2/8⟩ + ⟨3 4/8⟩를 계산하여 대분수로 나타낼 때, 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["자연수끼리 4 + 3 = 7.","진분수끼리 ⟨2/8⟩ + ⟨4/8⟩ = ⟨6/8⟩.","⟨4 2/8⟩ + ⟨3 4/8⟩ = ⟨7 6/8⟩."],"variant_rule":{"alt":[{"stem":"⟨1 1/6⟩ + ⟨2 3/6⟩을 계산하여 대분수로 나타낼 때, 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["자연수끼리 1 + 2 = 3.","진분수끼리 ⟨1/6⟩ + ⟨3/6⟩ = ⟨4/6⟩.","⟨1 1/6⟩ + ⟨2 3/6⟩ = ⟨3 4/6⟩."],"asset":null},{"stem":"⟨3 2/9⟩ + ⟨1 6/9⟩을 계산하여 대분수로 나타낼 때, 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["자연수끼리 3 + 1 = 4.","진분수끼리 ⟨2/9⟩ + ⟨6/9⟩ = ⟨8/9⟩.","⟨3 2/9⟩ + ⟨1 6/9⟩ = ⟨4 8/9⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
