INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L05_basic#5','math',4,2,'u1','L05','g4_2_math_u1_L05_basic','lesson_basic','M4-2-u1-C5',2,'mc','auto','⟨1 3/5⟩ + ⟨1 4/5⟩를 계산하면 얼마인가요?',ARRAY['M4-2-u1-X07','M4-2-u1-X01','M4-2-u1-X13']::text[],true,'{"seq":5,"concept":"M4-2-u1-C5","difficulty":2,"kind":"mc","stem":"⟨1 3/5⟩ + ⟨1 4/5⟩를 계산하면 얼마인가요?","options":[{"t":"⟨3 2/5⟩","correct":true},{"t":"⟨2 2/5⟩","mis":"M4-2-u1-X07"},{"t":"⟨2 7/10⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 2/5⟩","mis":"M4-2-u1-X13"}],"explanation":["자연수끼리 1 + 1 = 2.","진분수끼리 ⟨3/5⟩ + ⟨4/5⟩ = ⟨7/5⟩ — 1보다 커서 ⟨1 2/5⟩, 1을 자연수로 넘겨요.","⟨1 3/5⟩ + ⟨1 4/5⟩ = ⟨3 2/5⟩."],"variant_rule":{"alt":[{"stem":"⟨2 5/7⟩ + ⟨3 5/7⟩를 계산하면 얼마인가요?","options":[{"t":"⟨6 3/7⟩","correct":true},{"t":"⟨5 3/7⟩","mis":"M4-2-u1-X07"},{"t":"⟨5 10/14⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 3/7⟩","mis":"M4-2-u1-X13"}],"explanation":["자연수끼리 2 + 3 = 5.","진분수끼리 ⟨5/7⟩ + ⟨5/7⟩ = ⟨10/7⟩ — 1보다 커서 ⟨1 3/7⟩, 1을 자연수로 넘겨요.","⟨2 5/7⟩ + ⟨3 5/7⟩ = ⟨6 3/7⟩."],"asset":null},{"stem":"⟨2 5/9⟩ + ⟨3 6/9⟩을 계산하면 얼마인가요?","options":[{"t":"⟨6 2/9⟩","correct":true},{"t":"⟨5 2/9⟩","mis":"M4-2-u1-X07"},{"t":"⟨5 11/18⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 2/9⟩","mis":"M4-2-u1-X13"}],"explanation":["자연수끼리 2 + 3 = 5.","진분수끼리 ⟨5/9⟩ + ⟨6/9⟩ = ⟨11/9⟩ — 1보다 커서 ⟨1 2/9⟩, 1을 자연수로 넘겨요.","⟨2 5/9⟩ + ⟨3 6/9⟩ = ⟨6 2/9⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L05_basic#6','math',4,2,'u1','L05','g4_2_math_u1_L05_basic','lesson_basic','M4-2-u1-C5',2,'sa','auto','⟨1 3/8⟩ + ⟨3 6/8⟩을 가분수로 바꾸어 계산하면 ⟨□/8⟩ + ⟨△/8⟩ = ⟨○/8⟩이에요. ○에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u1-C5","difficulty":2,"kind":"sa","stem":"⟨1 3/8⟩ + ⟨3 6/8⟩을 가분수로 바꾸어 계산하면 ⟨□/8⟩ + ⟨△/8⟩ = ⟨○/8⟩이에요. ○에 알맞은 수를 쓰세요.","answer":["41"],"explanation":["⟨1 3/8⟩ = ⟨11/8⟩, ⟨3 6/8⟩ = ⟨30/8⟩.","⟨11/8⟩ + ⟨30/8⟩ = ⟨41/8⟩.","○ = 41 — 대분수로 ⟨5 1/8⟩."],"variant_rule":{"alt":[{"stem":"⟨2 3/4⟩ + ⟨3 2/4⟩를 가분수로 바꾸어 계산하면 ⟨□/4⟩ + ⟨△/4⟩ = ⟨○/4⟩이에요. ○에 알맞은 수를 쓰세요.","answer":["25"],"explanation":["⟨2 3/4⟩ = ⟨11/4⟩, ⟨3 2/4⟩ = ⟨14/4⟩.","⟨11/4⟩ + ⟨14/4⟩ = ⟨25/4⟩.","○ = 25 — 대분수로 ⟨6 1/4⟩."],"asset":null},{"stem":"⟨1 2/3⟩ + ⟨2 2/3⟩를 가분수로 바꾸어 계산하면 ⟨□/3⟩ + ⟨△/3⟩ = ⟨○/3⟩이에요. ○에 알맞은 수를 쓰세요.","answer":["13"],"explanation":["⟨1 2/3⟩ = ⟨5/3⟩, ⟨2 2/3⟩ = ⟨8/3⟩.","⟨5/3⟩ + ⟨8/3⟩ = ⟨13/3⟩.","○ = 13 — 대분수로 ⟨4 1/3⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
