INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L05_basic#8','math',4,2,'u1','L05','g4_2_math_u1_L05_basic','lesson_basic','M4-2-u1-C5',2,'mc','auto','⟨3 4/7⟩ + ⟨6/7⟩을 계산하면 얼마인가요?',ARRAY['M4-2-u1-X07','M4-2-u1-X13','M4-2-u1-X16']::text[],true,'{"seq":8,"concept":"M4-2-u1-C5","difficulty":2,"kind":"mc","stem":"⟨3 4/7⟩ + ⟨6/7⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4 3/7⟩","correct":true},{"t":"⟨3 3/7⟩","mis":"M4-2-u1-X07"},{"t":"⟨1 3/7⟩","mis":"M4-2-u1-X13"},{"t":"⟨4 4/7⟩","mis":"M4-2-u1-X16"}],"explanation":["자연수 부분 3은 그대로예요.","진분수끼리 ⟨4/7⟩ + ⟨6/7⟩ = ⟨10/7⟩ = ⟨1 3/7⟩.","⟨3 4/7⟩ + ⟨6/7⟩ = ⟨4 3/7⟩."],"variant_rule":{"alt":[{"stem":"⟨2 3/4⟩ + ⟨3/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨3 2/4⟩","correct":true},{"t":"⟨2 2/4⟩","mis":"M4-2-u1-X07"},{"t":"⟨1 2/4⟩","mis":"M4-2-u1-X13"},{"t":"⟨3 3/4⟩","mis":"M4-2-u1-X16"}],"explanation":["자연수 부분 2는 그대로예요.","진분수끼리 ⟨3/4⟩ + ⟨3/4⟩ = ⟨6/4⟩ = ⟨1 2/4⟩.","⟨2 3/4⟩ + ⟨3/4⟩ = ⟨3 2/4⟩."],"asset":null},{"stem":"⟨5 3/6⟩ + ⟨5/6⟩를 계산하면 얼마인가요?","options":[{"t":"⟨6 2/6⟩","correct":true},{"t":"⟨5 2/6⟩","mis":"M4-2-u1-X07"},{"t":"⟨1 2/6⟩","mis":"M4-2-u1-X13"},{"t":"⟨6 3/6⟩","mis":"M4-2-u1-X16"}],"explanation":["자연수 부분 5는 그대로예요.","진분수끼리 ⟨3/6⟩ + ⟨5/6⟩ = ⟨8/6⟩ = ⟨1 2/6⟩.","⟨5 3/6⟩ + ⟨5/6⟩ = ⟨6 2/6⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L05_basic#9','math',4,2,'u1','L05','g4_2_math_u1_L05_basic','lesson_basic','M4-2-u1-C5',2,'ox','auto','채원이 「⟨2 4/8⟩ + ⟨3 7/8⟩ = ⟨5 3/8⟩이야.」라고 했어요. 바르게 계산했어요.',ARRAY['M4-2-u1-X07']::text[],true,'{"seq":9,"concept":"M4-2-u1-C5","difficulty":2,"kind":"ox","stem":"채원이 「⟨2 4/8⟩ + ⟨3 7/8⟩ = ⟨5 3/8⟩이야.」라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"진분수끼리의 합에서 넘친 1을 자연수에 더해야 해서","correct":true},{"t":"자연수끼리만 더하면 되어서","mis":"M4-2-u1-X07"}],"mis":"M4-2-u1-X07","explanation":["진분수끼리 ⟨4/8⟩ + ⟨7/8⟩ = ⟨11/8⟩ = ⟨1 3/8⟩.","넘친 1을 자연수 5에 더해 6.","바른 답은 ⟨6 3/8⟩ — ×."],"variant_rule":{"alt":[{"stem":"채원이 「⟨1 3/4⟩ + ⟨1 2/4⟩ = ⟨2 1/4⟩이야.」라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"진분수끼리의 합에서 넘친 1을 자연수에 더해야 해서","correct":true},{"t":"자연수끼리만 더하면 되어서","mis":"M4-2-u1-X07"}],"explanation":["진분수끼리 ⟨3/4⟩ + ⟨2/4⟩ = ⟨5/4⟩ = ⟨1 1/4⟩.","넘친 1을 자연수 2에 더해 3.","바른 답은 ⟨3 1/4⟩ — ×."],"asset":null},{"stem":"채원이 「⟨1 4/5⟩ + ⟨3 2/5⟩ = ⟨4 1/5⟩이야.」라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"진분수끼리의 합에서 넘친 1을 자연수에 더해야 해서","correct":true},{"t":"자연수끼리만 더하면 되어서","mis":"M4-2-u1-X07"}],"explanation":["진분수끼리 ⟨4/5⟩ + ⟨2/5⟩ = ⟨6/5⟩ = ⟨1 1/5⟩.","넘친 1을 자연수 4에 더해 5.","바른 답은 ⟨5 1/5⟩ — ×."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L05_basic#10','math',4,2,'u1','L05','g4_2_math_u1_L05_basic','lesson_basic','M4-2-u1-C5',3,'mc','auto','⟨1 2/4⟩ + ⟨2 3/4⟩ ○ 4 — ○ 안에 알맞은 것은 무엇인가요?',ARRAY['M4-2-u1-X15','M4-2-u1-X18']::text[],true,'{"seq":10,"concept":"M4-2-u1-C5","difficulty":3,"kind":"mc","stem":"⟨1 2/4⟩ + ⟨2 3/4⟩ ○ 4 — ○ 안에 알맞은 것은 무엇인가요?","options":[{"t":">","correct":true},{"t":"<","mis":"M4-2-u1-X15"},{"t":"=","mis":"M4-2-u1-X18"},{"t":"알 수 없어요","mis":"M4-2-u1-X18"}],"explanation":["⟨1 2/4⟩ + ⟨2 3/4⟩ = ⟨4 1/4⟩.","4 = ⟨16/4⟩.","⟨4 1/4⟩ > 4."],"variant_rule":{"alt":[{"stem":"⟨2 3/4⟩ + ⟨2 3/4⟩ ○ 6 — ○ 안에 알맞은 것은 무엇인가요?","options":[{"t":"<","correct":true},{"t":">","mis":"M4-2-u1-X15"},{"t":"=","mis":"M4-2-u1-X18"},{"t":"알 수 없어요","mis":"M4-2-u1-X18"}],"explanation":["⟨2 3/4⟩ + ⟨2 3/4⟩ = ⟨5 2/4⟩.","6 = ⟨24/4⟩.","⟨5 2/4⟩ < 6."],"asset":null},{"stem":"⟨2 6/8⟩ + ⟨2 3/8⟩ ○ 6 — ○ 안에 알맞은 것은 무엇인가요?","options":[{"t":"<","correct":true},{"t":">","mis":"M4-2-u1-X15"},{"t":"=","mis":"M4-2-u1-X18"},{"t":"알 수 없어요","mis":"M4-2-u1-X18"}],"explanation":["⟨2 6/8⟩ + ⟨2 3/8⟩ = ⟨5 1/8⟩.","6 = ⟨48/8⟩.","⟨5 1/8⟩ < 6."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L05_challenge#1','math',4,2,'u1','L05','g4_2_math_u1_L05_challenge','lesson_challenge','M4-2-u1-C5',2,'mc','auto','⟨1 8/11⟩ + ⟨3 7/11⟩을 계산하면 얼마인가요?',ARRAY['M4-2-u1-X07','M4-2-u1-X01','M4-2-u1-X13']::text[],true,'{"seq":1,"concept":"M4-2-u1-C5","difficulty":2,"kind":"mc","stem":"⟨1 8/11⟩ + ⟨3 7/11⟩을 계산하면 얼마인가요?","options":[{"t":"⟨5 4/11⟩","correct":true},{"t":"⟨4 4/11⟩","mis":"M4-2-u1-X07"},{"t":"⟨4 15/22⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 4/11⟩","mis":"M4-2-u1-X13"}],"explanation":["자연수끼리 1 + 3 = 4.","진분수끼리 ⟨8/11⟩ + ⟨7/11⟩ = ⟨15/11⟩ — 1보다 커서 ⟨1 4/11⟩, 1을 자연수로 넘겨요.","⟨1 8/11⟩ + ⟨3 7/11⟩ = ⟨5 4/11⟩."],"variant_rule":{"alt":[{"stem":"⟨4 4/7⟩ + ⟨1 4/7⟩를 계산하면 얼마인가요?","options":[{"t":"⟨6 1/7⟩","correct":true},{"t":"⟨5 1/7⟩","mis":"M4-2-u1-X07"},{"t":"⟨5 8/14⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 1/7⟩","mis":"M4-2-u1-X13"}],"explanation":["자연수끼리 4 + 1 = 5.","진분수끼리 ⟨4/7⟩ + ⟨4/7⟩ = ⟨8/7⟩ — 1보다 커서 ⟨1 1/7⟩, 1을 자연수로 넘겨요.","⟨4 4/7⟩ + ⟨1 4/7⟩ = ⟨6 1/7⟩."],"asset":null},{"stem":"⟨5 6/7⟩ + ⟨1 6/7⟩을 계산하면 얼마인가요?","options":[{"t":"⟨7 5/7⟩","correct":true},{"t":"⟨6 5/7⟩","mis":"M4-2-u1-X07"},{"t":"⟨6 12/14⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 5/7⟩","mis":"M4-2-u1-X13"}],"explanation":["자연수끼리 5 + 1 = 6.","진분수끼리 ⟨6/7⟩ + ⟨6/7⟩ = ⟨12/7⟩ — 1보다 커서 ⟨1 5/7⟩, 1을 자연수로 넘겨요.","⟨5 6/7⟩ + ⟨1 6/7⟩ = ⟨7 5/7⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L05_challenge#2','math',4,2,'u1','L05','g4_2_math_u1_L05_challenge','lesson_challenge','M4-2-u1-C5',2,'mc','auto','천연 비료를 만들려고 깻묵 ⟨2 2/3⟩ kg과 쌀겨 ⟨4 2/3⟩ kg을 섞었어요. 섞은 비료는 모두 몇 kg인가요?',ARRAY['M4-2-u1-X07','M4-2-u1-X01','M4-2-u1-X13']::text[],true,'{"seq":2,"concept":"M4-2-u1-C5","difficulty":2,"kind":"mc","stem":"천연 비료를 만들려고 깻묵 ⟨2 2/3⟩ kg과 쌀겨 ⟨4 2/3⟩ kg을 섞었어요. 섞은 비료는 모두 몇 kg인가요?","options":[{"t":"⟨7 1/3⟩ kg","correct":true},{"t":"⟨6 1/3⟩ kg","mis":"M4-2-u1-X07"},{"t":"⟨6 4/6⟩ kg","mis":"M4-2-u1-X01"},{"t":"⟨1 1/3⟩ kg","mis":"M4-2-u1-X13"}],"explanation":["자연수끼리 2 + 4 = 6.","진분수끼리 ⟨2/3⟩ + ⟨2/3⟩ = ⟨4/3⟩ — 1보다 커서 ⟨1 1/3⟩, 1을 자연수로 넘겨요.","⟨2 2/3⟩ + ⟨4 2/3⟩ = ⟨7 1/3⟩."],"variant_rule":{"alt":[{"stem":"천연 비료를 만들려고 깻묵 ⟨1 8/9⟩ kg과 쌀겨 ⟨3 4/9⟩ kg을 섞었어요. 섞은 비료는 모두 몇 kg인가요?","options":[{"t":"⟨5 3/9⟩ kg","correct":true},{"t":"⟨4 3/9⟩ kg","mis":"M4-2-u1-X07"},{"t":"⟨4 12/18⟩ kg","mis":"M4-2-u1-X01"},{"t":"⟨1 3/9⟩ kg","mis":"M4-2-u1-X13"}],"explanation":["자연수끼리 1 + 3 = 4.","진분수끼리 ⟨8/9⟩ + ⟨4/9⟩ = ⟨12/9⟩ — 1보다 커서 ⟨1 3/9⟩, 1을 자연수로 넘겨요.","⟨1 8/9⟩ + ⟨3 4/9⟩ = ⟨5 3/9⟩."],"asset":null},{"stem":"천연 비료를 만들려고 깻묵 ⟨4 2/5⟩ kg과 쌀겨 ⟨3 4/5⟩ kg을 섞었어요. 섞은 비료는 모두 몇 kg인가요?","options":[{"t":"⟨8 1/5⟩ kg","correct":true},{"t":"⟨7 1/5⟩ kg","mis":"M4-2-u1-X07"},{"t":"⟨7 6/10⟩ kg","mis":"M4-2-u1-X01"},{"t":"⟨1 1/5⟩ kg","mis":"M4-2-u1-X13"}],"explanation":["자연수끼리 4 + 3 = 7.","진분수끼리 ⟨2/5⟩ + ⟨4/5⟩ = ⟨6/5⟩ — 1보다 커서 ⟨1 1/5⟩, 1을 자연수로 넘겨요.","⟨4 2/5⟩ + ⟨3 4/5⟩ = ⟨8 1/5⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L05_challenge#3','math',4,2,'u1','L05','g4_2_math_u1_L05_challenge','lesson_challenge','M4-2-u1-C5',3,'error','auto','친구들이 대분수의 덧셈을 했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M4-2-u1-X07','M4-2-u1-X15']::text[],true,'{"seq":3,"concept":"M4-2-u1-C5","difficulty":3,"kind":"error","stem":"친구들이 대분수의 덧셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"준우 — ⟨1 2/4⟩ + ⟨3 3/4⟩ = ⟨4 1/4⟩","correct":true,"mis_target":"M4-2-u1-X07"},{"t":"서윤 — ⟨3 2/3⟩ + ⟨1 2/3⟩ = ⟨5 1/3⟩","mis":"M4-2-u1-X15"},{"t":"채원 — ⟨1 3/5⟩ + ⟨1 4/5⟩ = ⟨3 2/5⟩","mis":"M4-2-u1-X15"},{"t":"지훈 — ⟨1 6/9⟩ + ⟨1 2/9⟩ = ⟨2 8/9⟩","mis":"M4-2-u1-X15"}],"explanation":["자연수끼리 1 + 3 = 4.","진분수끼리 ⟨2/4⟩ + ⟨3/4⟩ = ⟨5/4⟩ — 1보다 커서 ⟨1 1/4⟩, 1을 자연수로 넘겨요.","⟨1 2/4⟩ + ⟨3 3/4⟩ = ⟨5 1/4⟩."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 친구들이 대분수의 덧셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"은비 — ⟨2 2/4⟩ + ⟨2 3/4⟩ = ⟨1 1/4⟩","correct":true,"mis_target":"M4-2-u1-X13"},{"t":"준우 — ⟨3 2/5⟩ + ⟨3 4/5⟩ = ⟨7 1/5⟩","mis":"M4-2-u1-X15"},{"t":"민서 — ⟨3 2/6⟩ + ⟨1 3/6⟩ = ⟨4 5/6⟩","mis":"M4-2-u1-X15"},{"t":"서윤 — ⟨3 4/6⟩ + ⟨3 5/6⟩ = ⟨7 3/6⟩","mis":"M4-2-u1-X15"}],"explanation":["자연수끼리 2 + 2 = 4.","진분수끼리 ⟨2/4⟩ + ⟨3/4⟩ = ⟨5/4⟩ — 1보다 커서 ⟨1 1/4⟩, 1을 자연수로 넘겨요.","⟨2 2/4⟩ + ⟨2 3/4⟩ = ⟨5 1/4⟩."],"asset":null},{"stem":"이번에는 다른 문제예요. 친구들이 대분수의 덧셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"민서 — ⟨3 3/4⟩ + ⟨1 3/4⟩ = ⟨4 2/4⟩","correct":true,"mis_target":"M4-2-u1-X07"},{"t":"지훈 — ⟨1 5/9⟩ + ⟨1 3/9⟩ = ⟨2 8/9⟩","mis":"M4-2-u1-X15"},{"t":"건우 — ⟨2 4/9⟩ + ⟨1 3/9⟩ = ⟨3 7/9⟩","mis":"M4-2-u1-X15"},{"t":"은비 — ⟨2 4/5⟩ + ⟨1 2/5⟩ = ⟨4 1/5⟩","mis":"M4-2-u1-X15"}],"explanation":["자연수끼리 3 + 1 = 4.","진분수끼리 ⟨3/4⟩ + ⟨3/4⟩ = ⟨6/4⟩ — 1보다 커서 ⟨1 2/4⟩, 1을 자연수로 넘겨요.","⟨3 3/4⟩ + ⟨1 3/4⟩ = ⟨5 2/4⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L05_challenge#4','math',4,2,'u1','L05','g4_2_math_u1_L05_challenge','lesson_challenge','M4-2-u1-C5',3,'sa','auto','⟨3 8/11⟩ + ⟨1 9/11⟩를 계산하여 대분수로 나타낼 때, 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u1-C5","difficulty":3,"kind":"sa","stem":"⟨3 8/11⟩ + ⟨1 9/11⟩를 계산하여 대분수로 나타낼 때, 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["자연수끼리 3 + 1 = 4.","진분수끼리 ⟨8/11⟩ + ⟨9/11⟩ = ⟨17/11⟩ — 1보다 커서 ⟨1 6/11⟩, 1을 자연수로 넘겨요.","⟨3 8/11⟩ + ⟨1 9/11⟩ = ⟨5 6/11⟩."],"variant_rule":{"alt":[{"stem":"⟨4 11/12⟩ + ⟨2 8/12⟩을 계산하여 대분수로 나타낼 때, 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["자연수끼리 4 + 2 = 6.","진분수끼리 ⟨11/12⟩ + ⟨8/12⟩ = ⟨19/12⟩ — 1보다 커서 ⟨1 7/12⟩, 1을 자연수로 넘겨요.","⟨4 11/12⟩ + ⟨2 8/12⟩ = ⟨7 7/12⟩."],"asset":null},{"stem":"⟨5 10/11⟩ + ⟨4 4/11⟩를 계산하여 대분수로 나타낼 때, 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["자연수끼리 5 + 4 = 9.","진분수끼리 ⟨10/11⟩ + ⟨4/11⟩ = ⟨14/11⟩ — 1보다 커서 ⟨1 3/11⟩, 1을 자연수로 넘겨요.","⟨5 10/11⟩ + ⟨4 4/11⟩ = ⟨10 3/11⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L05_challenge#5','math',4,2,'u1','L05','g4_2_math_u1_L05_challenge','lesson_challenge','M4-2-u1-C5',3,'sa','auto','⟨3 6/7⟩ + ⟨4 2/7⟩를 가분수로 바꾸어 계산하면 ⟨□/7⟩ + ⟨△/7⟩ = ⟨○/7⟩이에요. ○에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u1-C5","difficulty":3,"kind":"sa","stem":"⟨3 6/7⟩ + ⟨4 2/7⟩를 가분수로 바꾸어 계산하면 ⟨□/7⟩ + ⟨△/7⟩ = ⟨○/7⟩이에요. ○에 알맞은 수를 쓰세요.","answer":["57"],"explanation":["⟨3 6/7⟩ = ⟨27/7⟩, ⟨4 2/7⟩ = ⟨30/7⟩.","⟨27/7⟩ + ⟨30/7⟩ = ⟨57/7⟩.","○ = 57 — 대분수로 ⟨8 1/7⟩."],"variant_rule":{"alt":[{"stem":"⟨1 4/5⟩ + ⟨3 2/5⟩를 가분수로 바꾸어 계산하면 ⟨□/5⟩ + ⟨△/5⟩ = ⟨○/5⟩이에요. ○에 알맞은 수를 쓰세요.","answer":["26"],"explanation":["⟨1 4/5⟩ = ⟨9/5⟩, ⟨3 2/5⟩ = ⟨17/5⟩.","⟨9/5⟩ + ⟨17/5⟩ = ⟨26/5⟩.","○ = 26 — 대분수로 ⟨5 1/5⟩."],"asset":null},{"stem":"⟨2 5/7⟩ + ⟨1 4/7⟩를 가분수로 바꾸어 계산하면 ⟨□/7⟩ + ⟨△/7⟩ = ⟨○/7⟩이에요. ○에 알맞은 수를 쓰세요.","answer":["30"],"explanation":["⟨2 5/7⟩ = ⟨19/7⟩, ⟨1 4/7⟩ = ⟨11/7⟩.","⟨19/7⟩ + ⟨11/7⟩ = ⟨30/7⟩.","○ = 30 — 대분수로 ⟨4 2/7⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L05_challenge#6','math',4,2,'u1','L05','g4_2_math_u1_L05_challenge','lesson_challenge','M4-2-u1-C5',3,'mc','auto','⟨1 4/7⟩ + ⟨1 5/7⟩ ○ 4 — ○ 안에 알맞은 것은 무엇인가요?',ARRAY['M4-2-u1-X15','M4-2-u1-X18']::text[],true,'{"seq":6,"concept":"M4-2-u1-C5","difficulty":3,"kind":"mc","stem":"⟨1 4/7⟩ + ⟨1 5/7⟩ ○ 4 — ○ 안에 알맞은 것은 무엇인가요?","options":[{"t":"<","correct":true},{"t":">","mis":"M4-2-u1-X15"},{"t":"=","mis":"M4-2-u1-X18"},{"t":"알 수 없어요","mis":"M4-2-u1-X18"}],"explanation":["⟨1 4/7⟩ + ⟨1 5/7⟩ = ⟨3 2/7⟩.","4 = ⟨28/7⟩.","⟨3 2/7⟩ < 4."],"variant_rule":{"alt":[{"stem":"⟨2 4/9⟩ + ⟨3 6/9⟩ ○ 6 — ○ 안에 알맞은 것은 무엇인가요?","options":[{"t":">","correct":true},{"t":"<","mis":"M4-2-u1-X15"},{"t":"=","mis":"M4-2-u1-X18"},{"t":"알 수 없어요","mis":"M4-2-u1-X18"}],"explanation":["⟨2 4/9⟩ + ⟨3 6/9⟩ = ⟨6 1/9⟩.","6 = ⟨54/9⟩.","⟨6 1/9⟩ > 6."],"asset":null},{"stem":"⟨2 8/9⟩ + ⟨1 8/9⟩ ○ 4 — ○ 안에 알맞은 것은 무엇인가요?","options":[{"t":">","correct":true},{"t":"<","mis":"M4-2-u1-X15"},{"t":"=","mis":"M4-2-u1-X18"},{"t":"알 수 없어요","mis":"M4-2-u1-X18"}],"explanation":["⟨2 8/9⟩ + ⟨1 8/9⟩ = ⟨4 7/9⟩.","4 = ⟨36/9⟩.","⟨4 7/9⟩ > 4."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L05_challenge#7','math',4,2,'u1','L05','g4_2_math_u1_L05_challenge','lesson_challenge','M4-2-u1-C5',3,'mc','auto','⟨4 3/4⟩ + □ = ⟨8 2/4⟩일 때, □에 알맞은 대분수는 무엇인가요?',ARRAY['M4-2-u1-X14','M4-2-u1-X16']::text[],true,'{"seq":7,"concept":"M4-2-u1-C5","difficulty":3,"kind":"mc","stem":"⟨4 3/4⟩ + □ = ⟨8 2/4⟩일 때, □에 알맞은 대분수는 무엇인가요?","options":[{"t":"⟨3 3/4⟩","correct":true},{"t":"⟨13 1/4⟩","mis":"M4-2-u1-X14"},{"t":"4","mis":"M4-2-u1-X16"},{"t":"⟨3 2/4⟩","mis":"M4-2-u1-X16"}],"explanation":["□ = ⟨8 2/4⟩ − ⟨4 3/4⟩ — 덧셈을 뺄셈으로 바꾸어요.","가분수로 ⟨34/4⟩ − ⟨19/4⟩ = ⟨15/4⟩.","□ = ⟨3 3/4⟩."],"variant_rule":{"alt":[{"stem":"⟨2 1/5⟩ + □ = ⟨6 3/5⟩일 때, □에 알맞은 대분수는 무엇인가요?","options":[{"t":"⟨4 2/5⟩","correct":true},{"t":"⟨8 4/5⟩","mis":"M4-2-u1-X14"},{"t":"⟨4 3/5⟩","mis":"M4-2-u1-X16"},{"t":"⟨4 1/5⟩","mis":"M4-2-u1-X16"}],"explanation":["□ = ⟨6 3/5⟩ − ⟨2 1/5⟩ — 덧셈을 뺄셈으로 바꾸어요.","가분수로 ⟨33/5⟩ − ⟨11/5⟩ = ⟨22/5⟩.","□ = ⟨4 2/5⟩."],"asset":null},{"stem":"⟨1 3/5⟩ + □ = ⟨6 2/5⟩일 때, □에 알맞은 대분수는 무엇인가요?","options":[{"t":"⟨4 4/5⟩","correct":true},{"t":"8","mis":"M4-2-u1-X14"},{"t":"5","mis":"M4-2-u1-X16"},{"t":"⟨4 3/5⟩","mis":"M4-2-u1-X16"}],"explanation":["□ = ⟨6 2/5⟩ − ⟨1 3/5⟩ — 덧셈을 뺄셈으로 바꾸어요.","가분수로 ⟨32/5⟩ − ⟨8/5⟩ = ⟨24/5⟩.","□ = ⟨4 4/5⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L05_challenge#8','math',4,2,'u1','L05','g4_2_math_u1_L05_challenge','lesson_challenge','M4-2-u1-C5',4,'essay','teacher','⟨1 3/5⟩ + ⟨1 4/5⟩를 두 가지 방법(자연수끼리·진분수끼리 더하기, 가분수로 바꾸어 더하기)으로 계산하고 두 답이 같은지 확인해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u1-C5","difficulty":4,"kind":"essay","stem":"⟨1 3/5⟩ + ⟨1 4/5⟩를 두 가지 방법(자연수끼리·진분수끼리 더하기, 가분수로 바꾸어 더하기)으로 계산하고 두 답이 같은지 확인해 보세요.","answer_guide":{"answer":"예: ① 자연수끼리 1 + 1 = 2, 진분수끼리 ⟨3/5⟩ + ⟨4/5⟩ = ⟨7/5⟩ = ⟨1 2/5⟩이므로 2 + ⟨1 2/5⟩ = ⟨3 2/5⟩. ② ⟨8/5⟩ + ⟨9/5⟩ = ⟨17/5⟩ = ⟨3 2/5⟩. 두 답이 ⟨3 2/5⟩로 같다.","scoring_points":["방법 ①로 ⟨3 2/5⟩를 구했는가","방법 ②로 ⟨17/5⟩ = ⟨3 2/5⟩를 구했는가","진분수끼리의 합에서 1을 자연수로 넘겼는가"]},"explanation":["2 + ⟨7/5⟩ = ⟨3 2/5⟩.","⟨8/5⟩ + ⟨9/5⟩ = ⟨17/5⟩.","⟨3 2/5⟩로 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L05_challenge#9','math',4,2,'u1','L05','g4_2_math_u1_L05_challenge','lesson_challenge','M4-2-u1-C5',4,'essay','teacher','천연 비료를 만들려고 깻묵 ⟨2 5/8⟩ kg과 쌀겨 ⟨1 6/8⟩ kg을 섞었어요. 은비는 「⟨3 11/8⟩ kg이야.」라고 했어요. 은비의 답을 바른 대분수로 고치고 그 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u1-C5","difficulty":4,"kind":"essay","stem":"천연 비료를 만들려고 깻묵 ⟨2 5/8⟩ kg과 쌀겨 ⟨1 6/8⟩ kg을 섞었어요. 은비는 「⟨3 11/8⟩ kg이야.」라고 했어요. 은비의 답을 바른 대분수로 고치고 그 까닭을 써 보세요.","answer_guide":{"answer":"예: 진분수끼리 ⟨5/8⟩ + ⟨6/8⟩ = ⟨11/8⟩ = ⟨1 3/8⟩이므로 넘친 1을 자연수 3에 더해 ⟨4 3/8⟩ kg이다. 대분수의 분수 부분은 진분수여야 하므로 ⟨3 11/8⟩은 바른 대분수가 아니다.","scoring_points":["⟨4 3/8⟩ kg으로 고쳤는가","⟨11/8⟩ = ⟨1 3/8⟩으로 바꾸었는가","분수 부분은 진분수여야 한다고 썼는가"]},"explanation":["⟨11/8⟩ = ⟨1 3/8⟩.","3 + 1 = 4.","⟨4 3/8⟩ kg."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
