INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L06_basic#7','math',4,2,'u1','L06','g4_2_math_u1_L06_basic','lesson_basic','M4-2-u1-C6',2,'mc','auto','드론 약품 통에 약품이 ⟨6 3/7⟩ L 있었어요. 밭에 ⟨3 2/7⟩ L를 뿌렸다면 남은 약품은 몇 L인가요?',ARRAY['M4-2-u1-X13','M4-2-u1-X14','M4-2-u1-X01']::text[],true,'{"seq":7,"concept":"M4-2-u1-C6","difficulty":2,"kind":"mc","stem":"드론 약품 통에 약품이 ⟨6 3/7⟩ L 있었어요. 밭에 ⟨3 2/7⟩ L를 뿌렸다면 남은 약품은 몇 L인가요?","options":[{"t":"⟨3 1/7⟩ L","correct":true},{"t":"⟨1/7⟩ L","mis":"M4-2-u1-X13"},{"t":"⟨9 5/7⟩ L","mis":"M4-2-u1-X14"},{"t":"⟨3 1/5⟩ L","mis":"M4-2-u1-X01"}],"explanation":["자연수끼리 6 − 3 = 3.","진분수끼리 ⟨3/7⟩ − ⟨2/7⟩ = ⟨1/7⟩.","⟨6 3/7⟩ − ⟨3 2/7⟩ = ⟨3 1/7⟩."],"variant_rule":{"alt":[{"stem":"드론 약품 통에 약품이 ⟨4 6/9⟩ L 있었어요. 밭에 ⟨1 2/9⟩ L를 뿌렸다면 남은 약품은 몇 L인가요?","options":[{"t":"⟨3 4/9⟩ L","correct":true},{"t":"⟨4/9⟩ L","mis":"M4-2-u1-X13"},{"t":"⟨5 8/9⟩ L","mis":"M4-2-u1-X14"},{"t":"⟨3 4/7⟩ L","mis":"M4-2-u1-X01"}],"explanation":["자연수끼리 4 − 1 = 3.","진분수끼리 ⟨6/9⟩ − ⟨2/9⟩ = ⟨4/9⟩.","⟨4 6/9⟩ − ⟨1 2/9⟩ = ⟨3 4/9⟩."],"asset":null},{"stem":"드론 약품 통에 약품이 ⟨5 4/5⟩ L 있었어요. 밭에 ⟨2 3/5⟩ L를 뿌렸다면 남은 약품은 몇 L인가요?","options":[{"t":"⟨3 1/5⟩ L","correct":true},{"t":"⟨1/5⟩ L","mis":"M4-2-u1-X13"},{"t":"⟨8 2/5⟩ L","mis":"M4-2-u1-X14"},{"t":"⟨3 1/2⟩ L","mis":"M4-2-u1-X01"}],"explanation":["자연수끼리 5 − 2 = 3.","진분수끼리 ⟨4/5⟩ − ⟨3/5⟩ = ⟨1/5⟩.","⟨5 4/5⟩ − ⟨2 3/5⟩ = ⟨3 1/5⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L06_basic#8','math',4,2,'u1','L06','g4_2_math_u1_L06_basic','lesson_basic','M4-2-u1-C6',2,'ox','auto','채원이 「⟨3 2/5⟩ − ⟨2 1/5⟩ = ⟨1/5⟩이야.」라고 했어요. 바르게 계산했어요.',ARRAY['M4-2-u1-X13']::text[],true,'{"seq":8,"concept":"M4-2-u1-C6","difficulty":2,"kind":"ox","stem":"채원이 「⟨3 2/5⟩ − ⟨2 1/5⟩ = ⟨1/5⟩이야.」라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"자연수끼리도 빼서 1을 써야 해서","correct":true},{"t":"진분수끼리만 빼면 되어서","mis":"M4-2-u1-X13"}],"mis":"M4-2-u1-X13","explanation":["자연수끼리 3 − 2 = 1.","진분수끼리 ⟨2/5⟩ − ⟨1/5⟩ = ⟨1/5⟩.","⟨3 2/5⟩ − ⟨2 1/5⟩ = ⟨1 1/5⟩."],"variant_rule":{"alt":[{"stem":"지훈이 「⟨6 2/5⟩ − ⟨2 1/5⟩ = ⟨4 1/5⟩이야.」라고 했어요. 바르게 계산했어요.","answer":"O","reason_options":[{"t":"자연수끼리, 진분수끼리 바르게 빼서","correct":true},{"t":"분모끼리도 빼야 해서","mis":"M4-2-u1-X01"}],"explanation":["자연수끼리 6 − 2 = 4.","진분수끼리 ⟨2/5⟩ − ⟨1/5⟩ = ⟨1/5⟩.","⟨6 2/5⟩ − ⟨2 1/5⟩ = ⟨4 1/5⟩."],"asset":null},{"stem":"채원이 「⟨4 3/8⟩ − ⟨1 1/8⟩ = ⟨2/8⟩야.」라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"자연수끼리도 빼서 3을 써야 해서","correct":true},{"t":"진분수끼리만 빼면 되어서","mis":"M4-2-u1-X13"}],"explanation":["자연수끼리 4 − 1 = 3.","진분수끼리 ⟨3/8⟩ − ⟨1/8⟩ = ⟨2/8⟩.","⟨4 3/8⟩ − ⟨1 1/8⟩ = ⟨3 2/8⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
