INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L06_challenge#2','math',4,2,'u1','L06','g4_2_math_u1_L06_challenge','lesson_challenge','M4-2-u1-C6',2,'mc','auto','드론 약품 통에 약품이 ⟨8 10/11⟩ L 있었어요. 밭에 ⟨7 4/11⟩ L를 뿌렸다면 남은 약품은 몇 L인가요?',ARRAY['M4-2-u1-X13','M4-2-u1-X14','M4-2-u1-X01']::text[],true,'{"seq":2,"concept":"M4-2-u1-C6","difficulty":2,"kind":"mc","stem":"드론 약품 통에 약품이 ⟨8 10/11⟩ L 있었어요. 밭에 ⟨7 4/11⟩ L를 뿌렸다면 남은 약품은 몇 L인가요?","options":[{"t":"⟨1 6/11⟩ L","correct":true},{"t":"⟨6/11⟩ L","mis":"M4-2-u1-X13"},{"t":"⟨16 3/11⟩ L","mis":"M4-2-u1-X14"},{"t":"⟨1 6/7⟩ L","mis":"M4-2-u1-X01"}],"explanation":["자연수끼리 8 − 7 = 1.","진분수끼리 ⟨10/11⟩ − ⟨4/11⟩ = ⟨6/11⟩.","⟨8 10/11⟩ − ⟨7 4/11⟩ = ⟨1 6/11⟩."],"variant_rule":{"alt":[{"stem":"드론 약품 통에 약품이 ⟨3 4/11⟩ L 있었어요. 밭에 ⟨2 1/11⟩ L를 뿌렸다면 남은 약품은 몇 L인가요?","options":[{"t":"⟨1 3/11⟩ L","correct":true},{"t":"⟨3/11⟩ L","mis":"M4-2-u1-X13"},{"t":"⟨5 5/11⟩ L","mis":"M4-2-u1-X14"},{"t":"⟨1 3/10⟩ L","mis":"M4-2-u1-X01"}],"explanation":["자연수끼리 3 − 2 = 1.","진분수끼리 ⟨4/11⟩ − ⟨1/11⟩ = ⟨3/11⟩.","⟨3 4/11⟩ − ⟨2 1/11⟩ = ⟨1 3/11⟩."],"asset":null},{"stem":"드론 약품 통에 약품이 ⟨7 4/9⟩ L 있었어요. 밭에 ⟨2 3/9⟩ L를 뿌렸다면 남은 약품은 몇 L인가요?","options":[{"t":"⟨5 1/9⟩ L","correct":true},{"t":"⟨1/9⟩ L","mis":"M4-2-u1-X13"},{"t":"⟨9 7/9⟩ L","mis":"M4-2-u1-X14"},{"t":"⟨5 1/6⟩ L","mis":"M4-2-u1-X01"}],"explanation":["자연수끼리 7 − 2 = 5.","진분수끼리 ⟨4/9⟩ − ⟨3/9⟩ = ⟨1/9⟩.","⟨7 4/9⟩ − ⟨2 3/9⟩ = ⟨5 1/9⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
