INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L06_challenge#4','math',4,2,'u1','L06','g4_2_math_u1_L06_challenge','lesson_challenge','M4-2-u1-C6',3,'sa','auto','⟨3 2/4⟩ − ⟨1 1/4⟩을 가분수로 바꾸어 계산하면 ⟨□/4⟩ − ⟨△/4⟩ = ⟨○/4⟩이에요. ○에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u1-C6","difficulty":3,"kind":"sa","stem":"⟨3 2/4⟩ − ⟨1 1/4⟩을 가분수로 바꾸어 계산하면 ⟨□/4⟩ − ⟨△/4⟩ = ⟨○/4⟩이에요. ○에 알맞은 수를 쓰세요.","answer":["9"],"explanation":["⟨3 2/4⟩ = ⟨14/4⟩, ⟨1 1/4⟩ = ⟨5/4⟩.","⟨14/4⟩ − ⟨5/4⟩ = ⟨9/4⟩.","○ = 9 — 대분수로 ⟨2 1/4⟩."],"variant_rule":{"alt":[{"stem":"⟨4 2/4⟩ − ⟨3 1/4⟩을 가분수로 바꾸어 계산하면 ⟨□/4⟩ − ⟨△/4⟩ = ⟨○/4⟩이에요. ○에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["⟨4 2/4⟩ = ⟨18/4⟩, ⟨3 1/4⟩ = ⟨13/4⟩.","⟨18/4⟩ − ⟨13/4⟩ = ⟨5/4⟩.","○ = 5 — 대분수로 ⟨1 1/4⟩."],"asset":null},{"stem":"⟨2 7/8⟩ − ⟨1 4/8⟩를 가분수로 바꾸어 계산하면 ⟨□/8⟩ − ⟨△/8⟩ = ⟨○/8⟩이에요. ○에 알맞은 수를 쓰세요.","answer":["11"],"explanation":["⟨2 7/8⟩ = ⟨23/8⟩, ⟨1 4/8⟩ = ⟨12/8⟩.","⟨23/8⟩ − ⟨12/8⟩ = ⟨11/8⟩.","○ = 11 — 대분수로 ⟨1 3/8⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
