INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L06_challenge#6','math',4,2,'u1','L06','g4_2_math_u1_L06_challenge','lesson_challenge','M4-2-u1-C6',3,'ox','auto','민서가 「⟨6 6/12⟩ − ⟨3 3/12⟩ = ⟨3 3/12⟩이야.」라고 했어요. 바르게 계산했어요.',ARRAY['M4-2-u1-X01']::text[],true,'{"seq":6,"concept":"M4-2-u1-C6","difficulty":3,"kind":"ox","stem":"민서가 「⟨6 6/12⟩ − ⟨3 3/12⟩ = ⟨3 3/12⟩이야.」라고 했어요. 바르게 계산했어요.","answer":"O","reason_options":[{"t":"자연수끼리, 진분수끼리 바르게 빼서","correct":true},{"t":"분모끼리도 빼야 해서","mis":"M4-2-u1-X01"}],"mis":"M4-2-u1-X01","explanation":["자연수끼리 6 − 3 = 3.","진분수끼리 ⟨6/12⟩ − ⟨3/12⟩ = ⟨3/12⟩.","⟨6 6/12⟩ − ⟨3 3/12⟩ = ⟨3 3/12⟩."],"variant_rule":{"alt":[{"stem":"은비가 「⟨3 4/10⟩ − ⟨1 2/10⟩ = ⟨2/10⟩야.」라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"자연수끼리도 빼서 2를 써야 해서","correct":true},{"t":"진분수끼리만 빼면 되어서","mis":"M4-2-u1-X13"}],"explanation":["자연수끼리 3 − 1 = 2.","진분수끼리 ⟨4/10⟩ − ⟨2/10⟩ = ⟨2/10⟩.","⟨3 4/10⟩ − ⟨1 2/10⟩ = ⟨2 2/10⟩."],"asset":null},{"stem":"민서가 「⟨6 3/5⟩ − ⟨4 1/5⟩ = ⟨2 2/5⟩야.」라고 했어요. 바르게 계산했어요.","answer":"O","reason_options":[{"t":"자연수끼리, 진분수끼리 바르게 빼서","correct":true},{"t":"분모끼리도 빼야 해서","mis":"M4-2-u1-X01"}],"explanation":["자연수끼리 6 − 4 = 2.","진분수끼리 ⟨3/5⟩ − ⟨1/5⟩ = ⟨2/5⟩.","⟨6 3/5⟩ − ⟨4 1/5⟩ = ⟨2 2/5⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L06_challenge#7','math',4,2,'u1','L06','g4_2_math_u1_L06_challenge','lesson_challenge','M4-2-u1-C6',3,'sa','auto','⟨6 8/10⟩ − ⟨4 7/10⟩을 계산하면 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-2-u1-C6","difficulty":3,"kind":"sa","stem":"⟨6 8/10⟩ − ⟨4 7/10⟩을 계산하면 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["자연수끼리 6 − 4 = 2.","진분수끼리 ⟨8/10⟩ − ⟨7/10⟩ = ⟨1/10⟩.","⟨6 8/10⟩ − ⟨4 7/10⟩ = ⟨2 1/10⟩."],"variant_rule":{"alt":[{"stem":"⟨9 3/9⟩ − ⟨7 2/9⟩를 계산하면 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["자연수끼리 9 − 7 = 2.","진분수끼리 ⟨3/9⟩ − ⟨2/9⟩ = ⟨1/9⟩.","⟨9 3/9⟩ − ⟨7 2/9⟩ = ⟨2 1/9⟩."],"asset":null},{"stem":"⟨3 5/11⟩ − ⟨1 3/11⟩을 계산하면 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["자연수끼리 3 − 1 = 2.","진분수끼리 ⟨5/11⟩ − ⟨3/11⟩ = ⟨2/11⟩.","⟨3 5/11⟩ − ⟨1 3/11⟩ = ⟨2 2/11⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L06_challenge#8','math',4,2,'u1','L06','g4_2_math_u1_L06_challenge','lesson_challenge','M4-2-u1-C6',4,'essay','teacher','드론 약품 통에 약품이 ⟨3 5/6⟩ L 있었는데 ⟨1 2/6⟩ L를 뿌렸어요. 남은 약품의 양을 두 가지 방법(자연수끼리·진분수끼리 빼기, 가분수로 바꾸어 빼기)으로 구해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u1-C6","difficulty":4,"kind":"essay","stem":"드론 약품 통에 약품이 ⟨3 5/6⟩ L 있었는데 ⟨1 2/6⟩ L를 뿌렸어요. 남은 약품의 양을 두 가지 방법(자연수끼리·진분수끼리 빼기, 가분수로 바꾸어 빼기)으로 구해 보세요.","answer_guide":{"answer":"예: ① 자연수끼리 3 − 1 = 2, 진분수끼리 ⟨5/6⟩ − ⟨2/6⟩ = ⟨3/6⟩이므로 ⟨2 3/6⟩ L. ② ⟨23/6⟩ − ⟨8/6⟩ = ⟨15/6⟩ = ⟨2 3/6⟩ L. 두 방법의 답이 같다.","scoring_points":["방법 ①로 ⟨2 3/6⟩을 구했는가","방법 ②로 ⟨23/6⟩ − ⟨8/6⟩ = ⟨15/6⟩를 구했는가","⟨2 3/6⟩ L라고 답했는가"]},"explanation":["2 + ⟨3/6⟩.","⟨23/6⟩ − ⟨8/6⟩ = ⟨15/6⟩.","⟨2 3/6⟩ L."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L06_challenge#9','math',4,2,'u1','L06','g4_2_math_u1_L06_challenge','lesson_challenge','M4-2-u1-C6',4,'essay','teacher','⟨4 3/5⟩ − ⟨4 1/5⟩을 계산하고, 「⟨0 2/5⟩」라고 쓰지 않고 어떻게 나타내야 하는지 까닭과 함께 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u1-C6","difficulty":4,"kind":"essay","stem":"⟨4 3/5⟩ − ⟨4 1/5⟩을 계산하고, 「⟨0 2/5⟩」라고 쓰지 않고 어떻게 나타내야 하는지 까닭과 함께 써 보세요.","answer_guide":{"answer":"예: 자연수끼리 4 − 4 = 0, 진분수끼리 ⟨3/5⟩ − ⟨1/5⟩ = ⟨2/5⟩이므로 답은 ⟨2/5⟩이다. 자연수 부분이 0이면 대분수가 아니라 진분수로 나타낸다.","scoring_points":["⟨2/5⟩라고 답했는가","자연수끼리 빼서 0이 된다고 썼는가","자연수 부분이 0이면 진분수로 쓴다고 했는가"]},"explanation":["4 − 4 = 0.","⟨3/5⟩ − ⟨1/5⟩ = ⟨2/5⟩.","답은 ⟨2/5⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L06_challenge#10','math',4,2,'u1','L06','g4_2_math_u1_L06_challenge','lesson_challenge','M4-2-u1-C6',4,'mc','auto','⟨8 10/11⟩ − □ = ⟨7 7/11⟩일 때, □에 알맞은 대분수는 무엇인가요?',ARRAY['M4-2-u1-X14','M4-2-u1-X16']::text[],true,'{"seq":10,"concept":"M4-2-u1-C6","difficulty":4,"kind":"mc","stem":"⟨8 10/11⟩ − □ = ⟨7 7/11⟩일 때, □에 알맞은 대분수는 무엇인가요?","options":[{"t":"⟨1 3/11⟩","correct":true},{"t":"⟨16 6/11⟩","mis":"M4-2-u1-X14"},{"t":"⟨1 4/11⟩","mis":"M4-2-u1-X16"},{"t":"⟨1 2/11⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨8 10/11⟩에서 □를 덜어 ⟨7 7/11⟩이 남았어요.","□ = ⟨8 10/11⟩ − ⟨7 7/11⟩.","□ = ⟨1 3/11⟩."],"variant_rule":{"alt":[{"stem":"⟨7 10/11⟩ − □ = ⟨5 2/11⟩일 때, □에 알맞은 대분수는 무엇인가요?","options":[{"t":"⟨2 8/11⟩","correct":true},{"t":"⟨13 1/11⟩","mis":"M4-2-u1-X14"},{"t":"⟨2 9/11⟩","mis":"M4-2-u1-X16"},{"t":"⟨2 7/11⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨7 10/11⟩에서 □를 덜어 ⟨5 2/11⟩가 남았어요.","□ = ⟨7 10/11⟩ − ⟨5 2/11⟩.","□ = ⟨2 8/11⟩."],"asset":null},{"stem":"⟨2 4/9⟩ − □ = ⟨1 3/9⟩일 때, □에 알맞은 대분수는 무엇인가요?","options":[{"t":"⟨1 1/9⟩","correct":true},{"t":"⟨3 7/9⟩","mis":"M4-2-u1-X14"},{"t":"⟨1 2/9⟩","mis":"M4-2-u1-X16"},{"t":"1","mis":"M4-2-u1-X16"}],"explanation":["⟨2 4/9⟩에서 □를 덜어 ⟨1 3/9⟩이 남았어요.","□ = ⟨2 4/9⟩ − ⟨1 3/9⟩.","□ = ⟨1 1/9⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L07_basic#1','math',4,2,'u1','L07','g4_2_math_u1_L07_basic','lesson_basic','M4-2-u1-C7',1,'sa','auto','3 − ⟨1/4⟩을 계산하려고 3을 ⟨2 □/4⟩로 바꾸었어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-2-u1-C7","difficulty":1,"kind":"sa","stem":"3 − ⟨1/4⟩을 계산하려고 3을 ⟨2 □/4⟩로 바꾸었어요. □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["1 = ⟨4/4⟩예요.","3 = 2 + 1 = ⟨2 4/4⟩.","□ = 4."],"variant_rule":{"alt":[{"stem":"5 − ⟨2/3⟩를 계산하려고 5를 ⟨4 □/3⟩로 바꾸었어요. □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["1 = ⟨3/3⟩이에요.","5 = 4 + 1 = ⟨4 3/3⟩.","□ = 3."],"asset":null},{"stem":"4 − ⟨6/7⟩을 계산하려고 4를 ⟨3 □/7⟩로 바꾸었어요. □에 알맞은 수를 쓰세요.","answer":["7"],"explanation":["1 = ⟨7/7⟩이에요.","4 = 3 + 1 = ⟨3 7/7⟩.","□ = 7."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L07_basic#2','math',4,2,'u1','L07','g4_2_math_u1_L07_basic','lesson_basic','M4-2-u1-C7',1,'sa','auto','5 − ⟨2/6⟩ = ⟨4 □/6⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u1-C7","difficulty":1,"kind":"sa","stem":"5 − ⟨2/6⟩ = ⟨4 □/6⟩ — □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["5에서 1만큼을 ⟨6/6⟩으로 바꾸어요 — 5 = ⟨4 6/6⟩.","⟨6/6⟩ − ⟨2/6⟩ = ⟨4/6⟩.","5 − ⟨2/6⟩ = ⟨4 4/6⟩ — 자연수 부분은 1 줄어요."],"variant_rule":{"alt":[{"stem":"2 − ⟨1/7⟩ = ⟨1 □/7⟩ — □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["2에서 1만큼을 ⟨7/7⟩로 바꾸어요 — 2 = ⟨1 7/7⟩.","⟨7/7⟩ − ⟨1/7⟩ = ⟨6/7⟩.","2 − ⟨1/7⟩ = ⟨1 6/7⟩ — 자연수 부분은 1 줄어요."],"asset":null},{"stem":"2 − ⟨2/6⟩ = ⟨1 □/6⟩ — □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["2에서 1만큼을 ⟨6/6⟩으로 바꾸어요 — 2 = ⟨1 6/6⟩.","⟨6/6⟩ − ⟨2/6⟩ = ⟨4/6⟩.","2 − ⟨2/6⟩ = ⟨1 4/6⟩ — 자연수 부분은 1 줄어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L07_basic#3','math',4,2,'u1','L07','g4_2_math_u1_L07_basic','lesson_basic','M4-2-u1-C7',1,'mc','auto','3 − ⟨1/4⟩을 계산하면 얼마인가요?',ARRAY['M4-2-u1-X09','M4-2-u1-X10','M4-2-u1-X16']::text[],true,'{"seq":3,"concept":"M4-2-u1-C7","difficulty":1,"kind":"mc","stem":"3 − ⟨1/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨2 3/4⟩","correct":true},{"t":"⟨3 3/4⟩","mis":"M4-2-u1-X09"},{"t":"⟨2 1/4⟩","mis":"M4-2-u1-X10"},{"t":"⟨2 2/4⟩","mis":"M4-2-u1-X16"}],"explanation":["3에서 1만큼을 ⟨4/4⟩로 바꾸어요 — 3 = ⟨2 4/4⟩.","⟨4/4⟩ − ⟨1/4⟩ = ⟨3/4⟩.","3 − ⟨1/4⟩ = ⟨2 3/4⟩ — 자연수 부분은 1 줄어요."],"variant_rule":{"alt":[{"stem":"5 − ⟨1/5⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4 4/5⟩","correct":true},{"t":"⟨5 4/5⟩","mis":"M4-2-u1-X09"},{"t":"⟨4 1/5⟩","mis":"M4-2-u1-X10"},{"t":"⟨4 3/5⟩","mis":"M4-2-u1-X16"}],"explanation":["5에서 1만큼을 ⟨5/5⟩로 바꾸어요 — 5 = ⟨4 5/5⟩.","⟨5/5⟩ − ⟨1/5⟩ = ⟨4/5⟩.","5 − ⟨1/5⟩ = ⟨4 4/5⟩ — 자연수 부분은 1 줄어요."],"asset":null},{"stem":"4 − ⟨1/7⟩을 계산하면 얼마인가요?","options":[{"t":"⟨3 6/7⟩","correct":true},{"t":"⟨4 6/7⟩","mis":"M4-2-u1-X09"},{"t":"⟨3 1/7⟩","mis":"M4-2-u1-X10"},{"t":"⟨3 5/7⟩","mis":"M4-2-u1-X16"}],"explanation":["4에서 1만큼을 ⟨7/7⟩로 바꾸어요 — 4 = ⟨3 7/7⟩.","⟨7/7⟩ − ⟨1/7⟩ = ⟨6/7⟩.","4 − ⟨1/7⟩ = ⟨3 6/7⟩ — 자연수 부분은 1 줄어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L07_basic#4','math',4,2,'u1','L07','g4_2_math_u1_L07_basic','lesson_basic','M4-2-u1-C8',1,'sa','auto','⟨2 1/5⟩을 자연수 부분에서 1만큼 바꾸어 ⟨1 □/5⟩로 나타내려고 해요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u1-C8","difficulty":1,"kind":"sa","stem":"⟨2 1/5⟩을 자연수 부분에서 1만큼 바꾸어 ⟨1 □/5⟩로 나타내려고 해요. □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["1 = ⟨5/5⟩.","⟨2 1/5⟩ = 1 + ⟨5/5⟩ + ⟨1/5⟩ = ⟨1 6/5⟩.","□ = 5 + 1 = 6 — 10을 더하지 않아요."],"variant_rule":{"alt":[{"stem":"⟨3 2/7⟩를 자연수 부분에서 1만큼 바꾸어 ⟨2 □/7⟩로 나타내려고 해요. □에 알맞은 수를 쓰세요.","answer":["9"],"explanation":["1 = ⟨7/7⟩.","⟨3 2/7⟩ = 2 + ⟨7/7⟩ + ⟨2/7⟩ = ⟨2 9/7⟩.","□ = 7 + 2 = 9 — 10을 더하지 않아요."],"asset":null},{"stem":"⟨5 7/8⟩을 자연수 부분에서 1만큼 바꾸어 ⟨4 □/8⟩로 나타내려고 해요. □에 알맞은 수를 쓰세요.","answer":["15"],"explanation":["1 = ⟨8/8⟩.","⟨5 7/8⟩ = 4 + ⟨8/8⟩ + ⟨7/8⟩ = ⟨4 15/8⟩.","□ = 8 + 7 = 15 — 10을 더하지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L07_basic#5','math',4,2,'u1','L07','g4_2_math_u1_L07_basic','lesson_basic','M4-2-u1-C8',2,'mc','auto','⟨2 1/5⟩ − ⟨3/5⟩을 계산하면 얼마인가요?',ARRAY['M4-2-u1-X11','M4-2-u1-X09','M4-2-u1-X12']::text[],true,'{"seq":5,"concept":"M4-2-u1-C8","difficulty":2,"kind":"mc","stem":"⟨2 1/5⟩ − ⟨3/5⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1 3/5⟩","correct":true},{"t":"⟨2 2/5⟩","mis":"M4-2-u1-X11"},{"t":"⟨2 3/5⟩","mis":"M4-2-u1-X09"},{"t":"⟨1 8/5⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨1/5⟩ − ⟨3/5⟩ — 진분수끼리 뺄 수 없어요(1 < 3).","1만큼 바꾸어요 — ⟨2 1/5⟩ = ⟨1 6/5⟩.","⟨1 6/5⟩ − ⟨3/5⟩ = ⟨1 3/5⟩ — 자연수 부분은 1 줄어요."],"variant_rule":{"alt":[{"stem":"⟨5 5/8⟩ − ⟨7/8⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4 6/8⟩","correct":true},{"t":"⟨5 2/8⟩","mis":"M4-2-u1-X11"},{"t":"⟨5 6/8⟩","mis":"M4-2-u1-X09"},{"t":"⟨4 8/8⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨5/8⟩ − ⟨7/8⟩ — 진분수끼리 뺄 수 없어요(5 < 7).","1만큼 바꾸어요 — ⟨5 5/8⟩ = ⟨4 13/8⟩.","⟨4 13/8⟩ − ⟨7/8⟩ = ⟨4 6/8⟩ — 자연수 부분은 1 줄어요."],"asset":null},{"stem":"⟨5 6/8⟩ − ⟨7/8⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4 7/8⟩","correct":true},{"t":"⟨5 1/8⟩","mis":"M4-2-u1-X11"},{"t":"⟨5 7/8⟩","mis":"M4-2-u1-X09"},{"t":"⟨4 9/8⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨6/8⟩ − ⟨7/8⟩ — 진분수끼리 뺄 수 없어요(6 < 7).","1만큼 바꾸어요 — ⟨5 6/8⟩ = ⟨4 14/8⟩.","⟨4 14/8⟩ − ⟨7/8⟩ = ⟨4 7/8⟩ — 자연수 부분은 1 줄어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L07_basic#6','math',4,2,'u1','L07','g4_2_math_u1_L07_basic','lesson_basic','M4-2-u1-C7',2,'mc','auto','4 − ⟨2 3/6⟩을 계산하면 얼마인가요?',ARRAY['M4-2-u1-X09','M4-2-u1-X16']::text[],true,'{"seq":6,"concept":"M4-2-u1-C7","difficulty":2,"kind":"mc","stem":"4 − ⟨2 3/6⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1 3/6⟩","correct":true},{"t":"⟨2 3/6⟩","mis":"M4-2-u1-X09"},{"t":"⟨1 4/6⟩","mis":"M4-2-u1-X16"},{"t":"⟨1 2/6⟩","mis":"M4-2-u1-X16"}],"explanation":["4 = ⟨3 6/6⟩으로 바꾸어요.","자연수끼리 3 − 2 = 1, 분수끼리 ⟨6/6⟩ − ⟨3/6⟩ = ⟨3/6⟩.","4 − ⟨2 3/6⟩ = ⟨1 3/6⟩."],"variant_rule":{"alt":[{"stem":"3 − ⟨1 2/4⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1 2/4⟩","correct":true},{"t":"⟨2 2/4⟩","mis":"M4-2-u1-X09"},{"t":"⟨1 3/4⟩","mis":"M4-2-u1-X16"},{"t":"⟨1 1/4⟩","mis":"M4-2-u1-X16"}],"explanation":["3 = ⟨2 4/4⟩로 바꾸어요.","자연수끼리 2 − 1 = 1, 분수끼리 ⟨4/4⟩ − ⟨2/4⟩ = ⟨2/4⟩.","3 − ⟨1 2/4⟩ = ⟨1 2/4⟩."],"asset":null},{"stem":"8 − ⟨6 1/7⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1 6/7⟩","correct":true},{"t":"⟨2 6/7⟩","mis":"M4-2-u1-X09"},{"t":"⟨1 1/7⟩","mis":"M4-2-u1-X10"},{"t":"2","mis":"M4-2-u1-X16"}],"explanation":["8 = ⟨7 7/7⟩로 바꾸어요.","자연수끼리 7 − 6 = 1, 분수끼리 ⟨7/7⟩ − ⟨1/7⟩ = ⟨6/7⟩.","8 − ⟨6 1/7⟩ = ⟨1 6/7⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L07_basic#7','math',4,2,'u1','L07','g4_2_math_u1_L07_basic','lesson_basic','M4-2-u1-C7',2,'mc','auto','두부를 만들려고 콩 4 kg 가운데 ⟨1 3/7⟩ kg을 물에 불렸어요. 불리지 않고 남은 콩은 몇 kg인가요?',ARRAY['M4-2-u1-X09','M4-2-u1-X10','M4-2-u1-X16']::text[],true,'{"seq":7,"concept":"M4-2-u1-C7","difficulty":2,"kind":"mc","stem":"두부를 만들려고 콩 4 kg 가운데 ⟨1 3/7⟩ kg을 물에 불렸어요. 불리지 않고 남은 콩은 몇 kg인가요?","options":[{"t":"⟨2 4/7⟩ kg","correct":true},{"t":"⟨3 4/7⟩ kg","mis":"M4-2-u1-X09"},{"t":"⟨2 3/7⟩ kg","mis":"M4-2-u1-X10"},{"t":"⟨2 5/7⟩ kg","mis":"M4-2-u1-X16"}],"explanation":["4 = ⟨3 7/7⟩로 바꾸어요.","⟨3 7/7⟩ − ⟨1 3/7⟩ = ⟨2 4/7⟩.","남은 콩은 ⟨2 4/7⟩ kg이에요."],"variant_rule":{"alt":[{"stem":"두부를 만들려고 콩 2 kg 가운데 ⟨1 1/3⟩ kg을 물에 불렸어요. 불리지 않고 남은 콩은 몇 kg인가요?","options":[{"t":"⟨2/3⟩ kg","correct":true},{"t":"⟨1 2/3⟩ kg","mis":"M4-2-u1-X09"},{"t":"⟨1/3⟩ kg","mis":"M4-2-u1-X10"},{"t":"1 kg","mis":"M4-2-u1-X16"}],"explanation":["2 = ⟨1 3/3⟩으로 바꾸어요.","⟨1 3/3⟩ − ⟨1 1/3⟩ = ⟨2/3⟩.","남은 콩은 ⟨2/3⟩ kg이에요."],"asset":null},{"stem":"두부를 만들려고 콩 6 kg 가운데 ⟨3 1/6⟩ kg을 물에 불렸어요. 불리지 않고 남은 콩은 몇 kg인가요?","options":[{"t":"⟨2 5/6⟩ kg","correct":true},{"t":"⟨3 5/6⟩ kg","mis":"M4-2-u1-X09"},{"t":"⟨2 1/6⟩ kg","mis":"M4-2-u1-X10"},{"t":"3 kg","mis":"M4-2-u1-X16"}],"explanation":["6 = ⟨5 6/6⟩으로 바꾸어요.","⟨5 6/6⟩ − ⟨3 1/6⟩ = ⟨2 5/6⟩.","남은 콩은 ⟨2 5/6⟩ kg이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L07_basic#8','math',4,2,'u1','L07','g4_2_math_u1_L07_basic','lesson_basic','M4-2-u1-C7',2,'ox','auto','채원이 「6 − ⟨5/7⟩ = ⟨5 5/7⟩야.」라고 했어요. 바르게 계산했어요.',ARRAY['M4-2-u1-X10']::text[],true,'{"seq":8,"concept":"M4-2-u1-C7","difficulty":2,"kind":"ox","stem":"채원이 「6 − ⟨5/7⟩ = ⟨5 5/7⟩야.」라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"⟨7/7⟩에서 ⟨5/7⟩를 덜어 내면 ⟨2/7⟩가 남아서","correct":true},{"t":"빼는 분수를 그대로 쓰면 되어서","mis":"M4-2-u1-X10"}],"mis":"M4-2-u1-X10","explanation":["6에서 1만큼을 ⟨7/7⟩로 바꾸어요 — 6 = ⟨5 7/7⟩.","⟨7/7⟩ − ⟨5/7⟩ = ⟨2/7⟩.","6 − ⟨5/7⟩ = ⟨5 2/7⟩ — 자연수 부분은 1 줄어요."],"variant_rule":{"alt":[{"stem":"준우가 「2 − ⟨2/7⟩ = ⟨2 5/7⟩야.」라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"1만큼을 분수로 바꾸었으니 자연수 부분이 1 줄어야 해서","correct":true},{"t":"자연수 부분은 그대로 두면 되어서","mis":"M4-2-u1-X09"}],"explanation":["2에서 1만큼을 ⟨7/7⟩로 바꾸어요 — 2 = ⟨1 7/7⟩.","⟨7/7⟩ − ⟨2/7⟩ = ⟨5/7⟩.","2 − ⟨2/7⟩ = ⟨1 5/7⟩ — 자연수 부분은 1 줄어요."],"asset":null},{"stem":"도연이 「5 − ⟨4/6⟩ = ⟨4 4/6⟩야.」라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"⟨6/6⟩에서 ⟨4/6⟩를 덜어 내면 ⟨2/6⟩가 남아서","correct":true},{"t":"빼는 분수를 그대로 쓰면 되어서","mis":"M4-2-u1-X10"}],"explanation":["5에서 1만큼을 ⟨6/6⟩으로 바꾸어요 — 5 = ⟨4 6/6⟩.","⟨6/6⟩ − ⟨4/6⟩ = ⟨2/6⟩.","5 − ⟨4/6⟩ = ⟨4 2/6⟩ — 자연수 부분은 1 줄어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L07_basic#9','math',4,2,'u1','L07','g4_2_math_u1_L07_basic','lesson_basic','M4-2-u1-C8',2,'mc','auto','⟨5 2/4⟩ − ⟨3/4⟩을 계산하면 얼마인가요?',ARRAY['M4-2-u1-X11','M4-2-u1-X09','M4-2-u1-X12']::text[],true,'{"seq":9,"concept":"M4-2-u1-C8","difficulty":2,"kind":"mc","stem":"⟨5 2/4⟩ − ⟨3/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4 3/4⟩","correct":true},{"t":"⟨5 1/4⟩","mis":"M4-2-u1-X11"},{"t":"⟨5 3/4⟩","mis":"M4-2-u1-X09"},{"t":"⟨4 9/4⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨2/4⟩ − ⟨3/4⟩ — 진분수끼리 뺄 수 없어요(2 < 3).","1만큼 바꾸어요 — ⟨5 2/4⟩ = ⟨4 6/4⟩.","⟨4 6/4⟩ − ⟨3/4⟩ = ⟨4 3/4⟩ — 자연수 부분은 1 줄어요."],"variant_rule":{"alt":[{"stem":"⟨5 3/5⟩ − ⟨4/5⟩를 계산하면 얼마인가요?","options":[{"t":"⟨4 4/5⟩","correct":true},{"t":"⟨5 1/5⟩","mis":"M4-2-u1-X11"},{"t":"⟨5 4/5⟩","mis":"M4-2-u1-X09"},{"t":"⟨4 9/5⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨3/5⟩ − ⟨4/5⟩ — 진분수끼리 뺄 수 없어요(3 < 4).","1만큼 바꾸어요 — ⟨5 3/5⟩ = ⟨4 8/5⟩.","⟨4 8/5⟩ − ⟨4/5⟩ = ⟨4 4/5⟩ — 자연수 부분은 1 줄어요."],"asset":null},{"stem":"⟨6 4/6⟩ − ⟨5/6⟩를 계산하면 얼마인가요?","options":[{"t":"⟨5 5/6⟩","correct":true},{"t":"⟨6 1/6⟩","mis":"M4-2-u1-X11"},{"t":"⟨6 5/6⟩","mis":"M4-2-u1-X09"},{"t":"⟨5 9/6⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨4/6⟩ − ⟨5/6⟩ — 진분수끼리 뺄 수 없어요(4 < 5).","1만큼 바꾸어요 — ⟨6 4/6⟩ = ⟨5 10/6⟩.","⟨5 10/6⟩ − ⟨5/6⟩ = ⟨5 5/6⟩ — 자연수 부분은 1 줄어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L07_basic#10','math',4,2,'u1','L07','g4_2_math_u1_L07_basic','lesson_basic','M4-2-u1-C8',3,'error','auto','⟨2 3/7⟩ − ⟨4/7⟩를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u1-X09','M4-2-u1-X15']::text[],true,'{"seq":10,"concept":"M4-2-u1-C8","difficulty":3,"kind":"error","stem":"⟨2 3/7⟩ − ⟨4/7⟩를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도연 — 「⟨2 3/7⟩ = ⟨2 10/7⟩으로 바꾸었어요」","correct":true,"mis_target":"M4-2-u1-X09"},{"t":"서윤 — 「⟨2 3/7⟩ = ⟨1 10/7⟩으로 바꾸었어요」","mis":"M4-2-u1-X15"},{"t":"하윤 — 「⟨10/7⟩ − ⟨4/7⟩ = ⟨6/7⟩으로 계산했어요」","mis":"M4-2-u1-X15"},{"t":"지훈 — 「답은 ⟨1 6/7⟩이에요」","mis":"M4-2-u1-X15"}],"explanation":["⟨3/7⟩ − ⟨4/7⟩ — 진분수끼리 뺄 수 없어요(3 < 4).","1만큼 바꾸어요 — ⟨2 3/7⟩ = ⟨1 10/7⟩.","⟨1 10/7⟩ − ⟨4/7⟩ = ⟨1 6/7⟩ — 자연수 부분은 1 줄어요."],"variant_rule":{"alt":[{"stem":"⟨4 5/9⟩ − ⟨6/9⟩을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"건우 — 「⟨4 5/9⟩ = ⟨3 15/9⟩로 바꾸었어요」","correct":true,"mis_target":"M4-2-u1-X12"},{"t":"지훈 — 「⟨4 5/9⟩ = ⟨3 14/9⟩로 바꾸었어요」","mis":"M4-2-u1-X15"},{"t":"도연 — 「⟨14/9⟩ − ⟨6/9⟩ = ⟨8/9⟩로 계산했어요」","mis":"M4-2-u1-X15"},{"t":"은비 — 「답은 ⟨3 8/9⟩이에요」","mis":"M4-2-u1-X15"}],"explanation":["⟨5/9⟩ − ⟨6/9⟩ — 진분수끼리 뺄 수 없어요(5 < 6).","1만큼 바꾸어요 — ⟨4 5/9⟩ = ⟨3 14/9⟩.","⟨3 14/9⟩ − ⟨6/9⟩ = ⟨3 8/9⟩ — 자연수 부분은 1 줄어요."],"asset":null},{"stem":"⟨4 3/5⟩ − ⟨4/5⟩를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은비 — 「⟨4 3/5⟩ − ⟨4/5⟩ = ⟨4 1/5⟩로 계산했어요」","correct":true,"mis_target":"M4-2-u1-X11"},{"t":"건우 — 「⟨4 3/5⟩ = ⟨3 8/5⟩로 바꾸었어요」","mis":"M4-2-u1-X15"},{"t":"서윤 — 「⟨8/5⟩ − ⟨4/5⟩ = ⟨4/5⟩로 계산했어요」","mis":"M4-2-u1-X15"},{"t":"민서 — 「답은 ⟨3 4/5⟩예요」","mis":"M4-2-u1-X15"}],"explanation":["⟨3/5⟩ − ⟨4/5⟩ — 진분수끼리 뺄 수 없어요(3 < 4).","1만큼 바꾸어요 — ⟨4 3/5⟩ = ⟨3 8/5⟩.","⟨3 8/5⟩ − ⟨4/5⟩ = ⟨3 4/5⟩ — 자연수 부분은 1 줄어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code,