INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L07_challenge#2','math',4,2,'u1','L07','g4_2_math_u1_L07_challenge','lesson_challenge','M4-2-u1-C8',2,'mc','auto','⟨5 6/10⟩ − ⟨9/10⟩를 계산하면 얼마인가요?',ARRAY['M4-2-u1-X11','M4-2-u1-X09','M4-2-u1-X16']::text[],true,'{"seq":2,"concept":"M4-2-u1-C8","difficulty":2,"kind":"mc","stem":"⟨5 6/10⟩ − ⟨9/10⟩를 계산하면 얼마인가요?","options":[{"t":"⟨4 7/10⟩","correct":true},{"t":"⟨5 3/10⟩","mis":"M4-2-u1-X11"},{"t":"⟨5 7/10⟩","mis":"M4-2-u1-X09"},{"t":"⟨4 8/10⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨6/10⟩ − ⟨9/10⟩ — 진분수끼리 뺄 수 없어요(6 < 9).","1만큼 바꾸어요 — ⟨5 6/10⟩ = ⟨4 16/10⟩.","⟨4 16/10⟩ − ⟨9/10⟩ = ⟨4 7/10⟩ — 자연수 부분은 1 줄어요."],"variant_rule":{"alt":[{"stem":"⟨8 2/6⟩ − ⟨5/6⟩를 계산하면 얼마인가요?","options":[{"t":"⟨7 3/6⟩","correct":true},{"t":"⟨8 3/6⟩","mis":"M4-2-u1-X11"},{"t":"⟨7 7/6⟩","mis":"M4-2-u1-X12"},{"t":"⟨7 4/6⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨2/6⟩ − ⟨5/6⟩ — 진분수끼리 뺄 수 없어요(2 < 5).","1만큼 바꾸어요 — ⟨8 2/6⟩ = ⟨7 8/6⟩.","⟨7 8/6⟩ − ⟨5/6⟩ = ⟨7 3/6⟩ — 자연수 부분은 1 줄어요."],"asset":null},{"stem":"⟨7 6/8⟩ − ⟨7/8⟩을 계산하면 얼마인가요?","options":[{"t":"⟨6 7/8⟩","correct":true},{"t":"⟨7 1/8⟩","mis":"M4-2-u1-X11"},{"t":"⟨7 7/8⟩","mis":"M4-2-u1-X09"},{"t":"⟨6 9/8⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨6/8⟩ − ⟨7/8⟩ — 진분수끼리 뺄 수 없어요(6 < 7).","1만큼 바꾸어요 — ⟨7 6/8⟩ = ⟨6 14/8⟩.","⟨6 14/8⟩ − ⟨7/8⟩ = ⟨6 7/8⟩ — 자연수 부분은 1 줄어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L07_challenge#3','math',4,2,'u1','L07','g4_2_math_u1_L07_challenge','lesson_challenge','M4-2-u1-C8',3,'error','auto','⟨2 6/9⟩ − ⟨7/9⟩을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-2-u1-X11','M4-2-u1-X15']::text[],true,'{"seq":3,"concept":"M4-2-u1-C8","difficulty":3,"kind":"error","stem":"⟨2 6/9⟩ − ⟨7/9⟩을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지훈 — 「⟨2 6/9⟩ − ⟨7/9⟩ = ⟨2 1/9⟩로 계산했어요」","correct":true,"mis_target":"M4-2-u1-X11"},{"t":"은비 — 「⟨2 6/9⟩ = ⟨1 15/9⟩로 바꾸었어요」","mis":"M4-2-u1-X15"},{"t":"서준 — 「⟨15/9⟩ − ⟨7/9⟩ = ⟨8/9⟩로 계산했어요」","mis":"M4-2-u1-X15"},{"t":"하윤 — 「답은 ⟨1 8/9⟩이에요」","mis":"M4-2-u1-X15"}],"explanation":["⟨6/9⟩ − ⟨7/9⟩ — 진분수끼리 뺄 수 없어요(6 < 7).","1만큼 바꾸어요 — ⟨2 6/9⟩ = ⟨1 15/9⟩.","⟨1 15/9⟩ − ⟨7/9⟩ = ⟨1 8/9⟩ — 자연수 부분은 1 줄어요."],"variant_rule":{"alt":[{"stem":"⟨7 1/9⟩ − ⟨6/9⟩을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서준 — 「⟨7 1/9⟩ = ⟨7 10/9⟩으로 바꾸었어요」","correct":true,"mis_target":"M4-2-u1-X09"},{"t":"민서 — 「⟨7 1/9⟩ = ⟨6 10/9⟩으로 바꾸었어요」","mis":"M4-2-u1-X15"},{"t":"지훈 — 「⟨10/9⟩ − ⟨6/9⟩ = ⟨4/9⟩로 계산했어요」","mis":"M4-2-u1-X15"},{"t":"건우 — 「답은 ⟨6 4/9⟩예요」","mis":"M4-2-u1-X15"}],"explanation":["⟨1/9⟩ − ⟨6/9⟩ — 진분수끼리 뺄 수 없어요(1 < 6).","1만큼 바꾸어요 — ⟨7 1/9⟩ = ⟨6 10/9⟩.","⟨6 10/9⟩ − ⟨6/9⟩ = ⟨6 4/9⟩ — 자연수 부분은 1 줄어요."],"asset":null},{"stem":"⟨7 2/4⟩ − ⟨3/4⟩을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하윤 — 「⟨7 2/4⟩ = ⟨6 12/4⟩로 바꾸었어요」","correct":true,"mis_target":"M4-2-u1-X12"},{"t":"건우 — 「⟨7 2/4⟩ = ⟨6 6/4⟩으로 바꾸었어요」","mis":"M4-2-u1-X15"},{"t":"민서 — 「⟨6/4⟩ − ⟨3/4⟩ = ⟨3/4⟩으로 계산했어요」","mis":"M4-2-u1-X15"},{"t":"채원 — 「답은 ⟨6 3/4⟩이에요」","mis":"M4-2-u1-X15"}],"explanation":["⟨2/4⟩ − ⟨3/4⟩ — 진분수끼리 뺄 수 없어요(2 < 3).","1만큼 바꾸어요 — ⟨7 2/4⟩ = ⟨6 6/4⟩.","⟨6 6/4⟩ − ⟨3/4⟩ = ⟨6 3/4⟩ — 자연수 부분은 1 줄어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L07_challenge#4','math',4,2,'u1','L07','g4_2_math_u1_L07_challenge','lesson_challenge','M4-2-u1-C7',3,'mc','auto','8 − ⟨1 1/4⟩을 계산하면 얼마인가요?',ARRAY['M4-2-u1-X09','M4-2-u1-X10','M4-2-u1-X16']::text[],true,'{"seq":4,"concept":"M4-2-u1-C7","difficulty":3,"kind":"mc","stem":"8 − ⟨1 1/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨6 3/4⟩","correct":true},{"t":"⟨7 3/4⟩","mis":"M4-2-u1-X09"},{"t":"⟨6 1/4⟩","mis":"M4-2-u1-X10"},{"t":"7","mis":"M4-2-u1-X16"}],"explanation":["8 = ⟨7 4/4⟩로 바꾸어요.","자연수끼리 7 − 1 = 6, 분수끼리 ⟨4/4⟩ − ⟨1/4⟩ = ⟨3/4⟩.","8 − ⟨1 1/4⟩ = ⟨6 3/4⟩."],"variant_rule":{"alt":[{"stem":"7 − ⟨5 2/3⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1 1/3⟩","correct":true},{"t":"⟨2 1/3⟩","mis":"M4-2-u1-X09"},{"t":"⟨1 2/3⟩","mis":"M4-2-u1-X10"},{"t":"1","mis":"M4-2-u1-X16"}],"explanation":["7 = ⟨6 3/3⟩으로 바꾸어요.","자연수끼리 6 − 5 = 1, 분수끼리 ⟨3/3⟩ − ⟨2/3⟩ = ⟨1/3⟩.","7 − ⟨5 2/3⟩ = ⟨1 1/3⟩."],"asset":null},{"stem":"5 − ⟨1 2/3⟩를 계산하면 얼마인가요?","options":[{"t":"⟨3 1/3⟩","correct":true},{"t":"⟨4 1/3⟩","mis":"M4-2-u1-X09"},{"t":"⟨3 2/3⟩","mis":"M4-2-u1-X10"},{"t":"3","mis":"M4-2-u1-X16"}],"explanation":["5 = ⟨4 3/3⟩으로 바꾸어요.","자연수끼리 4 − 1 = 3, 분수끼리 ⟨3/3⟩ − ⟨2/3⟩ = ⟨1/3⟩.","5 − ⟨1 2/3⟩ = ⟨3 1/3⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L07_challenge#5','math',4,2,'u1','L07','g4_2_math_u1_L07_challenge','lesson_challenge','M4-2-u1-C7',3,'mc','auto','두부를 만들려고 콩 5 kg 가운데 ⟨3 4/7⟩ kg을 물에 불렸어요. 불리지 않고 남은 콩은 몇 kg인가요?',ARRAY['M4-2-u1-X09','M4-2-u1-X10','M4-2-u1-X14']::text[],true,'{"seq":5,"concept":"M4-2-u1-C7","difficulty":3,"kind":"mc","stem":"두부를 만들려고 콩 5 kg 가운데 ⟨3 4/7⟩ kg을 물에 불렸어요. 불리지 않고 남은 콩은 몇 kg인가요?","options":[{"t":"⟨1 3/7⟩ kg","correct":true},{"t":"⟨2 3/7⟩ kg","mis":"M4-2-u1-X09"},{"t":"⟨1 4/7⟩ kg","mis":"M4-2-u1-X10"},{"t":"⟨8 4/7⟩ kg","mis":"M4-2-u1-X14"}],"explanation":["5 = ⟨4 7/7⟩로 바꾸어요.","⟨4 7/7⟩ − ⟨3 4/7⟩ = ⟨1 3/7⟩.","남은 콩은 ⟨1 3/7⟩ kg이에요."],"variant_rule":{"alt":[{"stem":"두부를 만들려고 콩 6 kg 가운데 ⟨2 4/8⟩ kg을 물에 불렸어요. 불리지 않고 남은 콩은 몇 kg인가요?","options":[{"t":"⟨3 4/8⟩ kg","correct":true},{"t":"⟨4 4/8⟩ kg","mis":"M4-2-u1-X09"},{"t":"⟨3 5/8⟩ kg","mis":"M4-2-u1-X16"},{"t":"⟨8 4/8⟩ kg","mis":"M4-2-u1-X14"}],"explanation":["6 = ⟨5 8/8⟩로 바꾸어요.","⟨5 8/8⟩ − ⟨2 4/8⟩ = ⟨3 4/8⟩.","남은 콩은 ⟨3 4/8⟩ kg이에요."],"asset":null},{"stem":"두부를 만들려고 콩 2 kg 가운데 ⟨1 1/8⟩ kg을 물에 불렸어요. 불리지 않고 남은 콩은 몇 kg인가요?","options":[{"t":"⟨7/8⟩ kg","correct":true},{"t":"⟨1 7/8⟩ kg","mis":"M4-2-u1-X09"},{"t":"⟨1/8⟩ kg","mis":"M4-2-u1-X10"},{"t":"1 kg","mis":"M4-2-u1-X16"}],"explanation":["2 = ⟨1 8/8⟩로 바꾸어요.","⟨1 8/8⟩ − ⟨1 1/8⟩ = ⟨7/8⟩.","남은 콩은 ⟨7/8⟩ kg이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L07_challenge#6','math',4,2,'u1','L07','g4_2_math_u1_L07_challenge','lesson_challenge','M4-2-u1-C7',3,'sa','auto','2 − ⟨□/9⟩ = ⟨1 2/9⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u1-C7","difficulty":3,"kind":"sa","stem":"2 − ⟨□/9⟩ = ⟨1 2/9⟩ — □에 알맞은 수를 쓰세요.","answer":["7"],"explanation":["2 = ⟨1 9/9⟩.","⟨1 9/9⟩ − ⟨□/9⟩ = ⟨1 2/9⟩ — 9 − □ = 2.","□ = 7."],"variant_rule":{"alt":[{"stem":"3 − ⟨□/10⟩ = ⟨2 2/10⟩ — □에 알맞은 수를 쓰세요.","answer":["8"],"explanation":["3 = ⟨2 10/10⟩.","⟨2 10/10⟩ − ⟨□/10⟩ = ⟨2 2/10⟩ — 10 − □ = 2.","□ = 8."],"asset":null},{"stem":"7 − ⟨□/9⟩ = ⟨6 7/9⟩ — □에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["7 = ⟨6 9/9⟩.","⟨6 9/9⟩ − ⟨□/9⟩ = ⟨6 7/9⟩ — 9 − □ = 7.","□ = 2."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L07_challenge#7','math',4,2,'u1','L07','g4_2_math_u1_L07_challenge','lesson_challenge','M4-2-u1-C7',3,'ox','auto','준우가 「4 − ⟨9/10⟩ = ⟨3 9/10⟩야.」라고 했어요. 바르게 계산했어요.',ARRAY['M4-2-u1-X10']::text[],true,'{"seq":7,"concept":"M4-2-u1-C7","difficulty":3,"kind":"ox","stem":"준우가 「4 − ⟨9/10⟩ = ⟨3 9/10⟩야.」라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"⟨10/10⟩에서 ⟨9/10⟩를 덜어 내면 ⟨1/10⟩이 남아서","correct":true},{"t":"빼는 분수를 그대로 쓰면 되어서","mis":"M4-2-u1-X10"}],"mis":"M4-2-u1-X10","explanation":["4에서 1만큼을 ⟨10/10⟩으로 바꾸어요 — 4 = ⟨3 10/10⟩.","⟨10/10⟩ − ⟨9/10⟩ = ⟨1/10⟩.","4 − ⟨9/10⟩ = ⟨3 1/10⟩ — 자연수 부분은 1 줄어요."],"variant_rule":{"alt":[{"stem":"하윤이 「4 − ⟨1/5⟩ = ⟨4 4/5⟩야.」라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"1만큼을 분수로 바꾸었으니 자연수 부분이 1 줄어야 해서","correct":true},{"t":"자연수 부분은 그대로 두면 되어서","mis":"M4-2-u1-X09"}],"explanation":["4에서 1만큼을 ⟨5/5⟩로 바꾸어요 — 4 = ⟨3 5/5⟩.","⟨5/5⟩ − ⟨1/5⟩ = ⟨4/5⟩.","4 − ⟨1/5⟩ = ⟨3 4/5⟩ — 자연수 부분은 1 줄어요."],"asset":null},{"stem":"건우가 「8 − ⟨2/11⟩ = ⟨7 2/11⟩야.」라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"⟨11/11⟩에서 ⟨2/11⟩를 덜어 내면 ⟨9/11⟩가 남아서","correct":true},{"t":"빼는 분수를 그대로 쓰면 되어서","mis":"M4-2-u1-X10"}],"explanation":["8에서 1만큼을 ⟨11/11⟩로 바꾸어요 — 8 = ⟨7 11/11⟩.","⟨11/11⟩ − ⟨2/11⟩ = ⟨9/11⟩.","8 − ⟨2/11⟩ = ⟨7 9/11⟩ — 자연수 부분은 1 줄어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L07_challenge#8','math',4,2,'u1','L07','g4_2_math_u1_L07_challenge','lesson_challenge','M4-2-u1-C7',4,'essay','teacher','두부를 만들려고 콩 3 kg 가운데 ⟨1/4⟩ kg을 불렸어요. 민서는 남은 콩을 「⟨2 1/4⟩ kg」이라고 했어요. 바르게 구하고 민서가 무엇을 잘못했는지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u1-C7","difficulty":4,"kind":"essay","stem":"두부를 만들려고 콩 3 kg 가운데 ⟨1/4⟩ kg을 불렸어요. 민서는 남은 콩을 「⟨2 1/4⟩ kg」이라고 했어요. 바르게 구하고 민서가 무엇을 잘못했는지 설명해 보세요.","answer_guide":{"answer":"예: 3을 ⟨2 4/4⟩로 바꾸면 ⟨2 4/4⟩ − ⟨1/4⟩ = ⟨2 3/4⟩ kg이다. 1만큼인 ⟨4/4⟩에서 ⟨1/4⟩을 덜어 내면 ⟨3/4⟩이 남는데, 민서는 빼는 분수 ⟨1/4⟩을 그대로 썼다.","scoring_points":["⟨2 3/4⟩ kg을 구했는가","3 = ⟨2 4/4⟩로 바꾸었는가","빼는 분수를 그대로 쓴 잘못을 짚었는가"]},"explanation":["3 = ⟨2 4/4⟩.","⟨4/4⟩ − ⟨1/4⟩ = ⟨3/4⟩.","⟨2 3/4⟩ kg."],"asset":{"type":"fbar","bars":[{"den":4,"num":4},{"den":4,"num":4},{"den":4,"num":3}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L07_challenge#9','math',4,2,'u1','L07','g4_2_math_u1_L07_challenge','lesson_challenge','M4-2-u1-C8',4,'essay','teacher','⟨2 1/5⟩ − ⟨3/5⟩을 계산하고, 진분수끼리 뺄 수 없을 때 자연수 부분에서 1만큼을 어떻게 바꾸는지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u1-C8","difficulty":4,"kind":"essay","stem":"⟨2 1/5⟩ − ⟨3/5⟩을 계산하고, 진분수끼리 뺄 수 없을 때 자연수 부분에서 1만큼을 어떻게 바꾸는지 설명해 보세요.","answer_guide":{"answer":"예: ⟨1/5⟩에서 ⟨3/5⟩을 뺄 수 없으므로 자연수 2에서 1만큼을 ⟨5/5⟩로 바꾸어 ⟨2 1/5⟩ = ⟨1 6/5⟩으로 나타낸다. ⟨1 6/5⟩ − ⟨3/5⟩ = ⟨1 3/5⟩이다. 1만큼 바꾸었으므로 자연수 부분은 1 줄어든다.","scoring_points":["⟨1 3/5⟩을 구했는가","⟨2 1/5⟩ = ⟨1 6/5⟩으로 바꾸었는가","자연수 부분이 1 줄어든다고 썼는가"]},"explanation":["⟨2 1/5⟩ = ⟨1 6/5⟩.","⟨6/5⟩ − ⟨3/5⟩ = ⟨3/5⟩.","⟨1 3/5⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L07_challenge#10','math',4,2,'u1','L07','g4_2_math_u1_L07_challenge','lesson_challenge','M4-2-u1-C7',4,'mc','auto','6 − ⟨1 5/11⟩를 계산하면 얼마인가요?',ARRAY['M4-2-u1-X09','M4-2-u1-X10','M4-2-u1-X16']::text[],true,'{"seq":10,"concept":"M4-2-u1-C7","difficulty":4,"kind":"mc","stem":"6 − ⟨1 5/11⟩를 계산하면 얼마인가요?","options":[{"t":"⟨4 6/11⟩","correct":true},{"t":"⟨5 6/11⟩","mis":"M4-2-u1-X09"},{"t":"⟨4 5/11⟩","mis":"M4-2-u1-X10"},{"t":"⟨4 7/11⟩","mis":"M4-2-u1-X16"}],"explanation":["6 = ⟨5 11/11⟩로 바꾸어요.","자연수끼리 5 − 1 = 4, 분수끼리 ⟨11/11⟩ − ⟨5/11⟩ = ⟨6/11⟩.","6 − ⟨1 5/11⟩ = ⟨4 6/11⟩."],"variant_rule":{"alt":[{"stem":"4 − ⟨2 6/12⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1 6/12⟩","correct":true},{"t":"⟨2 6/12⟩","mis":"M4-2-u1-X09"},{"t":"⟨1 7/12⟩","mis":"M4-2-u1-X16"},{"t":"⟨1 5/12⟩","mis":"M4-2-u1-X16"}],"explanation":["4 = ⟨3 12/12⟩로 바꾸어요.","자연수끼리 3 − 2 = 1, 분수끼리 ⟨12/12⟩ − ⟨6/12⟩ = ⟨6/12⟩.","4 − ⟨2 6/12⟩ = ⟨1 6/12⟩."],"asset":null},{"stem":"4 − ⟨1 9/11⟩를 계산하면 얼마인가요?","options":[{"t":"⟨2 2/11⟩","correct":true},{"t":"⟨3 2/11⟩","mis":"M4-2-u1-X09"},{"t":"⟨2 9/11⟩","mis":"M4-2-u1-X10"},{"t":"⟨2 3/11⟩","mis":"M4-2-u1-X16"}],"explanation":["4 = ⟨3 11/11⟩로 바꾸어요.","자연수끼리 3 − 1 = 2, 분수끼리 ⟨11/11⟩ − ⟨9/11⟩ = ⟨2/11⟩.","4 − ⟨1 9/11⟩ = ⟨2 2/11⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L08_basic#1','math',4,2,'u1','L08','g4_2_math_u1_L08_basic','lesson_basic','M4-2-u1-C9',1,'sa','auto','⟨5 1/4⟩ − ⟨2 3/4⟩을 1만큼 바꾸어 ⟨4 □/4⟩ − ⟨2 3/4⟩으로 계산하려고 해요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-2-u1-C9","difficulty":1,"kind":"sa","stem":"⟨5 1/4⟩ − ⟨2 3/4⟩을 1만큼 바꾸어 ⟨4 □/4⟩ − ⟨2 3/4⟩으로 계산하려고 해요. □에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["⟨1/4⟩ − ⟨3/4⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨5 1/4⟩ = ⟨4 5/4⟩.","자연수끼리 4 − 2 = 2, 분수끼리 ⟨5/4⟩ − ⟨3/4⟩ = ⟨2/4⟩ — 답 ⟨2 2/4⟩."],"variant_rule":{"alt":[{"stem":"⟨5 2/4⟩ − ⟨3 3/4⟩을 1만큼 바꾸어 ⟨4 □/4⟩ − ⟨3 3/4⟩으로 계산하려고 해요. □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["⟨2/4⟩ − ⟨3/4⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨5 2/4⟩ = ⟨4 6/4⟩.","자연수끼리 4 − 3 = 1, 분수끼리 ⟨6/4⟩ − ⟨3/4⟩ = ⟨3/4⟩ — 답 ⟨1 3/4⟩."],"asset":null},{"stem":"⟨4 2/4⟩ − ⟨3 3/4⟩을 1만큼 바꾸어 ⟨3 □/4⟩ − ⟨3 3/4⟩으로 계산하려고 해요. □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["⟨2/4⟩ − ⟨3/4⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨4 2/4⟩ = ⟨3 6/4⟩.","자연수끼리 3 − 3 = 0, 분수끼리 ⟨6/4⟩ − ⟨3/4⟩ = ⟨3/4⟩ — 답 ⟨3/4⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L08_basic#2','math',4,2,'u1','L08','g4_2_math_u1_L08_basic','lesson_basic','M4-2-u1-C9',1,'sa','auto','⟨4 1/3⟩ − ⟨1 2/3⟩를 계산하여 대분수로 나타낼 때, 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u1-C9","difficulty":1,"kind":"sa","stem":"⟨4 1/3⟩ − ⟨1 2/3⟩를 계산하여 대분수로 나타낼 때, 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["⟨1/3⟩ − ⟨2/3⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨4 1/3⟩ = ⟨3 4/3⟩.","자연수끼리 3 − 1 = 2, 분수끼리 ⟨4/3⟩ − ⟨2/3⟩ = ⟨2/3⟩ — 답 ⟨2 2/3⟩."],"variant_rule":{"alt":[{"stem":"⟨4 2/4⟩ − ⟨3 3/4⟩을 계산하여 대분수로 나타낼 때, 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["0"],"explanation":["⟨2/4⟩ − ⟨3/4⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨4 2/4⟩ = ⟨3 6/4⟩.","자연수끼리 3 − 3 = 0, 분수끼리 ⟨6/4⟩ − ⟨3/4⟩ = ⟨3/4⟩ — 답 ⟨3/4⟩."],"asset":null},{"stem":"⟨6 1/6⟩ − ⟨2 5/6⟩를 계산하여 대분수로 나타낼 때, 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["⟨1/6⟩ − ⟨5/6⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨6 1/6⟩ = ⟨5 7/6⟩.","자연수끼리 5 − 2 = 3, 분수끼리 ⟨7/6⟩ − ⟨5/6⟩ = ⟨2/6⟩ — 답 ⟨3 2/6⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
