INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L08_basic#7','math',4,2,'u1','L08','g4_2_math_u1_L08_basic','lesson_basic','M4-2-u1-C9',2,'ox','auto','채원이 「⟨4 1/5⟩ − ⟨2 2/5⟩ = ⟨2 4/5⟩야.」라고 했어요. 바르게 계산했어요.',ARRAY['M4-2-u1-X09']::text[],true,'{"seq":7,"concept":"M4-2-u1-C9","difficulty":2,"kind":"ox","stem":"채원이 「⟨4 1/5⟩ − ⟨2 2/5⟩ = ⟨2 4/5⟩야.」라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"1만큼 바꾼 만큼 자연수 부분이 1 줄어야 해서","correct":true},{"t":"자연수끼리 그대로 빼면 되어서","mis":"M4-2-u1-X09"}],"mis":"M4-2-u1-X09","explanation":["⟨1/5⟩ − ⟨2/5⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨4 1/5⟩ = ⟨3 6/5⟩.","자연수끼리 3 − 2 = 1, 분수끼리 ⟨6/5⟩ − ⟨2/5⟩ = ⟨4/5⟩ — 답 ⟨1 4/5⟩."],"variant_rule":{"alt":[{"stem":"건우가 「⟨4 2/6⟩ − ⟨2 4/6⟩ = ⟨2 2/6⟩야.」라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"진분수끼리 뺄 수 없으면 1만큼 바꾸어 빼야 해서","correct":true},{"t":"큰 분자에서 작은 분자를 빼면 되어서","mis":"M4-2-u1-X11"}],"explanation":["⟨2/6⟩ − ⟨4/6⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨4 2/6⟩ = ⟨3 8/6⟩.","자연수끼리 3 − 2 = 1, 분수끼리 ⟨8/6⟩ − ⟨4/6⟩ = ⟨4/6⟩ — 답 ⟨1 4/6⟩."],"asset":null},{"stem":"건우가 「⟨4 2/7⟩ − ⟨3 3/7⟩ = ⟨1 6/7⟩이야.」라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"1만큼 바꾼 만큼 자연수 부분이 1 줄어야 해서","correct":true},{"t":"자연수끼리 그대로 빼면 되어서","mis":"M4-2-u1-X09"}],"explanation":["⟨2/7⟩ − ⟨3/7⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨4 2/7⟩ = ⟨3 9/7⟩.","자연수끼리 3 − 3 = 0, 분수끼리 ⟨9/7⟩ − ⟨3/7⟩ = ⟨6/7⟩ — 답 ⟨6/7⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L08_basic#8','math',4,2,'u1','L08','g4_2_math_u1_L08_basic','lesson_basic','M4-2-u1-C9',2,'sa','auto','⟨4 3/8⟩ − ⟨2 4/8⟩를 가분수로 바꾸어 계산하면 ⟨□/8⟩ − ⟨△/8⟩ = ⟨○/8⟩이에요. ○에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u1-C9","difficulty":2,"kind":"sa","stem":"⟨4 3/8⟩ − ⟨2 4/8⟩를 가분수로 바꾸어 계산하면 ⟨□/8⟩ − ⟨△/8⟩ = ⟨○/8⟩이에요. ○에 알맞은 수를 쓰세요.","answer":["15"],"explanation":["⟨4 3/8⟩ = ⟨35/8⟩, ⟨2 4/8⟩ = ⟨20/8⟩.","⟨35/8⟩ − ⟨20/8⟩ = ⟨15/8⟩.","○ = 15 — 대분수로 ⟨1 7/8⟩."],"variant_rule":{"alt":[{"stem":"⟨2 3/5⟩ − ⟨1 4/5⟩를 가분수로 바꾸어 계산하면 ⟨□/5⟩ − ⟨△/5⟩ = ⟨○/5⟩이에요. ○에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["⟨2 3/5⟩ = ⟨13/5⟩, ⟨1 4/5⟩ = ⟨9/5⟩.","⟨13/5⟩ − ⟨9/5⟩ = ⟨4/5⟩.","○ = 4 — 대분수로 ⟨4/5⟩."],"asset":null},{"stem":"⟨5 3/6⟩ − ⟨1 4/6⟩를 가분수로 바꾸어 계산하면 ⟨□/6⟩ − ⟨△/6⟩ = ⟨○/6⟩이에요. ○에 알맞은 수를 쓰세요.","answer":["23"],"explanation":["⟨5 3/6⟩ = ⟨33/6⟩, ⟨1 4/6⟩ = ⟨10/6⟩.","⟨33/6⟩ − ⟨10/6⟩ = ⟨23/6⟩.","○ = 23 — 대분수로 ⟨3 5/6⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L08_basic#9','math',4,2,'u1','L08','g4_2_math_u1_L08_basic','lesson_basic','M4-2-u1-C9',2,'error','auto','친구들이 대분수의 뺄셈을 했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M4-2-u1-X09','M4-2-u1-X15']::text[],true,'{"seq":9,"concept":"M4-2-u1-C9","difficulty":2,"kind":"error","stem":"친구들이 대분수의 뺄셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"하윤 — ⟨3 3/7⟩ − ⟨1 5/7⟩ = ⟨2 5/7⟩","correct":true,"mis_target":"M4-2-u1-X09"},{"t":"서준 — ⟨7 3/5⟩ − ⟨3 4/5⟩ = ⟨3 4/5⟩","mis":"M4-2-u1-X15"},{"t":"도연 — ⟨5 3/7⟩ − ⟨3 6/7⟩ = ⟨1 4/7⟩","mis":"M4-2-u1-X15"},{"t":"준우 — ⟨3 2/6⟩ − ⟨2 3/6⟩ = ⟨5/6⟩","mis":"M4-2-u1-X15"}],"explanation":["⟨3/7⟩ − ⟨5/7⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨3 3/7⟩ = ⟨2 10/7⟩.","자연수끼리 2 − 1 = 1, 분수끼리 ⟨10/7⟩ − ⟨5/7⟩ = ⟨5/7⟩ — 답 ⟨1 5/7⟩."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 친구들이 대분수의 뺄셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"민서 — ⟨6 1/4⟩ − ⟨1 3/4⟩ = ⟨5 2/4⟩","correct":true,"mis_target":"M4-2-u1-X11"},{"t":"서윤 — ⟨4 1/3⟩ − ⟨3 2/3⟩ = ⟨2/3⟩","mis":"M4-2-u1-X15"},{"t":"준우 — ⟨2 1/4⟩ − ⟨1 2/4⟩ = ⟨3/4⟩","mis":"M4-2-u1-X15"},{"t":"건우 — ⟨2 3/5⟩ − ⟨1 4/5⟩ = ⟨4/5⟩","mis":"M4-2-u1-X15"}],"explanation":["⟨1/4⟩ − ⟨3/4⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨6 1/4⟩ = ⟨5 5/4⟩.","자연수끼리 5 − 1 = 4, 분수끼리 ⟨5/4⟩ − ⟨3/4⟩ = ⟨2/4⟩ — 답 ⟨4 2/4⟩."],"asset":null},{"stem":"이번에는 다른 문제예요. 친구들이 대분수의 뺄셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"준우 — ⟨5 1/4⟩ − ⟨3 3/4⟩ = ⟨2 2/4⟩","correct":true,"mis_target":"M4-2-u1-X09"},{"t":"서윤 — ⟨7 2/6⟩ − ⟨6 5/6⟩ = ⟨3/6⟩","mis":"M4-2-u1-X15"},{"t":"은비 — ⟨4 4/9⟩ − ⟨2 6/9⟩ = ⟨1 7/9⟩","mis":"M4-2-u1-X15"},{"t":"민서 — ⟨6 3/6⟩ − ⟨3 5/6⟩ = ⟨2 4/6⟩","mis":"M4-2-u1-X15"}],"explanation":["⟨1/4⟩ − ⟨3/4⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨5 1/4⟩ = ⟨4 5/4⟩.","자연수끼리 4 − 3 = 1, 분수끼리 ⟨5/4⟩ − ⟨3/4⟩ = ⟨2/4⟩ — 답 ⟨1 2/4⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.conce