INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L08_basic#10','math',4,2,'u1','L08','g4_2_math_u1_L08_basic','lesson_basic','M4-2-u1-C9',3,'mc','auto','□ − ⟨1 6/7⟩ = ⟨1 3/7⟩일 때, □에 알맞은 대분수는 무엇인가요?',ARRAY['M4-2-u1-X16','M4-2-u1-X09']::text[],true,'{"seq":10,"concept":"M4-2-u1-C9","difficulty":3,"kind":"mc","stem":"□ − ⟨1 6/7⟩ = ⟨1 3/7⟩일 때, □에 알맞은 대분수는 무엇인가요?","options":[{"t":"⟨3 2/7⟩","correct":true},{"t":"⟨3 3/7⟩","mis":"M4-2-u1-X16"},{"t":"⟨3 1/7⟩","mis":"M4-2-u1-X16"},{"t":"⟨2 2/7⟩","mis":"M4-2-u1-X09"}],"explanation":["□에서 ⟨1 6/7⟩을 덜어 ⟨1 3/7⟩이 남았어요.","덧셈으로 되돌려요 — □ = ⟨1 3/7⟩ + ⟨1 6/7⟩.","□ = ⟨3 2/7⟩."],"variant_rule":{"alt":[{"stem":"□ − ⟨3 8/9⟩ = ⟨5/9⟩일 때, □에 알맞은 대분수는 무엇인가요?","options":[{"t":"⟨4 4/9⟩","correct":true},{"t":"⟨4 5/9⟩","mis":"M4-2-u1-X16"},{"t":"⟨4 3/9⟩","mis":"M4-2-u1-X16"},{"t":"⟨3 4/9⟩","mis":"M4-2-u1-X09"}],"explanation":["□에서 ⟨3 8/9⟩을 덜어 ⟨5/9⟩가 남았어요.","덧셈으로 되돌려요 — □ = ⟨5/9⟩ + ⟨3 8/9⟩.","□ = ⟨4 4/9⟩."],"asset":null},{"stem":"□ − ⟨4 7/8⟩ = ⟨7/8⟩일 때, □에 알맞은 대분수는 무엇인가요?","options":[{"t":"⟨5 6/8⟩","correct":true},{"t":"⟨5 7/8⟩","mis":"M4-2-u1-X16"},{"t":"⟨5 5/8⟩","mis":"M4-2-u1-X16"},{"t":"⟨4 6/8⟩","mis":"M4-2-u1-X09"}],"explanation":["□에서 ⟨4 7/8⟩을 덜어 ⟨7/8⟩이 남았어요.","덧셈으로 되돌려요 — □ = ⟨7/8⟩ + ⟨4 7/8⟩.","□ = ⟨5 6/8⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L08_challenge#1','math',4,2,'u1','L08','g4_2_math_u1_L08_challenge','lesson_challenge','M4-2-u1-C9',2,'mc','auto','⟨3 3/6⟩ − ⟨2 5/6⟩를 계산하면 얼마인가요?',ARRAY['M4-2-u1-X11','M4-2-u1-X09','M4-2-u1-X12']::text[],true,'{"seq":1,"concept":"M4-2-u1-C9","difficulty":2,"kind":"mc","stem":"⟨3 3/6⟩ − ⟨2 5/6⟩를 계산하면 얼마인가요?","options":[{"t":"⟨4/6⟩","correct":true},{"t":"⟨1 2/6⟩","mis":"M4-2-u1-X11"},{"t":"⟨1 4/6⟩","mis":"M4-2-u1-X09"},{"t":"⟨8/6⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨3/6⟩ − ⟨5/6⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨3 3/6⟩ = ⟨2 9/6⟩.","자연수끼리 2 − 2 = 0, 분수끼리 ⟨9/6⟩ − ⟨5/6⟩ = ⟨4/6⟩ — 답 ⟨4/6⟩."],"variant_rule":{"alt":[{"stem":"⟨9 1/12⟩ − ⟨3 7/12⟩을 계산하면 얼마인가요?","options":[{"t":"⟨5 6/12⟩","correct":true},{"t":"⟨6 6/12⟩","mis":"M4-2-u1-X11"},{"t":"⟨5 4/12⟩","mis":"M4-2-u1-X12"},{"t":"⟨5 7/12⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨1/12⟩ − ⟨7/12⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨9 1/12⟩ = ⟨8 13/12⟩.","자연수끼리 8 − 3 = 5, 분수끼리 ⟨13/12⟩ − ⟨7/12⟩ = ⟨6/12⟩ — 답 ⟨5 6/12⟩."],"asset":null},{"stem":"⟨9 3/11⟩ − ⟨4 4/11⟩를 계산하면 얼마인가요?","options":[{"t":"⟨4 10/11⟩","correct":true},{"t":"⟨5 1/11⟩","mis":"M4-2-u1-X11"},{"t":"⟨5 10/11⟩","mis":"M4-2-u1-X09"},{"t":"⟨4 9/11⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨3/11⟩ − ⟨4/11⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨9 3/11⟩ = ⟨8 14/11⟩.","자연수끼리 8 − 4 = 4, 분수끼리 ⟨14/11⟩ − ⟨4/11⟩ = ⟨10/11⟩ — 답 ⟨4 10/11⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L08_challenge#2','math',4,2,'u1','L08','g4_2_math_u1_L08_challenge','lesson_challenge','M4-2-u1-C9',2,'mc','auto','곰이는 자전거로 ⟨8 1/9⟩ km, 펭이는 ⟨4 2/9⟩ km를 달렸어요. 곰이는 펭이보다 몇 km 더 달렸나요?',ARRAY['M4-2-u1-X11','M4-2-u1-X09','M4-2-u1-X12']::text[],true,'{"seq":2,"concept":"M4-2-u1-C9","difficulty":2,"kind":"mc","stem":"곰이는 자전거로 ⟨8 1/9⟩ km, 펭이는 ⟨4 2/9⟩ km를 달렸어요. 곰이는 펭이보다 몇 km 더 달렸나요?","options":[{"t":"⟨3 8/9⟩ km","correct":true},{"t":"⟨4 1/9⟩ km","mis":"M4-2-u1-X11"},{"t":"⟨4 8/9⟩ km","mis":"M4-2-u1-X09"},{"t":"⟨3 9/9⟩ km","mis":"M4-2-u1-X12"}],"explanation":["⟨1/9⟩ − ⟨2/9⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨8 1/9⟩ = ⟨7 10/9⟩.","자연수끼리 7 − 4 = 3, 분수끼리 ⟨10/9⟩ − ⟨2/9⟩ = ⟨8/9⟩ — 답 ⟨3 8/9⟩."],"variant_rule":{"alt":[{"stem":"곰이는 자전거로 ⟨6 3/8⟩ km, 펭이는 ⟨3 5/8⟩ km를 달렸어요. 곰이는 펭이보다 몇 km 더 달렸나요?","options":[{"t":"⟨2 6/8⟩ km","correct":true},{"t":"⟨3 2/8⟩ km","mis":"M4-2-u1-X11"},{"t":"⟨3 6/8⟩ km","mis":"M4-2-u1-X09"},{"t":"⟨2 8/8⟩ km","mis":"M4-2-u1-X12"}],"explanation":["⟨3/8⟩ − ⟨5/8⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨6 3/8⟩ = ⟨5 11/8⟩.","자연수끼리 5 − 3 = 2, 분수끼리 ⟨11/8⟩ − ⟨5/8⟩ = ⟨6/8⟩ — 답 ⟨2 6/8⟩."],"asset":null},{"stem":"곰이는 자전거로 ⟨5 7/10⟩ km, 펭이는 ⟨2 8/10⟩ km를 달렸어요. 곰이는 펭이보다 몇 km 더 달렸나요?","options":[{"t":"⟨2 9/10⟩ km","correct":true},{"t":"⟨3 1/10⟩ km","mis":"M4-2-u1-X11"},{"t":"⟨3 9/10⟩ km","mis":"M4-2-u1-X09"},{"t":"3 km","mis":"M4-2-u1-X16"}],"explanation":["⟨7/10⟩ − ⟨8/10⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨5 7/10⟩ = ⟨4 17/10⟩.","자연수끼리 4 − 2 = 2, 분수끼리 ⟨17/10⟩ − ⟨8/10⟩ = ⟨9/10⟩ — 답 ⟨2 9/10⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, i