INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L08_challenge#4','math',4,2,'u1','L08','g4_2_math_u1_L08_challenge','lesson_challenge','M4-2-u1-C9',3,'mc','auto','□ − ⟨5 7/8⟩ = ⟨2 4/8⟩일 때, □에 알맞은 대분수는 무엇인가요?',ARRAY['M4-2-u1-X16','M4-2-u1-X09']::text[],true,'{"seq":4,"concept":"M4-2-u1-C9","difficulty":3,"kind":"mc","stem":"□ − ⟨5 7/8⟩ = ⟨2 4/8⟩일 때, □에 알맞은 대분수는 무엇인가요?","options":[{"t":"⟨8 3/8⟩","correct":true},{"t":"⟨8 4/8⟩","mis":"M4-2-u1-X16"},{"t":"⟨8 2/8⟩","mis":"M4-2-u1-X16"},{"t":"⟨7 3/8⟩","mis":"M4-2-u1-X09"}],"explanation":["□에서 ⟨5 7/8⟩을 덜어 ⟨2 4/8⟩가 남았어요.","덧셈으로 되돌려요 — □ = ⟨2 4/8⟩ + ⟨5 7/8⟩.","□ = ⟨8 3/8⟩."],"variant_rule":{"alt":[{"stem":"□ − ⟨4 4/5⟩ = ⟨3/5⟩일 때, □에 알맞은 대분수는 무엇인가요?","options":[{"t":"⟨5 2/5⟩","correct":true},{"t":"⟨5 3/5⟩","mis":"M4-2-u1-X16"},{"t":"⟨5 1/5⟩","mis":"M4-2-u1-X16"},{"t":"⟨4 2/5⟩","mis":"M4-2-u1-X09"}],"explanation":["□에서 ⟨4 4/5⟩를 덜어 ⟨3/5⟩이 남았어요.","덧셈으로 되돌려요 — □ = ⟨3/5⟩ + ⟨4 4/5⟩.","□ = ⟨5 2/5⟩."],"asset":null},{"stem":"□ − ⟨5 10/11⟩ = ⟨10/11⟩일 때, □에 알맞은 대분수는 무엇인가요?","options":[{"t":"⟨6 9/11⟩","correct":true},{"t":"⟨6 10/11⟩","mis":"M4-2-u1-X16"},{"t":"⟨6 8/11⟩","mis":"M4-2-u1-X16"},{"t":"⟨5 9/11⟩","mis":"M4-2-u1-X09"}],"explanation":["□에서 ⟨5 10/11⟩을 덜어 ⟨10/11⟩이 남았어요.","덧셈으로 되돌려요 — □ = ⟨10/11⟩ + ⟨5 10/11⟩.","□ = ⟨6 9/11⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L08_challenge#5','math',4,2,'u1','L08','g4_2_math_u1_L08_challenge','lesson_challenge','M4-2-u1-C9',3,'mc','auto','계산 결과가 가장 큰 것은 무엇인가요?',ARRAY['M4-2-u1-X15','M4-2-u1-X17']::text[],true,'{"seq":5,"concept":"M4-2-u1-C9","difficulty":3,"kind":"mc","stem":"계산 결과가 가장 큰 것은 무엇인가요?","options":[{"t":"⟨4 1/7⟩ − ⟨2 3/7⟩","correct":true},{"t":"⟨4 4/7⟩ − ⟨3 6/7⟩","mis":"M4-2-u1-X15"},{"t":"⟨4 1/7⟩ − ⟨2 6/7⟩","mis":"M4-2-u1-X17"},{"t":"⟨5 5/7⟩ − ⟨4 6/7⟩","mis":"M4-2-u1-X17"}],"explanation":["하나씩 계산해요 — ⟨5/7⟩, ⟨1 5/7⟩, ⟨1 2/7⟩, ⟨6/7⟩.","자연수 부분부터 견주어요.","가장 큰 것은 ⟨4 1/7⟩ − ⟨2 3/7⟩ = ⟨1 5/7⟩."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 계산 결과가 가장 큰 것은 무엇인가요?","options":[{"t":"⟨4 1/8⟩ − ⟨1 3/8⟩","correct":true},{"t":"⟨4 1/8⟩ − ⟨1 4/8⟩","mis":"M4-2-u1-X17"},{"t":"⟨3 6/8⟩ − ⟨2 7/8⟩","mis":"M4-2-u1-X17"},{"t":"⟨3 4/8⟩ − ⟨2 7/8⟩","mis":"M4-2-u1-X15"}],"explanation":["하나씩 계산해요 — ⟨2 5/8⟩, ⟨7/8⟩, ⟨5/8⟩, ⟨2 6/8⟩.","자연수 부분부터 견주어요.","가장 큰 것은 ⟨4 1/8⟩ − ⟨1 3/8⟩ = ⟨2 6/8⟩."],"asset":null},{"stem":"이번에는 다른 문제예요. 계산 결과가 가장 큰 것은 무엇인가요?","options":[{"t":"⟨4 2/8⟩ − ⟨1 6/8⟩","correct":true},{"t":"⟨3 5/8⟩ − ⟨1 7/8⟩","mis":"M4-2-u1-X17"},{"t":"⟨5 3/8⟩ − ⟨3 7/8⟩","mis":"M4-2-u1-X15"},{"t":"⟨5 2/8⟩ − ⟨3 3/8⟩","mis":"M4-2-u1-X17"}],"explanation":["하나씩 계산해요 — ⟨1 6/8⟩, ⟨1 4/8⟩, ⟨1 7/8⟩, ⟨2 4/8⟩.","자연수 부분부터 견주어요.","가장 큰 것은 ⟨4 2/8⟩ − ⟨1 6/8⟩ = ⟨2 4/8⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L08_challenge#6','math',4,2,'u1','L08','g4_2_math_u1_L08_challenge','lesson_challenge','M4-2-u1-C9',3,'mc','auto','계산 결과가 가장 작은 것은 무엇인가요?',ARRAY['M4-2-u1-X15','M4-2-u1-X17']::text[],true,'{"seq":6,"concept":"M4-2-u1-C9","difficulty":3,"kind":"mc","stem":"계산 결과가 가장 작은 것은 무엇인가요?","options":[{"t":"⟨6 1/9⟩ − ⟨5 7/9⟩","correct":true},{"t":"⟨6 4/9⟩ − ⟨1 6/9⟩","mis":"M4-2-u1-X15"},{"t":"⟨3 1/9⟩ − ⟨1 7/9⟩","mis":"M4-2-u1-X17"},{"t":"⟨6 4/9⟩ − ⟨2 7/9⟩","mis":"M4-2-u1-X17"}],"explanation":["하나씩 계산해요 — ⟨4 7/9⟩, ⟨1 3/9⟩, ⟨3/9⟩, ⟨3 6/9⟩.","자연수 부분부터 견주어요.","가장 작은 것은 ⟨6 1/9⟩ − ⟨5 7/9⟩ = ⟨3/9⟩."],"variant_rule":{"alt":[{"stem":"이번에는 다른 문제예요. 계산 결과가 가장 작은 것은 무엇인가요?","options":[{"t":"⟨5 1/6⟩ − ⟨4 4/6⟩","correct":true},{"t":"⟨4 4/6⟩ − ⟨3 5/6⟩","mis":"M4-2-u1-X17"},{"t":"⟨4 3/6⟩ − ⟨1 5/6⟩","mis":"M4-2-u1-X15"},{"t":"⟨6 2/6⟩ − ⟨4 3/6⟩","mis":"M4-2-u1-X17"}],"explanation":["하나씩 계산해요 — ⟨3/6⟩, ⟨5/6⟩, ⟨2 4/6⟩, ⟨1 5/6⟩.","자연수 부분부터 견주어요.","가장 작은 것은 ⟨5 1/6⟩ − ⟨4 4/6⟩ = ⟨3/6⟩."],"asset":null},{"stem":"이번에는 다른 문제예요. 계산 결과가 가장 작은 것은 무엇인가요?","options":[{"t":"⟨3 3/7⟩ − ⟨1 6/7⟩","correct":true},{"t":"⟨5 3/7⟩ − ⟨2 4/7⟩","mis":"M4-2-u1-X17"},{"t":"⟨5 3/7⟩ − ⟨3 4/7⟩","mis":"M4-2-u1-X17"},{"t":"⟨6 5/7⟩ − ⟨1 6/7⟩","mis":"M4-2-u1-X15"}],"explanation":["하나씩 계산해요 — ⟨2 6/7⟩, ⟨1 6/7⟩, ⟨4 6/7⟩, ⟨1 4/7⟩.","자연수 부분부터 견주어요.","가장 작은 것은 ⟨3 3/7⟩ − ⟨1 6/7⟩ = ⟨1 4/7⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L08_challenge#7','math',4,2,'u1','L08','g4_2_math_u1_L08_challenge','lesson_challenge','M4-2-u1-C9',3,'ox','auto','채원이 「⟨2 1/6⟩ − ⟨1 2/6⟩ = ⟨1 1/6⟩이야.」라고 했어요. 바르게 계산했어요.',ARRAY['M4-2-u1-X11']::text[],true,'{"seq":7,"concept":"M4-2-u1-C9","difficulty":3,"kind":"ox","stem":"채원이 「⟨2 1/6⟩ − ⟨1 2/6⟩ = ⟨1 1/6⟩이야.」라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"진분수끼리 뺄 수 없으면 1만큼 바꾸어 빼야 해서","correct":true},{"t":"큰 분자에서 작은 분자를 빼면 되어서","mis":"M4-2-u1-X11"}],"mis":"M4-2-u1-X11","explanation":["⟨1/6⟩ − ⟨2/6⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨2 1/6⟩ = ⟨1 7/6⟩.","자연수끼리 1 − 1 = 0, 분수끼리 ⟨7/6⟩ − ⟨2/6⟩ = ⟨5/6⟩ — 답 ⟨5/6⟩."],"variant_rule":{"alt":[{"stem":"준우가 「⟨3 7/11⟩ − ⟨1 8/11⟩ = ⟨2 10/11⟩이야.」라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"1만큼 바꾼 만큼 자연수 부분이 1 줄어야 해서","correct":true},{"t":"자연수끼리 그대로 빼면 되어서","mis":"M4-2-u1-X09"}],"explanation":["⟨7/11⟩ − ⟨8/11⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨3 7/11⟩ = ⟨2 18/11⟩.","자연수끼리 2 − 1 = 1, 분수끼리 ⟨18/11⟩ − ⟨8/11⟩ = ⟨10/11⟩ — 답 ⟨1 10/11⟩."],"asset":null},{"stem":"서준이 「⟨8 6/10⟩ − ⟨4 9/10⟩ = ⟨4 3/10⟩이야.」라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"진분수끼리 뺄 수 없으면 1만큼 바꾸어 빼야 해서","correct":true},{"t":"큰 분자에서 작은 분자를 빼면 되어서","mis":"M4-2-u1-X11"}],"explanation":["⟨6/10⟩ − ⟨9/10⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨8 6/10⟩ = ⟨7 16/10⟩.","자연수끼리 7 − 4 = 3, 분수끼리 ⟨16/10⟩ − ⟨9/10⟩ = ⟨7/10⟩ — 답 ⟨3 7/10⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L08_challenge#8','math',4,2,'u1','L08','g4_2_math_u1_L08_challenge','lesson_challenge','M4-2-u1-C9',4,'essay','teacher','⟨3 2/7⟩ − ⟨1 6/7⟩을 두 가지 방법(1만큼 바꾸어 부분끼리 빼기, 가분수로 바꾸어 빼기)으로 계산해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u1-C9","difficulty":4,"kind":"essay","stem":"⟨3 2/7⟩ − ⟨1 6/7⟩을 두 가지 방법(1만큼 바꾸어 부분끼리 빼기, 가분수로 바꾸어 빼기)으로 계산해 보세요.","answer_guide":{"answer":"예: ① ⟨3 2/7⟩ = ⟨2 9/7⟩로 바꾸면 자연수끼리 2 − 1 = 1, 분수끼리 ⟨9/7⟩ − ⟨6/7⟩ = ⟨3/7⟩이므로 ⟨1 3/7⟩. ② ⟨23/7⟩ − ⟨13/7⟩ = ⟨10/7⟩ = ⟨1 3/7⟩. 두 답이 같다.","scoring_points":["⟨3 2/7⟩ = ⟨2 9/7⟩로 바꾸었는가","⟨23/7⟩ − ⟨13/7⟩ = ⟨10/7⟩을 구했는가","⟨1 3/7⟩이라고 답했는가"]},"explanation":["⟨2 9/7⟩ − ⟨1 6/7⟩.","⟨23/7⟩ − ⟨13/7⟩ = ⟨10/7⟩.","⟨1 3/7⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L08_challenge#9','math',4,2,'u1','L08','g4_2_math_u1_L08_challenge','lesson_challenge','M4-2-u1-C9',4,'essay','teacher','지훈이는 ⟨5 1/6⟩ − ⟨2 5/6⟩ = ⟨3 4/6⟩이라고 계산했어요. 지훈이가 잘못한 곳을 찾아 설명하고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u1-C9","difficulty":4,"kind":"essay","stem":"지훈이는 ⟨5 1/6⟩ − ⟨2 5/6⟩ = ⟨3 4/6⟩이라고 계산했어요. 지훈이가 잘못한 곳을 찾아 설명하고 바르게 계산해 보세요.","answer_guide":{"answer":"예: ⟨1/6⟩에서 ⟨5/6⟩를 뺄 수 없는데 지훈이는 ⟨5/6⟩ − ⟨1/6⟩로 거꾸로 뺐다. ⟨5 1/6⟩ = ⟨4 7/6⟩로 바꾸면 ⟨4 7/6⟩ − ⟨2 5/6⟩ = ⟨2 2/6⟩이다.","scoring_points":["분자를 거꾸로 뺀 잘못을 짚었는가","⟨5 1/6⟩ = ⟨4 7/6⟩로 바꾸었는가","⟨2 2/6⟩이라고 답했는가"]},"explanation":["거꾸로 빼면 안 돼요.","⟨5 1/6⟩ = ⟨4 7/6⟩.","⟨2 2/6⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L08_challenge#10','math',4,2,'u1','L08','g4_2_math_u1_L08_challenge','lesson_challenge','M4-2-u1-C9',4,'mc','auto','□ − ⟨2 4/6⟩ = ⟨6 5/6⟩일 때, □에 알맞은 대분수는 무엇인가요?',ARRAY['M4-2-u1-X14','M4-2-u1-X16']::text[],true,'{"seq":10,"concept":"M4-2-u1-C9","difficulty":4,"kind":"mc","stem":"□ − ⟨2 4/6⟩ = ⟨6 5/6⟩일 때, □에 알맞은 대분수는 무엇인가요?","options":[{"t":"⟨9 3/6⟩","correct":true},{"t":"⟨4 1/6⟩","mis":"M4-2-u1-X14"},{"t":"⟨9 4/6⟩","mis":"M4-2-u1-X16"},{"t":"⟨9 2/6⟩","mis":"M4-2-u1-X16"}],"explanation":["□에서 ⟨2 4/6⟩를 덜어 ⟨6 5/6⟩가 남았어요.","덧셈으로 되돌려요 — □ = ⟨6 5/6⟩ + ⟨2 4/6⟩.","□ = ⟨9 3/6⟩."],"variant_rule":{"alt":[{"stem":"□ − ⟨2 7/8⟩ = ⟨1 2/8⟩일 때, □에 알맞은 대분수는 무엇인가요?","options":[{"t":"⟨4 1/8⟩","correct":true},{"t":"⟨4 2/8⟩","mis":"M4-2-u1-X16"},{"t":"4","mis":"M4-2-u1-X16"},{"t":"⟨3 1/8⟩","mis":"M4-2-u1-X09"}],"explanation":["□에서 ⟨2 7/8⟩을 덜어 ⟨1 2/8⟩가 남았어요.","덧셈으로 되돌려요 — □ = ⟨1 2/8⟩ + ⟨2 7/8⟩.","□ = ⟨4 1/8⟩."],"asset":null},{"stem":"□ − ⟨4 7/8⟩ = ⟨2 7/8⟩일 때, □에 알맞은 대분수는 무엇인가요?","options":[{"t":"⟨7 6/8⟩","correct":true},{"t":"⟨7 7/8⟩","mis":"M4-2-u1-X16"},{"t":"⟨7 5/8⟩","mis":"M4-2-u1-X16"},{"t":"⟨6 6/8⟩","mis":"M4-2-u1-X09"}],"explanation":["□에서 ⟨4 7/8⟩을 덜어 ⟨2 7/8⟩이 남았어요.","덧셈으로 되돌려요 — □ = ⟨2 7/8⟩ + ⟨4 7/8⟩.","□ = ⟨7 6/8⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L09_basic#1','math',4,2,'u1','L09','g4_2_math_u1_L09_basic','lesson_basic','M4-2-u1-C10',1,'mc','auto','분수 카드 ⟨1 3/8⟩, ⟨2 3/8⟩, ⟨1 1/8⟩, ⟨2 1/8⟩ 중 두 장을 골라 합이 가장 크게 되도록 더하면 얼마인가요?',ARRAY['M4-2-u1-X17','M4-2-u1-X15']::text[],true,'{"seq":1,"concept":"M4-2-u1-C10","difficulty":1,"kind":"mc","stem":"분수 카드 ⟨1 3/8⟩, ⟨2 3/8⟩, ⟨1 1/8⟩, ⟨2 1/8⟩ 중 두 장을 골라 합이 가장 크게 되도록 더하면 얼마인가요?","options":[{"t":"⟨4 4/8⟩","correct":true},{"t":"⟨3 4/8⟩","mis":"M4-2-u1-X17"},{"t":"⟨2 4/8⟩","mis":"M4-2-u1-X15"},{"t":"⟨3 6/8⟩","mis":"M4-2-u1-X17"}],"explanation":["합이 가장 크려면 가장 큰 수와 둘째로 큰 수를 골라요.","⟨2 3/8⟩ + ⟨2 1/8⟩.","= ⟨4 4/8⟩."],"variant_rule":{"alt":[{"stem":"분수 카드 ⟨1/6⟩, ⟨1 2/6⟩, ⟨2 1/6⟩, ⟨1 3/6⟩ 중 두 장을 골라 합이 가장 크게 되도록 더하면 얼마인가요?","options":[{"t":"⟨3 4/6⟩","correct":true},{"t":"⟨2 2/6⟩","mis":"M4-2-u1-X17"},{"t":"⟨1 3/6⟩","mis":"M4-2-u1-X15"},{"t":"⟨3 3/6⟩","mis":"M4-2-u1-X17"}],"explanation":["합이 가장 크려면 가장 큰 수와 둘째로 큰 수를 골라요.","⟨2 1/6⟩ + ⟨1 3/6⟩.","= ⟨3 4/6⟩."],"asset":null},{"stem":"분수 카드 ⟨3/7⟩, ⟨2/7⟩, ⟨1 4/7⟩, ⟨1 5/7⟩ 중 두 장을 골라 합이 가장 크게 되도록 더하면 얼마인가요?","options":[{"t":"⟨3 2/7⟩","correct":true},{"t":"2","mis":"M4-2-u1-X17"},{"t":"⟨5/7⟩","mis":"M4-2-u1-X15"},{"t":"⟨2 1/7⟩","mis":"M4-2-u1-X17"}],"explanation":["합이 가장 크려면 가장 큰 수와 둘째로 큰 수를 골라요.","⟨1 5/7⟩ + ⟨1 4/7⟩.","= ⟨3 2/7⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L09_basic#2','math',4,2,'u1','L09','g4_2_math_u1_L09_basic','lesson_basic','M4-2-u1-C10',1,'mc','auto','분수 카드 ⟨5/9⟩, ⟨6/9⟩, ⟨1 1/9⟩, ⟨2/9⟩ 중 두 장을 골라 차가 가장 크게 되도록 빼면 얼마인가요?',ARRAY['M4-2-u1-X17','M4-2-u1-X15','M4-2-u1-X14']::text[],true,'{"seq":2,"concept":"M4-2-u1-C10","difficulty":1,"kind":"mc","stem":"분수 카드 ⟨5/9⟩, ⟨6/9⟩, ⟨1 1/9⟩, ⟨2/9⟩ 중 두 장을 골라 차가 가장 크게 되도록 빼면 얼마인가요?","options":[{"t":"⟨8/9⟩","correct":true},{"t":"⟨5/9⟩","mis":"M4-2-u1-X17"},{"t":"⟨3/9⟩","mis":"M4-2-u1-X15"},{"t":"⟨1 3/9⟩","mis":"M4-2-u1-X14"}],"explanation":["차가 가장 크려면 가장 큰 수에서 가장 작은 수를 빼요.","⟨1 1/9⟩ − ⟨2/9⟩.","= ⟨8/9⟩."],"variant_rule":{"alt":[{"stem":"분수 카드 ⟨3/5⟩, ⟨2/5⟩, ⟨1 1/5⟩, ⟨2 3/5⟩ 중 두 장을 골라 차가 가장 크게 되도록 빼면 얼마인가요?","options":[{"t":"⟨2 1/5⟩","correct":true},{"t":"2","mis":"M4-2-u1-X17"},{"t":"⟨1/5⟩","mis":"M4-2-u1-X15"},{"t":"3","mis":"M4-2-u1-X14"}],"explanation":["차가 가장 크려면 가장 큰 수에서 가장 작은 수를 빼요.","⟨2 3/5⟩ − ⟨2/5⟩.","= ⟨2 1/5⟩."],"asset":null},{"stem":"분수 카드 ⟨1 4/8⟩, ⟨1 5/8⟩, ⟨2 3/8⟩, ⟨1 3/8⟩ 중 두 장을 골라 차가 가장 크게 되도록 빼면 얼마인가요?","options":[{"t":"1","correct":true},{"t":"⟨7/8⟩","mis":"M4-2-u1-X17"},{"t":"⟨1/8⟩","mis":"M4-2-u1-X15"},{"t":"⟨3 6/8⟩","mis":"M4-2-u1-X14"}],"explanation":["차가 가장 크려면 가장 큰 수에서 가장 작은 수를 빼요.","⟨2 3/8⟩ − ⟨1 3/8⟩.","= 1."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L09_basic#3','math',4,2,'u1','L09','g4_2_math_u1_L09_basic','lesson_basic','M4-2-u1-C3',1,'mc','auto','⟨6/9⟩ + ⟨6/9⟩을 계산하여 대분수로 나타내면 얼마인가요?',ARRAY['M4-2-u1-X01','M4-2-u1-X16']::text[],true,'{"seq":3,"concept":"M4-2-u1-C3","difficulty":1,"kind":"mc","stem":"⟨6/9⟩ + ⟨6/9⟩을 계산하여 대분수로 나타내면 얼마인가요?","options":[{"t":"⟨1 3/9⟩","correct":true},{"t":"⟨12/18⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 4/9⟩","mis":"M4-2-u1-X16"},{"t":"⟨1 2/9⟩","mis":"M4-2-u1-X16"}],"explanation":["분모가 9로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/9⟩이 6 + 6 = 12개.","⟨6/9⟩ + ⟨6/9⟩ = ⟨12/9⟩.","⟨12/9⟩는 1보다 커요 — ⟨12/9⟩ = ⟨1 3/9⟩."],"variant_rule":{"alt":[{"stem":"⟨4/8⟩ + ⟨7/8⟩을 계산하여 대분수로 나타내면 얼마인가요?","options":[{"t":"⟨1 3/8⟩","correct":true},{"t":"⟨11/16⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 4/8⟩","mis":"M4-2-u1-X16"},{"t":"⟨1 2/8⟩","mis":"M4-2-u1-X16"}],"explanation":["분모가 8로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/8⟩이 4 + 7 = 11개.","⟨4/8⟩ + ⟨7/8⟩ = ⟨11/8⟩.","⟨11/8⟩은 1보다 커요 — ⟨11/8⟩ = ⟨1 3/8⟩."],"asset":null},{"stem":"⟨4/5⟩ + ⟨2/5⟩를 계산하여 대분수로 나타내면 얼마인가요?","options":[{"t":"⟨1 1/5⟩","correct":true},{"t":"⟨6/10⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 2/5⟩","mis":"M4-2-u1-X16"},{"t":"1","mis":"M4-2-u1-X16"}],"explanation":["분모가 5로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/5⟩이 4 + 2 = 6개.","⟨4/5⟩ + ⟨2/5⟩ = ⟨6/5⟩.","⟨6/5⟩은 1보다 커요 — ⟨6/5⟩ = ⟨1 1/5⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L09_basic#4','math',4,2,'u1','L09','g4_2_math_u1_L09_basic','lesson_basic','M4-2-u1-C10',1,'sa','auto','⟨2 3/7⟩ + ⟨□/7⟩ < 3일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u1-C10","difficulty":1,"kind":"sa","stem":"⟨2 3/7⟩ + ⟨□/7⟩ < 3일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["3 = ⟨2 7/7⟩ — 진분수끼리의 합이 1보다 작아야 해요.","3 + □ < 7 — □는 1, 2, 3.","모두 3개예요."],"variant_rule":{"alt":[{"stem":"⟨4 2/7⟩ + ⟨□/7⟩ < 5일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["5 = ⟨4 7/7⟩ — 진분수끼리의 합이 1보다 작아야 해요.","2 + □ < 7 — □는 1, 2, 3, 4.","모두 4개예요."],"asset":null},{"stem":"⟨4 1/10⟩ + ⟨□/10⟩ < 5일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["5 = ⟨4 10/10⟩ — 진분수끼리의 합이 1보다 작아야 해요.","1 + □ < 10 — □는 1, 2, 3, 4, 5, 6, 7, 8.","모두 8개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L09_basic#5','math',4,2,'u1','L09','g4_2_math_u1_L09_basic','lesson_basic','M4-2-u1-C10',2,'mc','auto','분수 카드 ⟨2 3/6⟩, ⟨1 3/6⟩, ⟨3 2/6⟩, ⟨3 1/6⟩ 중 두 장을 골라 합이 ⟨6 3/6⟩이 되게 하려고 해요. 어떤 두 장을 골라야 하나요?',ARRAY['M4-2-u1-X17']::text[],true,'{"seq":5,"concept":"M4-2-u1-C10","difficulty":2,"kind":"mc","stem":"분수 카드 ⟨2 3/6⟩, ⟨1 3/6⟩, ⟨3 2/6⟩, ⟨3 1/6⟩ 중 두 장을 골라 합이 ⟨6 3/6⟩이 되게 하려고 해요. 어떤 두 장을 골라야 하나요?","options":[{"t":"⟨3 2/6⟩, ⟨3 1/6⟩","correct":true},{"t":"⟨1 3/6⟩, ⟨3 1/6⟩","mis":"M4-2-u1-X17"},{"t":"⟨2 3/6⟩, ⟨1 3/6⟩","mis":"M4-2-u1-X17"},{"t":"⟨1 3/6⟩, ⟨3 2/6⟩","mis":"M4-2-u1-X17"}],"explanation":["어림해요 — 자연수 부분을 먼저 맞추어 보아요.","⟨3 2/6⟩ + ⟨3 1/6⟩ = ⟨6 3/6⟩.","⟨3 2/6⟩, ⟨3 1/6⟩을 골라요."],"variant_rule":{"alt":[{"stem":"분수 카드 ⟨3 6/8⟩, ⟨1 5/8⟩, ⟨3 4/8⟩, ⟨3 7/8⟩ 중 두 장을 골라 합이 ⟨5 3/8⟩이 되게 하려고 해요. 어떤 두 장을 골라야 하나요?","options":[{"t":"⟨3 6/8⟩, ⟨1 5/8⟩","correct":true},{"t":"⟨1 5/8⟩, ⟨3 4/8⟩","mis":"M4-2-u1-X17"},{"t":"⟨3 6/8⟩, ⟨3 4/8⟩","mis":"M4-2-u1-X17"},{"t":"⟨1 5/8⟩, ⟨3 7/8⟩","mis":"M4-2-u1-X17"}],"explanation":["어림해요 — 자연수 부분을 먼저 맞추어 보아요.","⟨3 6/8⟩ + ⟨1 5/8⟩ = ⟨5 3/8⟩.","⟨3 6/8⟩, ⟨1 5/8⟩를 골라요."],"asset":null},{"stem":"분수 카드 ⟨1 1/7⟩, ⟨1 6/7⟩, ⟨1 4/7⟩, ⟨3 4/7⟩ 중 두 장을 골라 합이 ⟨2 5/7⟩가 되게 하려고 해요. 어떤 두 장을 골라야 하나요?","options":[{"t":"⟨1 1/7⟩, ⟨1 4/7⟩","correct":true},{"t":"⟨1 4/7⟩, ⟨3 4/7⟩","mis":"M4-2-u1-X17"},{"t":"⟨1 6/7⟩, ⟨3 4/7⟩","mis":"M4-2-u1-X17"},{"t":"⟨1 1/7⟩, ⟨3 4/7⟩","mis":"M4-2-u1-X17"}],"explanation":["어림해요 — 자연수 부분을 먼저 맞추어 보아요.","⟨1 1/7⟩ + ⟨1 4/7⟩ = ⟨2 5/7⟩.","⟨1 1/7⟩, ⟨1 4/7⟩를 골라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L09_basic#6','math',4,2,'u1','L09','g4_2_math_u1_L09_basic','lesson_basic','M4-2-u1-C10',2,'mc','auto','어림해서 계산 결과가 7보다 큰 식을 골라 보세요.',ARRAY['M4-2-u1-X17']::text[],true,'{"seq":6,"concept":"M4-2-u1-C10","difficulty":2,"kind":"mc","stem":"어림해서 계산 결과가 7보다 큰 식을 골라 보세요.","options":[{"t":"⟨5 5/6⟩ + ⟨1 5/6⟩","correct":true},{"t":"⟨2 4/6⟩ + ⟨4 1/6⟩","mis":"M4-2-u1-X17"},{"t":"⟨3 1/6⟩ + ⟨3 3/6⟩","mis":"M4-2-u1-X17"},{"t":"⟨5 2/6⟩ + ⟨1 1/6⟩","mis":"M4-2-u1-X17"}],"explanation":["자연수 부분의 합을 먼저 보고, 진분수끼리의 합이 1보다 큰지 어림해요.","⟨5 5/6⟩ + ⟨1 5/6⟩ = ⟨7 4/6⟩.","7보다 큰 것은 ⟨5 5/6⟩ + ⟨1 5/6⟩."],"variant_rule":{"alt":[{"stem":"어림해서 계산 결과가 4보다 큰 식을 골라 보세요.","options":[{"t":"⟨1 7/9⟩ + ⟨2 7/9⟩","correct":true},{"t":"⟨2 7/9⟩ + ⟨1 1/9⟩","mis":"M4-2-u1-X17"},{"t":"⟨2 4/9⟩ + ⟨1 2/9⟩","mis":"M4-2-u1-X17"},{"t":"⟨1 3/9⟩ + ⟨2 2/9⟩","mis":"M4-2-u1-X17"}],"explanation":["자연수 부분의 합을 먼저 보고, 진분수끼리의 합이 1보다 큰지 어림해요.","⟨1 7/9⟩ + ⟨2 7/9⟩ = ⟨4 5/9⟩.","4보다 큰 것은 ⟨1 7/9⟩ + ⟨2 7/9⟩."],"asset":null},{"stem":"어림해서 계산 결과가 6보다 큰 식을 골라 보세요.","options":[{"t":"⟨2 4/6⟩ + ⟨3 5/6⟩","correct":true},{"t":"⟨2 3/6⟩ + ⟨3 1/6⟩","mis":"M4-2-u1-X17"},{"t":"⟨2 3/6⟩ + ⟨3 2/6⟩","mis":"M4-2-u1-X17"},{"t":"⟨3 2/6⟩ + ⟨2 3/6⟩","mis":"M4-2-u1-X17"}],"explanation":["자연수 부분의 합을 먼저 보고, 진분수끼리의 합이 1보다 큰지 어림해요.","⟨2 4/6⟩ + ⟨3 5/6⟩ = ⟨6 3/6⟩.","6보다 큰 것은 ⟨2 4/6⟩ + ⟨3 5/6⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L09_basic#7','math',4,2,'u1','L09','g4_2_math_u1_L09_basic','lesson_basic','M4-2-u1-C10',2,'ox','auto','분수 카드 ⟨4/5⟩, ⟨1 2/5⟩, ⟨2 3/5⟩, ⟨1 1/5⟩이 있어요. 서윤이 「가장 큰 카드에서 가장 작은 카드를 빼면 차가 가장 커.」라고 했어요. 바르게 말했어요.',ARRAY['M4-2-u1-X17']::text[],true,'{"seq":7,"concept":"M4-2-u1-C10","difficulty":2,"kind":"ox","stem":"분수 카드 ⟨4/5⟩, ⟨1 2/5⟩, ⟨2 3/5⟩, ⟨1 1/5⟩이 있어요. 서윤이 「가장 큰 카드에서 가장 작은 카드를 빼면 차가 가장 커.」라고 했어요. 바르게 말했어요.","answer":"O","reason_options":[{"t":"빼어지는 수는 크고 빼는 수는 작을수록 차가 커서","correct":true},{"t":"분자가 큰 카드 하나만 보면 되어서","mis":"M4-2-u1-X17"}],"mis":"M4-2-u1-X17","explanation":["차가 크려면 큰 수에서 작은 수를 빼요.","⟨2 3/5⟩ − ⟨4/5⟩ = ⟨1 4/5⟩.","바르게 말했어요 ○."],"variant_rule":{"alt":[{"stem":"분수 카드 ⟨1/9⟩, ⟨1 2/9⟩, ⟨8/9⟩, ⟨1 3/9⟩이 있어요. 준우가 「가장 큰 카드에서 가장 작은 카드를 빼면 차가 가장 커.」라고 했어요. 바르게 말했어요.","answer":"O","reason_options":[{"t":"빼어지는 수는 크고 빼는 수는 작을수록 차가 커서","correct":true},{"t":"분자가 큰 카드 하나만 보면 되어서","mis":"M4-2-u1-X17"}],"explanation":["차가 크려면 큰 수에서 작은 수를 빼요.","⟨1 3/9⟩ − ⟨1/9⟩ = ⟨1 2/9⟩.","바르게 말했어요 ○."],"asset":null},{"stem":"분수 카드 ⟨1/5⟩, ⟨2 1/5⟩, ⟨3/5⟩, ⟨1 3/5⟩이 있어요. 하윤이 「가장 큰 카드에서 가장 작은 카드를 빼면 차가 가장 커.」라고 했어요. 바르게 말했어요.","answer":"O","reason_options":[{"t":"빼어지는 수는 크고 빼는 수는 작을수록 차가 커서","correct":true},{"t":"분자가 큰 카드 하나만 보면 되어서","mis":"M4-2-u1-X17"}],"explanation":["차가 크려면 큰 수에서 작은 수를 빼요.","⟨2 1/5⟩ − ⟨1/5⟩ = 2.","바르게 말했어요 ○."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
