INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L09_basic#9','math',4,2,'u1','L09','g4_2_math_u1_L09_basic','lesson_basic','M4-2-u1-C5',2,'mc','auto','⟨2 4/5⟩ + ⟨2 2/5⟩를 계산하면 얼마인가요?',ARRAY['M4-2-u1-X07','M4-2-u1-X01','M4-2-u1-X13']::text[],true,'{"seq":9,"concept":"M4-2-u1-C5","difficulty":2,"kind":"mc","stem":"⟨2 4/5⟩ + ⟨2 2/5⟩를 계산하면 얼마인가요?","options":[{"t":"⟨5 1/5⟩","correct":true},{"t":"⟨4 1/5⟩","mis":"M4-2-u1-X07"},{"t":"⟨4 6/10⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 1/5⟩","mis":"M4-2-u1-X13"}],"explanation":["자연수끼리 2 + 2 = 4.","진분수끼리 ⟨4/5⟩ + ⟨2/5⟩ = ⟨6/5⟩ — 1보다 커서 ⟨1 1/5⟩, 1을 자연수로 넘겨요.","⟨2 4/5⟩ + ⟨2 2/5⟩ = ⟨5 1/5⟩."],"variant_rule":{"alt":[{"stem":"⟨1 4/6⟩ + ⟨3 3/6⟩을 계산하면 얼마인가요?","options":[{"t":"⟨5 1/6⟩","correct":true},{"t":"⟨4 1/6⟩","mis":"M4-2-u1-X07"},{"t":"⟨4 7/12⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 1/6⟩","mis":"M4-2-u1-X13"}],"explanation":["자연수끼리 1 + 3 = 4.","진분수끼리 ⟨4/6⟩ + ⟨3/6⟩ = ⟨7/6⟩ — 1보다 커서 ⟨1 1/6⟩, 1을 자연수로 넘겨요.","⟨1 4/6⟩ + ⟨3 3/6⟩ = ⟨5 1/6⟩."],"asset":null},{"stem":"⟨2 3/7⟩ + ⟨2 6/7⟩을 계산하면 얼마인가요?","options":[{"t":"⟨5 2/7⟩","correct":true},{"t":"⟨4 2/7⟩","mis":"M4-2-u1-X07"},{"t":"⟨4 9/14⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 2/7⟩","mis":"M4-2-u1-X13"}],"explanation":["자연수끼리 2 + 2 = 4.","진분수끼리 ⟨3/7⟩ + ⟨6/7⟩ = ⟨9/7⟩ — 1보다 커서 ⟨1 2/7⟩, 1을 자연수로 넘겨요.","⟨2 3/7⟩ + ⟨2 6/7⟩ = ⟨5 2/7⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L09_basic#10','math',4,2,'u1','L09','g4_2_math_u1_L09_basic','lesson_basic','M4-2-u1-C10',3,'mc','auto','수 카드 2, 5, 3 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 8인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 합은 얼마인가요?',ARRAY['M4-2-u1-X17','M4-2-u1-X16','M4-2-u1-X14']::text[],true,'{"seq":10,"concept":"M4-2-u1-C10","difficulty":3,"kind":"mc","stem":"수 카드 2, 5, 3 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 8인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 합은 얼마인가요?","options":[{"t":"⟨7 6/8⟩","correct":true},{"t":"⟨7 7/8⟩","mis":"M4-2-u1-X17"},{"t":"⟨7 5/8⟩","mis":"M4-2-u1-X16"},{"t":"3","mis":"M4-2-u1-X14"}],"explanation":["가장 큰 대분수 — 자연수 부분에 가장 큰 수 5, 분자에 다음 큰 수 3 → ⟨5 3/8⟩.","가장 작은 대분수 — 자연수 부분에 가장 작은 수 2, 분자에 3 → ⟨2 3/8⟩.","⟨5 3/8⟩ + ⟨2 3/8⟩ = ⟨7 6/8⟩."],"variant_rule":{"alt":[{"stem":"수 카드 2, 1, 5 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 7인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 합은 얼마인가요?","options":[{"t":"⟨6 4/7⟩","correct":true},{"t":"⟨6 6/7⟩","mis":"M4-2-u1-X17"},{"t":"⟨6 5/7⟩","mis":"M4-2-u1-X16"},{"t":"⟨6 3/7⟩","mis":"M4-2-u1-X16"}],"explanation":["가장 큰 대분수 — 자연수 부분에 가장 큰 수 5, 분자에 다음 큰 수 2 → ⟨5 2/7⟩.","가장 작은 대분수 — 자연수 부분에 가장 작은 수 1, 분자에 2 → ⟨1 2/7⟩.","⟨5 2/7⟩ + ⟨1 2/7⟩ = ⟨6 4/7⟩."],"asset":null},{"stem":"수 카드 1, 3, 4 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 8인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 합은 얼마인가요?","options":[{"t":"⟨5 6/8⟩","correct":true},{"t":"⟨5 5/8⟩","mis":"M4-2-u1-X17"},{"t":"⟨5 7/8⟩","mis":"M4-2-u1-X16"},{"t":"3","mis":"M4-2-u1-X14"}],"explanation":["가장 큰 대분수 — 자연수 부분에 가장 큰 수 4, 분자에 다음 큰 수 3 → ⟨4 3/8⟩.","가장 작은 대분수 — 자연수 부분에 가장 작은 수 1, 분자에 3 → ⟨1 3/8⟩.","⟨4 3/8⟩ + ⟨1 3/8⟩ = ⟨5 6/8⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDE