INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L09_challenge#4','math',4,2,'u1','L09','g4_2_math_u1_L09_challenge','lesson_challenge','M4-2-u1-C10',3,'mc','auto','분수 카드 ⟨3 4/6⟩, ⟨3 2/6⟩, ⟨3 3/6⟩, ⟨3 5/6⟩ 중 두 장을 골라 차가 ⟨3/6⟩이 되게 하려고 해요. 어떤 두 장을 골라야 하나요?',ARRAY['M4-2-u1-X17']::text[],true,'{"seq":4,"concept":"M4-2-u1-C10","difficulty":3,"kind":"mc","stem":"분수 카드 ⟨3 4/6⟩, ⟨3 2/6⟩, ⟨3 3/6⟩, ⟨3 5/6⟩ 중 두 장을 골라 차가 ⟨3/6⟩이 되게 하려고 해요. 어떤 두 장을 골라야 하나요?","options":[{"t":"⟨3 5/6⟩, ⟨3 2/6⟩","correct":true},{"t":"⟨3 3/6⟩, ⟨3 2/6⟩","mis":"M4-2-u1-X17"},{"t":"⟨3 5/6⟩, ⟨3 4/6⟩","mis":"M4-2-u1-X17"},{"t":"⟨3 5/6⟩, ⟨3 3/6⟩","mis":"M4-2-u1-X17"}],"explanation":["어림해요 — 자연수 부분을 먼저 맞추어 보아요.","⟨3 5/6⟩ − ⟨3 2/6⟩ = ⟨3/6⟩.","⟨3 5/6⟩, ⟨3 2/6⟩를 골라요."],"variant_rule":{"alt":[{"stem":"분수 카드 ⟨3 3/9⟩, ⟨3 5/9⟩, ⟨2 7/9⟩, ⟨2 8/9⟩ 중 두 장을 골라 차가 ⟨7/9⟩이 되게 하려고 해요. 어떤 두 장을 골라야 하나요?","options":[{"t":"⟨3 5/9⟩, ⟨2 7/9⟩","correct":true},{"t":"⟨3 3/9⟩, ⟨2 7/9⟩","mis":"M4-2-u1-X17"},{"t":"⟨3 3/9⟩, ⟨2 8/9⟩","mis":"M4-2-u1-X17"},{"t":"⟨2 8/9⟩, ⟨2 7/9⟩","mis":"M4-2-u1-X17"}],"explanation":["어림해요 — 자연수 부분을 먼저 맞추어 보아요.","⟨3 5/9⟩ − ⟨2 7/9⟩ = ⟨7/9⟩.","⟨3 5/9⟩, ⟨2 7/9⟩을 골라요."],"asset":null},{"stem":"분수 카드 ⟨2 2/6⟩, ⟨3 3/6⟩, ⟨2 5/6⟩, ⟨1 3/6⟩ 중 두 장을 골라 차가 ⟨3/6⟩이 되게 하려고 해요. 어떤 두 장을 골라야 하나요?","options":[{"t":"⟨2 5/6⟩, ⟨2 2/6⟩","correct":true},{"t":"⟨3 3/6⟩, ⟨2 2/6⟩","mis":"M4-2-u1-X17"},{"t":"⟨2 5/6⟩, ⟨1 3/6⟩","mis":"M4-2-u1-X17"},{"t":"⟨2 2/6⟩, ⟨1 3/6⟩","mis":"M4-2-u1-X17"}],"explanation":["어림해요 — 자연수 부분을 먼저 맞추어 보아요.","⟨2 5/6⟩ − ⟨2 2/6⟩ = ⟨3/6⟩.","⟨2 5/6⟩, ⟨2 2/6⟩를 골라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L09_challenge#5','math',4,2,'u1','L09','g4_2_math_u1_L09_challenge','lesson_challenge','M4-2-u1-C10',3,'mc','auto','수 카드 5, 2, 7 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 9인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 합은 얼마인가요?',ARRAY['M4-2-u1-X17','M4-2-u1-X16','M4-2-u1-X14']::text[],true,'{"seq":5,"concept":"M4-2-u1-C10","difficulty":3,"kind":"mc","stem":"수 카드 5, 2, 7 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 9인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 합은 얼마인가요?","options":[{"t":"⟨10 1/9⟩","correct":true},{"t":"10","mis":"M4-2-u1-X17"},{"t":"⟨10 2/9⟩","mis":"M4-2-u1-X16"},{"t":"5","mis":"M4-2-u1-X14"}],"explanation":["가장 큰 대분수 — 자연수 부분에 가장 큰 수 7, 분자에 다음 큰 수 5 → ⟨7 5/9⟩.","가장 작은 대분수 — 자연수 부분에 가장 작은 수 2, 분자에 5 → ⟨2 5/9⟩.","⟨7 5/9⟩ + ⟨2 5/9⟩ = ⟨10 1/9⟩."],"variant_rule":{"alt":[{"stem":"수 카드 7, 1, 4 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 8인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 합은 얼마인가요?","options":[{"t":"9","correct":true},{"t":"⟨9 1/8⟩","mis":"M4-2-u1-X16"},{"t":"⟨8 7/8⟩","mis":"M4-2-u1-X16"},{"t":"6","mis":"M4-2-u1-X14"}],"explanation":["가장 큰 대분수 — 자연수 부분에 가장 큰 수 7, 분자에 다음 큰 수 4 → ⟨7 4/8⟩.","가장 작은 대분수 — 자연수 부분에 가장 작은 수 1, 분자에 4 → ⟨1 4/8⟩.","⟨7 4/8⟩ + ⟨1 4/8⟩ = 9."],"asset":null},{"stem":"수 카드 2, 1, 6 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 7인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 합은 얼마인가요?","options":[{"t":"⟨7 4/7⟩","correct":true},{"t":"8","mis":"M4-2-u1-X17"},{"t":"⟨7 5/7⟩","mis":"M4-2-u1-X16"},{"t":"⟨7 3/7⟩","mis":"M4-2-u1-X16"}],"explanation":["가장 큰 대분수 — 자연수 부분에 가장 큰 수 6, 분자에 다음 큰 수 2 → ⟨6 2/7⟩.","가장 작은 대분수 — 자연수 부분에 가장 작은 수 1, 분자에 2 → ⟨1 2/7⟩.","⟨6 2/7⟩ + ⟨1 2/7⟩ = ⟨7 4/7⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L09_challenge#6','math',4,2,'u1','L09','g4_2_math_u1_L09_challenge','lesson_challenge','M4-2-u1-C10',3,'mc','auto','수 카드 1, 6, 4 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 7인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 차는 얼마인가요?',ARRAY['M4-2-u1-X17','M4-2-u1-X16']::text[],true,'{"seq":6,"concept":"M4-2-u1-C10","difficulty":3,"kind":"mc","stem":"수 카드 1, 6, 4 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 7인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 차는 얼마인가요?","options":[{"t":"5","correct":true},{"t":"⟨4 2/7⟩","mis":"M4-2-u1-X17"},{"t":"⟨5 1/7⟩","mis":"M4-2-u1-X16"},{"t":"⟨4 6/7⟩","mis":"M4-2-u1-X16"}],"explanation":["가장 큰 대분수 — 자연수 부분에 가장 큰 수 6, 분자에 다음 큰 수 4 → ⟨6 4/7⟩.","가장 작은 대분수 — 자연수 부분에 가장 작은 수 1, 분자에 4 → ⟨1 4/7⟩.","⟨6 4/7⟩ − ⟨1 4/7⟩ = 5."],"variant_rule":{"alt":[{"stem":"수 카드 7, 4, 2 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 8인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 차는 얼마인가요?","options":[{"t":"5","correct":true},{"t":"⟨4 3/8⟩","mis":"M4-2-u1-X17"},{"t":"⟨5 1/8⟩","mis":"M4-2-u1-X16"},{"t":"⟨4 7/8⟩","mis":"M4-2-u1-X16"}],"explanation":["가장 큰 대분수 — 자연수 부분에 가장 큰 수 7, 분자에 다음 큰 수 4 → ⟨7 4/8⟩.","가장 작은 대분수 — 자연수 부분에 가장 작은 수 2, 분자에 4 → ⟨2 4/8⟩.","⟨7 4/8⟩ − ⟨2 4/8⟩ = 5."],"asset":null},{"stem":"수 카드 7, 2, 3 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 9인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 차는 얼마인가요?","options":[{"t":"5","correct":true},{"t":"⟨4 4/9⟩","mis":"M4-2-u1-X17"},{"t":"⟨5 1/9⟩","mis":"M4-2-u1-X16"},{"t":"⟨4 8/9⟩","mis":"M4-2-u1-X16"}],"explanation":["가장 큰 대분수 — 자연수 부분에 가장 큰 수 7, 분자에 다음 큰 수 3 → ⟨7 3/9⟩.","가장 작은 대분수 — 자연수 부분에 가장 작은 수 2, 분자에 3 → ⟨2 3/9⟩.","⟨7 3/9⟩ − ⟨2 3/9⟩ = 5."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L09_challenge#7','math',4,2,'u1','L09','g4_2_math_u1_L09_challenge','lesson_challenge','M4-2-u1-C10',3,'sa','auto','⟨2 4/7⟩ + ⟨□/7⟩ < 3일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-2-u1-C10","difficulty":3,"kind":"sa","stem":"⟨2 4/7⟩ + ⟨□/7⟩ < 3일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["3 = ⟨2 7/7⟩ — 진분수끼리의 합이 1보다 작아야 해요.","4 + □ < 7 — □는 1, 2.","모두 2개예요."],"variant_rule":{"alt":[{"stem":"⟨1 1/7⟩ + ⟨□/7⟩ < 2일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["2 = ⟨1 7/7⟩ — 진분수끼리의 합이 1보다 작아야 해요.","1 + □ < 7 — □는 1, 2, 3, 4, 5.","모두 5개예요."],"asset":null},{"stem":"⟨1 2/7⟩ + ⟨□/7⟩ < 2일 때, □ 안에 들어갈 수 있는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["2 = ⟨1 7/7⟩ — 진분수끼리의 합이 1보다 작아야 해요.","2 + □ < 7 — □는 1, 2, 3, 4.","모두 4개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L09_challenge#8','math',4,2,'u1','L09','g4_2_math_u1_L09_challenge','lesson_challenge','M4-2-u1-C10',4,'essay','teacher','분수 카드 ⟨1 3/5⟩, ⟨2 4/5⟩, ⟨1 1/5⟩, ⟨3 2/5⟩ 중 두 장을 골라 합이 4가 되는 덧셈식을 찾으려고 해요. 어림으로 고른 방법과 계산으로 확인한 과정을 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-2-u1-C10","difficulty":4,"kind":"essay","stem":"분수 카드 ⟨1 3/5⟩, ⟨2 4/5⟩, ⟨1 1/5⟩, ⟨3 2/5⟩ 중 두 장을 골라 합이 4가 되는 덧셈식을 찾으려고 해요. 어림으로 고른 방법과 계산으로 확인한 과정을 써 보세요.","answer_guide":{"answer":"예: 자연수 부분의 합이 3이고 진분수끼리의 합이 1이 되어야 한다. ⟨2 4/5⟩와 ⟨1 1/5⟩은 자연수 2 + 1 = 3, 분수 ⟨4/5⟩ + ⟨1/5⟩ = 1이라서 고른다. 계산하면 ⟨2 4/5⟩ + ⟨1 1/5⟩ = ⟨3 5/5⟩ = 4이다.","scoring_points":["⟨2 4/5⟩와 ⟨1 1/5⟩을 골랐는가","자연수·분수 부분으로 어림한 방법을 썼는가","계산으로 4를 확인했는가"]},"explanation":["자연수 합 3 + 분수 합 1.","⟨2 4/5⟩ + ⟨1 1/5⟩.","= 4."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L09_challenge#9','math',4,2,'u1','L09','g4_2_math_u1_L09_challenge','lesson_challenge','M4-2-u1-C10',4,'essay','teacher','수 카드 2, 5, 8 중 두 장을 골라 분모가 9인 대분수를 만들 때, 가장 큰 대분수와 가장 작은 대분수를 쓰고 두 수의 차를 구해 보세요. 왜 그렇게 놓았는지도 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-2-u1-C10","difficulty":4,"kind":"essay","stem":"수 카드 2, 5, 8 중 두 장을 골라 분모가 9인 대분수를 만들 때, 가장 큰 대분수와 가장 작은 대분수를 쓰고 두 수의 차를 구해 보세요. 왜 그렇게 놓았는지도 써 보세요.","answer_guide":{"answer":"예: 가장 큰 대분수는 자연수 부분에 가장 큰 8, 분자에 5를 놓은 ⟨8 5/9⟩, 가장 작은 대분수는 자연수 부분에 가장 작은 2, 분자에 5를 놓은 ⟨2 5/9⟩이다. 차는 ⟨8 5/9⟩ − ⟨2 5/9⟩ = 6이다. 대분수의 크기는 자연수 부분이 먼저 정하기 때문이다.","scoring_points":["⟨8 5/9⟩와 ⟨2 5/9⟩를 썼는가","차 6을 구했는가","자연수 부분이 크기를 먼저 정한다고 썼는가"]},"explanation":["가장 큰 ⟨8 5/9⟩.","가장 작은 ⟨2 5/9⟩.","차 6."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_L09_challenge#10','math',4,2,'u1','L09','g4_2_math_u1_L09_challenge','lesson_challenge','M4-2-u1-C10',4,'mc','auto','수 카드 3, 1, 6 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 8인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 차는 얼마인가요?',ARRAY['M4-2-u1-X17','M4-2-u1-X16']::text[],true,'{"seq":10,"concept":"M4-2-u1-C10","difficulty":4,"kind":"mc","stem":"수 카드 3, 1, 6 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 8인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 차는 얼마인가요?","options":[{"t":"5","correct":true},{"t":"⟨4 3/8⟩","mis":"M4-2-u1-X17"},{"t":"⟨5 1/8⟩","mis":"M4-2-u1-X16"},{"t":"⟨4 7/8⟩","mis":"M4-2-u1-X16"}],"explanation":["가장 큰 대분수 — 자연수 부분에 가장 큰 수 6, 분자에 다음 큰 수 3 → ⟨6 3/8⟩.","가장 작은 대분수 — 자연수 부분에 가장 작은 수 1, 분자에 3 → ⟨1 3/8⟩.","⟨6 3/8⟩ − ⟨1 3/8⟩ = 5."],"variant_rule":{"alt":[{"stem":"수 카드 3, 4, 1 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 7인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 차는 얼마인가요?","options":[{"t":"3","correct":true},{"t":"⟨2 4/7⟩","mis":"M4-2-u1-X17"},{"t":"⟨3 1/7⟩","mis":"M4-2-u1-X16"},{"t":"⟨2 6/7⟩","mis":"M4-2-u1-X16"}],"explanation":["가장 큰 대분수 — 자연수 부분에 가장 큰 수 4, 분자에 다음 큰 수 3 → ⟨4 3/7⟩.","가장 작은 대분수 — 자연수 부분에 가장 작은 수 1, 분자에 3 → ⟨1 3/7⟩.","⟨4 3/7⟩ − ⟨1 3/7⟩ = 3."],"asset":null},{"stem":"수 카드 2, 1, 4 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 8인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 차는 얼마인가요?","options":[{"t":"3","correct":true},{"t":"⟨2 5/8⟩","mis":"M4-2-u1-X17"},{"t":"⟨3 1/8⟩","mis":"M4-2-u1-X16"},{"t":"⟨2 7/8⟩","mis":"M4-2-u1-X16"}],"explanation":["가장 큰 대분수 — 자연수 부분에 가장 큰 수 4, 분자에 다음 큰 수 2 → ⟨4 2/8⟩.","가장 작은 대분수 — 자연수 부분에 가장 작은 수 1, 분자에 2 → ⟨1 2/8⟩.","⟨4 2/8⟩ − ⟨1 2/8⟩ = 3."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_a#1','math',4,2,'u1','','g4_2_math_u1_review_a','unit_review','M4-2-u1-C1',1,'sa','auto','⟨5/4⟩는 ⟨1/4⟩이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-2-u1-C1","difficulty":1,"kind":"sa","stem":"⟨5/4⟩는 ⟨1/4⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["분모 4 — 1을 똑같이 4칸으로 나눈 것 중 한 칸이 ⟨1/4⟩이에요.","분자 5 — ⟨1/4⟩이 5개라는 뜻이에요.","⟨5/4⟩는 ⟨1/4⟩이 5개인 수예요."],"variant_rule":{"alt":[{"stem":"⟨6/4⟩은 ⟨1/4⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["분모 4 — 1을 똑같이 4칸으로 나눈 것 중 한 칸이 ⟨1/4⟩이에요.","분자 6 — ⟨1/4⟩이 6개라는 뜻이에요.","⟨6/4⟩은 ⟨1/4⟩이 6개인 수예요."],"asset":null},{"stem":"⟨13/6⟩은 ⟨1/6⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["분모 6 — 1을 똑같이 6칸으로 나눈 것 중 한 칸이 ⟨1/6⟩이에요.","분자 13 — ⟨1/6⟩이 13개라는 뜻이에요.","⟨13/6⟩은 ⟨1/6⟩이 13개인 수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_a#2','math',4,2,'u1','','g4_2_math_u1_review_a','unit_review','M4-2-u1-C2',1,'sa','auto','1을 ⟨1/7⟩이 3개인 분수와 ⟨1/7⟩이 □개인 분수로 갈랐어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u1-C2","difficulty":1,"kind":"sa","stem":"1을 ⟨1/7⟩이 3개인 분수와 ⟨1/7⟩이 □개인 분수로 갈랐어요. □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["분모가 7이면 1 = ⟨7/7⟩ — ⟨1/7⟩이 7개예요.","7개 중 3개를 떼면 7 − 3 = 4개가 남아요.","□ = 4 — 1 = ⟨3/7⟩ + ⟨4/7⟩."],"variant_rule":{"alt":[{"stem":"1을 ⟨1/4⟩이 3개인 분수와 ⟨1/4⟩이 □개인 분수로 갈랐어요. □에 알맞은 수를 쓰세요.","answer":["1"],"explanation":["분모가 4이면 1 = ⟨4/4⟩ — ⟨1/4⟩이 4개예요.","4개 중 3개를 떼면 4 − 3 = 1개가 남아요.","□ = 1 — 1 = ⟨3/4⟩ + ⟨1/4⟩."],"asset":null},{"stem":"1을 ⟨1/8⟩이 7개인 분수와 ⟨1/8⟩이 □개인 분수로 갈랐어요. □에 알맞은 수를 쓰세요.","answer":["1"],"explanation":["분모가 8이면 1 = ⟨8/8⟩ — ⟨1/8⟩이 8개예요.","8개 중 7개를 떼면 8 − 7 = 1개가 남아요.","□ = 1 — 1 = ⟨7/8⟩ + ⟨1/8⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_a#3','math',4,2,'u1','','g4_2_math_u1_review_a','unit_review','M4-2-u1-C3',1,'sa','auto','⟨2/5⟩ + ⟨1/5⟩ = ⟨□/5⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u1-C3","difficulty":1,"kind":"sa","stem":"⟨2/5⟩ + ⟨1/5⟩ = ⟨□/5⟩ — □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["분모가 5로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/5⟩이 2 + 1 = 3개.","⟨2/5⟩ + ⟨1/5⟩ = ⟨3/5⟩.","분모끼리 더해 ⟨3/10⟩으로 쓰지 않아요."],"variant_rule":{"alt":[{"stem":"⟨4/8⟩ + ⟨3/8⟩ = ⟨□/8⟩ — □에 알맞은 수를 쓰세요.","answer":["7"],"explanation":["분모가 8로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/8⟩이 4 + 3 = 7개.","⟨4/8⟩ + ⟨3/8⟩ = ⟨7/8⟩.","분모끼리 더해 ⟨7/16⟩로 쓰지 않아요."],"asset":null},{"stem":"⟨3/7⟩ + ⟨2/7⟩ = ⟨□/7⟩ — □에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["분모가 7로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/7⟩이 3 + 2 = 5개.","⟨3/7⟩ + ⟨2/7⟩ = ⟨5/7⟩.","분모끼리 더해 ⟨5/14⟩로 쓰지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_a#4','math',4,2,'u1','','g4_2_math_u1_review_a','unit_review','M4-2-u1-C4',1,'sa','auto','1 − ⟨2/5⟩ = ⟨□/5⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u1-C4","difficulty":1,"kind":"sa","stem":"1 − ⟨2/5⟩ = ⟨□/5⟩ — □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["1을 분모가 5인 분수로 바꾸면 ⟨5/5⟩예요.","⟨5/5⟩ − ⟨2/5⟩ — ⟨1/5⟩이 5 − 2 = 3개.","1 − ⟨2/5⟩ = ⟨3/5⟩."],"variant_rule":{"alt":[{"stem":"1 − ⟨3/5⟩ = ⟨□/5⟩ — □에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["1을 분모가 5인 분수로 바꾸면 ⟨5/5⟩예요.","⟨5/5⟩ − ⟨3/5⟩ — ⟨1/5⟩이 5 − 3 = 2개.","1 − ⟨3/5⟩ = ⟨2/5⟩."],"asset":null},{"stem":"1 − ⟨1/4⟩ = ⟨□/4⟩ — □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["1을 분모가 4인 분수로 바꾸면 ⟨4/4⟩예요.","⟨4/4⟩ − ⟨1/4⟩ — ⟨1/4⟩이 4 − 1 = 3개.","1 − ⟨1/4⟩ = ⟨3/4⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_a#5','math',4,2,'u1','','g4_2_math_u1_review_a','unit_review','M4-2-u1-C5',1,'sa','auto','⟨2 1/5⟩ + ⟨2 1/5⟩을 계산하여 대분수로 나타낼 때, 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u1-C5","difficulty":1,"kind":"sa","stem":"⟨2 1/5⟩ + ⟨2 1/5⟩을 계산하여 대분수로 나타낼 때, 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["자연수끼리 2 + 2 = 4.","진분수끼리 ⟨1/5⟩ + ⟨1/5⟩ = ⟨2/5⟩.","⟨2 1/5⟩ + ⟨2 1/5⟩ = ⟨4 2/5⟩."],"variant_rule":{"alt":[{"stem":"⟨3 2/8⟩ + ⟨2 1/8⟩을 계산하여 대분수로 나타낼 때, 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["자연수끼리 3 + 2 = 5.","진분수끼리 ⟨2/8⟩ + ⟨1/8⟩ = ⟨3/8⟩.","⟨3 2/8⟩ + ⟨2 1/8⟩ = ⟨5 3/8⟩."],"asset":null},{"stem":"⟨4 1/3⟩ + ⟨2 1/3⟩을 계산하여 대분수로 나타낼 때, 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["자연수끼리 4 + 2 = 6.","진분수끼리 ⟨1/3⟩ + ⟨1/3⟩ = ⟨2/3⟩.","⟨4 1/3⟩ + ⟨2 1/3⟩ = ⟨6 2/3⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_a#6','math',4,2,'u1','','g4_2_math_u1_review_a','unit_review','M4-2-u1-C6',1,'sa','auto','⟨5 5/7⟩ − ⟨4 2/7⟩ = ⟨1 △/7⟩ — △에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u1-C6","difficulty":1,"kind":"sa","stem":"⟨5 5/7⟩ − ⟨4 2/7⟩ = ⟨1 △/7⟩ — △에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["자연수끼리 5 − 4 = 1.","진분수끼리 ⟨5/7⟩ − ⟨2/7⟩ = ⟨3/7⟩.","⟨5 5/7⟩ − ⟨4 2/7⟩ = ⟨1 3/7⟩."],"variant_rule":{"alt":[{"stem":"⟨6 4/5⟩ − ⟨3 1/5⟩ = ⟨3 △/5⟩ — △에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["자연수끼리 6 − 3 = 3.","진분수끼리 ⟨4/5⟩ − ⟨1/5⟩ = ⟨3/5⟩.","⟨6 4/5⟩ − ⟨3 1/5⟩ = ⟨3 3/5⟩."],"asset":null},{"stem":"⟨5 2/3⟩ − ⟨2 1/3⟩ = ⟨3 △/3⟩ — △에 알맞은 수를 쓰세요.","answer":["1"],"explanation":["자연수끼리 5 − 2 = 3.","진분수끼리 ⟨2/3⟩ − ⟨1/3⟩ = ⟨1/3⟩.","⟨5 2/3⟩ − ⟨2 1/3⟩ = ⟨3 1/3⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_a#7','math',4,2,'u1','','g4_2_math_u1_review_a','unit_review','M4-2-u1-C7',1,'sa','auto','2 − ⟨1/4⟩ = ⟨1 □/4⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-2-u1-C7","difficulty":1,"kind":"sa","stem":"2 − ⟨1/4⟩ = ⟨1 □/4⟩ — □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["2에서 1만큼을 ⟨4/4⟩로 바꾸어요 — 2 = ⟨1 4/4⟩.","⟨4/4⟩ − ⟨1/4⟩ = ⟨3/4⟩.","2 − ⟨1/4⟩ = ⟨1 3/4⟩ — 자연수 부분은 1 줄어요."],"variant_rule":{"alt":[{"stem":"5 − ⟨1/4⟩ = ⟨4 □/4⟩ — □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["5에서 1만큼을 ⟨4/4⟩로 바꾸어요 — 5 = ⟨4 4/4⟩.","⟨4/4⟩ − ⟨1/4⟩ = ⟨3/4⟩.","5 − ⟨1/4⟩ = ⟨4 3/4⟩ — 자연수 부분은 1 줄어요."],"asset":null},{"stem":"6 − ⟨2/5⟩ = ⟨5 □/5⟩ — □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["6에서 1만큼을 ⟨5/5⟩로 바꾸어요 — 6 = ⟨5 5/5⟩.","⟨5/5⟩ − ⟨2/5⟩ = ⟨3/5⟩.","6 − ⟨2/5⟩ = ⟨5 3/5⟩ — 자연수 부분은 1 줄어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_a#8','math',4,2,'u1','','g4_2_math_u1_review_a','unit_review','M4-2-u1-C9',1,'sa','auto','⟨6 2/6⟩ − ⟨3 5/6⟩를 1만큼 바꾸어 ⟨5 □/6⟩ − ⟨3 5/6⟩로 계산하려고 해요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u1-C9","difficulty":1,"kind":"sa","stem":"⟨6 2/6⟩ − ⟨3 5/6⟩를 1만큼 바꾸어 ⟨5 □/6⟩ − ⟨3 5/6⟩로 계산하려고 해요. □에 알맞은 수를 쓰세요.","answer":["8"],"explanation":["⟨2/6⟩ − ⟨5/6⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨6 2/6⟩ = ⟨5 8/6⟩.","자연수끼리 5 − 3 = 2, 분수끼리 ⟨8/6⟩ − ⟨5/6⟩ = ⟨3/6⟩ — 답 ⟨2 3/6⟩."],"variant_rule":{"alt":[{"stem":"⟨3 1/4⟩ − ⟨2 3/4⟩을 1만큼 바꾸어 ⟨2 □/4⟩ − ⟨2 3/4⟩으로 계산하려고 해요. □에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["⟨1/4⟩ − ⟨3/4⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨3 1/4⟩ = ⟨2 5/4⟩.","자연수끼리 2 − 2 = 0, 분수끼리 ⟨5/4⟩ − ⟨3/4⟩ = ⟨2/4⟩ — 답 ⟨2/4⟩."],"asset":null},{"stem":"⟨5 2/8⟩ − ⟨3 4/8⟩를 1만큼 바꾸어 ⟨4 □/8⟩ − ⟨3 4/8⟩로 계산하려고 해요. □에 알맞은 수를 쓰세요.","answer":["10"],"explanation":["⟨2/8⟩ − ⟨4/8⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨5 2/8⟩ = ⟨4 10/8⟩.","자연수끼리 4 − 3 = 1, 분수끼리 ⟨10/8⟩ − ⟨4/8⟩ = ⟨6/8⟩ — 답 ⟨1 6/8⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_a#9','math',4,2,'u1','','g4_2_math_u1_review_a','unit_review','M4-2-u1-C1',2,'mc','auto','⟨13/4⟩을 대분수로 나타내면 무엇인가요?',ARRAY['M4-2-u1-X04','M4-2-u1-X16']::text[],true,'{"seq":9,"concept":"M4-2-u1-C1","difficulty":2,"kind":"mc","stem":"⟨13/4⟩을 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨3 1/4⟩","correct":true},{"t":"⟨4 1/4⟩","mis":"M4-2-u1-X04"},{"t":"⟨2 1/4⟩","mis":"M4-2-u1-X04"},{"t":"⟨3 2/4⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨13/4⟩은 ⟨1/4⟩이 13개예요.","⟨1/4⟩이 4개 모이면 1 — 4개씩 모으면 1이 3번, 1개가 남아요.","⟨13/4⟩ = ⟨3 1/4⟩."],"variant_rule":{"alt":[{"stem":"⟨6/4⟩을 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨1 2/4⟩","correct":true},{"t":"⟨2 2/4⟩","mis":"M4-2-u1-X04"},{"t":"⟨1 3/4⟩","mis":"M4-2-u1-X16"},{"t":"⟨1 1/4⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨6/4⟩은 ⟨1/4⟩이 6개예요.","⟨1/4⟩이 4개 모이면 1 — 4개씩 모으면 1이 1번, 2개가 남아요.","⟨6/4⟩ = ⟨1 2/4⟩."],"asset":null},{"stem":"⟨23/7⟩을 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨3 2/7⟩","correct":true},{"t":"⟨4 2/7⟩","mis":"M4-2-u1-X04"},{"t":"⟨2 2/7⟩","mis":"M4-2-u1-X04"},{"t":"⟨3 3/7⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨23/7⟩은 ⟨1/7⟩이 23개예요.","⟨1/7⟩이 7개 모이면 1 — 7개씩 모으면 1이 3번, 2개가 남아요.","⟨23/7⟩ = ⟨3 2/7⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_a#10','math',4,2,'u1','','g4_2_math_u1_review_a','unit_review','M4-2-u1-C3',2,'mc','auto','빨간 페인트 ⟨4/8⟩ L와 노란 페인트 ⟨6/8⟩ L를 섞었어요. 주황 페인트는 몇 L가 되었나요?',ARRAY['M4-2-u1-X01','M4-2-u1-X16']::text[],true,'{"seq":10,"concept":"M4-2-u1-C3","difficulty":2,"kind":"mc","stem":"빨간 페인트 ⟨4/8⟩ L와 노란 페인트 ⟨6/8⟩ L를 섞었어요. 주황 페인트는 몇 L가 되었나요?","options":[{"t":"⟨1 2/8⟩ L","correct":true},{"t":"⟨10/16⟩ L","mis":"M4-2-u1-X01"},{"t":"⟨1 3/8⟩ L","mis":"M4-2-u1-X16"},{"t":"⟨1 1/8⟩ L","mis":"M4-2-u1-X16"}],"explanation":["분모가 8로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/8⟩이 4 + 6 = 10개.","⟨4/8⟩ + ⟨6/8⟩ = ⟨10/8⟩.","⟨10/8⟩은 1보다 커요 — ⟨10/8⟩ = ⟨1 2/8⟩."],"variant_rule":{"alt":[{"stem":"곰이는 사과를 ⟨3/5⟩ kg, 펭이는 ⟨3/5⟩ kg 땄어요. 두 사람이 딴 사과는 모두 몇 kg인가요?","options":[{"t":"⟨1 1/5⟩ kg","correct":true},{"t":"⟨6/10⟩ kg","mis":"M4-2-u1-X01"},{"t":"⟨1 2/5⟩ kg","mis":"M4-2-u1-X16"},{"t":"1 kg","mis":"M4-2-u1-X16"}],"explanation":["분모가 5로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/5⟩이 3 + 3 = 6개.","⟨3/5⟩ + ⟨3/5⟩ = ⟨6/5⟩.","⟨6/5⟩은 1보다 커요 — ⟨6/5⟩ = ⟨1 1/5⟩."],"asset":null},{"stem":"빨간 페인트 ⟨8/9⟩ L와 노란 페인트 ⟨4/9⟩ L를 섞었어요. 주황 페인트는 몇 L가 되었나요?","options":[{"t":"⟨1 3/9⟩ L","correct":true},{"t":"⟨12/18⟩ L","mis":"M4-2-u1-X01"},{"t":"⟨1 4/9⟩ L","mis":"M4-2-u1-X16"},{"t":"⟨1 2/9⟩ L","mis":"M4-2-u1-X16"}],"explanation":["분모가 9로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/9⟩이 8 + 4 = 12개.","⟨8/9⟩ + ⟨4/9⟩ = ⟨12/9⟩.","⟨12/9⟩는 1보다 커요 — ⟨12/9⟩ = ⟨1 3/9⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_a#11','math',4,2,'u1','','g4_2_math_u1_review_a','unit_review','M4-2-u1-C4',2,'mc','auto','1 − ⟨7/11⟩을 계산하면 얼마인가요?',ARRAY['M4-2-u1-X08','M4-2-u1-X16']::text[],true,'{"seq":11,"concept":"M4-2-u1-C4","difficulty":2,"kind":"mc","stem":"1 − ⟨7/11⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4/11⟩","correct":true},{"t":"⟨6/11⟩","mis":"M4-2-u1-X08"},{"t":"⟨5/11⟩","mis":"M4-2-u1-X16"},{"t":"⟨3/11⟩","mis":"M4-2-u1-X16"}],"explanation":["1을 분모가 11인 분수로 바꾸면 ⟨11/11⟩이에요.","⟨11/11⟩ − ⟨7/11⟩ — ⟨1/11⟩이 11 − 7 = 4개.","1 − ⟨7/11⟩ = ⟨4/11⟩."],"variant_rule":{"alt":[{"stem":"1 − ⟨1/5⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4/5⟩","correct":true},{"t":"⟨3/5⟩","mis":"M4-2-u1-X16"},{"t":"⟨1/5⟩","mis":"M4-2-u1-X15"},{"t":"⟨1 1/5⟩","mis":"M4-2-u1-X14"}],"explanation":["1을 분모가 5인 분수로 바꾸면 ⟨5/5⟩예요.","⟨5/5⟩ − ⟨1/5⟩ — ⟨1/5⟩이 5 − 1 = 4개.","1 − ⟨1/5⟩ = ⟨4/5⟩."],"asset":null},{"stem":"1 − ⟨3/11⟩을 계산하면 얼마인가요?","options":[{"t":"⟨8/11⟩","correct":true},{"t":"⟨2/11⟩","mis":"M4-2-u1-X08"},{"t":"⟨9/11⟩","mis":"M4-2-u1-X16"},{"t":"⟨7/11⟩","mis":"M4-2-u1-X16"}],"explanation":["1을 분모가 11인 분수로 바꾸면 ⟨11/11⟩이에요.","⟨11/11⟩ − ⟨3/11⟩ — ⟨1/11⟩이 11 − 3 = 8개.","1 − ⟨3/11⟩ = ⟨8/11⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_a#12','math',4,2,'u1','','g4_2_math_u1_review_a','unit_review','M4-2-u1-C5',2,'mc','auto','⟨4 7/8⟩ + ⟨4 7/8⟩을 계산하면 얼마인가요?',ARRAY['M4-2-u1-X07','M4-2-u1-X01','M4-2-u1-X13']::text[],true,'{"seq":12,"concept":"M4-2-u1-C5","difficulty":2,"kind":"mc","stem":"⟨4 7/8⟩ + ⟨4 7/8⟩을 계산하면 얼마인가요?","options":[{"t":"⟨9 6/8⟩","correct":true},{"t":"⟨8 6/8⟩","mis":"M4-2-u1-X07"},{"t":"⟨8 14/16⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 6/8⟩","mis":"M4-2-u1-X13"}],"explanation":["자연수끼리 4 + 4 = 8.","진분수끼리 ⟨7/8⟩ + ⟨7/8⟩ = ⟨14/8⟩ — 1보다 커서 ⟨1 6/8⟩, 1을 자연수로 넘겨요.","⟨4 7/8⟩ + ⟨4 7/8⟩ = ⟨9 6/8⟩."],"variant_rule":{"alt":[{"stem":"⟨1 2/3⟩ + ⟨1 2/3⟩를 계산하면 얼마인가요?","options":[{"t":"⟨3 1/3⟩","correct":true},{"t":"⟨2 1/3⟩","mis":"M4-2-u1-X07"},{"t":"⟨2 4/6⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 1/3⟩","mis":"M4-2-u1-X13"}],"explanation":["자연수끼리 1 + 1 = 2.","진분수끼리 ⟨2/3⟩ + ⟨2/3⟩ = ⟨4/3⟩ — 1보다 커서 ⟨1 1/3⟩, 1을 자연수로 넘겨요.","⟨1 2/3⟩ + ⟨1 2/3⟩ = ⟨3 1/3⟩."],"asset":null},{"stem":"⟨3 5/6⟩ + ⟨2 3/6⟩을 계산하면 얼마인가요?","options":[{"t":"⟨6 2/6⟩","correct":true},{"t":"⟨5 2/6⟩","mis":"M4-2-u1-X07"},{"t":"⟨5 8/12⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 2/6⟩","mis":"M4-2-u1-X13"}],"explanation":["자연수끼리 3 + 2 = 5.","진분수끼리 ⟨5/6⟩ + ⟨3/6⟩ = ⟨8/6⟩ — 1보다 커서 ⟨1 2/6⟩, 1을 자연수로 넘겨요.","⟨3 5/6⟩ + ⟨2 3/6⟩ = ⟨6 2/6⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_a#13','math',4,2,'u1','','g4_2_math_u1_review_a','unit_review','M4-2-u1-C6',2,'mc','auto','드론 약품 통에 약품이 ⟨3 3/5⟩ L 있었어요. 밭에 ⟨2 1/5⟩ L를 뿌렸다면 남은 약품은 몇 L인가요?',ARRAY['M4-2-u1-X13','M4-2-u1-X14','M4-2-u1-X01']::text[],true,'{"seq":13,"concept":"M4-2-u1-C6","difficulty":2,"kind":"mc","stem":"드론 약품 통에 약품이 ⟨3 3/5⟩ L 있었어요. 밭에 ⟨2 1/5⟩ L를 뿌렸다면 남은 약품은 몇 L인가요?","options":[{"t":"⟨1 2/5⟩ L","correct":true},{"t":"⟨2/5⟩ L","mis":"M4-2-u1-X13"},{"t":"⟨5 4/5⟩ L","mis":"M4-2-u1-X14"},{"t":"⟨1 2/4⟩ L","mis":"M4-2-u1-X01"}],"explanation":["자연수끼리 3 − 2 = 1.","진분수끼리 ⟨3/5⟩ − ⟨1/5⟩ = ⟨2/5⟩.","⟨3 3/5⟩ − ⟨2 1/5⟩ = ⟨1 2/5⟩."],"variant_rule":{"alt":[{"stem":"드론 약품 통에 약품이 ⟨5 3/7⟩ L 있었어요. 밭에 ⟨1 2/7⟩ L를 뿌렸다면 남은 약품은 몇 L인가요?","options":[{"t":"⟨4 1/7⟩ L","correct":true},{"t":"⟨1/7⟩ L","mis":"M4-2-u1-X13"},{"t":"⟨6 5/7⟩ L","mis":"M4-2-u1-X14"},{"t":"⟨4 1/5⟩ L","mis":"M4-2-u1-X01"}],"explanation":["자연수끼리 5 − 1 = 4.","진분수끼리 ⟨3/7⟩ − ⟨2/7⟩ = ⟨1/7⟩.","⟨5 3/7⟩ − ⟨1 2/7⟩ = ⟨4 1/7⟩."],"asset":null},{"stem":"드론 약품 통에 약품이 ⟨6 6/7⟩ L 있었어요. 밭에 ⟨2 2/7⟩ L를 뿌렸다면 남은 약품은 몇 L인가요?","options":[{"t":"⟨4 4/7⟩ L","correct":true},{"t":"⟨4/7⟩ L","mis":"M4-2-u1-X13"},{"t":"⟨9 1/7⟩ L","mis":"M4-2-u1-X14"},{"t":"⟨4 4/5⟩ L","mis":"M4-2-u1-X01"}],"explanation":["자연수끼리 6 − 2 = 4.","진분수끼리 ⟨6/7⟩ − ⟨2/7⟩ = ⟨4/7⟩.","⟨6 6/7⟩ − ⟨2 2/7⟩ = ⟨4 4/7⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_a#14','math',4,2,'u1','','g4_2_math_u1_review_a','unit_review','M4-2-u1-C7',2,'mc','auto','6 − ⟨5/7⟩를 계산하면 얼마인가요?',ARRAY['M4-2-u1-X09','M4-2-u1-X10','M4-2-u1-X16']::text[],true,'{"seq":14,"concept":"M4-2-u1-C7","difficulty":2,"kind":"mc","stem":"6 − ⟨5/7⟩를 계산하면 얼마인가요?","options":[{"t":"⟨5 2/7⟩","correct":true},{"t":"⟨6 2/7⟩","mis":"M4-2-u1-X09"},{"t":"⟨5 5/7⟩","mis":"M4-2-u1-X10"},{"t":"⟨5 3/7⟩","mis":"M4-2-u1-X16"}],"explanation":["6에서 1만큼을 ⟨7/7⟩로 바꾸어요 — 6 = ⟨5 7/7⟩.","⟨7/7⟩ − ⟨5/7⟩ = ⟨2/7⟩.","6 − ⟨5/7⟩ = ⟨5 2/7⟩ — 자연수 부분은 1 줄어요."],"variant_rule":{"alt":[{"stem":"3 − ⟨8/9⟩을 계산하면 얼마인가요?","options":[{"t":"⟨2 1/9⟩","correct":true},{"t":"⟨3 1/9⟩","mis":"M4-2-u1-X09"},{"t":"⟨2 8/9⟩","mis":"M4-2-u1-X10"},{"t":"⟨2 2/9⟩","mis":"M4-2-u1-X16"}],"explanation":["3에서 1만큼을 ⟨9/9⟩로 바꾸어요 — 3 = ⟨2 9/9⟩.","⟨9/9⟩ − ⟨8/9⟩ = ⟨1/9⟩.","3 − ⟨8/9⟩ = ⟨2 1/9⟩ — 자연수 부분은 1 줄어요."],"asset":null},{"stem":"3 − ⟨6/7⟩을 계산하면 얼마인가요?","options":[{"t":"⟨2 1/7⟩","correct":true},{"t":"⟨3 1/7⟩","mis":"M4-2-u1-X09"},{"t":"⟨2 6/7⟩","mis":"M4-2-u1-X10"},{"t":"⟨2 2/7⟩","mis":"M4-2-u1-X16"}],"explanation":["3에서 1만큼을 ⟨7/7⟩로 바꾸어요 — 3 = ⟨2 7/7⟩.","⟨7/7⟩ − ⟨6/7⟩ = ⟨1/7⟩.","3 − ⟨6/7⟩ = ⟨2 1/7⟩ — 자연수 부분은 1 줄어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_a#15','math',4,2,'u1','','g4_2_math_u1_review_a','unit_review','M4-2-u1-C8',2,'mc','auto','⟨3 1/8⟩ − ⟨7/8⟩을 계산하면 얼마인가요?',ARRAY['M4-2-u1-X11','M4-2-u1-X09','M4-2-u1-X12']::text[],true,'{"seq":15,"concept":"M4-2-u1-C8","difficulty":2,"kind":"mc","stem":"⟨3 1/8⟩ − ⟨7/8⟩을 계산하면 얼마인가요?","options":[{"t":"⟨2 2/8⟩","correct":true},{"t":"⟨3 6/8⟩","mis":"M4-2-u1-X11"},{"t":"⟨3 2/8⟩","mis":"M4-2-u1-X09"},{"t":"⟨2 4/8⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨1/8⟩ − ⟨7/8⟩ — 진분수끼리 뺄 수 없어요(1 < 7).","1만큼 바꾸어요 — ⟨3 1/8⟩ = ⟨2 9/8⟩.","⟨2 9/8⟩ − ⟨7/8⟩ = ⟨2 2/8⟩ — 자연수 부분은 1 줄어요."],"variant_rule":{"alt":[{"stem":"⟨6 4/6⟩ − ⟨5/6⟩를 계산하면 얼마인가요?","options":[{"t":"⟨5 5/6⟩","correct":true},{"t":"⟨6 1/6⟩","mis":"M4-2-u1-X11"},{"t":"⟨6 5/6⟩","mis":"M4-2-u1-X09"},{"t":"⟨5 9/6⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨4/6⟩ − ⟨5/6⟩ — 진분수끼리 뺄 수 없어요(4 < 5).","1만큼 바꾸어요 — ⟨6 4/6⟩ = ⟨5 10/6⟩.","⟨5 10/6⟩ − ⟨5/6⟩ = ⟨5 5/6⟩ — 자연수 부분은 1 줄어요."],"asset":null},{"stem":"⟨2 7/9⟩ − ⟨8/9⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1 8/9⟩","correct":true},{"t":"⟨2 1/9⟩","mis":"M4-2-u1-X11"},{"t":"⟨2 8/9⟩","mis":"M4-2-u1-X09"},{"t":"⟨1 9/9⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨7/9⟩ − ⟨8/9⟩ — 진분수끼리 뺄 수 없어요(7 < 8).","1만큼 바꾸어요 — ⟨2 7/9⟩ = ⟨1 16/9⟩.","⟨1 16/9⟩ − ⟨8/9⟩ = ⟨1 8/9⟩ — 자연수 부분은 1 줄어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_a#16','math',4,2,'u1','','g4_2_math_u1_review_a','unit_review','M4-2-u1-C9',2,'mc','auto','⟨7 2/7⟩ − ⟨2 4/7⟩를 계산하면 얼마인가요?',ARRAY['M4-2-u1-X11','M4-2-u1-X09','M4-2-u1-X12']::text[],true,'{"seq":16,"concept":"M4-2-u1-C9","difficulty":2,"kind":"mc","stem":"⟨7 2/7⟩ − ⟨2 4/7⟩를 계산하면 얼마인가요?","options":[{"t":"⟨4 5/7⟩","correct":true},{"t":"⟨5 2/7⟩","mis":"M4-2-u1-X11"},{"t":"⟨5 5/7⟩","mis":"M4-2-u1-X09"},{"t":"⟨4 8/7⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨2/7⟩ − ⟨4/7⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨7 2/7⟩ = ⟨6 9/7⟩.","자연수끼리 6 − 2 = 4, 분수끼리 ⟨9/7⟩ − ⟨4/7⟩ = ⟨5/7⟩ — 답 ⟨4 5/7⟩."],"variant_rule":{"alt":[{"stem":"⟨5 1/4⟩ − ⟨4 3/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨2/4⟩","correct":true},{"t":"⟨1 2/4⟩","mis":"M4-2-u1-X11"},{"t":"⟨8/4⟩","mis":"M4-2-u1-X12"},{"t":"⟨3/4⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨1/4⟩ − ⟨3/4⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨5 1/4⟩ = ⟨4 5/4⟩.","자연수끼리 4 − 4 = 0, 분수끼리 ⟨5/4⟩ − ⟨3/4⟩ = ⟨2/4⟩ — 답 ⟨2/4⟩."],"asset":null},{"stem":"⟨4 7/9⟩ − ⟨3 8/9⟩을 계산하면 얼마인가요?","options":[{"t":"⟨8/9⟩","correct":true},{"t":"⟨1 1/9⟩","mis":"M4-2-u1-X11"},{"t":"⟨1 8/9⟩","mis":"M4-2-u1-X09"},{"t":"⟨9/9⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨7/9⟩ − ⟨8/9⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨4 7/9⟩ = ⟨3 16/9⟩.","자연수끼리 3 − 3 = 0, 분수끼리 ⟨16/9⟩ − ⟨8/9⟩ = ⟨8/9⟩ — 답 ⟨8/9⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_a#17','math',4,2,'u1','','g4_2_math_u1_review_a','unit_review','M4-2-u1-C2',3,'mc','auto','⟨1/7⟩과 모아서 1이 되는 분수는 무엇인가요?',ARRAY['M4-2-u1-X06','M4-2-u1-X16']::text[],true,'{"seq":17,"concept":"M4-2-u1-C2","difficulty":3,"kind":"mc","stem":"⟨1/7⟩과 모아서 1이 되는 분수는 무엇인가요?","options":[{"t":"⟨6/7⟩","correct":true},{"t":"⟨1/7⟩","mis":"M4-2-u1-X06"},{"t":"⟨7/7⟩","mis":"M4-2-u1-X16"},{"t":"⟨5/7⟩","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨7/7⟩ — ⟨1/7⟩이 7개예요.","⟨1/7⟩은 ⟨1/7⟩이 1개 — 6개가 모자라요.","⟨1/7⟩과 ⟨6/7⟩을 모으면 1이에요."],"variant_rule":{"alt":[{"stem":"⟨8/9⟩과 모아서 1이 되는 분수는 무엇인가요?","options":[{"t":"⟨1/9⟩","correct":true},{"t":"⟨8/9⟩","mis":"M4-2-u1-X06"},{"t":"⟨9/8⟩","mis":"M4-2-u1-X06"},{"t":"⟨2/9⟩","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨9/9⟩ — ⟨1/9⟩이 9개예요.","⟨8/9⟩은 ⟨1/9⟩이 8개 — 1개가 모자라요.","⟨8/9⟩과 ⟨1/9⟩을 모으면 1이에요."],"asset":null},{"stem":"⟨2/6⟩와 모아서 1이 되는 분수는 무엇인가요?","options":[{"t":"⟨4/6⟩","correct":true},{"t":"⟨2/6⟩","mis":"M4-2-u1-X06"},{"t":"⟨6/2⟩","mis":"M4-2-u1-X06"},{"t":"⟨5/6⟩","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨6/6⟩ — ⟨1/6⟩이 6개예요.","⟨2/6⟩는 ⟨1/6⟩이 2개 — 4개가 모자라요.","⟨2/6⟩와 ⟨4/6⟩를 모으면 1이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_a#18','math',4,2,'u1','','g4_2_math_u1_review_a','unit_review','M4-2-u1-C3',3,'sa','auto','⟨7/10⟩ + ⟨□/10⟩ = ⟨1 1/10⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M4-2-u1-C3","difficulty":3,"kind":"sa","stem":"⟨7/10⟩ + ⟨□/10⟩ = ⟨1 1/10⟩ — □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["⟨1 1/10⟩을 가분수로 — ⟨11/10⟩.","⟨1/10⟩이 11개가 되려면 7개에서 4개를 더 모아야 해요.","□ = 11 − 7 = 4."],"variant_rule":{"alt":[{"stem":"⟨10/11⟩ + ⟨□/11⟩ = ⟨1 1/11⟩ — □에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["⟨1 1/11⟩을 가분수로 — ⟨12/11⟩.","⟨1/11⟩이 12개가 되려면 10개에서 2개를 더 모아야 해요.","□ = 12 − 10 = 2."],"asset":null},{"stem":"⟨8/10⟩ + ⟨□/10⟩ = ⟨1 2/10⟩ — □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["⟨1 2/10⟩를 가분수로 — ⟨12/10⟩.","⟨1/10⟩이 12개가 되려면 8개에서 4개를 더 모아야 해요.","□ = 12 − 8 = 4."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_a#19','math',4,2,'u1','','g4_2_math_u1_review_a','unit_review','M4-2-u1-C5',3,'sa','auto','⟨3 5/8⟩ + ⟨1 7/8⟩을 가분수로 바꾸어 계산하면 ⟨□/8⟩ + ⟨△/8⟩ = ⟨○/8⟩이에요. ○에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M4-2-u1-C5","difficulty":3,"kind":"sa","stem":"⟨3 5/8⟩ + ⟨1 7/8⟩을 가분수로 바꾸어 계산하면 ⟨□/8⟩ + ⟨△/8⟩ = ⟨○/8⟩이에요. ○에 알맞은 수를 쓰세요.","answer":["44"],"explanation":["⟨3 5/8⟩ = ⟨29/8⟩, ⟨1 7/8⟩ = ⟨15/8⟩.","⟨29/8⟩ + ⟨15/8⟩ = ⟨44/8⟩.","○ = 44 — 대분수로 ⟨5 4/8⟩."],"variant_rule":{"alt":[{"stem":"⟨1 5/8⟩ + ⟨3 7/8⟩을 가분수로 바꾸어 계산하면 ⟨□/8⟩ + ⟨△/8⟩ = ⟨○/8⟩이에요. ○에 알맞은 수를 쓰세요.","answer":["44"],"explanation":["⟨1 5/8⟩ = ⟨13/8⟩, ⟨3 7/8⟩ = ⟨31/8⟩.","⟨13/8⟩ + ⟨31/8⟩ = ⟨44/8⟩.","○ = 44 — 대분수로 ⟨5 4/8⟩."],"asset":null},{"stem":"⟨3 6/9⟩ + ⟨4 4/9⟩를 가분수로 바꾸어 계산하면 ⟨□/9⟩ + ⟨△/9⟩ = ⟨○/9⟩이에요. ○에 알맞은 수를 쓰세요.","answer":["73"],"explanation":["⟨3 6/9⟩ = ⟨33/9⟩, ⟨4 4/9⟩ = ⟨40/9⟩.","⟨33/9⟩ + ⟨40/9⟩ = ⟨73/9⟩.","○ = 73 — 대분수로 ⟨8 1/9⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_a#20','math',4,2,'u1','','g4_2_math_u1_review_a','unit_review','M4-2-u1-C7',3,'mc','auto','두부를 만들려고 콩 6 kg 가운데 ⟨1 4/6⟩ kg을 물에 불렸어요. 불리지 않고 남은 콩은 몇 kg인가요?',ARRAY['M4-2-u1-X09','M4-2-u1-X10','M4-2-u1-X16']::text[],true,'{"seq":20,"concept":"M4-2-u1-C7","difficulty":3,"kind":"mc","stem":"두부를 만들려고 콩 6 kg 가운데 ⟨1 4/6⟩ kg을 물에 불렸어요. 불리지 않고 남은 콩은 몇 kg인가요?","options":[{"t":"⟨4 2/6⟩ kg","correct":true},{"t":"⟨5 2/6⟩ kg","mis":"M4-2-u1-X09"},{"t":"⟨4 4/6⟩ kg","mis":"M4-2-u1-X10"},{"t":"⟨4 3/6⟩ kg","mis":"M4-2-u1-X16"}],"explanation":["6 = ⟨5 6/6⟩으로 바꾸어요.","⟨5 6/6⟩ − ⟨1 4/6⟩ = ⟨4 2/6⟩.","남은 콩은 ⟨4 2/6⟩ kg이에요."],"variant_rule":{"alt":[{"stem":"두부를 만들려고 콩 6 kg 가운데 ⟨2 4/5⟩ kg을 물에 불렸어요. 불리지 않고 남은 콩은 몇 kg인가요?","options":[{"t":"⟨3 1/5⟩ kg","correct":true},{"t":"⟨4 1/5⟩ kg","mis":"M4-2-u1-X09"},{"t":"⟨3 4/5⟩ kg","mis":"M4-2-u1-X10"},{"t":"⟨3 2/5⟩ kg","mis":"M4-2-u1-X16"}],"explanation":["6 = ⟨5 5/5⟩로 바꾸어요.","⟨5 5/5⟩ − ⟨2 4/5⟩ = ⟨3 1/5⟩.","남은 콩은 ⟨3 1/5⟩ kg이에요."],"asset":null},{"stem":"두부를 만들려고 콩 2 kg 가운데 ⟨1 2/5⟩ kg을 물에 불렸어요. 불리지 않고 남은 콩은 몇 kg인가요?","options":[{"t":"⟨3/5⟩ kg","correct":true},{"t":"⟨1 3/5⟩ kg","mis":"M4-2-u1-X09"},{"t":"⟨2/5⟩ kg","mis":"M4-2-u1-X10"},{"t":"⟨4/5⟩ kg","mis":"M4-2-u1-X16"}],"explanation":["2 = ⟨1 5/5⟩로 바꾸어요.","⟨1 5/5⟩ − ⟨1 2/5⟩ = ⟨3/5⟩.","남은 콩은 ⟨3/5⟩ kg이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_a#21','math',4,2,'u1','','g4_2_math_u1_review_a','unit_review','M4-2-u1-C9',3,'mc','auto','곰이는 자전거로 ⟨7 2/7⟩ km, 펭이는 ⟨3 6/7⟩ km를 달렸어요. 곰이는 펭이보다 몇 km 더 달렸나요?',ARRAY['M4-2-u1-X11','M4-2-u1-X09','M4-2-u1-X12']::text[],true,'{"seq":21,"concept":"M4-2-u1-C9","difficulty":3,"kind":"mc","stem":"곰이는 자전거로 ⟨7 2/7⟩ km, 펭이는 ⟨3 6/7⟩ km를 달렸어요. 곰이는 펭이보다 몇 km 더 달렸나요?","options":[{"t":"⟨3 3/7⟩ km","correct":true},{"t":"⟨4 4/7⟩ km","mis":"M4-2-u1-X11"},{"t":"⟨4 3/7⟩ km","mis":"M4-2-u1-X09"},{"t":"⟨3 6/7⟩ km","mis":"M4-2-u1-X12"}],"explanation":["⟨2/7⟩ − ⟨6/7⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨7 2/7⟩ = ⟨6 9/7⟩.","자연수끼리 6 − 3 = 3, 분수끼리 ⟨9/7⟩ − ⟨6/7⟩ = ⟨3/7⟩ — 답 ⟨3 3/7⟩."],"variant_rule":{"alt":[{"stem":"곰이는 자전거로 ⟨2 3/7⟩ km, 펭이는 ⟨1 6/7⟩ km를 달렸어요. 곰이는 펭이보다 몇 km 더 달렸나요?","options":[{"t":"⟨4/7⟩ km","correct":true},{"t":"⟨1 3/7⟩ km","mis":"M4-2-u1-X11"},{"t":"⟨1 4/7⟩ km","mis":"M4-2-u1-X09"},{"t":"⟨7/7⟩ km","mis":"M4-2-u1-X12"}],"explanation":["⟨3/7⟩ − ⟨6/7⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨2 3/7⟩ = ⟨1 10/7⟩.","자연수끼리 1 − 1 = 0, 분수끼리 ⟨10/7⟩ − ⟨6/7⟩ = ⟨4/7⟩ — 답 ⟨4/7⟩."],"asset":null},{"stem":"곰이는 자전거로 ⟨8 8/12⟩ km, 펭이는 ⟨4 11/12⟩ km를 달렸어요. 곰이는 펭이보다 몇 km 더 달렸나요?","options":[{"t":"⟨3 9/12⟩ km","correct":true},{"t":"⟨4 3/12⟩ km","mis":"M4-2-u1-X11"},{"t":"⟨4 9/12⟩ km","mis":"M4-2-u1-X09"},{"t":"⟨3 7/12⟩ km","mis":"M4-2-u1-X12"}],"explanation":["⟨8/12⟩ − ⟨11/12⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨8 8/12⟩ = ⟨7 20/12⟩.","자연수끼리 7 − 4 = 3, 분수끼리 ⟨20/12⟩ − ⟨11/12⟩ = ⟨9/12⟩ — 답 ⟨3 9/12⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_a#22','math',4,2,'u1','','g4_2_math_u1_review_a','unit_review','M4-2-u1-C10',3,'mc','auto','분수 카드 ⟨1 2/6⟩, ⟨3 3/6⟩, ⟨1 5/6⟩, ⟨2 2/6⟩ 중 두 장을 골라 합이 ⟨4 1/6⟩이 되게 하려고 해요. 어떤 두 장을 골라야 하나요?',ARRAY['M4-2-u1-X17']::text[],true,'{"seq":22,"concept":"M4-2-u1-C10","difficulty":3,"kind":"mc","stem":"분수 카드 ⟨1 2/6⟩, ⟨3 3/6⟩, ⟨1 5/6⟩, ⟨2 2/6⟩ 중 두 장을 골라 합이 ⟨4 1/6⟩이 되게 하려고 해요. 어떤 두 장을 골라야 하나요?","options":[{"t":"⟨1 5/6⟩, ⟨2 2/6⟩","correct":true},{"t":"⟨3 3/6⟩, ⟨1 5/6⟩","mis":"M4-2-u1-X17"},{"t":"⟨1 2/6⟩, ⟨3 3/6⟩","mis":"M4-2-u1-X17"},{"t":"⟨1 2/6⟩, ⟨1 5/6⟩","mis":"M4-2-u1-X17"}],"explanation":["어림해요 — 자연수 부분을 먼저 맞추어 보아요.","⟨1 5/6⟩ + ⟨2 2/6⟩ = ⟨4 1/6⟩.","⟨1 5/6⟩, ⟨2 2/6⟩를 골라요."],"variant_rule":{"alt":[{"stem":"분수 카드 ⟨2 4/5⟩, ⟨2 1/5⟩, ⟨3 4/5⟩, ⟨3 1/5⟩ 중 두 장을 골라 합이 ⟨6 3/5⟩이 되게 하려고 해요. 어떤 두 장을 골라야 하나요?","options":[{"t":"⟨2 4/5⟩, ⟨3 4/5⟩","correct":true},{"t":"⟨2 1/5⟩, ⟨3 1/5⟩","mis":"M4-2-u1-X17"},{"t":"⟨2 4/5⟩, ⟨2 1/5⟩","mis":"M4-2-u1-X17"},{"t":"⟨2 4/5⟩, ⟨3 1/5⟩","mis":"M4-2-u1-X17"}],"explanation":["어림해요 — 자연수 부분을 먼저 맞추어 보아요.","⟨2 4/5⟩ + ⟨3 4/5⟩ = ⟨6 3/5⟩.","⟨2 4/5⟩, ⟨3 4/5⟩를 골라요."],"asset":null},{"stem":"분수 카드 ⟨3 2/6⟩, ⟨1 2/6⟩, ⟨2 4/6⟩, ⟨2 1/6⟩ 중 두 장을 골라 합이 ⟨5 3/6⟩이 되게 하려고 해요. 어떤 두 장을 골라야 하나요?","options":[{"t":"⟨3 2/6⟩, ⟨2 1/6⟩","correct":true},{"t":"⟨3 2/6⟩, ⟨2 4/6⟩","mis":"M4-2-u1-X17"},{"t":"⟨1 2/6⟩, ⟨2 4/6⟩","mis":"M4-2-u1-X17"},{"t":"⟨2 4/6⟩, ⟨2 1/6⟩","mis":"M4-2-u1-X17"}],"explanation":["어림해요 — 자연수 부분을 먼저 맞추어 보아요.","⟨3 2/6⟩ + ⟨2 1/6⟩ = ⟨5 3/6⟩.","⟨3 2/6⟩, ⟨2 1/6⟩을 골라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_a#23','math',4,2,'u1','','g4_2_math_u1_review_a','unit_review','M4-2-u1-C9',4,'mc','auto','□ − ⟨4 7/10⟩ = ⟨1 6/10⟩일 때, □에 알맞은 대분수는 무엇인가요?',ARRAY['M4-2-u1-X16','M4-2-u1-X09']::text[],true,'{"seq":23,"concept":"M4-2-u1-C9","difficulty":4,"kind":"mc","stem":"□ − ⟨4 7/10⟩ = ⟨1 6/10⟩일 때, □에 알맞은 대분수는 무엇인가요?","options":[{"t":"⟨6 3/10⟩","correct":true},{"t":"⟨6 4/10⟩","mis":"M4-2-u1-X16"},{"t":"⟨6 2/10⟩","mis":"M4-2-u1-X16"},{"t":"⟨5 3/10⟩","mis":"M4-2-u1-X09"}],"explanation":["□에서 ⟨4 7/10⟩을 덜어 ⟨1 6/10⟩이 남았어요.","덧셈으로 되돌려요 — □ = ⟨1 6/10⟩ + ⟨4 7/10⟩.","□ = ⟨6 3/10⟩."],"variant_rule":{"alt":[{"stem":"□ − ⟨2 10/11⟩ = ⟨1 7/11⟩일 때, □에 알맞은 대분수는 무엇인가요?","options":[{"t":"⟨4 6/11⟩","correct":true},{"t":"⟨4 7/11⟩","mis":"M4-2-u1-X16"},{"t":"⟨4 5/11⟩","mis":"M4-2-u1-X16"},{"t":"⟨3 6/11⟩","mis":"M4-2-u1-X09"}],"explanation":["□에서 ⟨2 10/11⟩을 덜어 ⟨1 7/11⟩이 남았어요.","덧셈으로 되돌려요 — □ = ⟨1 7/11⟩ + ⟨2 10/11⟩.","□ = ⟨4 6/11⟩."],"asset":null},{"stem":"□ − ⟨1 5/6⟩ = ⟨2 3/6⟩일 때, □에 알맞은 대분수는 무엇인가요?","options":[{"t":"⟨4 2/6⟩","correct":true},{"t":"⟨4/6⟩","mis":"M4-2-u1-X14"},{"t":"⟨4 3/6⟩","mis":"M4-2-u1-X16"},{"t":"⟨4 1/6⟩","mis":"M4-2-u1-X16"}],"explanation":["□에서 ⟨1 5/6⟩를 덜어 ⟨2 3/6⟩이 남았어요.","덧셈으로 되돌려요 — □ = ⟨2 3/6⟩ + ⟨1 5/6⟩.","□ = ⟨4 2/6⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_a#24','math',4,2,'u1','','g4_2_math_u1_review_a','unit_review','M4-2-u1-C10',4,'mc','auto','수 카드 2, 1, 3 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 8인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 합은 얼마인가요?',ARRAY['M4-2-u1-X16','M4-2-u1-X14']::text[],true,'{"seq":24,"concept":"M4-2-u1-C10","difficulty":4,"kind":"mc","stem":"수 카드 2, 1, 3 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 8인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 합은 얼마인가요?","options":[{"t":"⟨4 4/8⟩","correct":true},{"t":"⟨4 5/8⟩","mis":"M4-2-u1-X16"},{"t":"⟨4 3/8⟩","mis":"M4-2-u1-X16"},{"t":"2","mis":"M4-2-u1-X14"}],"explanation":["가장 큰 대분수 — 자연수 부분에 가장 큰 수 3, 분자에 다음 큰 수 2 → ⟨3 2/8⟩.","가장 작은 대분수 — 자연수 부분에 가장 작은 수 1, 분자에 2 → ⟨1 2/8⟩.","⟨3 2/8⟩ + ⟨1 2/8⟩ = ⟨4 4/8⟩."],"variant_rule":{"alt":[{"stem":"수 카드 3, 5, 2 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 7인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 합은 얼마인가요?","options":[{"t":"⟨7 6/7⟩","correct":true},{"t":"8","mis":"M4-2-u1-X17"},{"t":"⟨7 5/7⟩","mis":"M4-2-u1-X16"},{"t":"3","mis":"M4-2-u1-X14"}],"explanation":["가장 큰 대분수 — 자연수 부분에 가장 큰 수 5, 분자에 다음 큰 수 3 → ⟨5 3/7⟩.","가장 작은 대분수 — 자연수 부분에 가장 작은 수 2, 분자에 3 → ⟨2 3/7⟩.","⟨5 3/7⟩ + ⟨2 3/7⟩ = ⟨7 6/7⟩."],"asset":null},{"stem":"수 카드 4, 5, 1 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 8인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 합은 얼마인가요?","options":[{"t":"7","correct":true},{"t":"⟨6 6/8⟩","mis":"M4-2-u1-X17"},{"t":"⟨7 1/8⟩","mis":"M4-2-u1-X16"},{"t":"⟨6 7/8⟩","mis":"M4-2-u1-X16"}],"explanation":["가장 큰 대분수 — 자연수 부분에 가장 큰 수 5, 분자에 다음 큰 수 4 → ⟨5 4/8⟩.","가장 작은 대분수 — 자연수 부분에 가장 작은 수 1, 분자에 4 → ⟨1 4/8⟩.","⟨5 4/8⟩ + ⟨1 4/8⟩ = 7."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_a#25','math',4,2,'u1','','g4_2_math_u1_review_a','unit_review','M4-2-u1-C5',4,'essay','teacher','⟨2 5/6⟩ + ⟨1 4/6⟩를 계산하여 대분수로 나타내고, 진분수끼리의 합을 어떻게 처리했는지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u1-C5","difficulty":4,"kind":"essay","stem":"⟨2 5/6⟩ + ⟨1 4/6⟩를 계산하여 대분수로 나타내고, 진분수끼리의 합을 어떻게 처리했는지 설명해 보세요.","answer_guide":{"answer":"예: 자연수끼리 2 + 1 = 3, 진분수끼리 ⟨5/6⟩ + ⟨4/6⟩ = ⟨9/6⟩ = ⟨1 3/6⟩이다. 넘친 1을 자연수에 더해 ⟨4 3/6⟩이다.","scoring_points":["자연수끼리·진분수끼리 더했는가","⟨9/6⟩ = ⟨1 3/6⟩으로 바꾸었는가","⟨4 3/6⟩이라고 답했는가"]},"explanation":["3 + ⟨9/6⟩.","⟨9/6⟩ = ⟨1 3/6⟩.","⟨4 3/6⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_b#1','math',4,2,'u1','','g4_2_math_u1_review_b','unit_review','M4-2-u1-C1',1,'sa','auto','⟨10/8⟩은 ⟨1/8⟩이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-2-u1-C1","difficulty":1,"kind":"sa","stem":"⟨10/8⟩은 ⟨1/8⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["분모 8 — 1을 똑같이 8칸으로 나눈 것 중 한 칸이 ⟨1/8⟩이에요.","분자 10 — ⟨1/8⟩이 10개라는 뜻이에요.","⟨10/8⟩은 ⟨1/8⟩이 10개인 수예요."],"variant_rule":{"alt":[{"stem":"⟨15/9⟩는 ⟨1/9⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["분모 9 — 1을 똑같이 9칸으로 나눈 것 중 한 칸이 ⟨1/9⟩이에요.","분자 15 — ⟨1/9⟩이 15개라는 뜻이에요.","⟨15/9⟩는 ⟨1/9⟩이 15개인 수예요."],"asset":null},{"stem":"⟨17/7⟩은 ⟨1/7⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["분모 7 — 1을 똑같이 7칸으로 나눈 것 중 한 칸이 ⟨1/7⟩이에요.","분자 17 — ⟨1/7⟩이 17개라는 뜻이에요.","⟨17/7⟩은 ⟨1/7⟩이 17개인 수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_b#2','math',4,2,'u1','','g4_2_math_u1_review_b','unit_review','M4-2-u1-C2',1,'sa','auto','1을 ⟨1/4⟩이 1개인 분수와 ⟨1/4⟩이 □개인 분수로 갈랐어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u1-C2","difficulty":1,"kind":"sa","stem":"1을 ⟨1/4⟩이 1개인 분수와 ⟨1/4⟩이 □개인 분수로 갈랐어요. □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["분모가 4이면 1 = ⟨4/4⟩ — ⟨1/4⟩이 4개예요.","4개 중 1개를 떼면 4 − 1 = 3개가 남아요.","□ = 3 — 1 = ⟨1/4⟩ + ⟨3/4⟩."],"variant_rule":{"alt":[{"stem":"1을 ⟨1/9⟩이 6개인 분수와 ⟨1/9⟩이 □개인 분수로 갈랐어요. □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["분모가 9이면 1 = ⟨9/9⟩ — ⟨1/9⟩이 9개예요.","9개 중 6개를 떼면 9 − 6 = 3개가 남아요.","□ = 3 — 1 = ⟨6/9⟩ + ⟨3/9⟩."],"asset":null},{"stem":"1을 ⟨1/10⟩이 2개인 분수와 ⟨1/10⟩이 □개인 분수로 갈랐어요. □에 알맞은 수를 쓰세요.","answer":["8"],"explanation":["분모가 10이면 1 = ⟨10/10⟩ — ⟨1/10⟩이 10개예요.","10개 중 2개를 떼면 10 − 2 = 8개가 남아요.","□ = 8 — 1 = ⟨2/10⟩ + ⟨8/10⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_b#3','math',4,2,'u1','','g4_2_math_u1_review_b','unit_review','M4-2-u1-C3',1,'sa','auto','⟨2/10⟩ + ⟨7/10⟩ = ⟨□/10⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u1-C3","difficulty":1,"kind":"sa","stem":"⟨2/10⟩ + ⟨7/10⟩ = ⟨□/10⟩ — □에 알맞은 수를 쓰세요.","answer":["9"],"explanation":["분모가 10으로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/10⟩이 2 + 7 = 9개.","⟨2/10⟩ + ⟨7/10⟩ = ⟨9/10⟩.","분모끼리 더해 ⟨9/20⟩로 쓰지 않아요."],"variant_rule":{"alt":[{"stem":"⟨2/6⟩ + ⟨3/6⟩ = ⟨□/6⟩ — □에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["분모가 6으로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/6⟩이 2 + 3 = 5개.","⟨2/6⟩ + ⟨3/6⟩ = ⟨5/6⟩.","분모끼리 더해 ⟨5/12⟩로 쓰지 않아요."],"asset":null},{"stem":"⟨1/9⟩ + ⟨5/9⟩ = ⟨□/9⟩ — □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["분모가 9로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/9⟩이 1 + 5 = 6개.","⟨1/9⟩ + ⟨5/9⟩ = ⟨6/9⟩.","분모끼리 더해 ⟨6/18⟩으로 쓰지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_b#4','math',4,2,'u1','','g4_2_math_u1_review_b','unit_review','M4-2-u1-C4',1,'sa','auto','1 − ⟨8/9⟩ = ⟨□/9⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u1-C4","difficulty":1,"kind":"sa","stem":"1 − ⟨8/9⟩ = ⟨□/9⟩ — □에 알맞은 수를 쓰세요.","answer":["1"],"explanation":["1을 분모가 9인 분수로 바꾸면 ⟨9/9⟩예요.","⟨9/9⟩ − ⟨8/9⟩ — ⟨1/9⟩이 9 − 8 = 1개.","1 − ⟨8/9⟩ = ⟨1/9⟩."],"variant_rule":{"alt":[{"stem":"1 − ⟨5/6⟩ = ⟨□/6⟩ — □에 알맞은 수를 쓰세요.","answer":["1"],"explanation":["1을 분모가 6인 분수로 바꾸면 ⟨6/6⟩이에요.","⟨6/6⟩ − ⟨5/6⟩ — ⟨1/6⟩이 6 − 5 = 1개.","1 − ⟨5/6⟩ = ⟨1/6⟩."],"asset":null},{"stem":"1 − ⟨5/7⟩ = ⟨□/7⟩ — □에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["1을 분모가 7인 분수로 바꾸면 ⟨7/7⟩이에요.","⟨7/7⟩ − ⟨5/7⟩ — ⟨1/7⟩이 7 − 5 = 2개.","1 − ⟨5/7⟩ = ⟨2/7⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_b#5','math',4,2,'u1','','g4_2_math_u1_review_b','unit_review','M4-2-u1-C5',1,'sa','auto','⟨4 2/6⟩ + ⟨3 3/6⟩을 계산하여 대분수로 나타낼 때, 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u1-C5","difficulty":1,"kind":"sa","stem":"⟨4 2/6⟩ + ⟨3 3/6⟩을 계산하여 대분수로 나타낼 때, 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["자연수끼리 4 + 3 = 7.","진분수끼리 ⟨2/6⟩ + ⟨3/6⟩ = ⟨5/6⟩.","⟨4 2/6⟩ + ⟨3 3/6⟩ = ⟨7 5/6⟩."],"variant_rule":{"alt":[{"stem":"⟨3 3/5⟩ + ⟨1 1/5⟩을 계산하여 대분수로 나타낼 때, 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["자연수끼리 3 + 1 = 4.","진분수끼리 ⟨3/5⟩ + ⟨1/5⟩ = ⟨4/5⟩.","⟨3 3/5⟩ + ⟨1 1/5⟩ = ⟨4 4/5⟩."],"asset":null},{"stem":"⟨1 4/6⟩ + ⟨2 1/6⟩을 계산하여 대분수로 나타낼 때, 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["자연수끼리 1 + 2 = 3.","진분수끼리 ⟨4/6⟩ + ⟨1/6⟩ = ⟨5/6⟩.","⟨1 4/6⟩ + ⟨2 1/6⟩ = ⟨3 5/6⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_b#6','math',4,2,'u1','','g4_2_math_u1_review_b','unit_review','M4-2-u1-C6',1,'sa','auto','⟨5 2/4⟩ − ⟨2 1/4⟩ = ⟨3 △/4⟩ — △에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u1-C6","difficulty":1,"kind":"sa","stem":"⟨5 2/4⟩ − ⟨2 1/4⟩ = ⟨3 △/4⟩ — △에 알맞은 수를 쓰세요.","answer":["1"],"explanation":["자연수끼리 5 − 2 = 3.","진분수끼리 ⟨2/4⟩ − ⟨1/4⟩ = ⟨1/4⟩.","⟨5 2/4⟩ − ⟨2 1/4⟩ = ⟨3 1/4⟩."],"variant_rule":{"alt":[{"stem":"⟨6 2/3⟩ − ⟨3 1/3⟩ = ⟨3 △/3⟩ — △에 알맞은 수를 쓰세요.","answer":["1"],"explanation":["자연수끼리 6 − 3 = 3.","진분수끼리 ⟨2/3⟩ − ⟨1/3⟩ = ⟨1/3⟩.","⟨6 2/3⟩ − ⟨3 1/3⟩ = ⟨3 1/3⟩."],"asset":null},{"stem":"⟨5 7/8⟩ − ⟨3 3/8⟩ = ⟨2 △/8⟩ — △에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["자연수끼리 5 − 3 = 2.","진분수끼리 ⟨7/8⟩ − ⟨3/8⟩ = ⟨4/8⟩.","⟨5 7/8⟩ − ⟨3 3/8⟩ = ⟨2 4/8⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_b#7','math',4,2,'u1','','g4_2_math_u1_review_b','unit_review','M4-2-u1-C7',1,'sa','auto','5 − ⟨1/6⟩ = ⟨4 □/6⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-2-u1-C7","difficulty":1,"kind":"sa","stem":"5 − ⟨1/6⟩ = ⟨4 □/6⟩ — □에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["5에서 1만큼을 ⟨6/6⟩으로 바꾸어요 — 5 = ⟨4 6/6⟩.","⟨6/6⟩ − ⟨1/6⟩ = ⟨5/6⟩.","5 − ⟨1/6⟩ = ⟨4 5/6⟩ — 자연수 부분은 1 줄어요."],"variant_rule":{"alt":[{"stem":"6 − ⟨5/6⟩ = ⟨5 □/6⟩ — □에 알맞은 수를 쓰세요.","answer":["1"],"explanation":["6에서 1만큼을 ⟨6/6⟩으로 바꾸어요 — 6 = ⟨5 6/6⟩.","⟨6/6⟩ − ⟨5/6⟩ = ⟨1/6⟩.","6 − ⟨5/6⟩ = ⟨5 1/6⟩ — 자연수 부분은 1 줄어요."],"asset":null},{"stem":"2 − ⟨3/9⟩ = ⟨1 □/9⟩ — □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["2에서 1만큼을 ⟨9/9⟩로 바꾸어요 — 2 = ⟨1 9/9⟩.","⟨9/9⟩ − ⟨3/9⟩ = ⟨6/9⟩.","2 − ⟨3/9⟩ = ⟨1 6/9⟩ — 자연수 부분은 1 줄어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_b#8','math',4,2,'u1','','g4_2_math_u1_review_b','unit_review','M4-2-u1-C9',1,'sa','auto','⟨6 4/7⟩ − ⟨1 5/7⟩를 1만큼 바꾸어 ⟨5 □/7⟩ − ⟨1 5/7⟩로 계산하려고 해요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u1-C9","difficulty":1,"kind":"sa","stem":"⟨6 4/7⟩ − ⟨1 5/7⟩를 1만큼 바꾸어 ⟨5 □/7⟩ − ⟨1 5/7⟩로 계산하려고 해요. □에 알맞은 수를 쓰세요.","answer":["11"],"explanation":["⟨4/7⟩ − ⟨5/7⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨6 4/7⟩ = ⟨5 11/7⟩.","자연수끼리 5 − 1 = 4, 분수끼리 ⟨11/7⟩ − ⟨5/7⟩ = ⟨6/7⟩ — 답 ⟨4 6/7⟩."],"variant_rule":{"alt":[{"stem":"⟨5 6/9⟩ − ⟨4 7/9⟩을 1만큼 바꾸어 ⟨4 □/9⟩ − ⟨4 7/9⟩로 계산하려고 해요. □에 알맞은 수를 쓰세요.","answer":["15"],"explanation":["⟨6/9⟩ − ⟨7/9⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨5 6/9⟩ = ⟨4 15/9⟩.","자연수끼리 4 − 4 = 0, 분수끼리 ⟨15/9⟩ − ⟨7/9⟩ = ⟨8/9⟩ — 답 ⟨8/9⟩."],"asset":null},{"stem":"⟨5 3/5⟩ − ⟨1 4/5⟩를 1만큼 바꾸어 ⟨4 □/5⟩ − ⟨1 4/5⟩로 계산하려고 해요. □에 알맞은 수를 쓰세요.","answer":["8"],"explanation":["⟨3/5⟩ − ⟨4/5⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨5 3/5⟩ = ⟨4 8/5⟩.","자연수끼리 4 − 1 = 3, 분수끼리 ⟨8/5⟩ − ⟨4/5⟩ = ⟨4/5⟩ — 답 ⟨3 4/5⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_b#9','math',4,2,'u1','','g4_2_math_u1_review_b','unit_review','M4-2-u1-C1',2,'mc','auto','⟨4/3⟩를 대분수로 나타내면 무엇인가요?',ARRAY['M4-2-u1-X04','M4-2-u1-X16']::text[],true,'{"seq":9,"concept":"M4-2-u1-C1","difficulty":2,"kind":"mc","stem":"⟨4/3⟩를 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨1 1/3⟩","correct":true},{"t":"⟨2 1/3⟩","mis":"M4-2-u1-X04"},{"t":"⟨1 2/3⟩","mis":"M4-2-u1-X16"},{"t":"⟨3 1/3⟩","mis":"M4-2-u1-X04"}],"explanation":["⟨4/3⟩는 ⟨1/3⟩이 4개예요.","⟨1/3⟩이 3개 모이면 1 — 3개씩 모으면 1이 1번, 1개가 남아요.","⟨4/3⟩ = ⟨1 1/3⟩."],"variant_rule":{"alt":[{"stem":"⟨29/8⟩를 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨3 5/8⟩","correct":true},{"t":"⟨4 5/8⟩","mis":"M4-2-u1-X04"},{"t":"⟨2 5/8⟩","mis":"M4-2-u1-X04"},{"t":"⟨3 6/8⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨29/8⟩는 ⟨1/8⟩이 29개예요.","⟨1/8⟩이 8개 모이면 1 — 8개씩 모으면 1이 3번, 5개가 남아요.","⟨29/8⟩ = ⟨3 5/8⟩."],"asset":null},{"stem":"⟨14/6⟩를 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨2 2/6⟩","correct":true},{"t":"⟨3 2/6⟩","mis":"M4-2-u1-X04"},{"t":"⟨1 2/6⟩","mis":"M4-2-u1-X04"},{"t":"⟨2 3/6⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨14/6⟩는 ⟨1/6⟩이 14개예요.","⟨1/6⟩이 6개 모이면 1 — 6개씩 모으면 1이 2번, 2개가 남아요.","⟨14/6⟩ = ⟨2 2/6⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_b#10','math',4,2,'u1','','g4_2_math_u1_review_b','unit_review','M4-2-u1-C3',2,'mc','auto','곰이는 사과를 ⟨7/8⟩ kg, 펭이는 ⟨6/8⟩ kg 땄어요. 두 사람이 딴 사과는 모두 몇 kg인가요?',ARRAY['M4-2-u1-X01','M4-2-u1-X16']::text[],true,'{"seq":10,"concept":"M4-2-u1-C3","difficulty":2,"kind":"mc","stem":"곰이는 사과를 ⟨7/8⟩ kg, 펭이는 ⟨6/8⟩ kg 땄어요. 두 사람이 딴 사과는 모두 몇 kg인가요?","options":[{"t":"⟨1 5/8⟩ kg","correct":true},{"t":"⟨13/16⟩ kg","mis":"M4-2-u1-X01"},{"t":"⟨1 6/8⟩ kg","mis":"M4-2-u1-X16"},{"t":"⟨1 4/8⟩ kg","mis":"M4-2-u1-X16"}],"explanation":["분모가 8로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/8⟩이 7 + 6 = 13개.","⟨7/8⟩ + ⟨6/8⟩ = ⟨13/8⟩.","⟨13/8⟩은 1보다 커요 — ⟨13/8⟩ = ⟨1 5/8⟩."],"variant_rule":{"alt":[{"stem":"빨간 페인트 ⟨4/6⟩ L와 노란 페인트 ⟨3/6⟩ L를 섞었어요. 주황 페인트는 몇 L가 되었나요?","options":[{"t":"⟨1 1/6⟩ L","correct":true},{"t":"⟨7/12⟩ L","mis":"M4-2-u1-X01"},{"t":"⟨1 2/6⟩ L","mis":"M4-2-u1-X16"},{"t":"1 L","mis":"M4-2-u1-X16"}],"explanation":["분모가 6으로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/6⟩이 4 + 3 = 7개.","⟨4/6⟩ + ⟨3/6⟩ = ⟨7/6⟩.","⟨7/6⟩은 1보다 커요 — ⟨7/6⟩ = ⟨1 1/6⟩."],"asset":null},{"stem":"곰이는 사과를 ⟨3/5⟩ kg, 펭이는 ⟨3/5⟩ kg 땄어요. 두 사람이 딴 사과는 모두 몇 kg인가요?","options":[{"t":"⟨1 1/5⟩ kg","correct":true},{"t":"⟨6/10⟩ kg","mis":"M4-2-u1-X01"},{"t":"⟨1 2/5⟩ kg","mis":"M4-2-u1-X16"},{"t":"1 kg","mis":"M4-2-u1-X16"}],"explanation":["분모가 5로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/5⟩이 3 + 3 = 6개.","⟨3/5⟩ + ⟨3/5⟩ = ⟨6/5⟩.","⟨6/5⟩은 1보다 커요 — ⟨6/5⟩ = ⟨1 1/5⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_b#11','math',4,2,'u1','','g4_2_math_u1_review_b','unit_review','M4-2-u1-C4',2,'mc','auto','1 − ⟨2/8⟩를 계산하면 얼마인가요?',ARRAY['M4-2-u1-X08','M4-2-u1-X16']::text[],true,'{"seq":11,"concept":"M4-2-u1-C4","difficulty":2,"kind":"mc","stem":"1 − ⟨2/8⟩를 계산하면 얼마인가요?","options":[{"t":"⟨6/8⟩","correct":true},{"t":"⟨1/8⟩","mis":"M4-2-u1-X08"},{"t":"⟨7/8⟩","mis":"M4-2-u1-X16"},{"t":"⟨5/8⟩","mis":"M4-2-u1-X16"}],"explanation":["1을 분모가 8인 분수로 바꾸면 ⟨8/8⟩이에요.","⟨8/8⟩ − ⟨2/8⟩ — ⟨1/8⟩이 8 − 2 = 6개.","1 − ⟨2/8⟩ = ⟨6/8⟩."],"variant_rule":{"alt":[{"stem":"1 − ⟨5/10⟩를 계산하면 얼마인가요?","options":[{"t":"⟨5/10⟩","correct":true},{"t":"⟨4/10⟩","mis":"M4-2-u1-X08"},{"t":"⟨6/10⟩","mis":"M4-2-u1-X16"},{"t":"⟨1 5/10⟩","mis":"M4-2-u1-X14"}],"explanation":["1을 분모가 10인 분수로 바꾸면 ⟨10/10⟩이에요.","⟨10/10⟩ − ⟨5/10⟩ — ⟨1/10⟩이 10 − 5 = 5개.","1 − ⟨5/10⟩ = ⟨5/10⟩."],"asset":null},{"stem":"1 − ⟨1/6⟩을 계산하면 얼마인가요?","options":[{"t":"⟨5/6⟩","correct":true},{"t":"⟨4/6⟩","mis":"M4-2-u1-X16"},{"t":"⟨1/6⟩","mis":"M4-2-u1-X15"},{"t":"⟨1 1/6⟩","mis":"M4-2-u1-X14"}],"explanation":["1을 분모가 6인 분수로 바꾸면 ⟨6/6⟩이에요.","⟨6/6⟩ − ⟨1/6⟩ — ⟨1/6⟩이 6 − 1 = 5개.","1 − ⟨1/6⟩ = ⟨5/6⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_b#12','math',4,2,'u1','','g4_2_math_u1_review_b','unit_review','M4-2-u1-C5',2,'mc','auto','⟨2 3/6⟩ + ⟨1 5/6⟩를 계산하면 얼마인가요?',ARRAY['M4-2-u1-X07','M4-2-u1-X01','M4-2-u1-X13']::text[],true,'{"seq":12,"concept":"M4-2-u1-C5","difficulty":2,"kind":"mc","stem":"⟨2 3/6⟩ + ⟨1 5/6⟩를 계산하면 얼마인가요?","options":[{"t":"⟨4 2/6⟩","correct":true},{"t":"⟨3 2/6⟩","mis":"M4-2-u1-X07"},{"t":"⟨3 8/12⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 2/6⟩","mis":"M4-2-u1-X13"}],"explanation":["자연수끼리 2 + 1 = 3.","진분수끼리 ⟨3/6⟩ + ⟨5/6⟩ = ⟨8/6⟩ — 1보다 커서 ⟨1 2/6⟩, 1을 자연수로 넘겨요.","⟨2 3/6⟩ + ⟨1 5/6⟩ = ⟨4 2/6⟩."],"variant_rule":{"alt":[{"stem":"⟨4 4/6⟩ + ⟨1 4/6⟩를 계산하면 얼마인가요?","options":[{"t":"⟨6 2/6⟩","correct":true},{"t":"⟨5 2/6⟩","mis":"M4-2-u1-X07"},{"t":"⟨5 8/12⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 2/6⟩","mis":"M4-2-u1-X13"}],"explanation":["자연수끼리 4 + 1 = 5.","진분수끼리 ⟨4/6⟩ + ⟨4/6⟩ = ⟨8/6⟩ — 1보다 커서 ⟨1 2/6⟩, 1을 자연수로 넘겨요.","⟨4 4/6⟩ + ⟨1 4/6⟩ = ⟨6 2/6⟩."],"asset":null},{"stem":"⟨3 2/5⟩ + ⟨2 4/5⟩를 계산하면 얼마인가요?","options":[{"t":"⟨6 1/5⟩","correct":true},{"t":"⟨5 1/5⟩","mis":"M4-2-u1-X07"},{"t":"⟨5 6/10⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 1/5⟩","mis":"M4-2-u1-X13"}],"explanation":["자연수끼리 3 + 2 = 5.","진분수끼리 ⟨2/5⟩ + ⟨4/5⟩ = ⟨6/5⟩ — 1보다 커서 ⟨1 1/5⟩, 1을 자연수로 넘겨요.","⟨3 2/5⟩ + ⟨2 4/5⟩ = ⟨6 1/5⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_b#13','math',4,2,'u1','','g4_2_math_u1_review_b','unit_review','M4-2-u1-C6',2,'mc','auto','드론 약품 통에 약품이 ⟨4 3/7⟩ L 있었어요. 밭에 ⟨1 1/7⟩ L를 뿌렸다면 남은 약품은 몇 L인가요?',ARRAY['M4-2-u1-X13','M4-2-u1-X14','M4-2-u1-X01']::text[],true,'{"seq":13,"concept":"M4-2-u1-C6","difficulty":2,"kind":"mc","stem":"드론 약품 통에 약품이 ⟨4 3/7⟩ L 있었어요. 밭에 ⟨1 1/7⟩ L를 뿌렸다면 남은 약품은 몇 L인가요?","options":[{"t":"⟨3 2/7⟩ L","correct":true},{"t":"⟨2/7⟩ L","mis":"M4-2-u1-X13"},{"t":"⟨5 4/7⟩ L","mis":"M4-2-u1-X14"},{"t":"⟨3 2/6⟩ L","mis":"M4-2-u1-X01"}],"explanation":["자연수끼리 4 − 1 = 3.","진분수끼리 ⟨3/7⟩ − ⟨1/7⟩ = ⟨2/7⟩.","⟨4 3/7⟩ − ⟨1 1/7⟩ = ⟨3 2/7⟩."],"variant_rule":{"alt":[{"stem":"드론 약품 통에 약품이 ⟨4 3/9⟩ L 있었어요. 밭에 ⟨2 1/9⟩ L를 뿌렸다면 남은 약품은 몇 L인가요?","options":[{"t":"⟨2 2/9⟩ L","correct":true},{"t":"⟨2/9⟩ L","mis":"M4-2-u1-X13"},{"t":"⟨6 4/9⟩ L","mis":"M4-2-u1-X14"},{"t":"⟨2 2/8⟩ L","mis":"M4-2-u1-X01"}],"explanation":["자연수끼리 4 − 2 = 2.","진분수끼리 ⟨3/9⟩ − ⟨1/9⟩ = ⟨2/9⟩.","⟨4 3/9⟩ − ⟨2 1/9⟩ = ⟨2 2/9⟩."],"asset":null},{"stem":"드론 약품 통에 약품이 ⟨6 3/7⟩ L 있었어요. 밭에 ⟨1 2/7⟩ L를 뿌렸다면 남은 약품은 몇 L인가요?","options":[{"t":"⟨5 1/7⟩ L","correct":true},{"t":"⟨1/7⟩ L","mis":"M4-2-u1-X13"},{"t":"⟨7 5/7⟩ L","mis":"M4-2-u1-X14"},{"t":"⟨5 1/5⟩ L","mis":"M4-2-u1-X01"}],"explanation":["자연수끼리 6 − 1 = 5.","진분수끼리 ⟨3/7⟩ − ⟨2/7⟩ = ⟨1/7⟩.","⟨6 3/7⟩ − ⟨1 2/7⟩ = ⟨5 1/7⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_b#14','math',4,2,'u1','','g4_2_math_u1_review_b','unit_review','M4-2-u1-C7',2,'mc','auto','7 − ⟨2/9⟩를 계산하면 얼마인가요?',ARRAY['M4-2-u1-X09','M4-2-u1-X10','M4-2-u1-X16']::text[],true,'{"seq":14,"concept":"M4-2-u1-C7","difficulty":2,"kind":"mc","stem":"7 − ⟨2/9⟩를 계산하면 얼마인가요?","options":[{"t":"⟨6 7/9⟩","correct":true},{"t":"⟨7 7/9⟩","mis":"M4-2-u1-X09"},{"t":"⟨6 2/9⟩","mis":"M4-2-u1-X10"},{"t":"⟨6 8/9⟩","mis":"M4-2-u1-X16"}],"explanation":["7에서 1만큼을 ⟨9/9⟩로 바꾸어요 — 7 = ⟨6 9/9⟩.","⟨9/9⟩ − ⟨2/9⟩ = ⟨7/9⟩.","7 − ⟨2/9⟩ = ⟨6 7/9⟩ — 자연수 부분은 1 줄어요."],"variant_rule":{"alt":[{"stem":"2 − ⟨4/5⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1 1/5⟩","correct":true},{"t":"⟨2 1/5⟩","mis":"M4-2-u1-X09"},{"t":"⟨1 4/5⟩","mis":"M4-2-u1-X10"},{"t":"⟨1 2/5⟩","mis":"M4-2-u1-X16"}],"explanation":["2에서 1만큼을 ⟨5/5⟩로 바꾸어요 — 2 = ⟨1 5/5⟩.","⟨5/5⟩ − ⟨4/5⟩ = ⟨1/5⟩.","2 − ⟨4/5⟩ = ⟨1 1/5⟩ — 자연수 부분은 1 줄어요."],"asset":null},{"stem":"4 − ⟨1/7⟩을 계산하면 얼마인가요?","options":[{"t":"⟨3 6/7⟩","correct":true},{"t":"⟨4 6/7⟩","mis":"M4-2-u1-X09"},{"t":"⟨3 1/7⟩","mis":"M4-2-u1-X10"},{"t":"⟨3 5/7⟩","mis":"M4-2-u1-X16"}],"explanation":["4에서 1만큼을 ⟨7/7⟩로 바꾸어요 — 4 = ⟨3 7/7⟩.","⟨7/7⟩ − ⟨1/7⟩ = ⟨6/7⟩.","4 − ⟨1/7⟩ = ⟨3 6/7⟩ — 자연수 부분은 1 줄어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_b#15','math',4,2,'u1','','g4_2_math_u1_review_b','unit_review','M4-2-u1-C8',2,'mc','auto','⟨5 2/6⟩ − ⟨5/6⟩를 계산하면 얼마인가요?',ARRAY['M4-2-u1-X11','M4-2-u1-X12','M4-2-u1-X16']::text[],true,'{"seq":15,"concept":"M4-2-u1-C8","difficulty":2,"kind":"mc","stem":"⟨5 2/6⟩ − ⟨5/6⟩를 계산하면 얼마인가요?","options":[{"t":"⟨4 3/6⟩","correct":true},{"t":"⟨5 3/6⟩","mis":"M4-2-u1-X11"},{"t":"⟨4 7/6⟩","mis":"M4-2-u1-X12"},{"t":"⟨4 4/6⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨2/6⟩ − ⟨5/6⟩ — 진분수끼리 뺄 수 없어요(2 < 5).","1만큼 바꾸어요 — ⟨5 2/6⟩ = ⟨4 8/6⟩.","⟨4 8/6⟩ − ⟨5/6⟩ = ⟨4 3/6⟩ — 자연수 부분은 1 줄어요."],"variant_rule":{"alt":[{"stem":"⟨2 5/9⟩ − ⟨8/9⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1 6/9⟩","correct":true},{"t":"⟨2 3/9⟩","mis":"M4-2-u1-X11"},{"t":"⟨2 6/9⟩","mis":"M4-2-u1-X09"},{"t":"⟨1 7/9⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨5/9⟩ − ⟨8/9⟩ — 진분수끼리 뺄 수 없어요(5 < 8).","1만큼 바꾸어요 — ⟨2 5/9⟩ = ⟨1 14/9⟩.","⟨1 14/9⟩ − ⟨8/9⟩ = ⟨1 6/9⟩ — 자연수 부분은 1 줄어요."],"asset":null},{"stem":"⟨2 5/8⟩ − ⟨7/8⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1 6/8⟩","correct":true},{"t":"⟨2 2/8⟩","mis":"M4-2-u1-X11"},{"t":"⟨2 6/8⟩","mis":"M4-2-u1-X09"},{"t":"⟨1 8/8⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨5/8⟩ − ⟨7/8⟩ — 진분수끼리 뺄 수 없어요(5 < 7).","1만큼 바꾸어요 — ⟨2 5/8⟩ = ⟨1 13/8⟩.","⟨1 13/8⟩ − ⟨7/8⟩ = ⟨1 6/8⟩ — 자연수 부분은 1 줄어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_b#16','math',4,2,'u1','','g4_2_math_u1_review_b','unit_review','M4-2-u1-C9',2,'mc','auto','⟨4 1/5⟩ − ⟨3 3/5⟩을 계산하면 얼마인가요?',ARRAY['M4-2-u1-X11','M4-2-u1-X09','M4-2-u1-X12']::text[],true,'{"seq":16,"concept":"M4-2-u1-C9","difficulty":2,"kind":"mc","stem":"⟨4 1/5⟩ − ⟨3 3/5⟩을 계산하면 얼마인가요?","options":[{"t":"⟨3/5⟩","correct":true},{"t":"⟨1 2/5⟩","mis":"M4-2-u1-X11"},{"t":"⟨1 3/5⟩","mis":"M4-2-u1-X09"},{"t":"⟨8/5⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨1/5⟩ − ⟨3/5⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨4 1/5⟩ = ⟨3 6/5⟩.","자연수끼리 3 − 3 = 0, 분수끼리 ⟨6/5⟩ − ⟨3/5⟩ = ⟨3/5⟩ — 답 ⟨3/5⟩."],"variant_rule":{"alt":[{"stem":"⟨6 1/5⟩ − ⟨4 2/5⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1 4/5⟩","correct":true},{"t":"⟨2 1/5⟩","mis":"M4-2-u1-X11"},{"t":"⟨2 4/5⟩","mis":"M4-2-u1-X09"},{"t":"⟨1 9/5⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨1/5⟩ − ⟨2/5⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨6 1/5⟩ = ⟨5 6/5⟩.","자연수끼리 5 − 4 = 1, 분수끼리 ⟨6/5⟩ − ⟨2/5⟩ = ⟨4/5⟩ — 답 ⟨1 4/5⟩."],"asset":null},{"stem":"⟨4 2/4⟩ − ⟨3 3/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨3/4⟩","correct":true},{"t":"⟨1 1/4⟩","mis":"M4-2-u1-X11"},{"t":"⟨1 3/4⟩","mis":"M4-2-u1-X09"},{"t":"⟨9/4⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨2/4⟩ − ⟨3/4⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨4 2/4⟩ = ⟨3 6/4⟩.","자연수끼리 3 − 3 = 0, 분수끼리 ⟨6/4⟩ − ⟨3/4⟩ = ⟨3/4⟩ — 답 ⟨3/4⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_b#17','math',4,2,'u1','','g4_2_math_u1_review_b','unit_review','M4-2-u1-C2',3,'mc','auto','⟨3/11⟩과 모아서 1이 되는 분수는 무엇인가요?',ARRAY['M4-2-u1-X06','M4-2-u1-X16']::text[],true,'{"seq":17,"concept":"M4-2-u1-C2","difficulty":3,"kind":"mc","stem":"⟨3/11⟩과 모아서 1이 되는 분수는 무엇인가요?","options":[{"t":"⟨8/11⟩","correct":true},{"t":"⟨3/11⟩","mis":"M4-2-u1-X06"},{"t":"⟨11/3⟩","mis":"M4-2-u1-X06"},{"t":"⟨9/11⟩","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨11/11⟩ — ⟨1/11⟩이 11개예요.","⟨3/11⟩은 ⟨1/11⟩이 3개 — 8개가 모자라요.","⟨3/11⟩과 ⟨8/11⟩을 모으면 1이에요."],"variant_rule":{"alt":[{"stem":"⟨10/11⟩과 모아서 1이 되는 분수는 무엇인가요?","options":[{"t":"⟨1/11⟩","correct":true},{"t":"⟨10/11⟩","mis":"M4-2-u1-X06"},{"t":"⟨11/10⟩","mis":"M4-2-u1-X06"},{"t":"⟨2/11⟩","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨11/11⟩ — ⟨1/11⟩이 11개예요.","⟨10/11⟩은 ⟨1/11⟩이 10개 — 1개가 모자라요.","⟨10/11⟩과 ⟨1/11⟩을 모으면 1이에요."],"asset":null},{"stem":"⟨2/8⟩와 모아서 1이 되는 분수는 무엇인가요?","options":[{"t":"⟨6/8⟩","correct":true},{"t":"⟨2/8⟩","mis":"M4-2-u1-X06"},{"t":"⟨8/2⟩","mis":"M4-2-u1-X06"},{"t":"⟨7/8⟩","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨8/8⟩ — ⟨1/8⟩이 8개예요.","⟨2/8⟩는 ⟨1/8⟩이 2개 — 6개가 모자라요.","⟨2/8⟩와 ⟨6/8⟩을 모으면 1이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_b#18','math',4,2,'u1','','g4_2_math_u1_review_b','unit_review','M4-2-u1-C3',3,'sa','auto','⟨6/10⟩ + ⟨□/10⟩ = ⟨1 4/10⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M4-2-u1-C3","difficulty":3,"kind":"sa","stem":"⟨6/10⟩ + ⟨□/10⟩ = ⟨1 4/10⟩ — □에 알맞은 수를 쓰세요.","answer":["8"],"explanation":["⟨1 4/10⟩를 가분수로 — ⟨14/10⟩.","⟨1/10⟩이 14개가 되려면 6개에서 8개를 더 모아야 해요.","□ = 14 − 6 = 8."],"variant_rule":{"alt":[{"stem":"⟨3/5⟩ + ⟨□/5⟩ = ⟨1 1/5⟩ — □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["⟨1 1/5⟩을 가분수로 — ⟨6/5⟩.","⟨1/5⟩이 6개가 되려면 3개에서 3개를 더 모아야 해요.","□ = 6 − 3 = 3."],"asset":null},{"stem":"⟨9/12⟩ + ⟨□/12⟩ = ⟨1 4/12⟩ — □에 알맞은 수를 쓰세요.","answer":["7"],"explanation":["⟨1 4/12⟩를 가분수로 — ⟨16/12⟩.","⟨1/12⟩이 16개가 되려면 9개에서 7개를 더 모아야 해요.","□ = 16 − 9 = 7."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_b#19','math',4,2,'u1','','g4_2_math_u1_review_b','unit_review','M4-2-u1-C5',3,'sa','auto','⟨2 6/7⟩ + ⟨2 5/7⟩를 가분수로 바꾸어 계산하면 ⟨□/7⟩ + ⟨△/7⟩ = ⟨○/7⟩이에요. ○에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M4-2-u1-C5","difficulty":3,"kind":"sa","stem":"⟨2 6/7⟩ + ⟨2 5/7⟩를 가분수로 바꾸어 계산하면 ⟨□/7⟩ + ⟨△/7⟩ = ⟨○/7⟩이에요. ○에 알맞은 수를 쓰세요.","answer":["39"],"explanation":["⟨2 6/7⟩ = ⟨20/7⟩, ⟨2 5/7⟩ = ⟨19/7⟩.","⟨20/7⟩ + ⟨19/7⟩ = ⟨39/7⟩.","○ = 39 — 대분수로 ⟨5 4/7⟩."],"variant_rule":{"alt":[{"stem":"⟨4 6/7⟩ + ⟨4 2/7⟩를 가분수로 바꾸어 계산하면 ⟨□/7⟩ + ⟨△/7⟩ = ⟨○/7⟩이에요. ○에 알맞은 수를 쓰세요.","answer":["64"],"explanation":["⟨4 6/7⟩ = ⟨34/7⟩, ⟨4 2/7⟩ = ⟨30/7⟩.","⟨34/7⟩ + ⟨30/7⟩ = ⟨64/7⟩.","○ = 64 — 대분수로 ⟨9 1/7⟩."],"asset":null},{"stem":"⟨3 4/7⟩ + ⟨3 4/7⟩를 가분수로 바꾸어 계산하면 ⟨□/7⟩ + ⟨△/7⟩ = ⟨○/7⟩이에요. ○에 알맞은 수를 쓰세요.","answer":["50"],"explanation":["⟨3 4/7⟩ = ⟨25/7⟩, ⟨3 4/7⟩ = ⟨25/7⟩.","⟨25/7⟩ + ⟨25/7⟩ = ⟨50/7⟩.","○ = 50 — 대분수로 ⟨7 1/7⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_b#20','math',4,2,'u1','','g4_2_math_u1_review_b','unit_review','M4-2-u1-C7',3,'mc','auto','두부를 만들려고 콩 4 kg 가운데 ⟨2 3/5⟩ kg을 물에 불렸어요. 불리지 않고 남은 콩은 몇 kg인가요?',ARRAY['M4-2-u1-X09','M4-2-u1-X10','M4-2-u1-X14']::text[],true,'{"seq":20,"concept":"M4-2-u1-C7","difficulty":3,"kind":"mc","stem":"두부를 만들려고 콩 4 kg 가운데 ⟨2 3/5⟩ kg을 물에 불렸어요. 불리지 않고 남은 콩은 몇 kg인가요?","options":[{"t":"⟨1 2/5⟩ kg","correct":true},{"t":"⟨2 2/5⟩ kg","mis":"M4-2-u1-X09"},{"t":"⟨1 3/5⟩ kg","mis":"M4-2-u1-X10"},{"t":"⟨6 3/5⟩ kg","mis":"M4-2-u1-X14"}],"explanation":["4 = ⟨3 5/5⟩로 바꾸어요.","⟨3 5/5⟩ − ⟨2 3/5⟩ = ⟨1 2/5⟩.","남은 콩은 ⟨1 2/5⟩ kg이에요."],"variant_rule":{"alt":[{"stem":"두부를 만들려고 콩 5 kg 가운데 ⟨4 3/8⟩ kg을 물에 불렸어요. 불리지 않고 남은 콩은 몇 kg인가요?","options":[{"t":"⟨5/8⟩ kg","correct":true},{"t":"⟨1 5/8⟩ kg","mis":"M4-2-u1-X09"},{"t":"⟨3/8⟩ kg","mis":"M4-2-u1-X10"},{"t":"⟨6/8⟩ kg","mis":"M4-2-u1-X16"}],"explanation":["5 = ⟨4 8/8⟩로 바꾸어요.","⟨4 8/8⟩ − ⟨4 3/8⟩ = ⟨5/8⟩.","남은 콩은 ⟨5/8⟩ kg이에요."],"asset":null},{"stem":"두부를 만들려고 콩 6 kg 가운데 ⟨2 2/3⟩ kg을 물에 불렸어요. 불리지 않고 남은 콩은 몇 kg인가요?","options":[{"t":"⟨3 1/3⟩ kg","correct":true},{"t":"⟨4 1/3⟩ kg","mis":"M4-2-u1-X09"},{"t":"⟨3 2/3⟩ kg","mis":"M4-2-u1-X10"},{"t":"⟨8 2/3⟩ kg","mis":"M4-2-u1-X14"}],"explanation":["6 = ⟨5 3/3⟩으로 바꾸어요.","⟨5 3/3⟩ − ⟨2 2/3⟩ = ⟨3 1/3⟩.","남은 콩은 ⟨3 1/3⟩ kg이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_b#21','math',4,2,'u1','','g4_2_math_u1_review_b','unit_review','M4-2-u1-C9',3,'mc','auto','곰이는 자전거로 ⟨4 3/5⟩ km, 펭이는 ⟨2 4/5⟩ km를 달렸어요. 곰이는 펭이보다 몇 km 더 달렸나요?',ARRAY['M4-2-u1-X11','M4-2-u1-X09','M4-2-u1-X12']::text[],true,'{"seq":21,"concept":"M4-2-u1-C9","difficulty":3,"kind":"mc","stem":"곰이는 자전거로 ⟨4 3/5⟩ km, 펭이는 ⟨2 4/5⟩ km를 달렸어요. 곰이는 펭이보다 몇 km 더 달렸나요?","options":[{"t":"⟨1 4/5⟩ km","correct":true},{"t":"⟨2 1/5⟩ km","mis":"M4-2-u1-X11"},{"t":"⟨2 4/5⟩ km","mis":"M4-2-u1-X09"},{"t":"⟨1 9/5⟩ km","mis":"M4-2-u1-X12"}],"explanation":["⟨3/5⟩ − ⟨4/5⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨4 3/5⟩ = ⟨3 8/5⟩.","자연수끼리 3 − 2 = 1, 분수끼리 ⟨8/5⟩ − ⟨4/5⟩ = ⟨4/5⟩ — 답 ⟨1 4/5⟩."],"variant_rule":{"alt":[{"stem":"곰이는 자전거로 ⟨6 6/9⟩ km, 펭이는 ⟨2 8/9⟩ km를 달렸어요. 곰이는 펭이보다 몇 km 더 달렸나요?","options":[{"t":"⟨3 7/9⟩ km","correct":true},{"t":"⟨4 2/9⟩ km","mis":"M4-2-u1-X11"},{"t":"⟨4 7/9⟩ km","mis":"M4-2-u1-X09"},{"t":"⟨3 8/9⟩ km","mis":"M4-2-u1-X12"}],"explanation":["⟨6/9⟩ − ⟨8/9⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨6 6/9⟩ = ⟨5 15/9⟩.","자연수끼리 5 − 2 = 3, 분수끼리 ⟨15/9⟩ − ⟨8/9⟩ = ⟨7/9⟩ — 답 ⟨3 7/9⟩."],"asset":null},{"stem":"곰이는 자전거로 ⟨2 6/12⟩ km, 펭이는 ⟨1 10/12⟩ km를 달렸어요. 곰이는 펭이보다 몇 km 더 달렸나요?","options":[{"t":"⟨8/12⟩ km","correct":true},{"t":"⟨1 4/12⟩ km","mis":"M4-2-u1-X11"},{"t":"⟨1 8/12⟩ km","mis":"M4-2-u1-X09"},{"t":"⟨6/12⟩ km","mis":"M4-2-u1-X12"}],"explanation":["⟨6/12⟩ − ⟨10/12⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨2 6/12⟩ = ⟨1 18/12⟩.","자연수끼리 1 − 1 = 0, 분수끼리 ⟨18/12⟩ − ⟨10/12⟩ = ⟨8/12⟩ — 답 ⟨8/12⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_b#22','math',4,2,'u1','','g4_2_math_u1_review_b','unit_review','M4-2-u1-C10',3,'mc','auto','분수 카드 ⟨3 5/6⟩, ⟨3 1/6⟩, ⟨2 2/6⟩, ⟨1 3/6⟩ 중 두 장을 골라 합이 ⟨5 2/6⟩가 되게 하려고 해요. 어떤 두 장을 골라야 하나요?',ARRAY['M4-2-u1-X17']::text[],true,'{"seq":22,"concept":"M4-2-u1-C10","difficulty":3,"kind":"mc","stem":"분수 카드 ⟨3 5/6⟩, ⟨3 1/6⟩, ⟨2 2/6⟩, ⟨1 3/6⟩ 중 두 장을 골라 합이 ⟨5 2/6⟩가 되게 하려고 해요. 어떤 두 장을 골라야 하나요?","options":[{"t":"⟨3 5/6⟩, ⟨1 3/6⟩","correct":true},{"t":"⟨3 1/6⟩, ⟨1 3/6⟩","mis":"M4-2-u1-X17"},{"t":"⟨3 1/6⟩, ⟨2 2/6⟩","mis":"M4-2-u1-X17"},{"t":"⟨2 2/6⟩, ⟨1 3/6⟩","mis":"M4-2-u1-X17"}],"explanation":["어림해요 — 자연수 부분을 먼저 맞추어 보아요.","⟨3 5/6⟩ + ⟨1 3/6⟩ = ⟨5 2/6⟩.","⟨3 5/6⟩, ⟨1 3/6⟩을 골라요."],"variant_rule":{"alt":[{"stem":"분수 카드 ⟨1 3/7⟩, ⟨3 5/7⟩, ⟨1 4/7⟩, ⟨3 6/7⟩ 중 두 장을 골라 합이 ⟨7 4/7⟩가 되게 하려고 해요. 어떤 두 장을 골라야 하나요?","options":[{"t":"⟨3 5/7⟩, ⟨3 6/7⟩","correct":true},{"t":"⟨3 5/7⟩, ⟨1 4/7⟩","mis":"M4-2-u1-X17"},{"t":"⟨1 4/7⟩, ⟨3 6/7⟩","mis":"M4-2-u1-X17"},{"t":"⟨1 3/7⟩, ⟨1 4/7⟩","mis":"M4-2-u1-X17"}],"explanation":["어림해요 — 자연수 부분을 먼저 맞추어 보아요.","⟨3 5/7⟩ + ⟨3 6/7⟩ = ⟨7 4/7⟩.","⟨3 5/7⟩, ⟨3 6/7⟩을 골라요."],"asset":null},{"stem":"분수 카드 ⟨2 1/8⟩, ⟨3 4/8⟩, ⟨3 1/8⟩, ⟨1 4/8⟩ 중 두 장을 골라 합이 ⟨5 2/8⟩가 되게 하려고 해요. 어떤 두 장을 골라야 하나요?","options":[{"t":"⟨2 1/8⟩, ⟨3 1/8⟩","correct":true},{"t":"⟨2 1/8⟩, ⟨1 4/8⟩","mis":"M4-2-u1-X17"},{"t":"⟨3 1/8⟩, ⟨1 4/8⟩","mis":"M4-2-u1-X17"},{"t":"⟨3 4/8⟩, ⟨3 1/8⟩","mis":"M4-2-u1-X17"}],"explanation":["어림해요 — 자연수 부분을 먼저 맞추어 보아요.","⟨2 1/8⟩ + ⟨3 1/8⟩ = ⟨5 2/8⟩.","⟨2 1/8⟩, ⟨3 1/8⟩을 골라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_b#23','math',4,2,'u1','','g4_2_math_u1_review_b','unit_review','M4-2-u1-C9',4,'mc','auto','□ − ⟨2 5/6⟩ = ⟨1 5/6⟩일 때, □에 알맞은 대분수는 무엇인가요?',ARRAY['M4-2-u1-X16','M4-2-u1-X09']::text[],true,'{"seq":23,"concept":"M4-2-u1-C9","difficulty":4,"kind":"mc","stem":"□ − ⟨2 5/6⟩ = ⟨1 5/6⟩일 때, □에 알맞은 대분수는 무엇인가요?","options":[{"t":"⟨4 4/6⟩","correct":true},{"t":"⟨4 5/6⟩","mis":"M4-2-u1-X16"},{"t":"⟨4 3/6⟩","mis":"M4-2-u1-X16"},{"t":"⟨3 4/6⟩","mis":"M4-2-u1-X09"}],"explanation":["□에서 ⟨2 5/6⟩를 덜어 ⟨1 5/6⟩가 남았어요.","덧셈으로 되돌려요 — □ = ⟨1 5/6⟩ + ⟨2 5/6⟩.","□ = ⟨4 4/6⟩."],"variant_rule":{"alt":[{"stem":"□ − ⟨3 6/8⟩ = ⟨1 7/8⟩일 때, □에 알맞은 대분수는 무엇인가요?","options":[{"t":"⟨5 5/8⟩","correct":true},{"t":"⟨5 6/8⟩","mis":"M4-2-u1-X16"},{"t":"⟨5 4/8⟩","mis":"M4-2-u1-X16"},{"t":"⟨4 5/8⟩","mis":"M4-2-u1-X09"}],"explanation":["□에서 ⟨3 6/8⟩을 덜어 ⟨1 7/8⟩이 남았어요.","덧셈으로 되돌려요 — □ = ⟨1 7/8⟩ + ⟨3 6/8⟩.","□ = ⟨5 5/8⟩."],"asset":null},{"stem":"□ − ⟨1 8/10⟩ = ⟨4 7/10⟩일 때, □에 알맞은 대분수는 무엇인가요?","options":[{"t":"⟨6 5/10⟩","correct":true},{"t":"⟨2 9/10⟩","mis":"M4-2-u1-X14"},{"t":"⟨6 6/10⟩","mis":"M4-2-u1-X16"},{"t":"⟨6 4/10⟩","mis":"M4-2-u1-X16"}],"explanation":["□에서 ⟨1 8/10⟩을 덜어 ⟨4 7/10⟩이 남았어요.","덧셈으로 되돌려요 — □ = ⟨4 7/10⟩ + ⟨1 8/10⟩.","□ = ⟨6 5/10⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_b#24','math',4,2,'u1','','g4_2_math_u1_review_b','unit_review','M4-2-u1-C10',4,'mc','auto','수 카드 1, 3, 5 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 8인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 합은 얼마인가요?',ARRAY['M4-2-u1-X16','M4-2-u1-X14']::text[],true,'{"seq":24,"concept":"M4-2-u1-C10","difficulty":4,"kind":"mc","stem":"수 카드 1, 3, 5 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 8인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 합은 얼마인가요?","options":[{"t":"⟨6 6/8⟩","correct":true},{"t":"⟨6 7/8⟩","mis":"M4-2-u1-X16"},{"t":"⟨6 5/8⟩","mis":"M4-2-u1-X16"},{"t":"4","mis":"M4-2-u1-X14"}],"explanation":["가장 큰 대분수 — 자연수 부분에 가장 큰 수 5, 분자에 다음 큰 수 3 → ⟨5 3/8⟩.","가장 작은 대분수 — 자연수 부분에 가장 작은 수 1, 분자에 3 → ⟨1 3/8⟩.","⟨5 3/8⟩ + ⟨1 3/8⟩ = ⟨6 6/8⟩."],"variant_rule":{"alt":[{"stem":"수 카드 6, 3, 2 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 7인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 합은 얼마인가요?","options":[{"t":"⟨8 6/7⟩","correct":true},{"t":"⟨9 1/7⟩","mis":"M4-2-u1-X17"},{"t":"9","mis":"M4-2-u1-X16"},{"t":"⟨8 5/7⟩","mis":"M4-2-u1-X16"}],"explanation":["가장 큰 대분수 — 자연수 부분에 가장 큰 수 6, 분자에 다음 큰 수 3 → ⟨6 3/7⟩.","가장 작은 대분수 — 자연수 부분에 가장 작은 수 2, 분자에 3 → ⟨2 3/7⟩.","⟨6 3/7⟩ + ⟨2 3/7⟩ = ⟨8 6/7⟩."],"asset":null},{"stem":"수 카드 2, 6, 1 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 8인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 합은 얼마인가요?","options":[{"t":"⟨7 4/8⟩","correct":true},{"t":"⟨7 7/8⟩","mis":"M4-2-u1-X17"},{"t":"⟨7 5/8⟩","mis":"M4-2-u1-X16"},{"t":"⟨7 3/8⟩","mis":"M4-2-u1-X16"}],"explanation":["가장 큰 대분수 — 자연수 부분에 가장 큰 수 6, 분자에 다음 큰 수 2 → ⟨6 2/8⟩.","가장 작은 대분수 — 자연수 부분에 가장 작은 수 1, 분자에 2 → ⟨1 2/8⟩.","⟨6 2/8⟩ + ⟨1 2/8⟩ = ⟨7 4/8⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_b#25','math',4,2,'u1','','g4_2_math_u1_review_b','unit_review','M4-2-u1-C9',4,'essay','teacher','⟨4 1/5⟩ − ⟨1 3/5⟩을 계산하고, 1만큼을 바꾸는 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u1-C9","difficulty":4,"kind":"essay","stem":"⟨4 1/5⟩ − ⟨1 3/5⟩을 계산하고, 1만큼을 바꾸는 까닭을 설명해 보세요.","answer_guide":{"answer":"예: ⟨1/5⟩에서 ⟨3/5⟩을 뺄 수 없으므로 ⟨4 1/5⟩ = ⟨3 6/5⟩으로 바꾼다. ⟨3 6/5⟩ − ⟨1 3/5⟩ = ⟨2 3/5⟩이다. 1 = ⟨5/5⟩이므로 바꾸어도 크기는 같다.","scoring_points":["⟨4 1/5⟩ = ⟨3 6/5⟩으로 바꾸었는가","⟨2 3/5⟩이라고 답했는가","1 = ⟨5/5⟩라 크기가 같다고 썼는가"]},"explanation":["⟨3 6/5⟩ − ⟨1 3/5⟩.","= ⟨2 3/5⟩.","1 = ⟨5/5⟩."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_c#1','math',4,2,'u1','','g4_2_math_u1_review_c','unit_review','M4-2-u1-C1',1,'sa','auto','⟨25/9⟩는 ⟨1/9⟩이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-2-u1-C1","difficulty":1,"kind":"sa","stem":"⟨25/9⟩는 ⟨1/9⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["분모 9 — 1을 똑같이 9칸으로 나눈 것 중 한 칸이 ⟨1/9⟩이에요.","분자 25 — ⟨1/9⟩이 25개라는 뜻이에요.","⟨25/9⟩는 ⟨1/9⟩이 25개인 수예요."],"variant_rule":{"alt":[{"stem":"⟨6/4⟩은 ⟨1/4⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["분모 4 — 1을 똑같이 4칸으로 나눈 것 중 한 칸이 ⟨1/4⟩이에요.","분자 6 — ⟨1/4⟩이 6개라는 뜻이에요.","⟨6/4⟩은 ⟨1/4⟩이 6개인 수예요."],"asset":null},{"stem":"⟨14/9⟩는 ⟨1/9⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["분모 9 — 1을 똑같이 9칸으로 나눈 것 중 한 칸이 ⟨1/9⟩이에요.","분자 14 — ⟨1/9⟩이 14개라는 뜻이에요.","⟨14/9⟩는 ⟨1/9⟩이 14개인 수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_c#2','math',4,2,'u1','','g4_2_math_u1_review_c','unit_review','M4-2-u1-C2',1,'sa','auto','1을 ⟨1/10⟩이 3개인 분수와 ⟨1/10⟩이 □개인 분수로 갈랐어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u1-C2","difficulty":1,"kind":"sa","stem":"1을 ⟨1/10⟩이 3개인 분수와 ⟨1/10⟩이 □개인 분수로 갈랐어요. □에 알맞은 수를 쓰세요.","answer":["7"],"explanation":["분모가 10이면 1 = ⟨10/10⟩ — ⟨1/10⟩이 10개예요.","10개 중 3개를 떼면 10 − 3 = 7개가 남아요.","□ = 7 — 1 = ⟨3/10⟩ + ⟨7/10⟩."],"variant_rule":{"alt":[{"stem":"1을 ⟨1/9⟩이 3개인 분수와 ⟨1/9⟩이 □개인 분수로 갈랐어요. □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["분모가 9이면 1 = ⟨9/9⟩ — ⟨1/9⟩이 9개예요.","9개 중 3개를 떼면 9 − 3 = 6개가 남아요.","□ = 6 — 1 = ⟨3/9⟩ + ⟨6/9⟩."],"asset":null},{"stem":"1을 ⟨1/10⟩이 5개인 분수와 ⟨1/10⟩이 □개인 분수로 갈랐어요. □에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["분모가 10이면 1 = ⟨10/10⟩ — ⟨1/10⟩이 10개예요.","10개 중 5개를 떼면 10 − 5 = 5개가 남아요.","□ = 5 — 1 = ⟨5/10⟩ + ⟨5/10⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_c#3','math',4,2,'u1','','g4_2_math_u1_review_c','unit_review','M4-2-u1-C3',1,'sa','auto','⟨2/8⟩ + ⟨1/8⟩ = ⟨□/8⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u1-C3","difficulty":1,"kind":"sa","stem":"⟨2/8⟩ + ⟨1/8⟩ = ⟨□/8⟩ — □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["분모가 8로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/8⟩이 2 + 1 = 3개.","⟨2/8⟩ + ⟨1/8⟩ = ⟨3/8⟩.","분모끼리 더해 ⟨3/16⟩으로 쓰지 않아요."],"variant_rule":{"alt":[{"stem":"⟨5/9⟩ + ⟨3/9⟩ = ⟨□/9⟩ — □에 알맞은 수를 쓰세요.","answer":["8"],"explanation":["분모가 9로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/9⟩이 5 + 3 = 8개.","⟨5/9⟩ + ⟨3/9⟩ = ⟨8/9⟩.","분모끼리 더해 ⟨8/18⟩로 쓰지 않아요."],"asset":null},{"stem":"⟨1/5⟩ + ⟨3/5⟩ = ⟨□/5⟩ — □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["분모가 5로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/5⟩이 1 + 3 = 4개.","⟨1/5⟩ + ⟨3/5⟩ = ⟨4/5⟩.","분모끼리 더해 ⟨4/10⟩로 쓰지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_c#4','math',4,2,'u1','','g4_2_math_u1_review_c','unit_review','M4-2-u1-C4',1,'sa','auto','1 − ⟨7/10⟩ = ⟨□/10⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u1-C4","difficulty":1,"kind":"sa","stem":"1 − ⟨7/10⟩ = ⟨□/10⟩ — □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["1을 분모가 10인 분수로 바꾸면 ⟨10/10⟩이에요.","⟨10/10⟩ − ⟨7/10⟩ — ⟨1/10⟩이 10 − 7 = 3개.","1 − ⟨7/10⟩ = ⟨3/10⟩."],"variant_rule":{"alt":[{"stem":"1 − ⟨7/9⟩ = ⟨□/9⟩ — □에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["1을 분모가 9인 분수로 바꾸면 ⟨9/9⟩예요.","⟨9/9⟩ − ⟨7/9⟩ — ⟨1/9⟩이 9 − 7 = 2개.","1 − ⟨7/9⟩ = ⟨2/9⟩."],"asset":null},{"stem":"1 − ⟨1/5⟩ = ⟨□/5⟩ — □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["1을 분모가 5인 분수로 바꾸면 ⟨5/5⟩예요.","⟨5/5⟩ − ⟨1/5⟩ — ⟨1/5⟩이 5 − 1 = 4개.","1 − ⟨1/5⟩ = ⟨4/5⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_c#5','math',4,2,'u1','','g4_2_math_u1_review_c','unit_review','M4-2-u1-C5',1,'sa','auto','⟨2 2/7⟩ + ⟨2 3/7⟩을 계산하여 대분수로 나타낼 때, 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u1-C5","difficulty":1,"kind":"sa","stem":"⟨2 2/7⟩ + ⟨2 3/7⟩을 계산하여 대분수로 나타낼 때, 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["자연수끼리 2 + 2 = 4.","진분수끼리 ⟨2/7⟩ + ⟨3/7⟩ = ⟨5/7⟩.","⟨2 2/7⟩ + ⟨2 3/7⟩ = ⟨4 5/7⟩."],"variant_rule":{"alt":[{"stem":"⟨3 2/5⟩ + ⟨4 2/5⟩를 계산하여 대분수로 나타낼 때, 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["자연수끼리 3 + 4 = 7.","진분수끼리 ⟨2/5⟩ + ⟨2/5⟩ = ⟨4/5⟩.","⟨3 2/5⟩ + ⟨4 2/5⟩ = ⟨7 4/5⟩."],"asset":null},{"stem":"⟨4 1/3⟩ + ⟨2 1/3⟩을 계산하여 대분수로 나타낼 때, 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["자연수끼리 4 + 2 = 6.","진분수끼리 ⟨1/3⟩ + ⟨1/3⟩ = ⟨2/3⟩.","⟨4 1/3⟩ + ⟨2 1/3⟩ = ⟨6 2/3⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_c#6','math',4,2,'u1','','g4_2_math_u1_review_c','unit_review','M4-2-u1-C6',1,'sa','auto','⟨2 2/3⟩ − ⟨1 1/3⟩ = ⟨1 △/3⟩ — △에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u1-C6","difficulty":1,"kind":"sa","stem":"⟨2 2/3⟩ − ⟨1 1/3⟩ = ⟨1 △/3⟩ — △에 알맞은 수를 쓰세요.","answer":["1"],"explanation":["자연수끼리 2 − 1 = 1.","진분수끼리 ⟨2/3⟩ − ⟨1/3⟩ = ⟨1/3⟩.","⟨2 2/3⟩ − ⟨1 1/3⟩ = ⟨1 1/3⟩."],"variant_rule":{"alt":[{"stem":"⟨3 5/8⟩ − ⟨2 4/8⟩ = ⟨1 △/8⟩ — △에 알맞은 수를 쓰세요.","answer":["1"],"explanation":["자연수끼리 3 − 2 = 1.","진분수끼리 ⟨5/8⟩ − ⟨4/8⟩ = ⟨1/8⟩.","⟨3 5/8⟩ − ⟨2 4/8⟩ = ⟨1 1/8⟩."],"asset":null},{"stem":"⟨2 2/4⟩ − ⟨1 1/4⟩ = ⟨1 △/4⟩ — △에 알맞은 수를 쓰세요.","answer":["1"],"explanation":["자연수끼리 2 − 1 = 1.","진분수끼리 ⟨2/4⟩ − ⟨1/4⟩ = ⟨1/4⟩.","⟨2 2/4⟩ − ⟨1 1/4⟩ = ⟨1 1/4⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_c#7','math',4,2,'u1','','g4_2_math_u1_review_c','unit_review','M4-2-u1-C7',1,'sa','auto','5 − ⟨1/4⟩ = ⟨4 □/4⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-2-u1-C7","difficulty":1,"kind":"sa","stem":"5 − ⟨1/4⟩ = ⟨4 □/4⟩ — □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["5에서 1만큼을 ⟨4/4⟩로 바꾸어요 — 5 = ⟨4 4/4⟩.","⟨4/4⟩ − ⟨1/4⟩ = ⟨3/4⟩.","5 − ⟨1/4⟩ = ⟨4 3/4⟩ — 자연수 부분은 1 줄어요."],"variant_rule":{"alt":[{"stem":"6 − ⟨3/5⟩ = ⟨5 □/5⟩ — □에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["6에서 1만큼을 ⟨5/5⟩로 바꾸어요 — 6 = ⟨5 5/5⟩.","⟨5/5⟩ − ⟨3/5⟩ = ⟨2/5⟩.","6 − ⟨3/5⟩ = ⟨5 2/5⟩ — 자연수 부분은 1 줄어요."],"asset":null},{"stem":"2 − ⟨2/7⟩ = ⟨1 □/7⟩ — □에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["2에서 1만큼을 ⟨7/7⟩로 바꾸어요 — 2 = ⟨1 7/7⟩.","⟨7/7⟩ − ⟨2/7⟩ = ⟨5/7⟩.","2 − ⟨2/7⟩ = ⟨1 5/7⟩ — 자연수 부분은 1 줄어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_c#8','math',4,2,'u1','','g4_2_math_u1_review_c','unit_review','M4-2-u1-C9',1,'sa','auto','⟨5 4/7⟩ − ⟨1 5/7⟩를 1만큼 바꾸어 ⟨4 □/7⟩ − ⟨1 5/7⟩로 계산하려고 해요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u1-C9","difficulty":1,"kind":"sa","stem":"⟨5 4/7⟩ − ⟨1 5/7⟩를 1만큼 바꾸어 ⟨4 □/7⟩ − ⟨1 5/7⟩로 계산하려고 해요. □에 알맞은 수를 쓰세요.","answer":["11"],"explanation":["⟨4/7⟩ − ⟨5/7⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨5 4/7⟩ = ⟨4 11/7⟩.","자연수끼리 4 − 1 = 3, 분수끼리 ⟨11/7⟩ − ⟨5/7⟩ = ⟨6/7⟩ — 답 ⟨3 6/7⟩."],"variant_rule":{"alt":[{"stem":"⟨3 1/3⟩ − ⟨1 2/3⟩를 1만큼 바꾸어 ⟨2 □/3⟩ − ⟨1 2/3⟩로 계산하려고 해요. □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["⟨1/3⟩ − ⟨2/3⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨3 1/3⟩ = ⟨2 4/3⟩.","자연수끼리 2 − 1 = 1, 분수끼리 ⟨4/3⟩ − ⟨2/3⟩ = ⟨2/3⟩ — 답 ⟨1 2/3⟩."],"asset":null},{"stem":"⟨5 1/3⟩ − ⟨4 2/3⟩를 1만큼 바꾸어 ⟨4 □/3⟩ − ⟨4 2/3⟩로 계산하려고 해요. □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["⟨1/3⟩ − ⟨2/3⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨5 1/3⟩ = ⟨4 4/3⟩.","자연수끼리 4 − 4 = 0, 분수끼리 ⟨4/3⟩ − ⟨2/3⟩ = ⟨2/3⟩ — 답 ⟨2/3⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_c#9','math',4,2,'u1','','g4_2_math_u1_review_c','unit_review','M4-2-u1-C1',2,'mc','auto','⟨25/8⟩를 대분수로 나타내면 무엇인가요?',ARRAY['M4-2-u1-X04','M4-2-u1-X16']::text[],true,'{"seq":9,"concept":"M4-2-u1-C1","difficulty":2,"kind":"mc","stem":"⟨25/8⟩를 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨3 1/8⟩","correct":true},{"t":"⟨4 1/8⟩","mis":"M4-2-u1-X04"},{"t":"⟨2 1/8⟩","mis":"M4-2-u1-X04"},{"t":"⟨3 2/8⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨25/8⟩는 ⟨1/8⟩이 25개예요.","⟨1/8⟩이 8개 모이면 1 — 8개씩 모으면 1이 3번, 1개가 남아요.","⟨25/8⟩ = ⟨3 1/8⟩."],"variant_rule":{"alt":[{"stem":"⟨16/7⟩을 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨2 2/7⟩","correct":true},{"t":"⟨3 2/7⟩","mis":"M4-2-u1-X04"},{"t":"⟨1 2/7⟩","mis":"M4-2-u1-X04"},{"t":"⟨2 3/7⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨16/7⟩은 ⟨1/7⟩이 16개예요.","⟨1/7⟩이 7개 모이면 1 — 7개씩 모으면 1이 2번, 2개가 남아요.","⟨16/7⟩ = ⟨2 2/7⟩."],"asset":null},{"stem":"⟨14/4⟩를 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨3 2/4⟩","correct":true},{"t":"⟨4 2/4⟩","mis":"M4-2-u1-X04"},{"t":"⟨2 2/4⟩","mis":"M4-2-u1-X04"},{"t":"⟨3 3/4⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨14/4⟩는 ⟨1/4⟩이 14개예요.","⟨1/4⟩이 4개 모이면 1 — 4개씩 모으면 1이 3번, 2개가 남아요.","⟨14/4⟩ = ⟨3 2/4⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_c#10','math',4,2,'u1','','g4_2_math_u1_review_c','unit_review','M4-2-u1-C3',2,'mc','auto','빨간 페인트 ⟨4/6⟩ L와 노란 페인트 ⟨3/6⟩ L를 섞었어요. 주황 페인트는 몇 L가 되었나요?',ARRAY['M4-2-u1-X01','M4-2-u1-X16']::text[],true,'{"seq":10,"concept":"M4-2-u1-C3","difficulty":2,"kind":"mc","stem":"빨간 페인트 ⟨4/6⟩ L와 노란 페인트 ⟨3/6⟩ L를 섞었어요. 주황 페인트는 몇 L가 되었나요?","options":[{"t":"⟨1 1/6⟩ L","correct":true},{"t":"⟨7/12⟩ L","mis":"M4-2-u1-X01"},{"t":"⟨1 2/6⟩ L","mis":"M4-2-u1-X16"},{"t":"1 L","mis":"M4-2-u1-X16"}],"explanation":["분모가 6으로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/6⟩이 4 + 3 = 7개.","⟨4/6⟩ + ⟨3/6⟩ = ⟨7/6⟩.","⟨7/6⟩은 1보다 커요 — ⟨7/6⟩ = ⟨1 1/6⟩."],"variant_rule":{"alt":[{"stem":"곰이는 사과를 ⟨5/6⟩ kg, 펭이는 ⟨4/6⟩ kg 땄어요. 두 사람이 딴 사과는 모두 몇 kg인가요?","options":[{"t":"⟨1 3/6⟩ kg","correct":true},{"t":"⟨9/12⟩ kg","mis":"M4-2-u1-X01"},{"t":"⟨1 4/6⟩ kg","mis":"M4-2-u1-X16"},{"t":"⟨1 2/6⟩ kg","mis":"M4-2-u1-X16"}],"explanation":["분모가 6으로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/6⟩이 5 + 4 = 9개.","⟨5/6⟩ + ⟨4/6⟩ = ⟨9/6⟩.","⟨9/6⟩는 1보다 커요 — ⟨9/6⟩ = ⟨1 3/6⟩."],"asset":null},{"stem":"빨간 페인트 ⟨4/5⟩ L와 노란 페인트 ⟨2/5⟩ L를 섞었어요. 주황 페인트는 몇 L가 되었나요?","options":[{"t":"⟨1 1/5⟩ L","correct":true},{"t":"⟨6/10⟩ L","mis":"M4-2-u1-X01"},{"t":"⟨1 2/5⟩ L","mis":"M4-2-u1-X16"},{"t":"1 L","mis":"M4-2-u1-X16"}],"explanation":["분모가 5로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/5⟩이 4 + 2 = 6개.","⟨4/5⟩ + ⟨2/5⟩ = ⟨6/5⟩.","⟨6/5⟩은 1보다 커요 — ⟨6/5⟩ = ⟨1 1/5⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_c#11','math',4,2,'u1','','g4_2_math_u1_review_c','unit_review','M4-2-u1-C4',2,'mc','auto','1 − ⟨5/7⟩를 계산하면 얼마인가요?',ARRAY['M4-2-u1-X08','M4-2-u1-X16']::text[],true,'{"seq":11,"concept":"M4-2-u1-C4","difficulty":2,"kind":"mc","stem":"1 − ⟨5/7⟩를 계산하면 얼마인가요?","options":[{"t":"⟨2/7⟩","correct":true},{"t":"⟨4/7⟩","mis":"M4-2-u1-X08"},{"t":"⟨3/7⟩","mis":"M4-2-u1-X16"},{"t":"⟨1/7⟩","mis":"M4-2-u1-X16"}],"explanation":["1을 분모가 7인 분수로 바꾸면 ⟨7/7⟩이에요.","⟨7/7⟩ − ⟨5/7⟩ — ⟨1/7⟩이 7 − 5 = 2개.","1 − ⟨5/7⟩ = ⟨2/7⟩."],"variant_rule":{"alt":[{"stem":"1 − ⟨5/9⟩를 계산하면 얼마인가요?","options":[{"t":"⟨4/9⟩","correct":true},{"t":"⟨5/9⟩","mis":"M4-2-u1-X16"},{"t":"⟨3/9⟩","mis":"M4-2-u1-X16"},{"t":"⟨1 5/9⟩","mis":"M4-2-u1-X14"}],"explanation":["1을 분모가 9인 분수로 바꾸면 ⟨9/9⟩예요.","⟨9/9⟩ − ⟨5/9⟩ — ⟨1/9⟩이 9 − 5 = 4개.","1 − ⟨5/9⟩ = ⟨4/9⟩."],"asset":null},{"stem":"1 − ⟨3/8⟩을 계산하면 얼마인가요?","options":[{"t":"⟨5/8⟩","correct":true},{"t":"⟨2/8⟩","mis":"M4-2-u1-X08"},{"t":"⟨6/8⟩","mis":"M4-2-u1-X16"},{"t":"⟨4/8⟩","mis":"M4-2-u1-X16"}],"explanation":["1을 분모가 8인 분수로 바꾸면 ⟨8/8⟩이에요.","⟨8/8⟩ − ⟨3/8⟩ — ⟨1/8⟩이 8 − 3 = 5개.","1 − ⟨3/8⟩ = ⟨5/8⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_c#12','math',4,2,'u1','','g4_2_math_u1_review_c','unit_review','M4-2-u1-C5',2,'mc','auto','⟨2 2/3⟩ + ⟨3 2/3⟩를 계산하면 얼마인가요?',ARRAY['M4-2-u1-X07','M4-2-u1-X01','M4-2-u1-X13']::text[],true,'{"seq":12,"concept":"M4-2-u1-C5","difficulty":2,"kind":"mc","stem":"⟨2 2/3⟩ + ⟨3 2/3⟩를 계산하면 얼마인가요?","options":[{"t":"⟨6 1/3⟩","correct":true},{"t":"⟨5 1/3⟩","mis":"M4-2-u1-X07"},{"t":"⟨5 4/6⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 1/3⟩","mis":"M4-2-u1-X13"}],"explanation":["자연수끼리 2 + 3 = 5.","진분수끼리 ⟨2/3⟩ + ⟨2/3⟩ = ⟨4/3⟩ — 1보다 커서 ⟨1 1/3⟩, 1을 자연수로 넘겨요.","⟨2 2/3⟩ + ⟨3 2/3⟩ = ⟨6 1/3⟩."],"variant_rule":{"alt":[{"stem":"⟨3 6/8⟩ + ⟨1 7/8⟩을 계산하면 얼마인가요?","options":[{"t":"⟨5 5/8⟩","correct":true},{"t":"⟨4 5/8⟩","mis":"M4-2-u1-X07"},{"t":"⟨4 13/16⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 5/8⟩","mis":"M4-2-u1-X13"}],"explanation":["자연수끼리 3 + 1 = 4.","진분수끼리 ⟨6/8⟩ + ⟨7/8⟩ = ⟨13/8⟩ — 1보다 커서 ⟨1 5/8⟩, 1을 자연수로 넘겨요.","⟨3 6/8⟩ + ⟨1 7/8⟩ = ⟨5 5/8⟩."],"asset":null},{"stem":"⟨1 4/8⟩ + ⟨2 5/8⟩를 계산하면 얼마인가요?","options":[{"t":"⟨4 1/8⟩","correct":true},{"t":"⟨3 1/8⟩","mis":"M4-2-u1-X07"},{"t":"⟨3 9/16⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 1/8⟩","mis":"M4-2-u1-X13"}],"explanation":["자연수끼리 1 + 2 = 3.","진분수끼리 ⟨4/8⟩ + ⟨5/8⟩ = ⟨9/8⟩ — 1보다 커서 ⟨1 1/8⟩, 1을 자연수로 넘겨요.","⟨1 4/8⟩ + ⟨2 5/8⟩ = ⟨4 1/8⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_c#13','math',4,2,'u1','','g4_2_math_u1_review_c','unit_review','M4-2-u1-C6',2,'mc','auto','드론 약품 통에 약품이 ⟨5 3/4⟩ L 있었어요. 밭에 ⟨2 2/4⟩ L를 뿌렸다면 남은 약품은 몇 L인가요?',ARRAY['M4-2-u1-X13','M4-2-u1-X14','M4-2-u1-X01']::text[],true,'{"seq":13,"concept":"M4-2-u1-C6","difficulty":2,"kind":"mc","stem":"드론 약품 통에 약품이 ⟨5 3/4⟩ L 있었어요. 밭에 ⟨2 2/4⟩ L를 뿌렸다면 남은 약품은 몇 L인가요?","options":[{"t":"⟨3 1/4⟩ L","correct":true},{"t":"⟨1/4⟩ L","mis":"M4-2-u1-X13"},{"t":"⟨8 1/4⟩ L","mis":"M4-2-u1-X14"},{"t":"⟨3 1/2⟩ L","mis":"M4-2-u1-X01"}],"explanation":["자연수끼리 5 − 2 = 3.","진분수끼리 ⟨3/4⟩ − ⟨2/4⟩ = ⟨1/4⟩.","⟨5 3/4⟩ − ⟨2 2/4⟩ = ⟨3 1/4⟩."],"variant_rule":{"alt":[{"stem":"드론 약품 통에 약품이 ⟨6 2/3⟩ L 있었어요. 밭에 ⟨1 1/3⟩ L를 뿌렸다면 남은 약품은 몇 L인가요?","options":[{"t":"⟨5 1/3⟩ L","correct":true},{"t":"⟨1/3⟩ L","mis":"M4-2-u1-X13"},{"t":"8 L","mis":"M4-2-u1-X14"},{"t":"⟨5 1/2⟩ L","mis":"M4-2-u1-X01"}],"explanation":["자연수끼리 6 − 1 = 5.","진분수끼리 ⟨2/3⟩ − ⟨1/3⟩ = ⟨1/3⟩.","⟨6 2/3⟩ − ⟨1 1/3⟩ = ⟨5 1/3⟩."],"asset":null},{"stem":"드론 약품 통에 약품이 ⟨3 2/3⟩ L 있었어요. 밭에 ⟨1 1/3⟩ L를 뿌렸다면 남은 약품은 몇 L인가요?","options":[{"t":"⟨2 1/3⟩ L","correct":true},{"t":"⟨1/3⟩ L","mis":"M4-2-u1-X13"},{"t":"5 L","mis":"M4-2-u1-X14"},{"t":"⟨2 1/2⟩ L","mis":"M4-2-u1-X01"}],"explanation":["자연수끼리 3 − 1 = 2.","진분수끼리 ⟨2/3⟩ − ⟨1/3⟩ = ⟨1/3⟩.","⟨3 2/3⟩ − ⟨1 1/3⟩ = ⟨2 1/3⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_c#14','math',4,2,'u1','','g4_2_math_u1_review_c','unit_review','M4-2-u1-C7',2,'mc','auto','3 − ⟨4/5⟩를 계산하면 얼마인가요?',ARRAY['M4-2-u1-X09','M4-2-u1-X10','M4-2-u1-X16']::text[],true,'{"seq":14,"concept":"M4-2-u1-C7","difficulty":2,"kind":"mc","stem":"3 − ⟨4/5⟩를 계산하면 얼마인가요?","options":[{"t":"⟨2 1/5⟩","correct":true},{"t":"⟨3 1/5⟩","mis":"M4-2-u1-X09"},{"t":"⟨2 4/5⟩","mis":"M4-2-u1-X10"},{"t":"⟨2 2/5⟩","mis":"M4-2-u1-X16"}],"explanation":["3에서 1만큼을 ⟨5/5⟩로 바꾸어요 — 3 = ⟨2 5/5⟩.","⟨5/5⟩ − ⟨4/5⟩ = ⟨1/5⟩.","3 − ⟨4/5⟩ = ⟨2 1/5⟩ — 자연수 부분은 1 줄어요."],"variant_rule":{"alt":[{"stem":"7 − ⟨7/9⟩을 계산하면 얼마인가요?","options":[{"t":"⟨6 2/9⟩","correct":true},{"t":"⟨7 2/9⟩","mis":"M4-2-u1-X09"},{"t":"⟨6 7/9⟩","mis":"M4-2-u1-X10"},{"t":"⟨6 3/9⟩","mis":"M4-2-u1-X16"}],"explanation":["7에서 1만큼을 ⟨9/9⟩로 바꾸어요 — 7 = ⟨6 9/9⟩.","⟨9/9⟩ − ⟨7/9⟩ = ⟨2/9⟩.","7 − ⟨7/9⟩ = ⟨6 2/9⟩ — 자연수 부분은 1 줄어요."],"asset":null},{"stem":"5 − ⟨5/8⟩를 계산하면 얼마인가요?","options":[{"t":"⟨4 3/8⟩","correct":true},{"t":"⟨5 3/8⟩","mis":"M4-2-u1-X09"},{"t":"⟨4 5/8⟩","mis":"M4-2-u1-X10"},{"t":"⟨4 4/8⟩","mis":"M4-2-u1-X16"}],"explanation":["5에서 1만큼을 ⟨8/8⟩로 바꾸어요 — 5 = ⟨4 8/8⟩.","⟨8/8⟩ − ⟨5/8⟩ = ⟨3/8⟩.","5 − ⟨5/8⟩ = ⟨4 3/8⟩ — 자연수 부분은 1 줄어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_c#15','math',4,2,'u1','','g4_2_math_u1_review_c','unit_review','M4-2-u1-C8',2,'mc','auto','⟨5 2/4⟩ − ⟨3/4⟩을 계산하면 얼마인가요?',ARRAY['M4-2-u1-X11','M4-2-u1-X09','M4-2-u1-X12']::text[],true,'{"seq":15,"concept":"M4-2-u1-C8","difficulty":2,"kind":"mc","stem":"⟨5 2/4⟩ − ⟨3/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4 3/4⟩","correct":true},{"t":"⟨5 1/4⟩","mis":"M4-2-u1-X11"},{"t":"⟨5 3/4⟩","mis":"M4-2-u1-X09"},{"t":"⟨4 9/4⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨2/4⟩ − ⟨3/4⟩ — 진분수끼리 뺄 수 없어요(2 < 3).","1만큼 바꾸어요 — ⟨5 2/4⟩ = ⟨4 6/4⟩.","⟨4 6/4⟩ − ⟨3/4⟩ = ⟨4 3/4⟩ — 자연수 부분은 1 줄어요."],"variant_rule":{"alt":[{"stem":"⟨5 2/7⟩ − ⟨6/7⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4 3/7⟩","correct":true},{"t":"⟨5 4/7⟩","mis":"M4-2-u1-X11"},{"t":"⟨5 3/7⟩","mis":"M4-2-u1-X09"},{"t":"⟨4 6/7⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨2/7⟩ − ⟨6/7⟩ — 진분수끼리 뺄 수 없어요(2 < 6).","1만큼 바꾸어요 — ⟨5 2/7⟩ = ⟨4 9/7⟩.","⟨4 9/7⟩ − ⟨6/7⟩ = ⟨4 3/7⟩ — 자연수 부분은 1 줄어요."],"asset":null},{"stem":"⟨6 2/4⟩ − ⟨3/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨5 3/4⟩","correct":true},{"t":"⟨6 1/4⟩","mis":"M4-2-u1-X11"},{"t":"⟨6 3/4⟩","mis":"M4-2-u1-X09"},{"t":"⟨5 9/4⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨2/4⟩ − ⟨3/4⟩ — 진분수끼리 뺄 수 없어요(2 < 3).","1만큼 바꾸어요 — ⟨6 2/4⟩ = ⟨5 6/4⟩.","⟨5 6/4⟩ − ⟨3/4⟩ = ⟨5 3/4⟩ — 자연수 부분은 1 줄어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_c#16','math',4,2,'u1','','g4_2_math_u1_review_c','unit_review','M4-2-u1-C9',2,'mc','auto','⟨5 1/4⟩ − ⟨3 2/4⟩를 계산하면 얼마인가요?',ARRAY['M4-2-u1-X11','M4-2-u1-X09','M4-2-u1-X12']::text[],true,'{"seq":16,"concept":"M4-2-u1-C9","difficulty":2,"kind":"mc","stem":"⟨5 1/4⟩ − ⟨3 2/4⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1 3/4⟩","correct":true},{"t":"⟨2 1/4⟩","mis":"M4-2-u1-X11"},{"t":"⟨2 3/4⟩","mis":"M4-2-u1-X09"},{"t":"⟨1 9/4⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨1/4⟩ − ⟨2/4⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨5 1/4⟩ = ⟨4 5/4⟩.","자연수끼리 4 − 3 = 1, 분수끼리 ⟨5/4⟩ − ⟨2/4⟩ = ⟨3/4⟩ — 답 ⟨1 3/4⟩."],"variant_rule":{"alt":[{"stem":"⟨3 2/6⟩ − ⟨1 3/6⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1 5/6⟩","correct":true},{"t":"⟨2 1/6⟩","mis":"M4-2-u1-X11"},{"t":"⟨2 5/6⟩","mis":"M4-2-u1-X09"},{"t":"⟨1 9/6⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨2/6⟩ − ⟨3/6⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨3 2/6⟩ = ⟨2 8/6⟩.","자연수끼리 2 − 1 = 1, 분수끼리 ⟨8/6⟩ − ⟨3/6⟩ = ⟨5/6⟩ — 답 ⟨1 5/6⟩."],"asset":null},{"stem":"⟨3 2/7⟩ − ⟨1 5/7⟩를 계산하면 얼마인가요?","options":[{"t":"⟨1 4/7⟩","correct":true},{"t":"⟨2 3/7⟩","mis":"M4-2-u1-X11"},{"t":"⟨2 4/7⟩","mis":"M4-2-u1-X09"},{"t":"⟨1 7/7⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨2/7⟩ − ⟨5/7⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨3 2/7⟩ = ⟨2 9/7⟩.","자연수끼리 2 − 1 = 1, 분수끼리 ⟨9/7⟩ − ⟨5/7⟩ = ⟨4/7⟩ — 답 ⟨1 4/7⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_c#17','math',4,2,'u1','','g4_2_math_u1_review_c','unit_review','M4-2-u1-C2',3,'mc','auto','⟨2/11⟩와 모아서 1이 되는 분수는 무엇인가요?',ARRAY['M4-2-u1-X06','M4-2-u1-X16']::text[],true,'{"seq":17,"concept":"M4-2-u1-C2","difficulty":3,"kind":"mc","stem":"⟨2/11⟩와 모아서 1이 되는 분수는 무엇인가요?","options":[{"t":"⟨9/11⟩","correct":true},{"t":"⟨2/11⟩","mis":"M4-2-u1-X06"},{"t":"⟨11/2⟩","mis":"M4-2-u1-X06"},{"t":"⟨10/11⟩","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨11/11⟩ — ⟨1/11⟩이 11개예요.","⟨2/11⟩는 ⟨1/11⟩이 2개 — 9개가 모자라요.","⟨2/11⟩와 ⟨9/11⟩를 모으면 1이에요."],"variant_rule":{"alt":[{"stem":"⟨4/8⟩와 모아서 1이 되는 분수는 무엇인가요?","options":[{"t":"⟨4/8⟩","correct":true},{"t":"⟨8/4⟩","mis":"M4-2-u1-X06"},{"t":"⟨5/8⟩","mis":"M4-2-u1-X16"},{"t":"⟨3/8⟩","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨8/8⟩ — ⟨1/8⟩이 8개예요.","⟨4/8⟩는 ⟨1/8⟩이 4개 — 4개가 모자라요.","⟨4/8⟩와 ⟨4/8⟩를 모으면 1이에요."],"asset":null},{"stem":"⟨3/10⟩과 모아서 1이 되는 분수는 무엇인가요?","options":[{"t":"⟨7/10⟩","correct":true},{"t":"⟨3/10⟩","mis":"M4-2-u1-X06"},{"t":"⟨10/3⟩","mis":"M4-2-u1-X06"},{"t":"⟨8/10⟩","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨10/10⟩ — ⟨1/10⟩이 10개예요.","⟨3/10⟩은 ⟨1/10⟩이 3개 — 7개가 모자라요.","⟨3/10⟩과 ⟨7/10⟩을 모으면 1이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_c#18','math',4,2,'u1','','g4_2_math_u1_review_c','unit_review','M4-2-u1-C3',3,'sa','auto','⟨6/12⟩ + ⟨□/12⟩ = ⟨1 4/12⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M4-2-u1-C3","difficulty":3,"kind":"sa","stem":"⟨6/12⟩ + ⟨□/12⟩ = ⟨1 4/12⟩ — □에 알맞은 수를 쓰세요.","answer":["10"],"explanation":["⟨1 4/12⟩를 가분수로 — ⟨16/12⟩.","⟨1/12⟩이 16개가 되려면 6개에서 10개를 더 모아야 해요.","□ = 16 − 6 = 10."],"variant_rule":{"alt":[{"stem":"⟨7/11⟩ + ⟨□/11⟩ = ⟨1 3/11⟩ — □에 알맞은 수를 쓰세요.","answer":["7"],"explanation":["⟨1 3/11⟩을 가분수로 — ⟨14/11⟩.","⟨1/11⟩이 14개가 되려면 7개에서 7개를 더 모아야 해요.","□ = 14 − 7 = 7."],"asset":null},{"stem":"⟨7/8⟩ + ⟨□/8⟩ = ⟨1 5/8⟩ — □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["⟨1 5/8⟩를 가분수로 — ⟨13/8⟩.","⟨1/8⟩이 13개가 되려면 7개에서 6개를 더 모아야 해요.","□ = 13 − 7 = 6."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_c#19','math',4,2,'u1','','g4_2_math_u1_review_c','unit_review','M4-2-u1-C5',3,'sa','auto','⟨1 2/7⟩ + ⟨1 6/7⟩을 가분수로 바꾸어 계산하면 ⟨□/7⟩ + ⟨△/7⟩ = ⟨○/7⟩이에요. ○에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M4-2-u1-C5","difficulty":3,"kind":"sa","stem":"⟨1 2/7⟩ + ⟨1 6/7⟩을 가분수로 바꾸어 계산하면 ⟨□/7⟩ + ⟨△/7⟩ = ⟨○/7⟩이에요. ○에 알맞은 수를 쓰세요.","answer":["22"],"explanation":["⟨1 2/7⟩ = ⟨9/7⟩, ⟨1 6/7⟩ = ⟨13/7⟩.","⟨9/7⟩ + ⟨13/7⟩ = ⟨22/7⟩.","○ = 22 — 대분수로 ⟨3 1/7⟩."],"variant_rule":{"alt":[{"stem":"⟨1 5/6⟩ + ⟨4 3/6⟩을 가분수로 바꾸어 계산하면 ⟨□/6⟩ + ⟨△/6⟩ = ⟨○/6⟩이에요. ○에 알맞은 수를 쓰세요.","answer":["38"],"explanation":["⟨1 5/6⟩ = ⟨11/6⟩, ⟨4 3/6⟩ = ⟨27/6⟩.","⟨11/6⟩ + ⟨27/6⟩ = ⟨38/6⟩.","○ = 38 — 대분수로 ⟨6 2/6⟩."],"asset":null},{"stem":"⟨3 5/6⟩ + ⟨1 3/6⟩을 가분수로 바꾸어 계산하면 ⟨□/6⟩ + ⟨△/6⟩ = ⟨○/6⟩이에요. ○에 알맞은 수를 쓰세요.","answer":["32"],"explanation":["⟨3 5/6⟩ = ⟨23/6⟩, ⟨1 3/6⟩ = ⟨9/6⟩.","⟨23/6⟩ + ⟨9/6⟩ = ⟨32/6⟩.","○ = 32 — 대분수로 ⟨5 2/6⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_c#20','math',4,2,'u1','','g4_2_math_u1_review_c','unit_review','M4-2-u1-C7',3,'mc','auto','두부를 만들려고 콩 4 kg 가운데 ⟨3 1/3⟩ kg을 물에 불렸어요. 불리지 않고 남은 콩은 몇 kg인가요?',ARRAY['M4-2-u1-X09','M4-2-u1-X10','M4-2-u1-X16']::text[],true,'{"seq":20,"concept":"M4-2-u1-C7","difficulty":3,"kind":"mc","stem":"두부를 만들려고 콩 4 kg 가운데 ⟨3 1/3⟩ kg을 물에 불렸어요. 불리지 않고 남은 콩은 몇 kg인가요?","options":[{"t":"⟨2/3⟩ kg","correct":true},{"t":"⟨1 2/3⟩ kg","mis":"M4-2-u1-X09"},{"t":"⟨1/3⟩ kg","mis":"M4-2-u1-X10"},{"t":"1 kg","mis":"M4-2-u1-X16"}],"explanation":["4 = ⟨3 3/3⟩으로 바꾸어요.","⟨3 3/3⟩ − ⟨3 1/3⟩ = ⟨2/3⟩.","남은 콩은 ⟨2/3⟩ kg이에요."],"variant_rule":{"alt":[{"stem":"두부를 만들려고 콩 3 kg 가운데 ⟨1 4/8⟩ kg을 물에 불렸어요. 불리지 않고 남은 콩은 몇 kg인가요?","options":[{"t":"⟨1 4/8⟩ kg","correct":true},{"t":"⟨2 4/8⟩ kg","mis":"M4-2-u1-X09"},{"t":"⟨1 5/8⟩ kg","mis":"M4-2-u1-X16"},{"t":"⟨4 4/8⟩ kg","mis":"M4-2-u1-X14"}],"explanation":["3 = ⟨2 8/8⟩로 바꾸어요.","⟨2 8/8⟩ − ⟨1 4/8⟩ = ⟨1 4/8⟩.","남은 콩은 ⟨1 4/8⟩ kg이에요."],"asset":null},{"stem":"두부를 만들려고 콩 6 kg 가운데 ⟨4 1/8⟩ kg을 물에 불렸어요. 불리지 않고 남은 콩은 몇 kg인가요?","options":[{"t":"⟨1 7/8⟩ kg","correct":true},{"t":"⟨2 7/8⟩ kg","mis":"M4-2-u1-X09"},{"t":"⟨1 1/8⟩ kg","mis":"M4-2-u1-X10"},{"t":"2 kg","mis":"M4-2-u1-X16"}],"explanation":["6 = ⟨5 8/8⟩로 바꾸어요.","⟨5 8/8⟩ − ⟨4 1/8⟩ = ⟨1 7/8⟩.","남은 콩은 ⟨1 7/8⟩ kg이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_c#21','math',4,2,'u1','','g4_2_math_u1_review_c','unit_review','M4-2-u1-C9',3,'mc','auto','곰이는 자전거로 ⟨3 6/9⟩ km, 펭이는 ⟨2 7/9⟩ km를 달렸어요. 곰이는 펭이보다 몇 km 더 달렸나요?',ARRAY['M4-2-u1-X11','M4-2-u1-X09','M4-2-u1-X12']::text[],true,'{"seq":21,"concept":"M4-2-u1-C9","difficulty":3,"kind":"mc","stem":"곰이는 자전거로 ⟨3 6/9⟩ km, 펭이는 ⟨2 7/9⟩ km를 달렸어요. 곰이는 펭이보다 몇 km 더 달렸나요?","options":[{"t":"⟨8/9⟩ km","correct":true},{"t":"⟨1 1/9⟩ km","mis":"M4-2-u1-X11"},{"t":"⟨1 8/9⟩ km","mis":"M4-2-u1-X09"},{"t":"⟨9/9⟩ km","mis":"M4-2-u1-X12"}],"explanation":["⟨6/9⟩ − ⟨7/9⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨3 6/9⟩ = ⟨2 15/9⟩.","자연수끼리 2 − 2 = 0, 분수끼리 ⟨15/9⟩ − ⟨7/9⟩ = ⟨8/9⟩ — 답 ⟨8/9⟩."],"variant_rule":{"alt":[{"stem":"곰이는 자전거로 ⟨5 3/5⟩ km, 펭이는 ⟨2 4/5⟩ km를 달렸어요. 곰이는 펭이보다 몇 km 더 달렸나요?","options":[{"t":"⟨2 4/5⟩ km","correct":true},{"t":"⟨3 1/5⟩ km","mis":"M4-2-u1-X11"},{"t":"⟨3 4/5⟩ km","mis":"M4-2-u1-X09"},{"t":"⟨2 9/5⟩ km","mis":"M4-2-u1-X12"}],"explanation":["⟨3/5⟩ − ⟨4/5⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨5 3/5⟩ = ⟨4 8/5⟩.","자연수끼리 4 − 2 = 2, 분수끼리 ⟨8/5⟩ − ⟨4/5⟩ = ⟨4/5⟩ — 답 ⟨2 4/5⟩."],"asset":null},{"stem":"곰이는 자전거로 ⟨4 3/5⟩ km, 펭이는 ⟨1 4/5⟩ km를 달렸어요. 곰이는 펭이보다 몇 km 더 달렸나요?","options":[{"t":"⟨2 4/5⟩ km","correct":true},{"t":"⟨3 1/5⟩ km","mis":"M4-2-u1-X11"},{"t":"⟨3 4/5⟩ km","mis":"M4-2-u1-X09"},{"t":"⟨2 9/5⟩ km","mis":"M4-2-u1-X12"}],"explanation":["⟨3/5⟩ − ⟨4/5⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨4 3/5⟩ = ⟨3 8/5⟩.","자연수끼리 3 − 1 = 2, 분수끼리 ⟨8/5⟩ − ⟨4/5⟩ = ⟨4/5⟩ — 답 ⟨2 4/5⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_c#22','math',4,2,'u1','','g4_2_math_u1_review_c','unit_review','M4-2-u1-C10',3,'mc','auto','분수 카드 ⟨1 2/6⟩, ⟨3 3/6⟩, ⟨3 4/6⟩, ⟨1 4/6⟩ 중 두 장을 골라 합이 ⟨4 5/6⟩가 되게 하려고 해요. 어떤 두 장을 골라야 하나요?',ARRAY['M4-2-u1-X17']::text[],true,'{"seq":22,"concept":"M4-2-u1-C10","difficulty":3,"kind":"mc","stem":"분수 카드 ⟨1 2/6⟩, ⟨3 3/6⟩, ⟨3 4/6⟩, ⟨1 4/6⟩ 중 두 장을 골라 합이 ⟨4 5/6⟩가 되게 하려고 해요. 어떤 두 장을 골라야 하나요?","options":[{"t":"⟨1 2/6⟩, ⟨3 3/6⟩","correct":true},{"t":"⟨3 3/6⟩, ⟨1 4/6⟩","mis":"M4-2-u1-X17"},{"t":"⟨3 3/6⟩, ⟨3 4/6⟩","mis":"M4-2-u1-X17"},{"t":"⟨1 2/6⟩, ⟨1 4/6⟩","mis":"M4-2-u1-X17"}],"explanation":["어림해요 — 자연수 부분을 먼저 맞추어 보아요.","⟨1 2/6⟩ + ⟨3 3/6⟩ = ⟨4 5/6⟩.","⟨1 2/6⟩, ⟨3 3/6⟩을 골라요."],"variant_rule":{"alt":[{"stem":"분수 카드 ⟨2 2/6⟩, ⟨3 3/6⟩, ⟨1 1/6⟩, ⟨3 2/6⟩ 중 두 장을 골라 합이 ⟨4 4/6⟩가 되게 하려고 해요. 어떤 두 장을 골라야 하나요?","options":[{"t":"⟨3 3/6⟩, ⟨1 1/6⟩","correct":true},{"t":"⟨2 2/6⟩, ⟨1 1/6⟩","mis":"M4-2-u1-X17"},{"t":"⟨2 2/6⟩, ⟨3 3/6⟩","mis":"M4-2-u1-X17"},{"t":"⟨3 3/6⟩, ⟨3 2/6⟩","mis":"M4-2-u1-X17"}],"explanation":["어림해요 — 자연수 부분을 먼저 맞추어 보아요.","⟨3 3/6⟩ + ⟨1 1/6⟩ = ⟨4 4/6⟩.","⟨3 3/6⟩, ⟨1 1/6⟩을 골라요."],"asset":null},{"stem":"분수 카드 ⟨2 3/7⟩, ⟨2 6/7⟩, ⟨2 4/7⟩, ⟨3 1/7⟩ 중 두 장을 골라 합이 ⟨5 4/7⟩가 되게 하려고 해요. 어떤 두 장을 골라야 하나요?","options":[{"t":"⟨2 3/7⟩, ⟨3 1/7⟩","correct":true},{"t":"⟨2 6/7⟩, ⟨2 4/7⟩","mis":"M4-2-u1-X17"},{"t":"⟨2 3/7⟩, ⟨2 4/7⟩","mis":"M4-2-u1-X17"},{"t":"⟨2 4/7⟩, ⟨3 1/7⟩","mis":"M4-2-u1-X17"}],"explanation":["어림해요 — 자연수 부분을 먼저 맞추어 보아요.","⟨2 3/7⟩ + ⟨3 1/7⟩ = ⟨5 4/7⟩.","⟨2 3/7⟩, ⟨3 1/7⟩을 골라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_c#23','math',4,2,'u1','','g4_2_math_u1_review_c','unit_review','M4-2-u1-C9',4,'mc','auto','□ − ⟨1 4/5⟩ = ⟨1 4/5⟩일 때, □에 알맞은 대분수는 무엇인가요?',ARRAY['M4-2-u1-X16','M4-2-u1-X09']::text[],true,'{"seq":23,"concept":"M4-2-u1-C9","difficulty":4,"kind":"mc","stem":"□ − ⟨1 4/5⟩ = ⟨1 4/5⟩일 때, □에 알맞은 대분수는 무엇인가요?","options":[{"t":"⟨3 3/5⟩","correct":true},{"t":"⟨3 4/5⟩","mis":"M4-2-u1-X16"},{"t":"⟨3 2/5⟩","mis":"M4-2-u1-X16"},{"t":"⟨2 3/5⟩","mis":"M4-2-u1-X09"}],"explanation":["□에서 ⟨1 4/5⟩를 덜어 ⟨1 4/5⟩가 남았어요.","덧셈으로 되돌려요 — □ = ⟨1 4/5⟩ + ⟨1 4/5⟩.","□ = ⟨3 3/5⟩."],"variant_rule":{"alt":[{"stem":"□ − ⟨2 6/8⟩ = ⟨1 5/8⟩일 때, □에 알맞은 대분수는 무엇인가요?","options":[{"t":"⟨4 3/8⟩","correct":true},{"t":"⟨4 4/8⟩","mis":"M4-2-u1-X16"},{"t":"⟨4 2/8⟩","mis":"M4-2-u1-X16"},{"t":"⟨3 3/8⟩","mis":"M4-2-u1-X09"}],"explanation":["□에서 ⟨2 6/8⟩을 덜어 ⟨1 5/8⟩가 남았어요.","덧셈으로 되돌려요 — □ = ⟨1 5/8⟩ + ⟨2 6/8⟩.","□ = ⟨4 3/8⟩."],"asset":null},{"stem":"□ − ⟨1 4/5⟩ = ⟨3 3/5⟩일 때, □에 알맞은 대분수는 무엇인가요?","options":[{"t":"⟨5 2/5⟩","correct":true},{"t":"⟨1 4/5⟩","mis":"M4-2-u1-X14"},{"t":"⟨5 3/5⟩","mis":"M4-2-u1-X16"},{"t":"⟨5 1/5⟩","mis":"M4-2-u1-X16"}],"explanation":["□에서 ⟨1 4/5⟩를 덜어 ⟨3 3/5⟩이 남았어요.","덧셈으로 되돌려요 — □ = ⟨3 3/5⟩ + ⟨1 4/5⟩.","□ = ⟨5 2/5⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_c#24','math',4,2,'u1','','g4_2_math_u1_review_c','unit_review','M4-2-u1-C10',4,'mc','auto','수 카드 2, 8, 1 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 9인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 합은 얼마인가요?',ARRAY['M4-2-u1-X17','M4-2-u1-X16']::text[],true,'{"seq":24,"concept":"M4-2-u1-C10","difficulty":4,"kind":"mc","stem":"수 카드 2, 8, 1 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 9인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 합은 얼마인가요?","options":[{"t":"⟨9 4/9⟩","correct":true},{"t":"10","mis":"M4-2-u1-X17"},{"t":"⟨9 5/9⟩","mis":"M4-2-u1-X16"},{"t":"⟨9 3/9⟩","mis":"M4-2-u1-X16"}],"explanation":["가장 큰 대분수 — 자연수 부분에 가장 큰 수 8, 분자에 다음 큰 수 2 → ⟨8 2/9⟩.","가장 작은 대분수 — 자연수 부분에 가장 작은 수 1, 분자에 2 → ⟨1 2/9⟩.","⟨8 2/9⟩ + ⟨1 2/9⟩ = ⟨9 4/9⟩."],"variant_rule":{"alt":[{"stem":"수 카드 2, 6, 4 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 9인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 합은 얼마인가요?","options":[{"t":"⟨8 8/9⟩","correct":true},{"t":"9","mis":"M4-2-u1-X16"},{"t":"⟨8 7/9⟩","mis":"M4-2-u1-X16"},{"t":"4","mis":"M4-2-u1-X14"}],"explanation":["가장 큰 대분수 — 자연수 부분에 가장 큰 수 6, 분자에 다음 큰 수 4 → ⟨6 4/9⟩.","가장 작은 대분수 — 자연수 부분에 가장 작은 수 2, 분자에 4 → ⟨2 4/9⟩.","⟨6 4/9⟩ + ⟨2 4/9⟩ = ⟨8 8/9⟩."],"asset":null},{"stem":"수 카드 2, 5, 4 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 9인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 합은 얼마인가요?","options":[{"t":"⟨7 8/9⟩","correct":true},{"t":"⟨7 7/9⟩","mis":"M4-2-u1-X17"},{"t":"8","mis":"M4-2-u1-X16"},{"t":"3","mis":"M4-2-u1-X14"}],"explanation":["가장 큰 대분수 — 자연수 부분에 가장 큰 수 5, 분자에 다음 큰 수 4 → ⟨5 4/9⟩.","가장 작은 대분수 — 자연수 부분에 가장 작은 수 2, 분자에 4 → ⟨2 4/9⟩.","⟨5 4/9⟩ + ⟨2 4/9⟩ = ⟨7 8/9⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_c#25','math',4,2,'u1','','g4_2_math_u1_review_c','unit_review','M4-2-u1-C7',4,'essay','teacher','집으로 가는 두 길이 있어요. 가 길은 5 km, 나 길은 ⟨3 2/3⟩ km예요. 나 길이 몇 km 더 짧은지 구하고 계산 방법을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u1-C7","difficulty":4,"kind":"essay","stem":"집으로 가는 두 길이 있어요. 가 길은 5 km, 나 길은 ⟨3 2/3⟩ km예요. 나 길이 몇 km 더 짧은지 구하고 계산 방법을 설명해 보세요.","answer_guide":{"answer":"예: 5 − ⟨3 2/3⟩를 계산한다. 5 = ⟨4 3/3⟩으로 바꾸면 ⟨4 3/3⟩ − ⟨3 2/3⟩ = ⟨1 1/3⟩이다. 나 길이 ⟨1 1/3⟩ km 더 짧다.","scoring_points":["뺄셈식 5 − ⟨3 2/3⟩를 세웠는가","5 = ⟨4 3/3⟩으로 바꾸었는가","⟨1 1/3⟩ km라고 답했는가"]},"explanation":["5 = ⟨4 3/3⟩.","⟨4 3/3⟩ − ⟨3 2/3⟩ = ⟨1 1/3⟩.","⟨1 1/3⟩ km."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_d#1','math',4,2,'u1','','g4_2_math_u1_review_d','unit_review','M4-2-u1-C1',1,'sa','auto','⟨25/9⟩는 ⟨1/9⟩이 몇 개인 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-2-u1-C1","difficulty":1,"kind":"sa","stem":"⟨25/9⟩는 ⟨1/9⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["분모 9 — 1을 똑같이 9칸으로 나눈 것 중 한 칸이 ⟨1/9⟩이에요.","분자 25 — ⟨1/9⟩이 25개라는 뜻이에요.","⟨25/9⟩는 ⟨1/9⟩이 25개인 수예요."],"variant_rule":{"alt":[{"stem":"⟨6/4⟩은 ⟨1/4⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["분모 4 — 1을 똑같이 4칸으로 나눈 것 중 한 칸이 ⟨1/4⟩이에요.","분자 6 — ⟨1/4⟩이 6개라는 뜻이에요.","⟨6/4⟩은 ⟨1/4⟩이 6개인 수예요."],"asset":null},{"stem":"⟨10/8⟩은 ⟨1/8⟩이 몇 개인 수인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["분모 8 — 1을 똑같이 8칸으로 나눈 것 중 한 칸이 ⟨1/8⟩이에요.","분자 10 — ⟨1/8⟩이 10개라는 뜻이에요.","⟨10/8⟩은 ⟨1/8⟩이 10개인 수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_d#2','math',4,2,'u1','','g4_2_math_u1_review_d','unit_review','M4-2-u1-C2',1,'sa','auto','1을 ⟨1/4⟩이 3개인 분수와 ⟨1/4⟩이 □개인 분수로 갈랐어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-2-u1-C2","difficulty":1,"kind":"sa","stem":"1을 ⟨1/4⟩이 3개인 분수와 ⟨1/4⟩이 □개인 분수로 갈랐어요. □에 알맞은 수를 쓰세요.","answer":["1"],"explanation":["분모가 4이면 1 = ⟨4/4⟩ — ⟨1/4⟩이 4개예요.","4개 중 3개를 떼면 4 − 3 = 1개가 남아요.","□ = 1 — 1 = ⟨3/4⟩ + ⟨1/4⟩."],"variant_rule":{"alt":[{"stem":"1을 ⟨1/9⟩이 1개인 분수와 ⟨1/9⟩이 □개인 분수로 갈랐어요. □에 알맞은 수를 쓰세요.","answer":["8"],"explanation":["분모가 9이면 1 = ⟨9/9⟩ — ⟨1/9⟩이 9개예요.","9개 중 1개를 떼면 9 − 1 = 8개가 남아요.","□ = 8 — 1 = ⟨1/9⟩ + ⟨8/9⟩."],"asset":null},{"stem":"1을 ⟨1/5⟩이 3개인 분수와 ⟨1/5⟩이 □개인 분수로 갈랐어요. □에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["분모가 5이면 1 = ⟨5/5⟩ — ⟨1/5⟩이 5개예요.","5개 중 3개를 떼면 5 − 3 = 2개가 남아요.","□ = 2 — 1 = ⟨3/5⟩ + ⟨2/5⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_d#3','math',4,2,'u1','','g4_2_math_u1_review_d','unit_review','M4-2-u1-C3',1,'sa','auto','⟨3/7⟩ + ⟨3/7⟩ = ⟨□/7⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-2-u1-C3","difficulty":1,"kind":"sa","stem":"⟨3/7⟩ + ⟨3/7⟩ = ⟨□/7⟩ — □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["분모가 7로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/7⟩이 3 + 3 = 6개.","⟨3/7⟩ + ⟨3/7⟩ = ⟨6/7⟩.","분모끼리 더해 ⟨6/14⟩으로 쓰지 않아요."],"variant_rule":{"alt":[{"stem":"⟨2/5⟩ + ⟨2/5⟩ = ⟨□/5⟩ — □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["분모가 5로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/5⟩이 2 + 2 = 4개.","⟨2/5⟩ + ⟨2/5⟩ = ⟨4/5⟩.","분모끼리 더해 ⟨4/10⟩로 쓰지 않아요."],"asset":null},{"stem":"⟨5/9⟩ + ⟨3/9⟩ = ⟨□/9⟩ — □에 알맞은 수를 쓰세요.","answer":["8"],"explanation":["분모가 9로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/9⟩이 5 + 3 = 8개.","⟨5/9⟩ + ⟨3/9⟩ = ⟨8/9⟩.","분모끼리 더해 ⟨8/18⟩로 쓰지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_d#4','math',4,2,'u1','','g4_2_math_u1_review_d','unit_review','M4-2-u1-C4',1,'sa','auto','1 − ⟨7/9⟩ = ⟨□/9⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-2-u1-C4","difficulty":1,"kind":"sa","stem":"1 − ⟨7/9⟩ = ⟨□/9⟩ — □에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["1을 분모가 9인 분수로 바꾸면 ⟨9/9⟩예요.","⟨9/9⟩ − ⟨7/9⟩ — ⟨1/9⟩이 9 − 7 = 2개.","1 − ⟨7/9⟩ = ⟨2/9⟩."],"variant_rule":{"alt":[{"stem":"1 − ⟨1/8⟩ = ⟨□/8⟩ — □에 알맞은 수를 쓰세요.","answer":["7"],"explanation":["1을 분모가 8인 분수로 바꾸면 ⟨8/8⟩이에요.","⟨8/8⟩ − ⟨1/8⟩ — ⟨1/8⟩이 8 − 1 = 7개.","1 − ⟨1/8⟩ = ⟨7/8⟩."],"asset":null},{"stem":"1 − ⟨3/10⟩ = ⟨□/10⟩ — □에 알맞은 수를 쓰세요.","answer":["7"],"explanation":["1을 분모가 10인 분수로 바꾸면 ⟨10/10⟩이에요.","⟨10/10⟩ − ⟨3/10⟩ — ⟨1/10⟩이 10 − 3 = 7개.","1 − ⟨3/10⟩ = ⟨7/10⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_d#5','math',4,2,'u1','','g4_2_math_u1_review_d','unit_review','M4-2-u1-C5',1,'sa','auto','⟨2 3/8⟩ + ⟨2 3/8⟩을 계산하여 대분수로 나타낼 때, 자연수 부분은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-2-u1-C5","difficulty":1,"kind":"sa","stem":"⟨2 3/8⟩ + ⟨2 3/8⟩을 계산하여 대분수로 나타낼 때, 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["자연수끼리 2 + 2 = 4.","진분수끼리 ⟨3/8⟩ + ⟨3/8⟩ = ⟨6/8⟩.","⟨2 3/8⟩ + ⟨2 3/8⟩ = ⟨4 6/8⟩."],"variant_rule":{"alt":[{"stem":"⟨2 1/9⟩ + ⟨3 1/9⟩을 계산하여 대분수로 나타낼 때, 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["자연수끼리 2 + 3 = 5.","진분수끼리 ⟨1/9⟩ + ⟨1/9⟩ = ⟨2/9⟩.","⟨2 1/9⟩ + ⟨3 1/9⟩ = ⟨5 2/9⟩."],"asset":null},{"stem":"⟨1 1/7⟩ + ⟨4 3/7⟩을 계산하여 대분수로 나타낼 때, 자연수 부분은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["자연수끼리 1 + 4 = 5.","진분수끼리 ⟨1/7⟩ + ⟨3/7⟩ = ⟨4/7⟩.","⟨1 1/7⟩ + ⟨4 3/7⟩ = ⟨5 4/7⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_d#6','math',4,2,'u1','','g4_2_math_u1_review_d','unit_review','M4-2-u1-C6',1,'sa','auto','⟨5 4/6⟩ − ⟨1 3/6⟩ = ⟨4 △/6⟩ — △에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-2-u1-C6","difficulty":1,"kind":"sa","stem":"⟨5 4/6⟩ − ⟨1 3/6⟩ = ⟨4 △/6⟩ — △에 알맞은 수를 쓰세요.","answer":["1"],"explanation":["자연수끼리 5 − 1 = 4.","진분수끼리 ⟨4/6⟩ − ⟨3/6⟩ = ⟨1/6⟩.","⟨5 4/6⟩ − ⟨1 3/6⟩ = ⟨4 1/6⟩."],"variant_rule":{"alt":[{"stem":"⟨5 2/4⟩ − ⟨2 1/4⟩ = ⟨3 △/4⟩ — △에 알맞은 수를 쓰세요.","answer":["1"],"explanation":["자연수끼리 5 − 2 = 3.","진분수끼리 ⟨2/4⟩ − ⟨1/4⟩ = ⟨1/4⟩.","⟨5 2/4⟩ − ⟨2 1/4⟩ = ⟨3 1/4⟩."],"asset":null},{"stem":"⟨5 3/4⟩ − ⟨2 2/4⟩ = ⟨3 △/4⟩ — △에 알맞은 수를 쓰세요.","answer":["1"],"explanation":["자연수끼리 5 − 2 = 3.","진분수끼리 ⟨3/4⟩ − ⟨2/4⟩ = ⟨1/4⟩.","⟨5 3/4⟩ − ⟨2 2/4⟩ = ⟨3 1/4⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_d#7','math',4,2,'u1','','g4_2_math_u1_review_d','unit_review','M4-2-u1-C7',1,'sa','auto','4 − ⟨5/7⟩ = ⟨3 □/7⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-2-u1-C7","difficulty":1,"kind":"sa","stem":"4 − ⟨5/7⟩ = ⟨3 □/7⟩ — □에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["4에서 1만큼을 ⟨7/7⟩로 바꾸어요 — 4 = ⟨3 7/7⟩.","⟨7/7⟩ − ⟨5/7⟩ = ⟨2/7⟩.","4 − ⟨5/7⟩ = ⟨3 2/7⟩ — 자연수 부분은 1 줄어요."],"variant_rule":{"alt":[{"stem":"6 − ⟨1/9⟩ = ⟨5 □/9⟩ — □에 알맞은 수를 쓰세요.","answer":["8"],"explanation":["6에서 1만큼을 ⟨9/9⟩로 바꾸어요 — 6 = ⟨5 9/9⟩.","⟨9/9⟩ − ⟨1/9⟩ = ⟨8/9⟩.","6 − ⟨1/9⟩ = ⟨5 8/9⟩ — 자연수 부분은 1 줄어요."],"asset":null},{"stem":"2 − ⟨3/7⟩ = ⟨1 □/7⟩ — □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["2에서 1만큼을 ⟨7/7⟩로 바꾸어요 — 2 = ⟨1 7/7⟩.","⟨7/7⟩ − ⟨3/7⟩ = ⟨4/7⟩.","2 − ⟨3/7⟩ = ⟨1 4/7⟩ — 자연수 부분은 1 줄어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_d#8','math',4,2,'u1','','g4_2_math_u1_review_d','unit_review','M4-2-u1-C9',1,'sa','auto','⟨5 3/5⟩ − ⟨4 4/5⟩를 1만큼 바꾸어 ⟨4 □/5⟩ − ⟨4 4/5⟩로 계산하려고 해요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-2-u1-C9","difficulty":1,"kind":"sa","stem":"⟨5 3/5⟩ − ⟨4 4/5⟩를 1만큼 바꾸어 ⟨4 □/5⟩ − ⟨4 4/5⟩로 계산하려고 해요. □에 알맞은 수를 쓰세요.","answer":["8"],"explanation":["⟨3/5⟩ − ⟨4/5⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨5 3/5⟩ = ⟨4 8/5⟩.","자연수끼리 4 − 4 = 0, 분수끼리 ⟨8/5⟩ − ⟨4/5⟩ = ⟨4/5⟩ — 답 ⟨4/5⟩."],"variant_rule":{"alt":[{"stem":"⟨4 2/4⟩ − ⟨1 3/4⟩을 1만큼 바꾸어 ⟨3 □/4⟩ − ⟨1 3/4⟩으로 계산하려고 해요. □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["⟨2/4⟩ − ⟨3/4⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨4 2/4⟩ = ⟨3 6/4⟩.","자연수끼리 3 − 1 = 2, 분수끼리 ⟨6/4⟩ − ⟨3/4⟩ = ⟨3/4⟩ — 답 ⟨2 3/4⟩."],"asset":null},{"stem":"⟨2 1/4⟩ − ⟨1 2/4⟩를 1만큼 바꾸어 ⟨1 □/4⟩ − ⟨1 2/4⟩로 계산하려고 해요. □에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["⟨1/4⟩ − ⟨2/4⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨2 1/4⟩ = ⟨1 5/4⟩.","자연수끼리 1 − 1 = 0, 분수끼리 ⟨5/4⟩ − ⟨2/4⟩ = ⟨3/4⟩ — 답 ⟨3/4⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_d#9','math',4,2,'u1','','g4_2_math_u1_review_d','unit_review','M4-2-u1-C1',2,'mc','auto','⟨10/7⟩을 대분수로 나타내면 무엇인가요?',ARRAY['M4-2-u1-X04','M4-2-u1-X16']::text[],true,'{"seq":9,"concept":"M4-2-u1-C1","difficulty":2,"kind":"mc","stem":"⟨10/7⟩을 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨1 3/7⟩","correct":true},{"t":"⟨2 3/7⟩","mis":"M4-2-u1-X04"},{"t":"⟨1 4/7⟩","mis":"M4-2-u1-X16"},{"t":"⟨1 2/7⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨10/7⟩은 ⟨1/7⟩이 10개예요.","⟨1/7⟩이 7개 모이면 1 — 7개씩 모으면 1이 1번, 3개가 남아요.","⟨10/7⟩ = ⟨1 3/7⟩."],"variant_rule":{"alt":[{"stem":"⟨28/9⟩을 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨3 1/9⟩","correct":true},{"t":"⟨4 1/9⟩","mis":"M4-2-u1-X04"},{"t":"⟨2 1/9⟩","mis":"M4-2-u1-X04"},{"t":"⟨3 2/9⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨28/9⟩은 ⟨1/9⟩이 28개예요.","⟨1/9⟩이 9개 모이면 1 — 9개씩 모으면 1이 3번, 1개가 남아요.","⟨28/9⟩ = ⟨3 1/9⟩."],"asset":null},{"stem":"⟨14/8⟩를 대분수로 나타내면 무엇인가요?","options":[{"t":"⟨1 6/8⟩","correct":true},{"t":"⟨2 6/8⟩","mis":"M4-2-u1-X04"},{"t":"⟨1 7/8⟩","mis":"M4-2-u1-X16"},{"t":"⟨1 5/8⟩","mis":"M4-2-u1-X16"}],"explanation":["⟨14/8⟩는 ⟨1/8⟩이 14개예요.","⟨1/8⟩이 8개 모이면 1 — 8개씩 모으면 1이 1번, 6개가 남아요.","⟨14/8⟩ = ⟨1 6/8⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_d#10','math',4,2,'u1','','g4_2_math_u1_review_d','unit_review','M4-2-u1-C3',2,'mc','auto','곰이는 사과를 ⟨4/6⟩ kg, 펭이는 ⟨3/6⟩ kg 땄어요. 두 사람이 딴 사과는 모두 몇 kg인가요?',ARRAY['M4-2-u1-X01','M4-2-u1-X16']::text[],true,'{"seq":10,"concept":"M4-2-u1-C3","difficulty":2,"kind":"mc","stem":"곰이는 사과를 ⟨4/6⟩ kg, 펭이는 ⟨3/6⟩ kg 땄어요. 두 사람이 딴 사과는 모두 몇 kg인가요?","options":[{"t":"⟨1 1/6⟩ kg","correct":true},{"t":"⟨7/12⟩ kg","mis":"M4-2-u1-X01"},{"t":"⟨1 2/6⟩ kg","mis":"M4-2-u1-X16"},{"t":"1 kg","mis":"M4-2-u1-X16"}],"explanation":["분모가 6으로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/6⟩이 4 + 3 = 7개.","⟨4/6⟩ + ⟨3/6⟩ = ⟨7/6⟩.","⟨7/6⟩은 1보다 커요 — ⟨7/6⟩ = ⟨1 1/6⟩."],"variant_rule":{"alt":[{"stem":"빨간 페인트 ⟨5/6⟩ L와 노란 페인트 ⟨3/6⟩ L를 섞었어요. 주황 페인트는 몇 L가 되었나요?","options":[{"t":"⟨1 2/6⟩ L","correct":true},{"t":"⟨8/12⟩ L","mis":"M4-2-u1-X01"},{"t":"⟨1 3/6⟩ L","mis":"M4-2-u1-X16"},{"t":"⟨1 1/6⟩ L","mis":"M4-2-u1-X16"}],"explanation":["분모가 6으로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/6⟩이 5 + 3 = 8개.","⟨5/6⟩ + ⟨3/6⟩ = ⟨8/6⟩.","⟨8/6⟩은 1보다 커요 — ⟨8/6⟩ = ⟨1 2/6⟩."],"asset":null},{"stem":"곰이는 사과를 ⟨4/7⟩ kg, 펭이는 ⟨4/7⟩ kg 땄어요. 두 사람이 딴 사과는 모두 몇 kg인가요?","options":[{"t":"⟨1 1/7⟩ kg","correct":true},{"t":"⟨8/14⟩ kg","mis":"M4-2-u1-X01"},{"t":"⟨1 2/7⟩ kg","mis":"M4-2-u1-X16"},{"t":"1 kg","mis":"M4-2-u1-X16"}],"explanation":["분모가 7로 같으니 분모는 그대로 두고 분자끼리 더해요 — ⟨1/7⟩이 4 + 4 = 8개.","⟨4/7⟩ + ⟨4/7⟩ = ⟨8/7⟩.","⟨8/7⟩은 1보다 커요 — ⟨8/7⟩ = ⟨1 1/7⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_d#11','math',4,2,'u1','','g4_2_math_u1_review_d','unit_review','M4-2-u1-C4',2,'mc','auto','1 − ⟨6/7⟩을 계산하면 얼마인가요?',ARRAY['M4-2-u1-X08','M4-2-u1-X16','M4-2-u1-X15']::text[],true,'{"seq":11,"concept":"M4-2-u1-C4","difficulty":2,"kind":"mc","stem":"1 − ⟨6/7⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1/7⟩","correct":true},{"t":"⟨5/7⟩","mis":"M4-2-u1-X08"},{"t":"⟨2/7⟩","mis":"M4-2-u1-X16"},{"t":"⟨6/7⟩","mis":"M4-2-u1-X15"}],"explanation":["1을 분모가 7인 분수로 바꾸면 ⟨7/7⟩이에요.","⟨7/7⟩ − ⟨6/7⟩ — ⟨1/7⟩이 7 − 6 = 1개.","1 − ⟨6/7⟩ = ⟨1/7⟩."],"variant_rule":{"alt":[{"stem":"1 − ⟨4/6⟩를 계산하면 얼마인가요?","options":[{"t":"⟨2/6⟩","correct":true},{"t":"⟨3/6⟩","mis":"M4-2-u1-X08"},{"t":"⟨1/6⟩","mis":"M4-2-u1-X16"},{"t":"⟨4/6⟩","mis":"M4-2-u1-X15"}],"explanation":["1을 분모가 6인 분수로 바꾸면 ⟨6/6⟩이에요.","⟨6/6⟩ − ⟨4/6⟩ — ⟨1/6⟩이 6 − 4 = 2개.","1 − ⟨4/6⟩ = ⟨2/6⟩."],"asset":null},{"stem":"1 − ⟨1/9⟩을 계산하면 얼마인가요?","options":[{"t":"⟨8/9⟩","correct":true},{"t":"⟨7/9⟩","mis":"M4-2-u1-X16"},{"t":"⟨1/9⟩","mis":"M4-2-u1-X15"},{"t":"⟨1 1/9⟩","mis":"M4-2-u1-X14"}],"explanation":["1을 분모가 9인 분수로 바꾸면 ⟨9/9⟩예요.","⟨9/9⟩ − ⟨1/9⟩ — ⟨1/9⟩이 9 − 1 = 8개.","1 − ⟨1/9⟩ = ⟨8/9⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_d#12','math',4,2,'u1','','g4_2_math_u1_review_d','unit_review','M4-2-u1-C5',2,'mc','auto','⟨4 2/4⟩ + ⟨3 3/4⟩을 계산하면 얼마인가요?',ARRAY['M4-2-u1-X07','M4-2-u1-X01','M4-2-u1-X13']::text[],true,'{"seq":12,"concept":"M4-2-u1-C5","difficulty":2,"kind":"mc","stem":"⟨4 2/4⟩ + ⟨3 3/4⟩을 계산하면 얼마인가요?","options":[{"t":"⟨8 1/4⟩","correct":true},{"t":"⟨7 1/4⟩","mis":"M4-2-u1-X07"},{"t":"⟨7 5/8⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 1/4⟩","mis":"M4-2-u1-X13"}],"explanation":["자연수끼리 4 + 3 = 7.","진분수끼리 ⟨2/4⟩ + ⟨3/4⟩ = ⟨5/4⟩ — 1보다 커서 ⟨1 1/4⟩, 1을 자연수로 넘겨요.","⟨4 2/4⟩ + ⟨3 3/4⟩ = ⟨8 1/4⟩."],"variant_rule":{"alt":[{"stem":"⟨3 2/8⟩ + ⟨3 7/8⟩을 계산하면 얼마인가요?","options":[{"t":"⟨7 1/8⟩","correct":true},{"t":"⟨6 1/8⟩","mis":"M4-2-u1-X07"},{"t":"⟨6 9/16⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 1/8⟩","mis":"M4-2-u1-X13"}],"explanation":["자연수끼리 3 + 3 = 6.","진분수끼리 ⟨2/8⟩ + ⟨7/8⟩ = ⟨9/8⟩ — 1보다 커서 ⟨1 1/8⟩, 1을 자연수로 넘겨요.","⟨3 2/8⟩ + ⟨3 7/8⟩ = ⟨7 1/8⟩."],"asset":null},{"stem":"⟨4 6/7⟩ + ⟨1 4/7⟩를 계산하면 얼마인가요?","options":[{"t":"⟨6 3/7⟩","correct":true},{"t":"⟨5 3/7⟩","mis":"M4-2-u1-X07"},{"t":"⟨5 10/14⟩","mis":"M4-2-u1-X01"},{"t":"⟨1 3/7⟩","mis":"M4-2-u1-X13"}],"explanation":["자연수끼리 4 + 1 = 5.","진분수끼리 ⟨6/7⟩ + ⟨4/7⟩ = ⟨10/7⟩ — 1보다 커서 ⟨1 3/7⟩, 1을 자연수로 넘겨요.","⟨4 6/7⟩ + ⟨1 4/7⟩ = ⟨6 3/7⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_d#13','math',4,2,'u1','','g4_2_math_u1_review_d','unit_review','M4-2-u1-C6',2,'mc','auto','드론 약품 통에 약품이 ⟨4 2/3⟩ L 있었어요. 밭에 ⟨1 1/3⟩ L를 뿌렸다면 남은 약품은 몇 L인가요?',ARRAY['M4-2-u1-X13','M4-2-u1-X14','M4-2-u1-X01']::text[],true,'{"seq":13,"concept":"M4-2-u1-C6","difficulty":2,"kind":"mc","stem":"드론 약품 통에 약품이 ⟨4 2/3⟩ L 있었어요. 밭에 ⟨1 1/3⟩ L를 뿌렸다면 남은 약품은 몇 L인가요?","options":[{"t":"⟨3 1/3⟩ L","correct":true},{"t":"⟨1/3⟩ L","mis":"M4-2-u1-X13"},{"t":"6 L","mis":"M4-2-u1-X14"},{"t":"⟨3 1/2⟩ L","mis":"M4-2-u1-X01"}],"explanation":["자연수끼리 4 − 1 = 3.","진분수끼리 ⟨2/3⟩ − ⟨1/3⟩ = ⟨1/3⟩.","⟨4 2/3⟩ − ⟨1 1/3⟩ = ⟨3 1/3⟩."],"variant_rule":{"alt":[{"stem":"드론 약품 통에 약품이 ⟨4 2/8⟩ L 있었어요. 밭에 ⟨3 1/8⟩ L를 뿌렸다면 남은 약품은 몇 L인가요?","options":[{"t":"⟨1 1/8⟩ L","correct":true},{"t":"⟨1/8⟩ L","mis":"M4-2-u1-X13"},{"t":"⟨7 3/8⟩ L","mis":"M4-2-u1-X14"},{"t":"⟨1 1/7⟩ L","mis":"M4-2-u1-X01"}],"explanation":["자연수끼리 4 − 3 = 1.","진분수끼리 ⟨2/8⟩ − ⟨1/8⟩ = ⟨1/8⟩.","⟨4 2/8⟩ − ⟨3 1/8⟩ = ⟨1 1/8⟩."],"asset":null},{"stem":"드론 약품 통에 약품이 ⟨6 4/9⟩ L 있었어요. 밭에 ⟨1 2/9⟩ L를 뿌렸다면 남은 약품은 몇 L인가요?","options":[{"t":"⟨5 2/9⟩ L","correct":true},{"t":"⟨2/9⟩ L","mis":"M4-2-u1-X13"},{"t":"⟨7 6/9⟩ L","mis":"M4-2-u1-X14"},{"t":"⟨5 2/7⟩ L","mis":"M4-2-u1-X01"}],"explanation":["자연수끼리 6 − 1 = 5.","진분수끼리 ⟨4/9⟩ − ⟨2/9⟩ = ⟨2/9⟩.","⟨6 4/9⟩ − ⟨1 2/9⟩ = ⟨5 2/9⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_d#14','math',4,2,'u1','','g4_2_math_u1_review_d','unit_review','M4-2-u1-C7',2,'mc','auto','6 − ⟨4/6⟩를 계산하면 얼마인가요?',ARRAY['M4-2-u1-X09','M4-2-u1-X10','M4-2-u1-X16']::text[],true,'{"seq":14,"concept":"M4-2-u1-C7","difficulty":2,"kind":"mc","stem":"6 − ⟨4/6⟩를 계산하면 얼마인가요?","options":[{"t":"⟨5 2/6⟩","correct":true},{"t":"⟨6 2/6⟩","mis":"M4-2-u1-X09"},{"t":"⟨5 4/6⟩","mis":"M4-2-u1-X10"},{"t":"⟨5 3/6⟩","mis":"M4-2-u1-X16"}],"explanation":["6에서 1만큼을 ⟨6/6⟩으로 바꾸어요 — 6 = ⟨5 6/6⟩.","⟨6/6⟩ − ⟨4/6⟩ = ⟨2/6⟩.","6 − ⟨4/6⟩ = ⟨5 2/6⟩ — 자연수 부분은 1 줄어요."],"variant_rule":{"alt":[{"stem":"5 − ⟨5/10⟩를 계산하면 얼마인가요?","options":[{"t":"⟨4 5/10⟩","correct":true},{"t":"⟨5 5/10⟩","mis":"M4-2-u1-X09"},{"t":"⟨4 6/10⟩","mis":"M4-2-u1-X16"},{"t":"⟨4 4/10⟩","mis":"M4-2-u1-X16"}],"explanation":["5에서 1만큼을 ⟨10/10⟩으로 바꾸어요 — 5 = ⟨4 10/10⟩.","⟨10/10⟩ − ⟨5/10⟩ = ⟨5/10⟩.","5 − ⟨5/10⟩ = ⟨4 5/10⟩ — 자연수 부분은 1 줄어요."],"asset":null},{"stem":"3 − ⟨1/6⟩을 계산하면 얼마인가요?","options":[{"t":"⟨2 5/6⟩","correct":true},{"t":"⟨3 5/6⟩","mis":"M4-2-u1-X09"},{"t":"⟨2 1/6⟩","mis":"M4-2-u1-X10"},{"t":"⟨2 4/6⟩","mis":"M4-2-u1-X16"}],"explanation":["3에서 1만큼을 ⟨6/6⟩으로 바꾸어요 — 3 = ⟨2 6/6⟩.","⟨6/6⟩ − ⟨1/6⟩ = ⟨5/6⟩.","3 − ⟨1/6⟩ = ⟨2 5/6⟩ — 자연수 부분은 1 줄어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_d#15','math',4,2,'u1','','g4_2_math_u1_review_d','unit_review','M4-2-u1-C8',2,'mc','auto','⟨3 4/9⟩ − ⟨6/9⟩을 계산하면 얼마인가요?',ARRAY['M4-2-u1-X11','M4-2-u1-X09','M4-2-u1-X12']::text[],true,'{"seq":15,"concept":"M4-2-u1-C8","difficulty":2,"kind":"mc","stem":"⟨3 4/9⟩ − ⟨6/9⟩을 계산하면 얼마인가요?","options":[{"t":"⟨2 7/9⟩","correct":true},{"t":"⟨3 2/9⟩","mis":"M4-2-u1-X11"},{"t":"⟨3 7/9⟩","mis":"M4-2-u1-X09"},{"t":"⟨2 8/9⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨4/9⟩ − ⟨6/9⟩ — 진분수끼리 뺄 수 없어요(4 < 6).","1만큼 바꾸어요 — ⟨3 4/9⟩ = ⟨2 13/9⟩.","⟨2 13/9⟩ − ⟨6/9⟩ = ⟨2 7/9⟩ — 자연수 부분은 1 줄어요."],"variant_rule":{"alt":[{"stem":"⟨2 5/9⟩ − ⟨7/9⟩을 계산하면 얼마인가요?","options":[{"t":"⟨1 7/9⟩","correct":true},{"t":"⟨2 2/9⟩","mis":"M4-2-u1-X11"},{"t":"⟨2 7/9⟩","mis":"M4-2-u1-X09"},{"t":"⟨1 8/9⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨5/9⟩ − ⟨7/9⟩ — 진분수끼리 뺄 수 없어요(5 < 7).","1만큼 바꾸어요 — ⟨2 5/9⟩ = ⟨1 14/9⟩.","⟨1 14/9⟩ − ⟨7/9⟩ = ⟨1 7/9⟩ — 자연수 부분은 1 줄어요."],"asset":null},{"stem":"⟨5 5/8⟩ − ⟨6/8⟩을 계산하면 얼마인가요?","options":[{"t":"⟨4 7/8⟩","correct":true},{"t":"⟨5 1/8⟩","mis":"M4-2-u1-X11"},{"t":"⟨5 7/8⟩","mis":"M4-2-u1-X09"},{"t":"⟨4 9/8⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨5/8⟩ − ⟨6/8⟩ — 진분수끼리 뺄 수 없어요(5 < 6).","1만큼 바꾸어요 — ⟨5 5/8⟩ = ⟨4 13/8⟩.","⟨4 13/8⟩ − ⟨6/8⟩ = ⟨4 7/8⟩ — 자연수 부분은 1 줄어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_d#16','math',4,2,'u1','','g4_2_math_u1_review_d','unit_review','M4-2-u1-C9',2,'mc','auto','⟨2 5/7⟩ − ⟨1 6/7⟩을 계산하면 얼마인가요?',ARRAY['M4-2-u1-X11','M4-2-u1-X09','M4-2-u1-X12']::text[],true,'{"seq":16,"concept":"M4-2-u1-C9","difficulty":2,"kind":"mc","stem":"⟨2 5/7⟩ − ⟨1 6/7⟩을 계산하면 얼마인가요?","options":[{"t":"⟨6/7⟩","correct":true},{"t":"⟨1 1/7⟩","mis":"M4-2-u1-X11"},{"t":"⟨1 6/7⟩","mis":"M4-2-u1-X09"},{"t":"⟨9/7⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨5/7⟩ − ⟨6/7⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨2 5/7⟩ = ⟨1 12/7⟩.","자연수끼리 1 − 1 = 0, 분수끼리 ⟨12/7⟩ − ⟨6/7⟩ = ⟨6/7⟩ — 답 ⟨6/7⟩."],"variant_rule":{"alt":[{"stem":"⟨7 2/5⟩ − ⟨4 3/5⟩을 계산하면 얼마인가요?","options":[{"t":"⟨2 4/5⟩","correct":true},{"t":"⟨3 1/5⟩","mis":"M4-2-u1-X11"},{"t":"⟨3 4/5⟩","mis":"M4-2-u1-X09"},{"t":"⟨2 9/5⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨2/5⟩ − ⟨3/5⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨7 2/5⟩ = ⟨6 7/5⟩.","자연수끼리 6 − 4 = 2, 분수끼리 ⟨7/5⟩ − ⟨3/5⟩ = ⟨4/5⟩ — 답 ⟨2 4/5⟩."],"asset":null},{"stem":"⟨4 6/9⟩ − ⟨3 8/9⟩을 계산하면 얼마인가요?","options":[{"t":"⟨7/9⟩","correct":true},{"t":"⟨1 2/9⟩","mis":"M4-2-u1-X11"},{"t":"⟨1 7/9⟩","mis":"M4-2-u1-X09"},{"t":"⟨8/9⟩","mis":"M4-2-u1-X12"}],"explanation":["⟨6/9⟩ − ⟨8/9⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨4 6/9⟩ = ⟨3 15/9⟩.","자연수끼리 3 − 3 = 0, 분수끼리 ⟨15/9⟩ − ⟨8/9⟩ = ⟨7/9⟩ — 답 ⟨7/9⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_d#17','math',4,2,'u1','','g4_2_math_u1_review_d','unit_review','M4-2-u1-C2',3,'mc','auto','⟨6/10⟩과 모아서 1이 되는 분수는 무엇인가요?',ARRAY['M4-2-u1-X06','M4-2-u1-X16']::text[],true,'{"seq":17,"concept":"M4-2-u1-C2","difficulty":3,"kind":"mc","stem":"⟨6/10⟩과 모아서 1이 되는 분수는 무엇인가요?","options":[{"t":"⟨4/10⟩","correct":true},{"t":"⟨6/10⟩","mis":"M4-2-u1-X06"},{"t":"⟨10/6⟩","mis":"M4-2-u1-X06"},{"t":"⟨5/10⟩","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨10/10⟩ — ⟨1/10⟩이 10개예요.","⟨6/10⟩은 ⟨1/10⟩이 6개 — 4개가 모자라요.","⟨6/10⟩과 ⟨4/10⟩를 모으면 1이에요."],"variant_rule":{"alt":[{"stem":"⟨2/9⟩와 모아서 1이 되는 분수는 무엇인가요?","options":[{"t":"⟨7/9⟩","correct":true},{"t":"⟨2/9⟩","mis":"M4-2-u1-X06"},{"t":"⟨9/2⟩","mis":"M4-2-u1-X06"},{"t":"⟨8/9⟩","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨9/9⟩ — ⟨1/9⟩이 9개예요.","⟨2/9⟩는 ⟨1/9⟩이 2개 — 7개가 모자라요.","⟨2/9⟩와 ⟨7/9⟩을 모으면 1이에요."],"asset":null},{"stem":"⟨4/6⟩와 모아서 1이 되는 분수는 무엇인가요?","options":[{"t":"⟨2/6⟩","correct":true},{"t":"⟨4/6⟩","mis":"M4-2-u1-X06"},{"t":"⟨6/4⟩","mis":"M4-2-u1-X06"},{"t":"⟨3/6⟩","mis":"M4-2-u1-X16"}],"explanation":["1 = ⟨6/6⟩ — ⟨1/6⟩이 6개예요.","⟨4/6⟩는 ⟨1/6⟩이 4개 — 2개가 모자라요.","⟨4/6⟩와 ⟨2/6⟩를 모으면 1이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_d#18','math',4,2,'u1','','g4_2_math_u1_review_d','unit_review','M4-2-u1-C3',3,'sa','auto','⟨7/9⟩ + ⟨□/9⟩ = ⟨1 1/9⟩ — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M4-2-u1-C3","difficulty":3,"kind":"sa","stem":"⟨7/9⟩ + ⟨□/9⟩ = ⟨1 1/9⟩ — □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["⟨1 1/9⟩을 가분수로 — ⟨10/9⟩.","⟨1/9⟩이 10개가 되려면 7개에서 3개를 더 모아야 해요.","□ = 10 − 7 = 3."],"variant_rule":{"alt":[{"stem":"⟨8/11⟩ + ⟨□/11⟩ = ⟨1 7/11⟩ — □에 알맞은 수를 쓰세요.","answer":["10"],"explanation":["⟨1 7/11⟩을 가분수로 — ⟨18/11⟩.","⟨1/11⟩이 18개가 되려면 8개에서 10개를 더 모아야 해요.","□ = 18 − 8 = 10."],"asset":null},{"stem":"⟨6/12⟩ + ⟨□/12⟩ = ⟨1 4/12⟩ — □에 알맞은 수를 쓰세요.","answer":["10"],"explanation":["⟨1 4/12⟩를 가분수로 — ⟨16/12⟩.","⟨1/12⟩이 16개가 되려면 6개에서 10개를 더 모아야 해요.","□ = 16 − 6 = 10."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_d#19','math',4,2,'u1','','g4_2_math_u1_review_d','unit_review','M4-2-u1-C5',3,'sa','auto','⟨3 7/9⟩ + ⟨1 6/9⟩을 가분수로 바꾸어 계산하면 ⟨□/9⟩ + ⟨△/9⟩ = ⟨○/9⟩이에요. ○에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M4-2-u1-C5","difficulty":3,"kind":"sa","stem":"⟨3 7/9⟩ + ⟨1 6/9⟩을 가분수로 바꾸어 계산하면 ⟨□/9⟩ + ⟨△/9⟩ = ⟨○/9⟩이에요. ○에 알맞은 수를 쓰세요.","answer":["49"],"explanation":["⟨3 7/9⟩ = ⟨34/9⟩, ⟨1 6/9⟩ = ⟨15/9⟩.","⟨34/9⟩ + ⟨15/9⟩ = ⟨49/9⟩.","○ = 49 — 대분수로 ⟨5 4/9⟩."],"variant_rule":{"alt":[{"stem":"⟨1 4/6⟩ + ⟨3 3/6⟩을 가분수로 바꾸어 계산하면 ⟨□/6⟩ + ⟨△/6⟩ = ⟨○/6⟩이에요. ○에 알맞은 수를 쓰세요.","answer":["31"],"explanation":["⟨1 4/6⟩ = ⟨10/6⟩, ⟨3 3/6⟩ = ⟨21/6⟩.","⟨10/6⟩ + ⟨21/6⟩ = ⟨31/6⟩.","○ = 31 — 대분수로 ⟨5 1/6⟩."],"asset":null},{"stem":"⟨2 5/7⟩ + ⟨1 6/7⟩을 가분수로 바꾸어 계산하면 ⟨□/7⟩ + ⟨△/7⟩ = ⟨○/7⟩이에요. ○에 알맞은 수를 쓰세요.","answer":["32"],"explanation":["⟨2 5/7⟩ = ⟨19/7⟩, ⟨1 6/7⟩ = ⟨13/7⟩.","⟨19/7⟩ + ⟨13/7⟩ = ⟨32/7⟩.","○ = 32 — 대분수로 ⟨4 4/7⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_d#20','math',4,2,'u1','','g4_2_math_u1_review_d','unit_review','M4-2-u1-C7',3,'mc','auto','두부를 만들려고 콩 4 kg 가운데 ⟨1 2/5⟩ kg을 물에 불렸어요. 불리지 않고 남은 콩은 몇 kg인가요?',ARRAY['M4-2-u1-X09','M4-2-u1-X10','M4-2-u1-X16']::text[],true,'{"seq":20,"concept":"M4-2-u1-C7","difficulty":3,"kind":"mc","stem":"두부를 만들려고 콩 4 kg 가운데 ⟨1 2/5⟩ kg을 물에 불렸어요. 불리지 않고 남은 콩은 몇 kg인가요?","options":[{"t":"⟨2 3/5⟩ kg","correct":true},{"t":"⟨3 3/5⟩ kg","mis":"M4-2-u1-X09"},{"t":"⟨2 2/5⟩ kg","mis":"M4-2-u1-X10"},{"t":"⟨2 4/5⟩ kg","mis":"M4-2-u1-X16"}],"explanation":["4 = ⟨3 5/5⟩로 바꾸어요.","⟨3 5/5⟩ − ⟨1 2/5⟩ = ⟨2 3/5⟩.","남은 콩은 ⟨2 3/5⟩ kg이에요."],"variant_rule":{"alt":[{"stem":"두부를 만들려고 콩 2 kg 가운데 ⟨1 5/8⟩ kg을 물에 불렸어요. 불리지 않고 남은 콩은 몇 kg인가요?","options":[{"t":"⟨3/8⟩ kg","correct":true},{"t":"⟨1 3/8⟩ kg","mis":"M4-2-u1-X09"},{"t":"⟨5/8⟩ kg","mis":"M4-2-u1-X10"},{"t":"⟨4/8⟩ kg","mis":"M4-2-u1-X16"}],"explanation":["2 = ⟨1 8/8⟩로 바꾸어요.","⟨1 8/8⟩ − ⟨1 5/8⟩ = ⟨3/8⟩.","남은 콩은 ⟨3/8⟩ kg이에요."],"asset":null},{"stem":"두부를 만들려고 콩 6 kg 가운데 ⟨5 7/8⟩ kg을 물에 불렸어요. 불리지 않고 남은 콩은 몇 kg인가요?","options":[{"t":"⟨1/8⟩ kg","correct":true},{"t":"⟨1 1/8⟩ kg","mis":"M4-2-u1-X09"},{"t":"⟨7/8⟩ kg","mis":"M4-2-u1-X10"},{"t":"⟨2/8⟩ kg","mis":"M4-2-u1-X16"}],"explanation":["6 = ⟨5 8/8⟩로 바꾸어요.","⟨5 8/8⟩ − ⟨5 7/8⟩ = ⟨1/8⟩.","남은 콩은 ⟨1/8⟩ kg이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_d#21','math',4,2,'u1','','g4_2_math_u1_review_d','unit_review','M4-2-u1-C9',3,'mc','auto','곰이는 자전거로 ⟨5 1/9⟩ km, 펭이는 ⟨4 6/9⟩ km를 달렸어요. 곰이는 펭이보다 몇 km 더 달렸나요?',ARRAY['M4-2-u1-X11','M4-2-u1-X09','M4-2-u1-X12']::text[],true,'{"seq":21,"concept":"M4-2-u1-C9","difficulty":3,"kind":"mc","stem":"곰이는 자전거로 ⟨5 1/9⟩ km, 펭이는 ⟨4 6/9⟩ km를 달렸어요. 곰이는 펭이보다 몇 km 더 달렸나요?","options":[{"t":"⟨4/9⟩ km","correct":true},{"t":"⟨1 5/9⟩ km","mis":"M4-2-u1-X11"},{"t":"⟨1 4/9⟩ km","mis":"M4-2-u1-X09"},{"t":"⟨5/9⟩ km","mis":"M4-2-u1-X12"}],"explanation":["⟨1/9⟩ − ⟨6/9⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨5 1/9⟩ = ⟨4 10/9⟩.","자연수끼리 4 − 4 = 0, 분수끼리 ⟨10/9⟩ − ⟨6/9⟩ = ⟨4/9⟩ — 답 ⟨4/9⟩."],"variant_rule":{"alt":[{"stem":"곰이는 자전거로 ⟨4 1/5⟩ km, 펭이는 ⟨3 3/5⟩ km를 달렸어요. 곰이는 펭이보다 몇 km 더 달렸나요?","options":[{"t":"⟨3/5⟩ km","correct":true},{"t":"⟨1 2/5⟩ km","mis":"M4-2-u1-X11"},{"t":"⟨1 3/5⟩ km","mis":"M4-2-u1-X09"},{"t":"⟨8/5⟩ km","mis":"M4-2-u1-X12"}],"explanation":["⟨1/5⟩ − ⟨3/5⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨4 1/5⟩ = ⟨3 6/5⟩.","자연수끼리 3 − 3 = 0, 분수끼리 ⟨6/5⟩ − ⟨3/5⟩ = ⟨3/5⟩ — 답 ⟨3/5⟩."],"asset":null},{"stem":"곰이는 자전거로 ⟨5 3/5⟩ km, 펭이는 ⟨4 4/5⟩ km를 달렸어요. 곰이는 펭이보다 몇 km 더 달렸나요?","options":[{"t":"⟨4/5⟩ km","correct":true},{"t":"⟨1 1/5⟩ km","mis":"M4-2-u1-X11"},{"t":"⟨1 4/5⟩ km","mis":"M4-2-u1-X09"},{"t":"⟨9/5⟩ km","mis":"M4-2-u1-X12"}],"explanation":["⟨3/5⟩ − ⟨4/5⟩ — 진분수끼리 뺄 수 없어요.","1만큼 바꾸어요 — ⟨5 3/5⟩ = ⟨4 8/5⟩.","자연수끼리 4 − 4 = 0, 분수끼리 ⟨8/5⟩ − ⟨4/5⟩ = ⟨4/5⟩ — 답 ⟨4/5⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_d#22','math',4,2,'u1','','g4_2_math_u1_review_d','unit_review','M4-2-u1-C10',3,'mc','auto','분수 카드 ⟨2 7/8⟩, ⟨2 6/8⟩, ⟨2 5/8⟩, ⟨2 2/8⟩ 중 두 장을 골라 합이 ⟨5 3/8⟩이 되게 하려고 해요. 어떤 두 장을 골라야 하나요?',ARRAY['M4-2-u1-X17']::text[],true,'{"seq":22,"concept":"M4-2-u1-C10","difficulty":3,"kind":"mc","stem":"분수 카드 ⟨2 7/8⟩, ⟨2 6/8⟩, ⟨2 5/8⟩, ⟨2 2/8⟩ 중 두 장을 골라 합이 ⟨5 3/8⟩이 되게 하려고 해요. 어떤 두 장을 골라야 하나요?","options":[{"t":"⟨2 6/8⟩, ⟨2 5/8⟩","correct":true},{"t":"⟨2 7/8⟩, ⟨2 6/8⟩","mis":"M4-2-u1-X17"},{"t":"⟨2 5/8⟩, ⟨2 2/8⟩","mis":"M4-2-u1-X17"},{"t":"⟨2 7/8⟩, ⟨2 2/8⟩","mis":"M4-2-u1-X17"}],"explanation":["어림해요 — 자연수 부분을 먼저 맞추어 보아요.","⟨2 6/8⟩ + ⟨2 5/8⟩ = ⟨5 3/8⟩.","⟨2 6/8⟩, ⟨2 5/8⟩를 골라요."],"variant_rule":{"alt":[{"stem":"분수 카드 ⟨3 1/5⟩, ⟨2 2/5⟩, ⟨3 2/5⟩, ⟨1 1/5⟩ 중 두 장을 골라 합이 ⟨5 3/5⟩이 되게 하려고 해요. 어떤 두 장을 골라야 하나요?","options":[{"t":"⟨3 1/5⟩, ⟨2 2/5⟩","correct":true},{"t":"⟨3 1/5⟩, ⟨1 1/5⟩","mis":"M4-2-u1-X17"},{"t":"⟨2 2/5⟩, ⟨3 2/5⟩","mis":"M4-2-u1-X17"},{"t":"⟨3 1/5⟩, ⟨3 2/5⟩","mis":"M4-2-u1-X17"}],"explanation":["어림해요 — 자연수 부분을 먼저 맞추어 보아요.","⟨3 1/5⟩ + ⟨2 2/5⟩ = ⟨5 3/5⟩.","⟨3 1/5⟩, ⟨2 2/5⟩를 골라요."],"asset":null},{"stem":"분수 카드 ⟨2 3/5⟩, ⟨3 3/5⟩, ⟨1 1/5⟩, ⟨2 1/5⟩ 중 두 장을 골라 합이 ⟨5 4/5⟩가 되게 하려고 해요. 어떤 두 장을 골라야 하나요?","options":[{"t":"⟨3 3/5⟩, ⟨2 1/5⟩","correct":true},{"t":"⟨1 1/5⟩, ⟨2 1/5⟩","mis":"M4-2-u1-X17"},{"t":"⟨3 3/5⟩, ⟨1 1/5⟩","mis":"M4-2-u1-X17"},{"t":"⟨2 3/5⟩, ⟨1 1/5⟩","mis":"M4-2-u1-X17"}],"explanation":["어림해요 — 자연수 부분을 먼저 맞추어 보아요.","⟨3 3/5⟩ + ⟨2 1/5⟩ = ⟨5 4/5⟩.","⟨3 3/5⟩, ⟨2 1/5⟩을 골라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_d#23','math',4,2,'u1','','g4_2_math_u1_review_d','unit_review','M4-2-u1-C9',4,'mc','auto','□ − ⟨4 5/6⟩ = ⟨2 5/6⟩일 때, □에 알맞은 대분수는 무엇인가요?',ARRAY['M4-2-u1-X16','M4-2-u1-X09']::text[],true,'{"seq":23,"concept":"M4-2-u1-C9","difficulty":4,"kind":"mc","stem":"□ − ⟨4 5/6⟩ = ⟨2 5/6⟩일 때, □에 알맞은 대분수는 무엇인가요?","options":[{"t":"⟨7 4/6⟩","correct":true},{"t":"⟨7 5/6⟩","mis":"M4-2-u1-X16"},{"t":"⟨7 3/6⟩","mis":"M4-2-u1-X16"},{"t":"⟨6 4/6⟩","mis":"M4-2-u1-X09"}],"explanation":["□에서 ⟨4 5/6⟩를 덜어 ⟨2 5/6⟩가 남았어요.","덧셈으로 되돌려요 — □ = ⟨2 5/6⟩ + ⟨4 5/6⟩.","□ = ⟨7 4/6⟩."],"variant_rule":{"alt":[{"stem":"□ − ⟨1 10/11⟩ = ⟨3/11⟩일 때, □에 알맞은 대분수는 무엇인가요?","options":[{"t":"⟨2 2/11⟩","correct":true},{"t":"⟨2 3/11⟩","mis":"M4-2-u1-X16"},{"t":"⟨2 1/11⟩","mis":"M4-2-u1-X16"},{"t":"⟨1 2/11⟩","mis":"M4-2-u1-X09"}],"explanation":["□에서 ⟨1 10/11⟩을 덜어 ⟨3/11⟩이 남았어요.","덧셈으로 되돌려요 — □ = ⟨3/11⟩ + ⟨1 10/11⟩.","□ = ⟨2 2/11⟩."],"asset":null},{"stem":"□ − ⟨2 7/12⟩ = ⟨2 11/12⟩일 때, □에 알맞은 대분수는 무엇인가요?","options":[{"t":"⟨5 6/12⟩","correct":true},{"t":"⟨4/12⟩","mis":"M4-2-u1-X14"},{"t":"⟨5 7/12⟩","mis":"M4-2-u1-X16"},{"t":"⟨5 5/12⟩","mis":"M4-2-u1-X16"}],"explanation":["□에서 ⟨2 7/12⟩을 덜어 ⟨2 11/12⟩이 남았어요.","덧셈으로 되돌려요 — □ = ⟨2 11/12⟩ + ⟨2 7/12⟩.","□ = ⟨5 6/12⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_d#24','math',4,2,'u1','','g4_2_math_u1_review_d','unit_review','M4-2-u1-C10',4,'mc','auto','수 카드 3, 5, 4 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 7인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 합은 얼마인가요?',ARRAY['M4-2-u1-X16','M4-2-u1-X14']::text[],true,'{"seq":24,"concept":"M4-2-u1-C10","difficulty":4,"kind":"mc","stem":"수 카드 3, 5, 4 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 7인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 합은 얼마인가요?","options":[{"t":"⟨9 1/7⟩","correct":true},{"t":"⟨9 2/7⟩","mis":"M4-2-u1-X16"},{"t":"9","mis":"M4-2-u1-X16"},{"t":"2","mis":"M4-2-u1-X14"}],"explanation":["가장 큰 대분수 — 자연수 부분에 가장 큰 수 5, 분자에 다음 큰 수 4 → ⟨5 4/7⟩.","가장 작은 대분수 — 자연수 부분에 가장 작은 수 3, 분자에 4 → ⟨3 4/7⟩.","⟨5 4/7⟩ + ⟨3 4/7⟩ = ⟨9 1/7⟩."],"variant_rule":{"alt":[{"stem":"수 카드 2, 1, 5 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 8인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 합은 얼마인가요?","options":[{"t":"⟨6 4/8⟩","correct":true},{"t":"⟨6 6/8⟩","mis":"M4-2-u1-X17"},{"t":"⟨6 5/8⟩","mis":"M4-2-u1-X16"},{"t":"⟨6 3/8⟩","mis":"M4-2-u1-X16"}],"explanation":["가장 큰 대분수 — 자연수 부분에 가장 큰 수 5, 분자에 다음 큰 수 2 → ⟨5 2/8⟩.","가장 작은 대분수 — 자연수 부분에 가장 작은 수 1, 분자에 2 → ⟨1 2/8⟩.","⟨5 2/8⟩ + ⟨1 2/8⟩ = ⟨6 4/8⟩."],"asset":null},{"stem":"수 카드 4, 6, 7 중 두 장을 골라 자연수 부분과 분자에 한 장씩 놓아 분모가 8인 대분수를 만들려고 해요. 만들 수 있는 가장 큰 대분수와 가장 작은 대분수의 합은 얼마인가요?","options":[{"t":"⟨12 4/8⟩","correct":true},{"t":"⟨12 3/8⟩","mis":"M4-2-u1-X17"},{"t":"⟨12 5/8⟩","mis":"M4-2-u1-X16"},{"t":"3","mis":"M4-2-u1-X14"}],"explanation":["가장 큰 대분수 — 자연수 부분에 가장 큰 수 7, 분자에 다음 큰 수 6 → ⟨7 6/8⟩.","가장 작은 대분수 — 자연수 부분에 가장 작은 수 4, 분자에 6 → ⟨4 6/8⟩.","⟨7 6/8⟩ + ⟨4 6/8⟩ = ⟨12 4/8⟩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_math_u1_review_d#25','math',4,2,'u1','','g4_2_math_u1_review_d','unit_review','M4-2-u1-C3',4,'essay','teacher','곰이와 펭이가 사과를 각각 ⟨5/8⟩ kg, ⟨7/8⟩ kg 땄어요. 두 사람이 딴 사과는 모두 몇 kg인지, 곰이는 펭이보다 몇 kg 덜 땄는지 각각 구하고 어떤 셈을 골랐는지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-2-u1-C3","difficulty":4,"kind":"essay","stem":"곰이와 펭이가 사과를 각각 ⟨5/8⟩ kg, ⟨7/8⟩ kg 땄어요. 두 사람이 딴 사과는 모두 몇 kg인지, 곰이는 펭이보다 몇 kg 덜 땄는지 각각 구하고 어떤 셈을 골랐는지 설명해 보세요.","answer_guide":{"answer":"예: 모두 몇 kg인지는 모으는 것이라 덧셈 — ⟨5/8⟩ + ⟨7/8⟩ = ⟨12/8⟩ = ⟨1 4/8⟩ kg. 덜 딴 양은 차이라 뺄셈 — ⟨7/8⟩ − ⟨5/8⟩ = ⟨2/8⟩ kg.","scoring_points":["⟨1 4/8⟩ kg을 구했는가","⟨2/8⟩ kg을 구했는가","덧셈·뺄셈을 고른 까닭을 썼는가"]},"explanation":["모두 = 덧셈 ⟨1 4/8⟩.","차이 = 뺄셈 ⟨2/8⟩.","셈 고르기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
